alter table public.case_charges add constraint case_charges_imposed_jail_judge_check CHECK (((imposed_jail_months IS NULL) OR snap_judge_set_jail));
alter table public.case_charges add constraint case_charges_imposed_jail_months_check CHECK (((imposed_jail_months IS NULL) OR (imposed_jail_months >= (0)::numeric)));
alter table public.case_charges add constraint case_charges_status_check CHECK ((status = ANY (ARRAY['approved'::text, 'filed'::text, 'convicted'::text, 'dismissed'::text, 'withdrawn'::text])));
alter table public.case_charges add constraint case_charges_substance_check CHECK ((((substance_quantity IS NULL) AND (substance_unit IS NULL) AND (substance_note IS NULL)) OR (snap_substance_schedule IS NOT NULL)));
alter table public.case_charges add constraint case_charges_substance_quantity_check CHECK (((substance_quantity IS NULL) OR (substance_quantity >= (0)::numeric)));
alter table public.case_charges add constraint case_charges_added_by_fkey FOREIGN KEY (added_by) REFERENCES profiles(id);
alter table public.case_charges add constraint case_charges_case_id_fkey FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE CASCADE;
alter table public.case_charges add constraint case_charges_charge_id_fkey FOREIGN KEY (charge_id) REFERENCES penal_charges(id);
