alter table public.legal_requests add constraint legal_requests_case_id_fkey FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE RESTRICT;
alter table public.legal_requests add constraint legal_requests_cid_reviewed_by_fkey FOREIGN KEY (cid_reviewed_by) REFERENCES profiles(id);
