END) AND ((entity_type <> 'person'::text) OR (person_id IS NOT NULL)) AND ((entity_type <> 'vehicle'::text) OR (vehicle_id IS NOT NULL)) AND ((entity_type <> 'gang'::text) OR (gang_id IS NOT NULL)) AND ((entity_type <> 'place'::text) OR (place_id IS NOT NULL)) AND ((entity_type <> 'account'::text) OR (account_id IS NOT NULL)) AND ((entity_type <> 'indicator'::text) OR (indicator_id IS NOT NULL)) AND ((entity_type <> 'unknown'::text) OR (NULLIF(btrim(COALESCE(label, ''::text)), ''::text) IS NOT NULL))));
