-- ============================================================
-- Views
-- ============================================================

create or replace view public.membership_history as
SELECT re.target_id AS user_id,
    'cid'::text AS organization,
    (re.new_role)::text AS role,
        CASE
            WHEN re.new_active THEN 'active'::text
            ELSE 'ended'::text
        END AS status,
    re.created_at AS recorded_at,
    re.reason,
    re.source,
    re.source_id AS reference_id
   FROM role_events re
UNION ALL
 SELECT m.user_id,
        CASE m.agency
            WHEN 'judiciary'::text THEN 'judiciary'::text
            ELSE 'doj'::text
        END AS organization,
    m.justice_role AS role,
        CASE
            WHEN (m.active AND ((m.expires_at IS NULL) OR (m.expires_at > now()))) THEN 'active'::text
            WHEN ((m.expires_at IS NOT NULL) AND (m.expires_at <= now())) THEN 'expired'::text
            ELSE 'ended'::text
        END AS status,
    COALESCE(m.approved_at, m.created_at) AS recorded_at,
    NULL::text AS reason,
    'justice_membership'::text AS source,
    NULL::uuid AS reference_id
   FROM justice_memberships m
UNION ALL
 SELECT tr.user_id,
    'transfer'::text AS organization,
    ((tr.direction || ':'::text) || tr.requested_role) AS role,
    tr.status,
    COALESCE(tr.effective_at, tr.updated_at) AS recorded_at,
    tr.reason,
    'member_transfer'::text AS source,
    tr.id AS reference_id
   FROM member_transfers tr;

