CREATE OR REPLACE FUNCTION public.account_merge(p_survivor uuid, p_victims uuid[], p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_reason text := btrim(coalesce(p_reason, ''));
  s public.accounts;
  v public.accounts;
  v_victim uuid;
  n_links int; n_handles int; n_cil int;
begin
  if not (private.is_command() or private.can_delete()) then
    raise exception 'account merge is restricted to command (Bureau Lead or higher)';
  end if;
  if v_reason = '' then
    raise exception 'a reason is required to merge account records';
  end if;
  if p_victims is null or cardinality(p_victims) = 0 then
    raise exception 'at least one merge victim is required';
  end if;
  if p_survivor = any (p_victims) then
    raise exception 'the survivor cannot also be a merge victim';
  end if;

  select * into s from public.accounts where id = p_survivor for update;
  if s.id is null then raise exception 'survivor account not found'; end if;
  if s.lifecycle = 'merged' then
    raise exception 'the survivor is already merged into another record — merge into its survivor instead';
  end if;

  foreach v_victim in array p_victims loop
    select * into v from public.accounts where id = v_victim for update;
    if v.id is null then raise exception 'merge victim % not found', v_victim; end if;
    if v.lifecycle = 'merged' then
      raise exception 'account % is already merged and cannot be merged again', v_victim;
    end if;
  end loop;

  foreach v_victim in array p_victims loop
    select * into v from public.accounts where id = v_victim;

    delete from public.account_links l
     where l.account_id = v_victim
       and exists (select 1 from public.account_links d
                    where d.account_id = p_survivor
                      and d.subject_kind = l.subject_kind
                      and d.subject_id = l.subject_id);
    update public.account_links set account_id = p_survivor where account_id = v_victim;
    get diagnostics n_links = row_count;

    insert into public.account_handles (account_id, handle, is_current, observed_at, source)
    select p_survivor, h.handle, false, h.observed_at, coalesce(h.source, 'merged')
      from public.account_handles h where h.account_id = v_victim;
    get diagnostics n_handles = row_count;

    delete from public.case_intel_links l
     where l.kind = 'account' and l.ref_id = v_victim
       and exists (select 1 from public.case_intel_links d
                    where d.case_id = l.case_id and d.kind = 'account' and d.ref_id = p_survivor);
    update public.case_intel_links set ref_id = p_survivor
     where kind = 'account' and ref_id = v_victim;
    get diagnostics n_cil = row_count;

    update public.accounts
       set lifecycle = 'merged', merged_into = p_survivor
     where id = v_victim;

    if (s.display_name is null or btrim(s.display_name) = '')
       and v.display_name is not null and btrim(v.display_name) <> '' then
      update public.accounts set display_name = v.display_name where id = p_survivor;
      s.display_name := v.display_name;
    end if;
    if (s.summary is null or btrim(s.summary) = '')
       and v.summary is not null and btrim(v.summary) <> '' then
      update public.accounts set summary = v.summary where id = p_survivor;
      s.summary := v.summary;
    end if;
    if (v.operator_unknown and not s.operator_unknown)
       or (v.is_impersonation and not s.is_impersonation)
       or (v.is_compromised and not s.is_compromised) then
      update public.accounts
         set operator_unknown = s.operator_unknown or v.operator_unknown,
             is_impersonation = s.is_impersonation or v.is_impersonation,
             is_compromised = s.is_compromised or v.is_compromised
       where id = p_survivor;
      s.operator_unknown := s.operator_unknown or v.operator_unknown;
      s.is_impersonation := s.is_impersonation or v.is_impersonation;
      s.is_compromised := s.is_compromised or v.is_compromised;
    end if;
    if s.external_id is null and v.external_id is not null then
      update public.accounts set external_id = v.external_id where id = p_survivor;
      s.external_id := v.external_id;
    end if;

    insert into public.audit_log (actor_id, action, entity, entity_id, detail)
    values (v_uid, 'ACCOUNT_MERGED', 'accounts', v_victim, jsonb_build_object(
      'survivor_id', p_survivor, 'victim_id', v_victim,
      'victim_platform', v.platform, 'victim_handle', v.handle,
      'reason', left(v_reason, 500),
      'repointed', jsonb_build_object(
        'account_links', n_links, 'account_handles', n_handles,
        'case_intel_links', n_cil)));
  end loop;
end $function$
;

CREATE OR REPLACE FUNCTION public.acknowledge_document(p_document uuid)
 RETURNS document_acknowledgements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.documents; v_uid uuid := (select auth.uid());
  v_version uuid; ack public.document_acknowledgements;
begin
  select * into d from public.documents where id = p_document;
  if not found then raise exception 'document not found'; end if;
  if not private.doc_class_visible(d.classification, d.owner_user_id) then
    raise exception 'document not found';
  end if;
  if not d.acknowledgement_required then
    raise exception 'this document does not require acknowledgement';
  end if;
  select id into v_version from public.documents_versions
   where document_id = d.id and version_number = d.current_version_number;
  if v_version is null then raise exception 'no version row for the current content'; end if;
  insert into public.document_acknowledgements (document_id, user_id, document_version_id)
  values (d.id, v_uid, v_version)
  on conflict (document_id, user_id, document_version_id) do update
    set method = excluded.method
  returning * into ack;
  return ack;
end $function$
;

CREATE OR REPLACE FUNCTION public.add_legal_exhibit(p_request uuid, p_type text, p_source_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_meta jsonb DEFAULT '{}'::jsonb, p_rationale text DEFAULT NULL::text)
 RETURNS legal_request_exhibits
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
        e public.legal_request_exhibits; v_title text := nullif(btrim(coalesce(p_title, '')), '');
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if not private.can_edit_legal_draft(p_request, v_uid) then
    raise exception 'exhibits can only change while the request is editable';
  end if;
  if p_type = 'evidence' then
    if not exists (select 1 from public.evidence ev where ev.id = p_source_id
                   and ev.case_id is not null and private.can_access_case(ev.case_id)) then
      raise exception 'evidence not found or not accessible';
    end if;
    v_title := coalesce(v_title, (select coalesce(item_code || ' — ', '') || coalesce(description, 'Evidence')
                                    from public.evidence where id = p_source_id));
  elsif p_type = 'attachment' then
    if not exists (select 1 from public.case_files f
                   join public.cases c on c.case_number = f.case_number
                   where f.id = p_source_id and private.can_access_case(c.id)) then
      raise exception 'attachment not found or not accessible';
    end if;
    v_title := coalesce(v_title, (select name from public.case_files where id = p_source_id));
  elsif p_type = 'finalized_report' then
    if not exists (select 1 from public.reports rp where rp.id = p_source_id
                   and rp.finalized and private.can_access_case(rp.case_id)) then
      raise exception 'finalized report not found or not accessible';
    end if;
    v_title := coalesce(v_title, (select template || ' report' from public.reports where id = p_source_id));
  elsif p_type = 'case_media' then
    if not exists (select 1 from public.media m where m.id = p_source_id
                   and m.case_id is not null and private.can_access_case(m.case_id)) then
      raise exception 'media not found or not accessible';
    end if;
    v_title := coalesce(v_title, (select title from public.media where id = p_source_id));
  elsif p_type = 'related_case' then
    if not (p_source_id is not null and private.can_access_case(p_source_id)) then
      raise exception 'related case not found or not accessible';
    end if;
    v_title := coalesce(v_title, (select case_number || coalesce(' — ' || title, '')
                                    from public.cases where id = p_source_id));
  elsif p_type = 'person_record' then
    if not exists (select 1 from public.persons pe where pe.id = p_source_id) then
      raise exception 'person not found';
    end if;
    v_title := coalesce(v_title, (select name from public.persons where id = p_source_id));
  elsif p_type = 'vehicle' then
    if not exists (select 1 from public.vehicles vh where vh.id = p_source_id) then
      raise exception 'vehicle not found';
    end if;
    v_title := coalesce(v_title, (select plate || coalesce(' — ' || model, '')
                                    from public.vehicles where id = p_source_id));
  elsif p_type = 'place' then
    if not exists (select 1 from public.places pl where pl.id = p_source_id) then
      raise exception 'place not found';
    end if;
    v_title := coalesce(v_title, (select name from public.places where id = p_source_id));
  elsif p_type = 'prior_legal_request' then
    if p_source_id is null or p_source_id = p_request
       or not private.can_view_legal_request(p_source_id, v_uid) then
      raise exception 'prior legal request not found or not accessible';
    end if;
    v_title := coalesce(v_title,
      (select lr.request_number
              || case when lr.classification = 'sealed' then '' else ' — ' || lr.title end
         from public.legal_requests lr where lr.id = p_source_id));
  elsif p_type = 'external_link' then
    if btrim(coalesce(p_meta->>'url', '')) = '' then raise exception 'external links require a url'; end if;
    if btrim(p_meta->>'url') !~* '^https?://' then
      raise exception 'external links must use http:// or https://';
    end if;
    v_title := coalesce(v_title, p_meta->>'url');
  else
    raise exception 'invalid exhibit type';
  end if;

  insert into public.legal_request_exhibits
    (legal_request_id, exhibit_type, source_id, display_title, snapshot_metadata, added_by, rationale)
  values (p_request, p_type, p_source_id, coalesce(v_title, 'Exhibit'),
          coalesce(p_meta, '{}'::jsonb), v_uid,
          nullif(btrim(coalesce(p_rationale, '')), ''))
  returning * into e;
  perform private.legal_log(p_request, null, 'exhibit_added', null, null, e.display_title, null);
  perform private.legal_audit(p_request, 'LEGAL_EXHIBIT_ADDED',
    jsonb_build_object('exhibit_id', e.id, 'type', p_type));
  return e;
end $function$
;

CREATE OR REPLACE FUNCTION public.add_narcotic_sale_observation(p_series uuid, p_observation jsonb, p_stacks jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_series public.narcotic_sale_series%rowtype;
  v_obs_id uuid;
  v_num integer;
  v_manager boolean := private.can_manage_narcotics();
  v_state text;
  v_stack jsonb;
  v_i integer := 0;
begin
  if not private.can_edit_narcotics_intel() then
    raise exception 'not authorized to record sale observations' using errcode = '42501';
  end if;
  select * into v_series from public.narcotic_sale_series where id = p_series for update;
  if not found then raise exception 'series not found' using errcode = 'P0002'; end if;
  select coalesce(max(observation_number), 0) + 1 into v_num
    from public.narcotic_sale_observations where series_id = p_series;
  v_state := coalesce(p_observation->>'state', 'draft');
  if not v_manager then v_state := 'draft'; end if;
  insert into public.narcotic_sale_observations (
    series_id, narcotic_id, observation_number, product_name, product_state,
    quality_tier, observed_at, observed_date_precision, investigator_id,
    payment_type, payment_amount, currency, total_units,
    recorded_weight_value, recorded_weight_unit, recorded_weight_text, weight_is_derived,
    state, source_confidence, provenance, restricted, location_ref, buyer_ref,
    methodology, analyst_note, notes, source_case_id, created_by
  ) values (
    p_series, v_series.narcotic_id, v_num,
    coalesce(p_observation->>'product_name', v_series.product_name),
    coalesce(p_observation->>'product_state', 'unknown'),
    nullif(p_observation->>'quality_tier', ''),
    (p_observation->>'observed_at')::timestamptz,
    coalesce(p_observation->>'observed_date_precision', 'unknown'),
    coalesce((p_observation->>'investigator_id')::uuid, v_uid),
    coalesce(p_observation->>'payment_type', 'dirty_money'),
    coalesce((p_observation->>'payment_amount')::numeric, 0),
    coalesce(p_observation->>'currency', 'USD'),
    coalesce((p_observation->>'total_units')::integer, 0),
    (p_observation->>'recorded_weight_value')::numeric,
    nullif(p_observation->>'recorded_weight_unit', ''),
    nullif(p_observation->>'recorded_weight_text', ''),
    coalesce((p_observation->>'weight_is_derived')::boolean, false),
    v_state,
    coalesce(p_observation->>'source_confidence', 'confirmed'),
    coalesce(p_observation->>'provenance', 'reported'),
    true,
    nullif(p_observation->>'location_ref', ''),
    nullif(p_observation->>'buyer_ref', ''),
    nullif(p_observation->>'methodology', ''),
    nullif(p_observation->>'analyst_note', ''),
    nullif(p_observation->>'notes', ''),
    (p_observation->>'source_case_id')::uuid,
    v_uid
  ) returning id into v_obs_id;
  if jsonb_typeof(p_stacks) = 'array' then
    for v_stack in select * from jsonb_array_elements(p_stacks) loop
      v_i := v_i + 1;
      insert into public.narcotic_sale_stacks (
        observation_id, stack_number, units, recorded_weight_value,
        recorded_weight_unit, recorded_weight_text, weight_is_derived, notes, created_by
      ) values (
        v_obs_id, coalesce((v_stack->>'stack_number')::integer, v_i),
        coalesce((v_stack->>'units')::integer, 0),
        (v_stack->>'recorded_weight_value')::numeric,
        nullif(v_stack->>'recorded_weight_unit', ''),
        nullif(v_stack->>'recorded_weight_text', ''),
        coalesce((v_stack->>'weight_is_derived')::boolean, false),
        nullif(v_stack->>'notes', ''), v_uid
      );
    end loop;
  end if;
  return v_obs_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_justice_membership_requests()
 RETURNS SETOF justice_membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not (coalesce(private.justice_role() in ('district_attorney', 'attorney_general'), false)
          or coalesce((select is_owner and removed_at is null from public.profiles
                       where id = (select auth.uid())), false)) then
    raise exception 'not authorized';
  end if;
  return query select r.* from public.justice_membership_requests r
   where not private.is_test_user(r.applicant_id)
      or private.is_test_user((select auth.uid()))
   order by r.submitted_at desc nulls last, r.created_at desc;
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_member_emails()
 RETURNS TABLE(id uuid, email text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_command() then raise exception 'not authorized'; end if;
  return query select p.id, p.email from public.profiles p
   where (not p.is_test or private.is_test_user((select auth.uid())))
     and not p.is_system;
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_membership_requests()
 RETURNS SETOF membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not (private.is_active() and (private.is_command() or private.is_owner())) then
    raise exception 'not authorized';
  end if;
  return query select r.* from public.membership_requests r
   where not private.is_test_user(r.applicant_id)
      or private.is_test_user((select auth.uid()))
   order by r.submitted_at desc nulls last, r.created_at desc;
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_remove_member(p_target uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); a public.profiles; t public.profiles;
begin
  select * into a from public.profiles where id = v_actor;
  if not private.is_command() then raise exception 'not authorized'; end if;
  if p_target = v_actor then raise exception 'you cannot remove yourself'; end if;
  select * into t from public.profiles where id = p_target;
  if not found then raise exception 'member not found'; end if;
  if t.is_system then raise exception 'system accounts cannot be modified'; end if;
  if t.is_owner and not coalesce(a.is_owner, false) then
    raise exception 'only the owner may remove an owner account';
  end if;
  if not coalesce(a.is_owner, false) then
    if a.role = 'bureau_lead' then
      if t.division is distinct from a.division or t.role not in ('detective','senior_detective') then
        raise exception 'bureau leads may only remove rank-and-file members of their own bureau';
      end if;
    elsif a.role = 'deputy_director' then
      if t.role in ('deputy_director','director') then
        raise exception 'removing command staff at this level requires a Director';
      end if;
    end if;
  end if;
  if t.role = 'director' and t.active
     and (select count(*) from public.profiles where role = 'director' and active and id <> p_target) = 0 then
    raise exception 'cannot remove the last active director';
  end if;
  delete from public.watchlist where user_id = p_target;
  delete from public.case_assignments where officer_id = p_target;
  update public.profiles
     set active = false, removed_at = now(), email = null
   where id = p_target;
  insert into public.role_events (target_id, actor_id, old_role, new_role,
    old_division, new_division, old_active, new_active, reason, source)
  values (p_target, v_actor, t.role, t.role, t.division, t.division, t.active, false,
    coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'removed by command'), 'admin_remove_member');
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_actor, 'REMOVE_MEMBER', 'profiles', p_target);
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_restore_member(p_target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); a public.profiles; t public.profiles;
begin
  select * into a from public.profiles where id = v_actor;
  if not (a.id is not null and coalesce(a.active, false)
          and (a.role = 'director' or coalesce(a.is_owner, false))) then
    raise exception 'only a Director or the Owner may restore a removed member';
  end if;
  select * into t from public.profiles where id = p_target;
  if not found then raise exception 'member not found'; end if;
  if t.is_system then raise exception 'system accounts cannot be modified'; end if;
  update public.profiles set removed_at = null where id = p_target;
  insert into public.role_events (target_id, actor_id, old_role, new_role,
    old_division, new_division, old_active, new_active, reason, source)
  values (p_target, v_actor, t.role, t.role, t.division, t.division, t.active, t.active,
    'restored by command', 'admin_restore_member');
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_actor, 'RESTORE_MEMBER', 'profiles', p_target);
end $function$
;

CREATE OR REPLACE FUNCTION public.announcement_notify_update(p_announce uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); a public.announcements; v_n int := 0; rec record;
begin
  if not (private.is_active() and private.can_announce()) then raise exception 'not authorized'; end if;
  select * into a from public.announcements where id = p_announce;
  if not found then raise exception 'announcement not found'; end if;
  for rec in select * from private.announcement_recipients(a.audience, a.mentions, v_uid) loop
    insert into public.notifications (user_id, type, payload)
    values (rec.user_id, 'announcement', jsonb_build_object(
      'announce_id', a.id, 'title', a.title,
      'reason', 'Announcement updated: ' || a.title,
      'actor_id', v_uid,
      'actor_name', (select display_name from public.profiles where id = v_uid)));
    v_n := v_n + 1;
  end loop;
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, 'ANNOUNCEMENT_UPDATE_NOTIFIED', 'announcements', a.id);
  return v_n;
end $function$
;

CREATE OR REPLACE FUNCTION public.announcement_recipient_count(p_audience text, p_mentions jsonb DEFAULT '[]'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not (private.is_active() and private.can_announce()) then raise exception 'not authorized'; end if;
  return (select count(*) from private.announcement_recipients(p_audience, p_mentions, (select auth.uid())));
end $function$
;

CREATE OR REPLACE FUNCTION public.approve_transfer_source(p_id uuid, p_note text DEFAULT NULL::text)
 RETURNS transfer_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles; r public.transfer_requests;
begin
  select * into me from public.profiles where id = (select auth.uid());
  select * into r from public.transfer_requests where id = p_id for update;
  if r.id is null then raise exception 'transfer not found'; end if;
  if r.status <> 'pending_source' then raise exception 'transfer is not awaiting source approval'; end if;
  if r.target_id = me.id then raise exception 'you cannot approve your own transfer'; end if;
  if not private.can_decide_transfer_side(r.from_bureau) then
    raise exception 'not authorized to approve for %', r.from_bureau;
  end if;
  update public.transfer_requests
     set status = 'pending_target', source_approved_by = me.id, source_approved_at = now(),
         decision_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), decision_note)
   where id = p_id returning * into r;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (me.id, 'TRANSFER_SOURCE_APPROVED', 'transfer_requests', r.id,
    jsonb_build_object('target_id', r.target_id, 'note', p_note));
  perform private.transfer_notify(r, me,
    r.from_bureau || ' approved the transfer; awaiting ' || r.to_bureau || '.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.approve_transfer_target(p_id uuid, p_note text DEFAULT NULL::text)
 RETURNS transfer_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles; r public.transfer_requests;
begin
  select * into me from public.profiles where id = (select auth.uid());
  select * into r from public.transfer_requests where id = p_id for update;
  if r.id is null then raise exception 'transfer not found'; end if;
  if r.status <> 'pending_target' then raise exception 'transfer is not awaiting target approval'; end if;
  if r.target_id = me.id then raise exception 'you cannot approve your own transfer'; end if;
  if not private.can_decide_transfer_side(r.to_bureau) then
    raise exception 'not authorized to approve for %', r.to_bureau;
  end if;
  update public.transfer_requests
     set target_approved_by = me.id, target_approved_at = now(),
         decision_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), decision_note)
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (me.id, 'TRANSFER_TARGET_APPROVED', 'transfer_requests', r.id,
    jsonb_build_object('target_id', r.target_id, 'note', p_note));
  -- Both bureaus have now consented — apply the move in the same transaction.
  return private.transfer_apply(p_id, me, false);
end $function$
;

CREATE OR REPLACE FUNCTION public.assign_ada_to_bureau(p_prosecutor uuid, p_bureau bureau, p_type text DEFAULT 'supporting'::text, p_note text DEFAULT NULL::text, p_replace boolean DEFAULT true)
 RETURNS prosecutor_bureau_assignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); a public.prosecutor_bureau_assignments;
        v_actor_name text; v_is_test boolean;
        v_actor_is_test boolean := coalesce((select is_test from public.profiles where id = (select auth.uid())), false);
        displaced record;
begin
  if not private.can_manage_prosecutors() then
    raise exception 'only a District Attorney, Attorney General, or the Owner may manage ADA assignments';
  end if;
  if p_type not in ('primary', 'supporting', 'acting') then raise exception 'invalid assignment type'; end if;
  if p_prosecutor = v_uid and not coalesce((select is_owner from public.profiles where id = v_uid), false)
     and p_type in ('primary', 'acting') then
    raise exception 'you cannot make yourself the routing prosecutor';
  end if;
  perform private.pba_validate(p_prosecutor, p_bureau, p_type);
  if exists (select 1 from public.prosecutor_bureau_assignments
             where prosecutor_id = p_prosecutor and bureau = p_bureau
               and assignment_type = p_type and ends_at is null) then
    raise exception 'that assignment already exists';
  end if;
  select display_name into v_actor_name from public.profiles where id = v_uid;
  if p_type in ('primary', 'acting') then
    select b.id, b.prosecutor_id, coalesce(bp.is_test, false) as pros_is_test
      into displaced
      from public.prosecutor_bureau_assignments b
      left join public.profiles bp on bp.id = b.prosecutor_id
     where b.bureau = p_bureau and b.assignment_type = p_type and b.ends_at is null;
    if displaced.id is not null then
      if not p_replace then
        raise exception 'an active % assignment already exists for %', p_type, p_bureau;
      end if;
      if v_actor_is_test and not displaced.pros_is_test then
        raise exception 'test fixtures may not replace the live % assignment for % held by a real prosecutor', p_type, p_bureau;
      end if;
      update public.prosecutor_bureau_assignments
         set ends_at = now()
       where id = displaced.id;
      insert into public.audit_log (actor_id, action, entity, entity_id, detail)
      values (v_uid, 'ADA_ASSIGNMENT_ENDED', 'prosecutor_bureau_assignments', displaced.id,
              jsonb_build_object('prosecutor_id', displaced.prosecutor_id, 'bureau', p_bureau,
                'type', p_type, 'replaced_by', p_prosecutor));
      if not displaced.pros_is_test then
        insert into public.notifications (user_id, type, payload)
        values (displaced.prosecutor_id, 'ada_assignment', jsonb_build_object(
          'assignment_id', displaced.id, 'bureau', p_bureau, 'assignment_type', p_type, 'ended', true,
          'reason', 'Your ' || p_type || ' assignment for ' || p_bureau || ' has ended (replaced).',
          'actor_id', v_uid, 'actor_name', v_actor_name));
      end if;
    end if;
  end if;
  insert into public.prosecutor_bureau_assignments
    (prosecutor_id, bureau, assignment_type, assigned_by, assignment_note)
  values (p_prosecutor, p_bureau, p_type, v_uid, nullif(btrim(coalesce(p_note, '')), ''))
  returning * into a;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'ADA_ASSIGNED', 'prosecutor_bureau_assignments', a.id,
          jsonb_build_object('prosecutor_id', p_prosecutor, 'bureau', p_bureau, 'type', p_type));
  select email like 'rls-test-%@cidportal.test' into v_is_test from auth.users where id = p_prosecutor;
  if not coalesce(v_is_test, false) then
    insert into public.notifications (user_id, type, payload)
    values (p_prosecutor, 'ada_assignment', jsonb_build_object(
      'assignment_id', a.id, 'bureau', p_bureau, 'assignment_type', p_type,
      'reason', 'You are now the ' || p_type || ' prosecutor for ' || p_bureau || '.',
      'actor_id', v_uid, 'actor_name', v_actor_name));
  end if;
  return a;
end $function$
;

CREATE OR REPLACE FUNCTION public.assign_field_officer(p_user uuid, p_agency text, p_callsign text DEFAULT NULL::text, p_rank text DEFAULT NULL::text, p_unit text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_id uuid;
begin
  if not private.is_command() then raise exception 'not authorized'; end if;
  if p_agency not in ('SAHP', 'BCSO', 'LSPD') then
    raise exception 'unknown agency: %', p_agency;
  end if;
  if not exists (select 1 from public.profiles where id = p_user) then
    raise exception 'no such account -- the officer must sign in once first';
  end if;

  insert into public.field_officers
    (user_id, agency, callsign, officer_rank, unit, appointed_by)
  values (p_user, p_agency, nullif(btrim(coalesce(p_callsign, '')), ''),
          nullif(btrim(coalesce(p_rank, '')), ''),
          nullif(btrim(coalesce(p_unit, '')), ''), v_actor)
  on conflict (user_id) do update
    set agency = excluded.agency,
        callsign = excluded.callsign,
        officer_rank = excluded.officer_rank,
        unit = excluded.unit,
        active = true,
        appointed_by = v_actor,
        appointed_at = now(),
        ended_by = null, ended_at = null, end_reason = null,
        updated_at = now()
  returning id into v_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_OFFICER_APPOINTED', 'field_officers', v_id,
          jsonb_build_object('user_id', p_user, 'agency', p_agency,
                             'callsign', p_callsign, 'rank', p_rank, 'unit', p_unit));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.assign_judge(p_request uuid, p_judge uuid)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'submitted_to_judge' then
    raise exception 'request is not awaiting judicial assignment';
  end if;
  if not (coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)
          or private.owner_flag(v_uid)
          or (coalesce(private.justice_role_effective(v_uid) = 'prosecutor', false)
              and exists (select 1 from public.legal_request_signatures s
                           where s.legal_request_id = p_request
                             and s.signer_id = v_uid and s.action = 'prosecutor_decision'))) then
    raise exception 'not authorized to assign a Judge';
  end if;
  if private.justice_role_effective(p_judge) is distinct from 'judge' then
    raise exception 'the assignee must be an active Judge';
  end if;
  if private.legal_is_prosecution_side(p_request, p_judge) or p_judge = r.created_by then
    raise exception 'conflict of role: this user acted on the prosecution side of this request';
  end if;
  if private.legal_is_conflicted(p_request, p_judge) then
    raise exception 'conflict of interest: the assignee participated in this case as an investigator — recusal required';
  end if;
  update public.legal_requests
     set assigned_judge_id = p_judge, review_status = 'judicial_review'
   where id = p_request returning * into r;
  perform private.legal_add_participant(p_request, p_judge, 'judicial_reviewer');
  perform private.legal_log(p_request, r.current_version_id, 'judge_assigned',
    'submitted_to_judge', 'judicial_review', null, null);
  perform private.legal_audit(p_request, 'LEGAL_JUDGE_ASSIGNED', jsonb_build_object('judge', p_judge));
  perform private.legal_notify(p_judge, p_request, 'legal_request',
    'A ' || r.request_type || ' request was assigned to you for judicial review.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.assign_member(target uuid, set_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  me public.profiles;
  t public.profiles;
  r public.membership_requests;
begin
  select * into me from public.profiles where id = v_uid;
  if me.id is null or not (me.active and (me.role in ('bureau_lead','deputy_director','director') or me.is_owner)) then
    raise exception 'not authorized';
  end if;
  select * into t from public.profiles where id = target for update;
  if t.id is null then raise exception 'target not found'; end if;
  if t.is_system then
    raise exception 'system accounts cannot be modified';
  end if;
  if me.role = 'bureau_lead' and not me.is_owner then
    if t.division is distinct from me.division then
      raise exception 'bureau leads may only manage members in their own bureau';
    end if;
    if t.role in ('bureau_lead','deputy_director','director') then
      raise exception 'bureau leads cannot manage command staff';
    end if;
  end if;
  if set_active and t.removed_at is not null then
    raise exception 'member was removed — restore them first';
  end if;
  if set_active and t.login_denied then
    raise exception 'member login is denied — restore login first';
  end if;
  if set_active and exists (
    select 1 from public.justice_memberships m where m.user_id = target and m.active
  ) then
    raise exception 'member holds an active DOJ/Judiciary membership — use organization correction (Move to CID) to bring them back, do not reactivate CID access';
  end if;
  if set_active and not t.active and exists (
    select 1 from public.membership_requests mr
    where mr.applicant_id = target and mr.status in ('rejected', 'withdrawn')
  ) then
    raise exception 'this applicant''s membership request was rejected — re-review it in the approval queue before activating';
  end if;
  if t.active = set_active then return; end if;

  update public.profiles set active = set_active where id = target;
  insert into public.role_events (target_id, actor_id, old_role, new_role,
    old_division, new_division, old_active, new_active, source)
  values (target, v_uid, t.role, t.role, t.division, t.division, t.active, set_active, 'activation');

  if set_active then
    select * into r from public.membership_requests
     where applicant_id = target and status in ('pending', 'correction_requested')
     for update;
    if found then
      update public.membership_requests
         set status = 'approved',
             decided_by = v_uid,
             decided_at = now(),
             decided_role = t.role,
             decided_bureau = case when t.division in ('major_crimes', 'street_crimes')
                                   then t.division else null end,
             internal_decision_note = case
               when internal_decision_note is null or btrim(internal_decision_note) = ''
                 then 'Auto-reconciled: member activated directly via assign_member.'
               else internal_decision_note || E'\n'
                 || 'Auto-reconciled: member activated directly via assign_member.'
             end
       where id = r.id;
      perform private.mr_history(r.id, 'approved', r.status, 'approved',
        'Auto-reconciled: member activated directly via assign_member.', true);
    end if;
  end if;
end $function$
;

CREATE OR REPLACE FUNCTION public.bridge_ingest_event(p_source text, p_event_type text, p_source_event_id text, p_event_time timestamp with time zone, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.bridge_ingestion_events;
  v_target public.surveillance_targets;
  v_obs_id uuid;
  v_activity text;
  v_err text;
begin
  if coalesce(btrim(p_source), '') = '' or coalesce(btrim(p_source_event_id), '') = '' then
    raise exception 'source and source_event_id are required';
  end if;
  insert into public.bridge_ingestion_events (source, event_type, source_event_id, event_time, payload)
  values (p_source, coalesce(p_event_type, 'other'), p_source_event_id, p_event_time,
          coalesce(p_payload, '{}'::jsonb))
  on conflict (source, source_event_id) do nothing
  returning * into v_event;
  if v_event.id is null then
    return jsonb_build_object('status', 'duplicate', 'source_event_id', p_source_event_id);
  end if;

  v_err := case
    when p_event_type is null or p_event_type not in
      ('fixed_camera', 'alpr', 'monitored_location', 'vehicle_observation',
       'person_observation', 'meeting_event', 'patrol_submission') then 'unknown event_type'
    when p_payload is null or jsonb_typeof(p_payload) <> 'object' then 'payload must be an object'
    when coalesce(btrim(p_payload ->> 'activity'), '') = '' then 'payload.activity is required'
    when p_payload ->> 'target_id' is null then 'payload.target_id is required'
    when p_event_time is null then 'event_time is required'
    else null end;
  if v_err is null then
    begin
      select * into v_target from public.surveillance_targets
       where id = (p_payload ->> 'target_id')::uuid;
      if not found then v_err := 'unknown surveillance target';
      elsif v_target.status not in ('authorized', 'active') then
        v_err := 'surveillance target is not authorized/active';
      elsif v_target.expires_at is not null and v_target.expires_at <= now() then
        v_err := 'surveillance authorization has expired';
      end if;
    exception when invalid_text_representation then
      v_err := 'payload.target_id is not a uuid';
    end;
  end if;
  if v_err is not null then
    update public.bridge_ingestion_events
       set status = 'quarantined', error = v_err where id = v_event.id;
    insert into public.audit_log (actor_id, action, entity, entity_id, detail)
    values (null, 'BRIDGE_EVENT_QUARANTINED', 'bridge_ingestion_events', v_event.id,
            jsonb_build_object('source', p_source, 'event_type', p_event_type, 'error', v_err));
    return jsonb_build_object('status', 'quarantined', 'error', v_err, 'ingestion_id', v_event.id);
  end if;

  v_activity := btrim(p_payload ->> 'activity');
  insert into public.surveillance_observations
    (case_id, target_id, observed_at, source_type, source_ref, source_event_id,
     location_text, lat, lng, plate_snapshot, subject_description, activity,
     confidence, verification_status, ingestion_id, created_by)
  values (v_target.case_id, v_target.id, p_event_time,
          case p_event_type
            when 'alpr' then 'alpr'
            when 'fixed_camera' then 'fixed_camera'
            when 'monitored_location' then 'property_monitor'
            when 'vehicle_observation' then 'vehicle_sensor'
            when 'patrol_submission' then 'patrol_submission'
            else 'fivem_bridge' end,
          p_source, p_source_event_id,
          p_payload ->> 'location', (p_payload ->> 'lat')::double precision,
          (p_payload ->> 'lng')::double precision,
          p_payload ->> 'plate', p_payload ->> 'description', v_activity,
          'unverified', 'unverified', v_event.id, null)
  returning id into v_obs_id;

  update public.bridge_ingestion_events
     set status = 'processed', observation_id = v_obs_id, processed_at = now()
   where id = v_event.id;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (null, 'BRIDGE_EVENT_INGESTED', 'bridge_ingestion_events', v_event.id,
          jsonb_build_object('source', p_source, 'event_type', p_event_type,
                             'observation_id', v_obs_id, 'target_id', v_target.id));
  return jsonb_build_object('status', 'processed', 'ingestion_id', v_event.id,
                            'observation_id', v_obs_id);
end $function$
;

CREATE OR REPLACE FUNCTION public.cancel_transfer(p_id uuid)
 RETURNS transfer_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles; r public.transfer_requests;
begin
  select * into me from public.profiles where id = (select auth.uid());
  select * into r from public.transfer_requests where id = p_id for update;
  if r.id is null then raise exception 'transfer not found'; end if;
  if r.status not in ('pending_source', 'pending_target', 'approved') then
    raise exception 'transfer is not open';
  end if;
  if r.target_id = me.id then raise exception 'you cannot decide your own transfer'; end if;
  if not (r.requested_by = me.id
          or (me.active and (me.role in ('deputy_director','director') or me.is_owner))) then
    raise exception 'only the requester or higher command may cancel';
  end if;
  update public.transfer_requests set status = 'cancelled' where id = p_id returning * into r;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (me.id, 'TRANSFER_CANCELLED', 'transfer_requests', r.id,
    jsonb_build_object('target_id', r.target_id));
  perform private.transfer_notify(r, me, 'Transfer to ' || r.to_bureau || ' was cancelled.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.case_access_decide(p_request uuid, p_approve boolean, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  r public.case_access_requests;
  c public.cases;
  v_req_name text;
begin
  select * into r from public.case_access_requests where id = p_request for update;
  if not found then
    raise exception 'access request not found';
  end if;
  if not private.can_grant_case(r.case_id) then
    raise exception 'only the case lead or command may decide access requests';
  end if;
  if r.status <> 'pending' then
    raise exception 'this request was already decided (%)', r.status;
  end if;
  select * into c from public.cases where id = r.case_id;

  if p_approve then
    insert into public.case_access_grants (case_id, officer_id, granted_by)
    values (r.case_id, r.requester_id, v_uid)
    on conflict (case_id, officer_id) do nothing;
  end if;
  update public.case_access_requests
     set status = case when p_approve then 'approved' else 'denied' end,
         decided_by = v_uid, decided_at = now()
   where id = p_request;

  v_req_name := coalesce(nullif(btrim(coalesce(r.requester_name, '')), ''),
                         (select display_name from public.profiles where id = r.requester_id),
                         'Officer');
  perform private.case_service_notify(r.requester_id,
    case when p_approve then 'access_granted' else 'access_denied' end,
    jsonb_build_object('case_id', r.case_id, 'case_number', c.case_number,
                       'title', v_req_name || ' requested case access'));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'CASE_ACCESS_DECIDED', 'case_access_requests', p_request,
          jsonb_build_object('request', p_request, 'case_id', r.case_id,
                             'officer', r.requester_id, 'approved', p_approve,
                             'note', nullif(btrim(coalesce(p_note, '')), '')));
end $function$
;

CREATE OR REPLACE FUNCTION public.case_archive(p_case uuid, p_note text DEFAULT NULL::text)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.cases; v_uid uuid := (select auth.uid());
begin
  if not private.is_command() then raise exception 'archiving a case is a command action'; end if;
  select * into c from public.cases where id = p_case for update;
  if not found then raise exception 'case not found'; end if;
  if private.case_has_active_hold(p_case) then
    raise exception 'this case is under an active legal hold and cannot be archived — lift the hold first';
  end if;
  if c.archived_at is not null then raise exception 'this case is already archived'; end if;
  update public.cases set archived_at = now(), archived_by = v_uid, updated_at = now()
   where id = p_case returning * into c;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'CASE_ARCHIVED', 'cases', p_case,
          jsonb_build_object('case_number', c.case_number, 'note', nullif(btrim(coalesce(p_note, '')), '')));
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.case_charge_totals(p_case uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with live as (
    select * from public.case_charges
     where case_id = p_case and status not in ('withdrawn', 'dismissed')
  ), agg as (
    select
      coalesce(sum(coalesce(imposed_jail_months, snap_jail_months) * counts), 0) as months,
      coalesce(sum(coalesce(imposed_fine, snap_fine) * counts), 0) as fine,
      count(*) filter (where snap_judge_set_jail and imposed_jail_months is null) as jail_pending,
      count(*) filter (where snap_judge_set_fine and imposed_fine is null) as fine_pending,
      count(*) as charges,
      coalesce(sum(counts), 0) as total_counts,
      count(*) filter (where snap_is_rico) as rico,
      count(*) filter (where snap_is_modifier) as modifiers,
      count(*) filter (where status = 'convicted') as convicted
      from live
  ), cap as (
    -- The cap belongs to the version the charges were brought under. NULL when
    -- that version never stated one -- the legacy code does not -- rather than
    -- a 200 borrowed from a different code.
    select max(l.max_total_months) as cap_months
      from public.penal_limits l
     where l.version_id in (select distinct version_id from live)
  )
  select jsonb_build_object(
    'charges', a.charges,
    'counts', a.total_counts,
    'months', a.months,
    'fine', a.fine,
    'judge_jail_pending', a.jail_pending,
    'judge_fine_pending', a.fine_pending,
    'rico', a.rico,
    'modifiers', a.modifiers,
    'convicted', a.convicted,
    'cap_months', c.cap_months,
    -- NULL, not false, when no cap is stated: "not over the limit" and "there
    -- is no stated limit" are different answers.
    'over_cap', case when c.cap_months is null then null else a.months > c.cap_months end,
    'by_status', coalesce((select jsonb_object_agg(s.status, s.n) from (
        select status, count(*) as n from public.case_charges
         where case_id = p_case group by status) s), '{}'::jsonb))
    from agg a cross join cap c
$function$
;

CREATE OR REPLACE FUNCTION public.case_charges_for(p_case uuid)
 RETURNS TABLE(id uuid, charge_id uuid, code text, offense text, penal_title text, charge_class text, counts integer, status text, fine numeric, jail_months numeric, judge_set_fine boolean, judge_set_jail boolean, imposed_fine numeric, imposed_jail_months numeric, is_modifier boolean, is_rico boolean, stackable boolean, substance_schedule integer, substance_quantity numeric, substance_unit text, substance_note text, note text, decision_note text, version_name text, version_status text, added_by uuid, added_at timestamp with time zone, decided_by uuid, decided_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select cc.id, cc.charge_id, cc.snap_code, cc.snap_offense, cc.snap_penal_title,
         cc.snap_charge_class, cc.counts, cc.status,
         cc.snap_fine, cc.snap_jail_months,
         cc.snap_judge_set_fine, cc.snap_judge_set_jail,
         cc.imposed_fine, cc.imposed_jail_months,
         cc.snap_is_modifier, cc.snap_is_rico, cc.snap_stackable,
         cc.snap_substance_schedule, cc.substance_quantity, cc.substance_unit,
         cc.substance_note, cc.note, cc.decision_note,
         v.name, v.status,
         cc.added_by, cc.added_at, cc.decided_by, cc.decided_at
    from public.case_charges cc
    join public.penal_code_versions v on v.id = cc.version_id
   where cc.case_id = p_case
   order by cc.snap_code nulls last, cc.added_at
$function$
;

CREATE OR REPLACE FUNCTION public.case_create(p_bureau text, p_title text, p_summary text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_area text DEFAULT NULL::text, p_lead uuid DEFAULT NULL::uuid, p_template uuid DEFAULT NULL::uuid, p_case_number text DEFAULT NULL::text)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  c public.cases;
  tpl public.case_templates;
  v_no text := nullif(btrim(coalesce(p_case_number, '')), '');
  v_explicit boolean := nullif(btrim(coalesce(p_case_number, '')), '') is not null;
  v_lead uuid;
  v_try int := 0;
begin
  if p_bureau not in ('major_crimes', 'street_crimes', 'JTF') then
    raise exception 'unknown bureau';
  end if;
  if not private.can_create_case(p_bureau::public.bureau) then
    raise exception 'not authorized to open cases in this bureau';
  end if;
  if nullif(btrim(coalesce(p_title, '')), '') is null then
    raise exception 'the case needs a title';
  end if;
  if p_priority is not null and p_priority not in ('low', 'medium', 'high', 'critical') then
    raise exception 'invalid priority';
  end if;

  v_lead := case when private.is_command() then p_lead else v_uid end;
  if v_lead is not null and v_lead <> v_uid
     and not exists (select 1 from public.profiles p where p.id = v_lead and p.active) then
    raise exception 'the lead detective must be an active member';
  end if;

  if v_explicit and v_no !~ '^[A-Z]+-[0-9]+$' then
    raise exception 'invalid case number — expected PREFIX-digits (e.g. MCB-4000123)';
  end if;

  perform pg_advisory_xact_lock(hashtext('case_number:' || p_bureau));
  loop
    v_try := v_try + 1;
    if v_no is null then
      v_no := public.next_case_number(p_bureau);
      if coalesce(v_no, '') = '' then
        raise exception 'could not allocate a case number';
      end if;
    end if;
    begin
      insert into public.cases
        (case_number, bureau, title, area, lead_detective_id, summary, priority, created_by)
      values
        (v_no, p_bureau::public.bureau, btrim(p_title),
         nullif(btrim(coalesce(p_area, '')), ''), v_lead,
         nullif(btrim(coalesce(p_summary, '')), ''), p_priority, v_uid)
      returning * into c;
      exit;
    exception when unique_violation then
      if v_explicit then
        raise exception 'case number % is already in use', v_no;
      end if;
      if v_try >= 5 then
        raise exception 'could not allocate a unique case number — try again';
      end if;
      v_no := null;
    end;
  end loop;

  if p_template is not null then
    select * into tpl from public.case_templates t
     where t.id = p_template and coalesce(t.active, true);
    if found then
      insert into public.case_tasks (case_id, title, created_by)
      select c.id, btrim(x.v), v_uid
        from jsonb_array_elements_text(coalesce(tpl.tasks, '[]'::jsonb)) x(v)
       where btrim(x.v) <> '';
    end if;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'CASE_CREATED', 'cases', c.id,
          jsonb_build_object('bureau', p_bureau, 'case_number', c.case_number,
                             'template', p_template));
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.case_delete_preview(p_case uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare rec record; cnt bigint; out jsonb := '[]'::jsonb; v_legal bigint; v_hold boolean;
begin
  if not private.is_owner() then raise exception 'permanent case deletion is restricted to the owner'; end if;
  if not exists (select 1 from public.cases where id = p_case) then raise exception 'case not found'; end if;
  for rec in
    select c.conrelid::regclass::text as tbl, a.attname as col, c.confdeltype
      from pg_constraint c
      join lateral unnest(c.conkey) with ordinality k(attnum, ord) on true
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k.attnum
     where c.contype = 'f' and c.confrelid = 'public.cases'::regclass
  loop
    execute format('select count(*) from %s where %I = $1', rec.tbl, rec.col) into cnt using p_case;
    if cnt > 0 then
      out := out || jsonb_build_object('table', rec.tbl, 'column', rec.col, 'rows', cnt,
        'on_delete', case rec.confdeltype when 'c' then 'destroyed'
                                          when 'n' then 'unlinked'
                                          else 'blocks deletion' end);
    end if;
  end loop;
  select count(*) into v_legal from public.legal_requests where case_id = p_case;
  v_hold := private.case_has_active_hold(p_case);
  return jsonb_build_object('items', out, 'legal_requests', v_legal, 'active_hold', v_hold,
                            'deletable', v_legal = 0 and not v_hold);
end $function$
;

CREATE OR REPLACE FUNCTION public.case_permanent_delete(p_case uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); c public.cases; v_preview jsonb;
begin
  if not private.is_owner() then raise exception 'permanent case deletion is restricted to the owner'; end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  select * into c from public.cases where id = p_case for update;
  if not found then raise exception 'case not found'; end if;
  if private.case_has_active_hold(p_case) then
    raise exception 'this case is under an active legal hold and cannot be deleted — lift the hold first';
  end if;
  if exists (select 1 from public.legal_requests where case_id = p_case) then
    raise exception 'this case has legal requests on file and cannot be deleted — withdraw or close them first';
  end if;
  v_preview := public.case_delete_preview(p_case);
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'CASE_PERMANENT_DELETE', 'cases', p_case,
          jsonb_build_object('case_number', c.case_number, 'title', c.title,
                             'reason', btrim(p_reason), 'destroyed', v_preview));
  delete from public.cases where id = p_case;
end $function$
;

CREATE OR REPLACE FUNCTION public.case_reassign_bureau(p_case uuid, p_to_bureau bureau, p_reason text, p_update_originating boolean DEFAULT false)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  me public.profiles;
  c public.cases;
  v_from public.bureau;
  v_orig_from public.bureau;
  v_orig_to public.bureau;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_is_test boolean;
begin
  select * into me from public.profiles where id = v_uid;
  if me.id is null or not (coalesce(me.active, false)
       and (me.role in ('deputy_director', 'director') or coalesce(me.is_owner, false))) then
    raise exception 'only a Deputy Director or higher may reassign a case between bureaus';
  end if;
  if v_reason = '' then raise exception 'a reason is required'; end if;
  if p_to_bureau not in ('major_crimes', 'street_crimes') then
    raise exception 'cases may only be reassigned to Major Crimes or Street Crimes — JTF is a shared-visibility designation, and SIB takes control through its own assumption workflow';
  end if;

  select * into c from public.cases where id = p_case for update;
  if c.id is null then raise exception 'case not found'; end if;
  if c.bureau = p_to_bureau then
    raise exception 'case is already in % — reload and retry', private.bureau_label(p_to_bureau::text);
  end if;

  v_from := c.bureau;
  v_orig_from := c.originating_bureau;
  v_orig_to := case when p_update_originating then p_to_bureau else c.originating_bureau end;

  update public.cases
     set bureau = p_to_bureau, originating_bureau = v_orig_to
   where id = p_case returning * into c;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'REASSIGN_BUREAU', 'cases', p_case, jsonb_build_object(
    'case_number', c.case_number,
    'from', v_from, 'to', p_to_bureau,
    'originating_from', v_orig_from, 'originating_to', v_orig_to,
    'reason', left(v_reason, 500),
    'status', c.status, 'is_joint_case', c.is_joint_case));

  select u.email like 'rls-test-%@cidportal.test' into v_is_test
    from auth.users u where u.id = v_uid;
  insert into public.notifications (user_id, type, payload)
  select p.id, 'case_reassigned', jsonb_build_object(
    'case_id', p_case, 'case_number', c.case_number,
    'from', v_from, 'to', p_to_bureau,
    'reason', 'Case ' || coalesce(c.case_number, '') || ' was reassigned from '
      || private.bureau_label(v_from::text) || ' to ' || private.bureau_label(p_to_bureau::text)
      || '. Reason: ' || v_reason,
    'actor_id', v_uid, 'actor_name', me.display_name)
    from public.profiles p
   where p.active and p.removed_at is null and p.id <> v_uid
     and (p.id is not distinct from c.lead_detective_id
          or exists (select 1 from public.case_assignments a
                      where a.case_id = p_case and a.officer_id = p.id
                        and a.removed_at is null
                        and (a.expires_at is null or a.expires_at > now())))
     and (not coalesce(v_is_test, false)
          or exists (select 1 from auth.users u
                      where u.id = p.id and u.email like 'rls-test-%@cidportal.test'));

  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.case_restore(p_case uuid)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.cases; v_uid uuid := (select auth.uid());
begin
  if not private.is_command() then raise exception 'restoring a case is a command action'; end if;
  select * into c from public.cases where id = p_case for update;
  if not found then raise exception 'case not found'; end if;
  if c.archived_at is null then raise exception 'this case is not archived'; end if;
  update public.cases set archived_at = null, archived_by = null, updated_at = now()
   where id = p_case returning * into c;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'CASE_RESTORED', 'cases', p_case, jsonb_build_object('case_number', c.case_number));
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.case_restricted_events(p_case uuid)
 RETURNS SETOF restricted_access_log
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_active() or not private.can_access_case(p_case) then
    raise exception 'not authorized';
  end if;
  return query
    select l.* from public.restricted_access_log l
    where l.entity_id = p_case
       or (l.entity_type = 'media'
           and exists (select 1 from public.media m where m.id = l.entity_id and m.case_id = p_case))
    order by l.created_at, l.id;
end $function$
;

CREATE OR REPLACE FUNCTION public.case_set_lead(p_case uuid, p_to uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  c public.cases;
  v_actor_name text;
  v_to_name text;
  v_payload jsonb;
begin
  if p_to is null then
    raise exception 'select the officer to hand the case to';
  end if;
  select * into c from public.cases where id = p_case for update;
  if not found or not private.can_access_case(p_case) then
    raise exception 'case not found or not accessible';
  end if;
  if c.lead_detective_id is distinct from v_uid and not private.is_command() then
    raise exception 'only the current lead or command may hand over a case';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_to and p.active) then
    raise exception 'the new lead must be an active member';
  end if;

  update public.cases set lead_detective_id = p_to where id = p_case;

  v_actor_name := coalesce((select display_name from public.profiles where id = v_uid), 'An officer');
  v_to_name    := coalesce((select display_name from public.profiles where id = p_to), 'Another officer');
  v_payload := jsonb_build_object(
    'case_id', c.id, 'case_number', c.case_number,
    'detective', v_actor_name,
    'title', coalesce(nullif(c.title, ''), c.case_number));
  perform private.case_service_notify(p_to, 'case_handover',
    v_payload || jsonb_build_object('reason',
      coalesce(nullif(btrim(coalesce(p_note, '')), ''),
               v_actor_name || ' handed you the lead on ' || c.case_number || '.')));
  if c.lead_detective_id is not null and c.lead_detective_id <> v_uid then
    perform private.case_service_notify(c.lead_detective_id, 'case_handover',
      v_payload || jsonb_build_object('reason',
        v_to_name || ' is now the lead on ' || c.case_number || '.'));
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'CASE_LEAD_CHANGED', 'cases', p_case,
          jsonb_build_object('from', c.lead_detective_id, 'to', p_to,
                             'note', nullif(btrim(coalesce(p_note, '')), '')));
end $function$
;

CREATE OR REPLACE FUNCTION public.case_set_stage(p_case uuid, p_stage text, p_reason text)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); c public.cases; me public.profiles; v_prev text;
begin
  if p_stage not in ('intake', 'active_investigation', 'legal_process',
                     'enforcement_ready', 'pending_closure', 'closed') then
    raise exception 'invalid investigative stage';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  select * into me from public.profiles where id = v_uid;
  select * into c from public.cases where id = p_case for update;
  if not found or not private.can_access_case(p_case) then
    raise exception 'case not found or not accessible';
  end if;
  if not (coalesce(me.is_owner, false)
          or (coalesce(me.active, false)
              and (me.role in ('senior_detective', 'bureau_lead', 'deputy_director', 'director')
                   or c.lead_detective_id = v_uid))) then
    raise exception 'only the case lead or a supervisor may change the investigative stage';
  end if;
  if c.investigative_stage = p_stage then
    raise exception 'the case is already at that stage';
  end if;
  v_prev := c.investigative_stage;
  update public.cases set investigative_stage = p_stage where id = p_case returning * into c;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'CASE_STAGE_CHANGED', 'cases', p_case,
          jsonb_build_object('from', v_prev, 'to', p_stage, 'reason', left(btrim(p_reason), 500)));
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.case_set_status(p_case uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  c public.cases;
begin
  if p_status not in ('open', 'active', 'cold', 'closed') then
    raise exception 'invalid case status';
  end if;
  select * into c from public.cases where id = p_case for update;
  if not found or not private.can_access_case(p_case) then
    raise exception 'case not found or not accessible';
  end if;
  update public.cases set status = p_status::public.case_status where id = p_case;
  if c.status::text is distinct from p_status then
    insert into public.audit_log (actor_id, action, entity, entity_id, detail)
    values (v_uid, 'CASE_STATUS_CHANGED', 'cases', p_case,
            jsonb_build_object('from', c.status, 'to', p_status,
                               'reason', nullif(btrim(coalesce(p_reason, '')), '')));
  end if;
end $function$
;

CREATE OR REPLACE FUNCTION public.case_stage_history(p_case uuid)
 RETURNS TABLE(changed_at timestamp with time zone, actor_id uuid, actor_name text, from_stage text, to_stage text, reason text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select a.created_at, a.actor_id, p.display_name,
         a.detail->>'from', a.detail->>'to', a.detail->>'reason'
    from public.audit_log a
    left join public.profiles p on p.id = a.actor_id
   where a.entity = 'cases'
     and a.entity_id = p_case
     and a.action = 'CASE_STAGE_CHANGED'
     and private.can_access_case(p_case)
   order by a.created_at desc
$function$
;

CREATE OR REPLACE FUNCTION public.case_timeline(p_case uuid)
 RETURNS TABLE(kind text, at timestamp with time zone, title text, actor uuid, ref_id uuid, meta jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_full boolean;
begin
  if not private.is_active() or not private.can_read_case(p_case) then
    raise exception 'not authorized';
  end if;
  v_full := private.can_access_case(p_case);

  return query
  with vis_media as (
    select m.* from public.media m
    where m.case_id = p_case
      and ((not m.restricted)
           or private.can_edit_narcotics_intel()
           or private.has_media_break_glass(m.case_id, v_uid))
      and not private.siu_blocked('gang',    m.gang_id,    'media')
      and not private.siu_blocked('person',  m.person_id,  'media')
      and not private.siu_blocked('place',   m.place_id,   'media')
      and not private.siu_blocked('vehicle', m.vehicle_id, 'media')
  )
  select * from (
    (select 'evidence'::text, coalesce(e.collected_at, e.created_at),
            nullif(e.item_code, ''), e.created_by, e.id,
            jsonb_build_object('description', e.description)
       from public.evidence e where e.case_id = p_case
      order by coalesce(e.collected_at, e.created_at) desc limit 400)
    union all
    (select 'media_added'::text, max(vm.created_at),
            case when count(*) = 1 then min(vm.title) end,
            vm.uploaded_by,
            (array_agg(vm.id order by vm.created_at desc))[1],
            jsonb_build_object('count', count(*),
                               'items', jsonb_agg(vm.title order by vm.created_at))
       from vis_media vm
      group by vm.uploaded_by, date_trunc('hour', vm.created_at)
      order by 2 desc limit 300)
    union all
    (select 'media_archived'::text, vm.archived_at, vm.title, null::uuid, vm.id, '{}'::jsonb
       from vis_media vm where vm.archived_at is not null
      order by vm.archived_at desc limit 300)
    union all
    (select 'media_featured'::text, vm.updated_at, vm.title, null::uuid, vm.id, '{}'::jsonb
       from vis_media vm where vm.featured
      order by vm.updated_at desc limit 300)
    union all
    (select 'report'::text, r.created_at, r.template, r.author_id, r.id,
            jsonb_build_object('finalized', r.finalized)
       from public.reports r where r.case_id = p_case
      order by r.created_at desc limit 400)
    union all
    (select 'task'::text, t.created_at, t.title, t.created_by, t.id,
            jsonb_build_object('done', t.done)
       from public.case_tasks t where t.case_id = p_case
      order by t.created_at desc limit 400)
    union all
    (select 'signoff'::text, s.created_at, s.action, s.actor_id, s.id,
            jsonb_build_object('actor_name', s.actor_name)
       from public.case_signoff_history s where s.case_id = p_case
      order by s.created_at desc limit 400)
    union all
    (select 'hold_placed'::text, h.placed_at, null::text, h.placed_by, h.id,
            jsonb_build_object('reason', h.reason)
       from public.legal_holds h
      where h.case_id = p_case and (v_full or private.is_command())
      order by h.placed_at desc limit 200)
    union all
    (select 'hold_lifted'::text, h.lifted_at, null::text, h.lifted_by, h.id,
            jsonb_build_object('lift_reason', h.lift_reason)
       from public.legal_holds h
      where h.case_id = p_case and h.lifted_at is not null
        and (v_full or private.is_command())
      order by h.lifted_at desc limit 200)
    union all
    (select 'restricted'::text, l.created_at, l.action, l.actor_id, l.entity_id,
            jsonb_build_object('entity_type', l.entity_type, 'reason', l.reason,
              'media_title', (select vm.title from vis_media vm where vm.id = l.entity_id))
       from public.restricted_access_log l
      where v_full
        and (l.entity_id = p_case
             or (l.entity_type = 'media' and exists (
                   select 1 from public.media m2
                   where m2.id = l.entity_id and m2.case_id = p_case)))
      order by l.created_at desc limit 300)
    union all
    (select 'op_link'::text, ol.added_at, null::text, ol.added_by, ol.operation_id,
            jsonb_build_object('was_jtf', ol.was_jtf, 'removed_at', ol.removed_at)
       from public.operation_case_links ol where ol.case_id = p_case
      order by ol.added_at desc limit 200)
    union all
    (select 'op_unlink'::text, ol.removed_at, null::text, ol.removed_by, ol.operation_id,
            jsonb_build_object('was_jtf', ol.was_jtf, 'removal_reason', ol.removal_reason)
       from public.operation_case_links ol
      where ol.case_id = p_case and ol.removed_at is not null
      order by ol.removed_at desc limit 200)
    union all
    (select 'surv_requested'::text, st.created_at, st.label, st.requested_by, st.id,
            jsonb_build_object('status', st.status)
       from public.surveillance_targets st
      where st.case_id = p_case and v_full
      order by st.created_at desc limit 200)
    union all
    (select 'surv_authorized'::text, st.approved_at, st.label, st.approved_by, st.id,
            '{}'::jsonb
       from public.surveillance_targets st
      where st.case_id = p_case and st.approved_at is not null and v_full
      order by st.approved_at desc limit 200)
    union all
    (select 'surv_ended'::text, st.ended_at, st.label, st.ended_by, st.id,
            jsonb_build_object('status', st.status)
       from public.surveillance_targets st
      where st.case_id = p_case and st.ended_at is not null and v_full
      order by st.ended_at desc limit 200)
    union all
    (select 'surv_observation'::text, so.created_at, null::text, so.created_by, so.id,
            jsonb_build_object('activity', so.activity)
       from public.surveillance_observations so
      where so.case_id = p_case and v_full
        and ((not so.restricted) or private.is_command()
             or coalesce((select p.is_owner from public.profiles p where p.id = v_uid), false)
             or so.created_by = v_uid or so.reviewed_by = v_uid)
      order by so.created_at desc limit 300)
    union all
    (select 'surv_verified'::text, so.reviewed_at, null::text, so.reviewed_by, so.id,
            jsonb_build_object('activity', so.activity)
       from public.surveillance_observations so
      where so.case_id = p_case and v_full
        and so.reviewed_at is not null and so.verification_status = 'verified'
        and ((not so.restricted) or private.is_command()
             or coalesce((select p.is_owner from public.profiles p where p.id = v_uid), false)
             or so.created_by = v_uid or so.reviewed_by = v_uid)
      order by so.reviewed_at desc limit 300)
    union all
    (select 'surv_alert'::text, sa.created_at, sa.title, null::uuid, sa.id, '{}'::jsonb
       from public.surveillance_alerts sa
      where sa.case_id = p_case and v_full
      order by sa.created_at desc limit 200)
  ) ev(kind, at, title, actor, ref_id, meta)
  order by ev.at desc
  limit 2000;
end $function$
;

CREATE OR REPLACE FUNCTION public.change_member_role(p_target uuid, p_new_role app_role, p_reason text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  me public.profiles;
  t public.profiles;
  v_old_role public.app_role;
begin
  select * into me from public.profiles where id = v_uid;
  if me.id is null or not (me.active and (me.role in ('bureau_lead','deputy_director','director') or me.is_owner)) then
    raise exception 'not authorized to change roles';
  end if;
  if p_target = v_uid then raise exception 'you cannot change your own role'; end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  if p_new_role is null
     or p_new_role not in ('detective','senior_detective','bureau_lead','deputy_director','director') then
    raise exception 'invalid role';
  end if;

  select * into t from public.profiles where id = p_target for update;
  if t.id is null then raise exception 'member not found'; end if;
  if t.removed_at is not null then raise exception 'member has been removed'; end if;
  if not t.active then raise exception 'member is not active — reactivate or re-approve first'; end if;
  if t.login_denied then raise exception 'member login is denied'; end if;
  if t.role = p_new_role then raise exception 'member already holds this role'; end if;
  if t.division not in ('major_crimes','street_crimes') then
    raise exception 'member has no permanent department yet';
  end if;
  if t.is_owner and not me.is_owner then
    raise exception 'only the owner may change an owner account';
  end if;
  if not (private.can_assign_cid_role(t.role, t.division)
          and private.can_assign_cid_role(p_new_role, t.division)) then
    raise exception 'you are not authorized to change % to % in %', t.role, p_new_role, private.bureau_label(t.division::text);
  end if;

  v_old_role := t.role;
  update public.profiles set role = p_new_role where id = p_target returning * into t;
  insert into public.role_events (target_id, actor_id, old_role, new_role,
    old_division, new_division, old_active, new_active, reason, source)
  values (p_target, v_uid, v_old_role, p_new_role,
    t.division, t.division, t.active, t.active, p_reason, 'role_change');
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'ROLE_CHANGED', 'profiles', p_target,
    jsonb_build_object('new_role', p_new_role, 'reason', p_reason));
  insert into public.notifications (user_id, type, payload)
  values (p_target, 'membership_update', jsonb_build_object(
    'status', 'role_changed',
    'reason', 'Your role is now ' || initcap(replace(p_new_role::text, '_', ' ')) || '. Reason: ' || p_reason,
    'actor_id', v_uid, 'actor_name', me.display_name));
  return t;
end $function$
;

CREATE OR REPLACE FUNCTION public.cid_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin new.updated_at = now(); return new; end $function$
;

CREATE OR REPLACE FUNCTION public.claim_legal_request_as_judge(p_request uuid)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_cap text;
begin
  -- `is distinct from` on purpose: a NULL justice role must fail this gate.
  if private.justice_role_effective(v_uid) is distinct from 'judge' then
    raise exception 'only an active Judge may claim a request';
  end if;
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'submitted_to_judge' then
    raise exception 'request is not awaiting judicial review';
  end if;
  if r.classification = 'sealed' then
    raise exception 'sealed requests require formal judicial assignment';
  end if;
  if r.assigned_judge_id is not null then
    raise exception 'request already has an assigned judge';
  end if;
  if private.legal_is_prosecution_side(p_request, v_uid) then
    raise exception 'conflict of role: you acted on the prosecution side of this request';
  end if;
  if r.created_by = v_uid then
    raise exception 'conflict of interest: you created this request';
  end if;
  if private.legal_is_conflicted(p_request, v_uid) then
    raise exception 'conflict of interest: you participated in this case as an investigator — recusal required';
  end if;
  v_cap := private.legal_capacity(v_uid, 'doj');
  update public.legal_requests
     set assigned_judge_id = v_uid, review_status = 'judicial_review',
         submitted_to_judge_at = coalesce(submitted_to_judge_at, now())
   where id = p_request returning * into r;
  perform private.legal_add_participant(p_request, v_uid, 'judicial_reviewer');
  perform private.legal_log(p_request, r.current_version_id, 'judge_claimed',
    'submitted_to_judge', 'judicial_review', null, 'capacity: ' || v_cap);
  perform private.legal_audit(p_request, 'LEGAL_JUDGE_CLAIMED', jsonb_build_object('capacity', v_cap));
  perform private.legal_notify(r.created_by, p_request, 'legal_update',
    'A judge took your ' || r.request_type || ' request into judicial review.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.close_legal_request(p_request uuid, p_outcome text DEFAULT 'closed'::text, p_note text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.fulfilment_status = 'closed' then raise exception 'request is already closed'; end if;
  if p_outcome not in ('closed', 'expired', 'revoked') then raise exception 'invalid outcome'; end if;

  if p_outcome = 'revoked' then
    if not (coalesce(v_uid = r.assigned_judge_id, false)
            and coalesce(private.justice_role_of(v_uid) = 'judge', false))
       and not private.can_manage_legal_assignment(p_request, v_uid) then
      raise exception 'only the assigned Judge, DOJ management, or the Owner may revoke';
    end if;
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a revocation reason is required'; end if;
    update public.legal_requests
       set fulfilment_status = 'revoked', revoked_at = now(), revoked_by = v_uid,
           revoke_reason = p_note
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'revoked', null, 'revoked', p_note, null);
    perform private.legal_audit(p_request, 'LEGAL_REVOKED', jsonb_build_object('reason', left(p_note, 200)));
    perform private.mdt_project(p_request, 'revoked');
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' was revoked.');
    return r;
  end if;

  if p_outcome = 'expired' then
    if not (private.can_fulfil_legal(p_request, v_uid)
            or private.can_manage_legal_assignment(p_request, v_uid)) then
      raise exception 'not authorized';
    end if;
    if r.expires_at is null or r.expires_at > now() then
      raise exception 'this request has not reached its expiration';
    end if;
    update public.legal_requests set fulfilment_status = 'expired'
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'expired', null, 'expired', null, null);
    perform private.legal_audit(p_request, 'LEGAL_EXPIRED', null);
    perform private.mdt_project(p_request, 'expired');
    return r;
  end if;

  -- closed
  if not (private.can_fulfil_legal(p_request, v_uid)
          or private.can_manage_legal_assignment(p_request, v_uid)) then
    raise exception 'not authorized';
  end if;
  if r.review_status not in ('approved', 'denied', 'withdrawn') then
    raise exception 'only decided or withdrawn requests can be closed';
  end if;
  update public.legal_requests
     set fulfilment_status = 'closed', closed_at = now(), closed_by = v_uid,
         close_note = nullif(btrim(coalesce(p_note, '')), '')
   where id = p_request returning * into r;
  perform private.legal_log(p_request, r.current_version_id, 'closed', null, 'closed', p_note, null);
  perform private.legal_audit(p_request, 'LEGAL_CLOSED', null);
  if r.request_type = 'warrant' and exists (
      select 1 from public.mdt_wanted_projections m
      where m.legal_request_id = p_request and m.wanted_status = 'wanted') then
    perform private.mdt_project(p_request, 'cleared');
  end if;
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.close_reading_campaign(p_campaign uuid, p_reason text DEFAULT NULL::text)
 RETURNS document_reading_campaigns
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.document_reading_campaigns; v_uid uuid := (select auth.uid());
begin
  if not private.can_manage_required_reading() then raise exception 'not authorized'; end if;
  select * into c from public.document_reading_campaigns where id = p_campaign for update;
  if not found then raise exception 'campaign not found'; end if;
  if c.status <> 'active' then return c; end if;
  update public.document_reading_campaigns set status = 'closed'
   where id = c.id returning * into c;
  if not exists (select 1 from public.document_reading_campaigns x
                  where x.document_id = c.document_id and x.status = 'active') then
    update public.documents
       set acknowledgement_required = false, acknowledgement_deadline = null
     where id = c.document_id;
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_CAMPAIGN_CLOSED', 'document_reading_campaigns', c.id,
          jsonb_build_object('document_id', c.document_id, 'reason', p_reason));
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.comment_on_document_suggestion(p_suggestion uuid, p_body text)
 RETURNS document_suggestion_comments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.document_suggestions; d public.documents; c public.document_suggestion_comments;
        v_uid uuid := (select auth.uid()); v_is_mgr boolean := false;
begin
  if btrim(coalesce(p_body, '')) = '' then raise exception 'a message is required'; end if;
  select * into s from public.document_suggestions where id = p_suggestion;
  if not found then raise exception 'suggestion not found'; end if;

  if s.document_id is not null then
    select * into d from public.documents where id = s.document_id;
    v_is_mgr := private.can_manage_document_suggestions(d.classification, d.owner_user_id, d.folder, d.bureau);
  else
    v_is_mgr := private.is_owner() or coalesce((select active and role in ('deputy_director','director')
                 from public.profiles where id = v_uid), false);
  end if;
  if not (s.created_by = v_uid or v_is_mgr) then raise exception 'not authorized'; end if;

  insert into public.document_suggestion_comments (suggestion_id, body, author_id)
  values (s.id, btrim(p_body), v_uid) returning * into c;

  insert into public.document_suggestion_events (suggestion_id, event_type, note, actor_id)
  values (s.id, 'comment', left(btrim(p_body), 280), v_uid);

  if v_uid = s.created_by then
    if s.document_id is not null then
      insert into public.notifications (user_id, type, payload)
      select m.user_id, 'document_suggestion', jsonb_build_object(
          'suggestion_id', s.id, 'document_id', s.document_id, 'title', s.title,
          'status', s.status, 'actor_id', v_uid,
          'reason', 'New reply on suggestion: ' || s.title)
        from private.document_suggestion_managers(s.document_id) m
       where m.user_id <> v_uid;
    end if;
  else
    if s.created_by <> v_uid then
      insert into public.notifications (user_id, type, payload)
      values (s.created_by, 'document_suggestion', jsonb_build_object(
          'suggestion_id', s.id, 'document_id', s.document_id, 'title', s.title,
          'status', s.status, 'actor_id', v_uid,
          'reason', 'New reply on your suggestion: ' || s.title));
    end if;
  end if;
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.complete_transfer(p_id uuid)
 RETURNS transfer_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles; r public.transfer_requests; v_override boolean;
begin
  select * into me from public.profiles where id = (select auth.uid());
  if me.id is null or not (me.active and (me.role in ('deputy_director','director') or me.is_owner)) then
    raise exception 'only Deputy Director or higher may complete a transfer directly';
  end if;
  select * into r from public.transfer_requests where id = p_id for update;
  if r.id is null then raise exception 'transfer not found'; end if;
  if r.status not in ('pending_source', 'pending_target', 'approved') then
    raise exception 'transfer is not open';
  end if;
  if r.target_id = me.id then raise exception 'you cannot complete your own transfer'; end if;
  v_override := r.status <> 'approved';
  return private.transfer_apply(p_id, me, v_override);
end $function$
;

CREATE OR REPLACE FUNCTION public.confirm_narcotic_sale_observation(p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.can_edit_narcotics_intel() then
    raise exception 'not authorized to confirm sale observations' using errcode = '42501';
  end if;
  update public.narcotic_sale_observations
     set state = 'confirmed',
         notes = case when p_reason is null or btrim(p_reason) = '' then notes
                      else coalesce(notes || E'\n', '') || 'Confirmed: ' || btrim(p_reason) end
   where id = p_id and state <> 'confirmed';
  if not found then
    if not exists (select 1 from public.narcotic_sale_observations where id = p_id) then
      raise exception 'observation not found' using errcode = 'P0002';
    end if;
  end if;
end $function$
;

CREATE OR REPLACE FUNCTION public.convert_case_to_joint(p_case uuid, p_members jsonb, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); c public.cases; v_n int;
begin
  if not private.can_manage_joint(p_case) then raise exception 'not permitted to manage this case'; end if;
  select * into c from public.cases where id = p_case for update;
  if not found then raise exception 'case not found'; end if;
  if c.is_joint_case then raise exception 'case is already a joint case'; end if;
  update public.cases
     set is_joint_case = true,
         originating_bureau = coalesce(originating_bureau,
           case when bureau in ('major_crimes', 'street_crimes') then bureau end),
         joint_case_created_by = v_uid, joint_case_created_at = now(),
         joint_case_ended_by = null, joint_case_ended_at = null
   where id = p_case;
  v_n := private.joint_apply_members(p_case, p_members, v_uid);
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, 'JOINT_CASE_CREATED', 'cases', p_case);
  return jsonb_build_object('case_id', p_case, 'members_added', v_n);
end $function$
;

CREATE OR REPLACE FUNCTION public.correct_membership_organization(p_target uuid, p_direction text, p_reason text, p_requested_justice_role text DEFAULT NULL::text, p_requested_bureau bureau DEFAULT NULL::bureau, p_requested_role app_role DEFAULT NULL::app_role)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  me public.profiles;
  t public.profiles;
  v_role text;
  v_agency text;
  v_req uuid;
  v_existing record;
  n_lead int; n_assign int; n_tasks int; n_transfers int; n_legal int; n_cov int;
begin
  select * into me from public.profiles where id = v_uid;
  if not private.is_owner() then
    raise exception 'organization correction is restricted to the owner';
  end if;
  if p_target = v_uid then raise exception 'you cannot correct your own membership'; end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  if p_direction not in ('cid_to_doj', 'cid_to_judiciary', 'justice_to_cid') then
    raise exception 'invalid direction';
  end if;

  select * into t from public.profiles where id = p_target for update;
  if t.id is null then raise exception 'member not found'; end if;
  if t.removed_at is not null then raise exception 'member has been removed — restore them first'; end if;
  if t.login_denied then raise exception 'member login is denied — restore login first'; end if;
  if t.is_test then raise exception 'test fixtures cannot be moved between organizations'; end if;

  if p_direction in ('cid_to_doj', 'cid_to_judiciary') then
    v_agency := case when p_direction = 'cid_to_doj' then 'doj' else 'judiciary' end;
    v_role := case when p_direction = 'cid_to_judiciary' then 'judge' else p_requested_justice_role end;
    if v_role is null
       or (v_agency = 'doj' and v_role not in ('assistant_district_attorney', 'district_attorney', 'attorney_general'))
       or (v_agency = 'judiciary' and v_role <> 'judge') then
      raise exception 'invalid justice role for %', v_agency;
    end if;
    if not t.active then raise exception 'target is not an active CID member'; end if;
    if exists (select 1 from public.justice_memberships m where m.user_id = p_target and m.active) then
      raise exception 'member already holds an active justice membership';
    end if;

    select count(*) into n_lead from public.cases c
     where c.lead_detective_id = p_target and c.status <> 'closed';
    select count(*) into n_assign from public.case_assignments a
     where a.officer_id = p_target and (a.expires_at is null or a.expires_at > now());
    select count(*) into n_tasks from public.case_tasks k
     where k.assignee = p_target and not k.done;
    select count(*) into n_transfers from public.transfer_requests r
     where r.target_id = p_target and r.status in ('pending_source', 'pending_target', 'approved');
    if n_lead + n_assign + n_tasks + n_transfers > 0 then
      raise exception 'unresolved active assignments block this correction (% lead cases, % case assignments, % open tasks, % open transfers) — reassign them first',
        n_lead, n_assign, n_tasks, n_transfers;
    end if;

    update public.profiles set active = false where id = p_target;
    insert into public.role_events (target_id, actor_id, old_role, new_role,
      old_division, new_division, old_active, new_active, reason, source)
    values (p_target, v_uid, t.role, t.role, t.division, t.division, true, false,
      p_reason, 'activation');

    select id, status into v_existing from public.justice_membership_requests
     where applicant_id = p_target for update;
    if v_existing.id is not null and v_existing.status in ('draft', 'pending', 'correction_requested') then
      raise exception 'member already has an open justice membership request';
    end if;
    if v_existing.id is not null then
      update public.justice_membership_requests
         set requested_agency = v_agency, requested_justice_role = v_role,
             display_name = coalesce(t.display_name, 'Officer'),
             reason = p_reason, additional_notes = 'Organization correction initiated by the owner.',
             status = 'pending', submitted_at = now(),
             decided_agency = null, decided_justice_role = null,
             applicant_visible_decision_note = null, decided_by = null, decided_at = null
       where id = v_existing.id returning id into v_req;
      perform private.jmr_history(v_req, 'submitted', v_existing.status, 'pending',
        'Organization correction: ' || p_reason, false);
    else
      insert into public.justice_membership_requests
        (applicant_id, display_name, requested_agency, requested_justice_role,
         reason, additional_notes, status, submitted_at)
      values (p_target, coalesce(t.display_name, 'Officer'), v_agency, v_role,
        p_reason, 'Organization correction initiated by the owner.', 'pending', now())
      returning id into v_req;
      perform private.jmr_history(v_req, 'submitted', 'draft', 'pending',
        'Organization correction: ' || p_reason, false);
    end if;

  else  -- justice_to_cid
    if p_requested_bureau is null or p_requested_bureau not in ('major_crimes', 'street_crimes') then
      raise exception 'a permanent CID department (Major Crimes or Street Crimes) is required';
    end if;
    if p_requested_role is null
       or p_requested_role not in ('detective','senior_detective','bureau_lead','deputy_director','director') then
      raise exception 'invalid CID role';
    end if;
    if not exists (select 1 from public.justice_memberships m where m.user_id = p_target and m.active) then
      raise exception 'target has no active justice membership';
    end if;

    select count(*) into n_legal from public.legal_requests l
     where (l.assigned_ada_id = p_target or l.assigned_judge_id = p_target)
       and l.review_status not in ('denied', 'withdrawn', 'closed');
    select count(*) into n_cov from public.prosecutor_bureau_assignments a
     where a.prosecutor_id = p_target and (a.ends_at is null or a.ends_at > now());
    if n_legal + n_cov > 0 then
      raise exception 'unresolved justice work blocks this correction (% assigned legal requests, % bureau coverage assignments) — reassign them first',
        n_legal, n_cov;
    end if;

    update public.justice_memberships set active = false where user_id = p_target;

    select id, status into v_existing from public.membership_requests
     where applicant_id = p_target for update;
    if v_existing.id is not null and v_existing.status in ('draft', 'pending', 'correction_requested') then
      raise exception 'member already has an open CID membership request';
    end if;
    if v_existing.id is not null then
      update public.membership_requests
         set requested_bureau = p_requested_bureau, requested_role = p_requested_role,
             display_name = coalesce(t.display_name, 'Officer'),
             reason = p_reason, additional_notes = 'Organization correction initiated by the owner.',
             status = 'pending', submitted_at = now(),
             decided_bureau = null, decided_role = null,
             applicant_visible_decision_note = null, decided_by = null, decided_at = null
       where id = v_existing.id returning id into v_req;
      perform private.mr_history(v_req, 'submitted', v_existing.status, 'pending',
        'Organization correction: ' || p_reason, false);
    else
      insert into public.membership_requests
        (applicant_id, display_name, requested_bureau, requested_role,
         reason, additional_notes, status, submitted_at)
      values (p_target, coalesce(t.display_name, 'Officer'), p_requested_bureau, p_requested_role,
        p_reason, 'Organization correction initiated by the owner.', 'pending', now())
      returning id into v_req;
      perform private.mr_history(v_req, 'submitted', 'draft', 'pending',
        'Organization correction: ' || p_reason, false);
    end if;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'ORG_CORRECTION_INITIATED', 'profiles', p_target,
    jsonb_build_object('direction', p_direction, 'reason', p_reason,
      'request_id', v_req,
      'requested_justice_role', case when p_direction <> 'justice_to_cid' then v_role end,
      'requested_bureau', case when p_direction = 'justice_to_cid' then p_requested_bureau::text end,
      'requested_role', case when p_direction = 'justice_to_cid' then p_requested_role::text end));
  insert into public.notifications (user_id, type, payload)
  values (p_target, 'membership_update', jsonb_build_object(
    'status', 'org_correction', 'request_id', v_req,
    'reason', case when p_direction = 'justice_to_cid'
      then 'Your account is being moved to CID — a membership request is awaiting Command approval. Reason: ' || p_reason
      else 'Your account is being moved to ' || case when p_direction = 'cid_to_doj' then 'the DOJ' else 'the Judiciary' end
        || ' — a membership request is awaiting approval. Reason: ' || p_reason end,
    'actor_id', v_uid, 'actor_name', me.display_name));

  return jsonb_build_object('request_id', v_req, 'direction', p_direction);
end $function$
;

CREATE OR REPLACE FUNCTION public.create_legal_request(p_case uuid, p_request_type text, p_subtype text, p_title text, p_priority text DEFAULT NULL::text, p_form jsonb DEFAULT '{}'::jsonb, p_narrative text DEFAULT NULL::text, p_person uuid DEFAULT NULL::uuid, p_recipient_type text DEFAULT NULL::text, p_recipient_name text DEFAULT NULL::text, p_source_report uuid DEFAULT NULL::uuid, p_classification text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; c public.cases;
        v_person public.persons; v_report public.reports; v_bureau public.bureau;
begin
  if not private.is_active() then raise exception 'not an active CID member'; end if;
  select * into c from public.cases where id = p_case;
  if not found or not private.can_access_case(p_case) then
    raise exception 'case not found or not accessible';
  end if;
  if p_request_type not in ('warrant', 'subpoena') then raise exception 'invalid request type'; end if;
  if p_request_type = 'warrant' and p_subtype not in ('arrest_warrant', 'search_warrant') then
    raise exception 'unsupported warrant subtype';
  end if;
  if btrim(coalesce(p_title, '')) = '' then raise exception 'a title is required'; end if;
  v_bureau := private.legal_resolve_bureau(p_case);

  if p_person is not null then
    select * into v_person from public.persons where id = p_person;
    if not found then raise exception 'person not found'; end if;
  end if;
  if p_request_type = 'warrant' then
    if p_subtype = 'arrest_warrant' and p_person is null then
      raise exception 'an arrest warrant requires a suspect from the Persons registry';
    end if;
    if p_subtype = 'search_warrant'
       and p_person is null
       and nullif(btrim(coalesce(p_form->>'search_targets', '')), '') is null then
      raise exception 'a search warrant requires a subject or at least one search target';
    end if;
  end if;
  if p_request_type = 'subpoena' then
    if p_recipient_type not in ('player', 'entity') then raise exception 'invalid recipient type'; end if;
    if p_recipient_type = 'player' and p_person is null then
      raise exception 'a player subpoena requires a Persons-registry recipient';
    end if;
    if p_recipient_type = 'entity' and btrim(coalesce(p_recipient_name, '')) = '' then
      raise exception 'an entity subpoena requires a recipient name';
    end if;
  end if;
  if p_source_report is not null then
    select * into v_report from public.reports where id = p_source_report;
    if not found or v_report.case_id <> p_case then
      raise exception 'source report must belong to the same case';
    end if;
  end if;
  if p_classification is not null
     and p_classification not in ('standard', 'restricted', 'classified', 'sealed') then
    raise exception 'invalid classification';
  end if;

  insert into public.legal_requests
    (request_type, subtype, case_id, source_report_id, source_report_seq, created_by,
     responsible_bureau, classification, priority, title, form_data, narrative,
     person_id, person_name_snapshot, recipient_type, recipient_name,
     case_number_snapshot, case_title_snapshot, approval_route)
  values
    (p_request_type, p_subtype, p_case, p_source_report, v_report.seq, v_uid,
     v_bureau,
     coalesce(p_classification, private.legal_default_classification(p_request_type, p_subtype)),
     p_priority, btrim(p_title), coalesce(p_form, '{}'::jsonb), p_narrative,
     p_person, v_person.name, p_recipient_type,
     nullif(btrim(coalesce(p_recipient_name, '')), ''),
     c.case_number, c.title,
     private.legal_default_route(p_request_type, p_subtype))
  returning * into r;

  perform private.legal_add_participant(r.id, v_uid, 'requesting_investigator');
  perform private.legal_log(r.id, null, 'created', null, 'not_submitted', null, null);
  perform private.legal_audit(r.id, 'LEGAL_CREATED', jsonb_build_object(
    'type', p_request_type, 'subtype', p_subtype, 'case_id', p_case, 'bureau', v_bureau));
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.create_notification(p_user_id uuid, p_type text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_case uuid := nullif(p_payload->>'case_id', '')::uuid;
  v_payload jsonb;
begin
  if v_actor is null or not private.is_active() then
    raise exception 'not authorized';
  end if;
  if p_user_id is null then return; end if;

  -- Only the types the client legitimately emits (src/lib/notify.ts callers);
  -- every server-owned type is inserted directly by its own definer RPC.
  if p_type not in (
    'member_approved', 'access_requested', 'stale_case',
    'task_assigned', 'chat_mention', 'case_handover',
    'tracker_authorized', 'tracker_pending',
    'access_granted', 'access_denied'
  ) then
    raise exception 'unsupported notification type';
  end if;

  if p_type = 'member_approved' then
    if not private.is_command() then raise exception 'not authorized'; end if;
  elsif p_type = 'access_requested' then
    if v_case is null or not exists (
      select 1 from public.case_access_requests r
      where r.case_id = v_case and r.requester_id = v_actor and r.status = 'pending'
    ) then raise exception 'not authorized'; end if;
  elsif p_type in ('access_granted', 'access_denied') then
    -- Decision notices: only someone who can decide the underlying request
    -- (car_upd / cag_ins authority) may tell the requester the outcome.
    if v_case is null or not private.can_grant_case(v_case) then
      raise exception 'not authorized';
    end if;
  elsif p_type in ('stale_case', 'task_assigned', 'chat_mention', 'case_handover') then
    if v_case is null or not private.can_access_case(v_case) then
      raise exception 'not authorized';
    end if;
  elsif p_type = 'tracker_authorized' then
    if p_user_id <> v_actor and not private.is_command() then raise exception 'not authorized'; end if;
  elsif p_type = 'tracker_pending' then
    if p_user_id <> v_actor then raise exception 'not authorized'; end if;
  end if;

  v_payload :=
    (coalesce(p_payload, '{}'::jsonb)
      || case when p_payload ? 'reason' then jsonb_build_object('reason', left(p_payload->>'reason', 500)) else '{}'::jsonb end
      || case when p_payload ? 'title'  then jsonb_build_object('title',  left(p_payload->>'title', 300))  else '{}'::jsonb end)
      || jsonb_build_object(
        'actor_id', v_actor,
        'actor_name', (select display_name from public.profiles where id = v_actor)
      );

  -- Dedupe guard: an identical UNREAD notification in the last hour (same
  -- recipient, same type, same payload identity — volatile actor stamps
  -- excluded) suppresses this one. Read notifications never suppress, so a
  -- re-ping after the user handled the first still lands.
  if exists (
    select 1 from public.notifications n
    where n.user_id = p_user_id
      and n.type = p_type
      and n.read = false
      and n.created_at > now() - interval '1 hour'
      and n.payload->>'case_id'    is not distinct from v_payload->>'case_id'
      and n.payload->>'request_id' is not distinct from v_payload->>'request_id'
      and n.payload->>'task_id'    is not distinct from v_payload->>'task_id'
      and n.payload->>'reason'     is not distinct from v_payload->>'reason'
      and n.payload->>'title'      is not distinct from v_payload->>'title'
      and n.payload->>'target'     is not distinct from v_payload->>'target'
  ) then
    return;
  end if;

  insert into public.notifications (user_id, type, payload)
  values (p_user_id, p_type, v_payload);
end $function$
;

CREATE OR REPLACE FUNCTION public.decide_document_suggestion(p_suggestion uuid, p_status text, p_note text DEFAULT NULL::text, p_assigned_editor uuid DEFAULT NULL::uuid)
 RETURNS document_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.document_suggestions; d public.documents; v_uid uuid := (select auth.uid()); v_from text;
begin
  select * into s from public.document_suggestions where id = p_suggestion for update;
  if not found then raise exception 'suggestion not found'; end if;
  if p_status not in ('under_review','accepted','partially_accepted','declined','needs_more_information') then
    raise exception 'invalid decision status';
  end if;

  if s.document_id is not null then
    select * into d from public.documents where id = s.document_id;
    if not private.can_manage_document_suggestions(d.classification, d.owner_user_id, d.folder, d.bureau) then
      raise exception 'not authorized';
    end if;
  else
    if not (private.is_owner() or coalesce((select active and role in ('deputy_director','director')
             from public.profiles where id = v_uid), false)) then
      raise exception 'not authorized';
    end if;
  end if;

  if p_status in ('declined','needs_more_information')
     and btrim(coalesce(p_note, '')) = '' then
    raise exception 'a note is required for this decision';
  end if;

  v_from := s.status;
  update public.document_suggestions
     set status = p_status,
         decided_by = v_uid, decided_at = now(),
         decision_note = coalesce(nullif(btrim(p_note), ''), decision_note),
         assigned_editor = case when p_status in ('accepted','partially_accepted')
                                then coalesce(p_assigned_editor, assigned_editor)
                                else assigned_editor end
   where id = s.id returning * into s;

  insert into public.document_suggestion_events
    (suggestion_id, event_type, from_status, to_status, note, actor_id)
  values (s.id, 'decision', v_from, p_status, nullif(btrim(p_note), ''), v_uid);

  if s.created_by <> v_uid then
    insert into public.notifications (user_id, type, payload)
    values (s.created_by, 'document_suggestion', jsonb_build_object(
        'suggestion_id', s.id, 'document_id', s.document_id, 'title', s.title,
        'status', p_status, 'actor_id', v_uid,
        'reason', 'Your suggestion was updated: ' || s.title));
  end if;
  if s.assigned_editor is not null and s.assigned_editor <> v_uid
     and p_status in ('accepted','partially_accepted') then
    insert into public.notifications (user_id, type, payload)
    values (s.assigned_editor, 'document_suggestion', jsonb_build_object(
        'suggestion_id', s.id, 'document_id', s.document_id, 'title', s.title,
        'status', p_status, 'actor_id', v_uid,
        'reason', 'You were assigned to implement: ' || s.title));
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_SUGGESTION_DECIDED', 'document_suggestions', s.id,
          jsonb_build_object('from', v_from, 'to', p_status));
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.decide_legal_request_as_judge(p_request uuid, p_decision text, p_note text DEFAULT NULL::text, p_conditions text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_signature text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_ver uuid; v_cap text;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'judicial_review' then
    raise exception 'request is not under judicial review';
  end if;
  if r.assigned_judge_id is distinct from v_uid then
    raise exception 'only the assigned judge may decide this request';
  end if;
  if private.legal_is_prosecution_side(p_request, v_uid) then
    raise exception 'conflict of role: you acted on the prosecution side of this request';
  end if;
  if p_decision not in ('approve', 'deny', 'return') then raise exception 'invalid decision'; end if;
  v_cap := private.legal_capacity(v_uid, 'doj');

  if p_decision = 'return' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a return requires reasoning'; end if;
    perform private.legal_end_participant(p_request, v_uid, 'judicial_reviewer');
    update public.legal_requests
       set review_status = 'returned_by_judge', document_status = 'reopened',
           assigned_judge_id = null
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'returned_by_judge',
      'judicial_review', 'returned_by_judge', p_note, 'capacity: ' || v_cap);
    perform private.legal_audit(p_request, 'LEGAL_RETURNED_BY_JUDGE',
      jsonb_build_object('note', left(p_note, 200), 'capacity', v_cap));
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' request was returned by the judge.');
    return r;
  end if;

  if btrim(coalesce(p_note, '')) = '' then
    raise exception 'a judicial decision requires recorded reasoning';
  end if;
  update public.legal_requests
     set review_status = case p_decision when 'approve' then 'approved' else 'denied' end,
         decision = case p_decision when 'approve' then 'approved' else 'denied' end,
         decision_note = p_note,
         judicial_conditions = nullif(btrim(coalesce(p_conditions, '')), ''),
         expires_at = coalesce(p_expires_at, expires_at),
         decided_by = v_uid, decided_at = now()
   where id = p_request returning * into r;
  v_ver := private.legal_freeze_version(p_request, case p_decision when 'approve' then 'judicial_approval' else 'denied' end);
  select * into r from public.legal_requests where id = p_request;
  perform private.legal_sign(p_request, v_ver, 'judge_decision', p_signature);
  perform private.legal_log(p_request, v_ver, r.review_status,
    'judicial_review', r.review_status, p_note, 'capacity: ' || v_cap);
  perform private.legal_audit(p_request, 'LEGAL_JUDGE_DECISION',
    jsonb_build_object('version', v_ver, 'decision', p_decision,
                       'conditions', r.judicial_conditions is not null, 'capacity', v_cap));
  perform private.legal_notify(r.created_by, p_request, 'legal_decision',
    'Your ' || r.request_type || ' request was ' ||
    case p_decision when 'approve' then 'approved by the judge and is ready to issue.'
                    else 'denied by the judge.' end);
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.decide_narcotic_suggestion(p_suggestion uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS narcotic_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s public.narcotic_suggestions;
  v_uid uuid := (select auth.uid());
  v_from text;
begin
  if not private.can_manage_narcotics() then
    raise exception 'deciding narcotics suggestions is restricted to Bureau Lead or higher';
  end if;
  select * into s from public.narcotic_suggestions where id = p_suggestion for update;
  if not found then raise exception 'suggestion not found'; end if;
  if p_status not in ('under_review','accepted','declined','needs_more_information','duplicate') then
    raise exception 'invalid decision status';
  end if;
  if p_status in ('declined', 'needs_more_information')
     and btrim(coalesce(p_note, '')) = '' then
    raise exception 'a note is required for this decision';
  end if;

  v_from := s.status;
  update public.narcotic_suggestions
     set status = p_status,
         decided_by = v_uid, decided_at = now(),
         decision_note = coalesce(nullif(btrim(p_note), ''), decision_note)
   where id = s.id returning * into s;

  insert into public.narcotic_suggestion_events
    (suggestion_id, event_type, from_status, to_status, note, actor_id)
  values (s.id, 'decision', v_from, p_status, nullif(btrim(coalesce(p_note, '')), ''), v_uid);

  -- Notify the submitter (they can always see their own suggestion).
  if s.created_by <> v_uid then
    insert into public.notifications (user_id, type, payload)
    values (s.created_by, 'narcotic_suggestion', jsonb_build_object(
        'suggestion_id', s.id, 'narcotic_id', s.narcotic_id, 'title', s.title,
        'status', p_status, 'actor_id', v_uid,
        'reason', 'Your narcotics suggestion was updated: ' || s.title));
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'NARCOTIC_SUGGESTION_DECIDED', 'narcotic_suggestions', s.id,
          jsonb_build_object('from', v_from, 'to', p_status));
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.deny_member_login(p_target uuid, p_reason text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles; t public.profiles;
begin
  select * into me from public.profiles where id = (select auth.uid());
  if me.id is null or not me.active or not (me.role in ('bureau_lead', 'deputy_director', 'director') or me.is_owner) then
    raise exception 'not authorized to deny login';
  end if;
  if p_target = me.id then raise exception 'you cannot deny your own login'; end if;
  select * into t from public.profiles where id = p_target for update;
  if t.id is null then raise exception 'member not found'; end if;
  if me.role = 'bureau_lead' and not me.is_owner then
    if t.division <> me.division then raise exception 'bureau leads may only deny members in their own bureau'; end if;
    if t.role in ('bureau_lead', 'deputy_director', 'director') then raise exception 'bureau leads may not deny a command member'; end if;
  end if;
  if t.is_owner then raise exception 'the owner account cannot be denied'; end if;
  update public.profiles
     set login_denied = true, login_denied_at = now(), login_denied_by = me.id,
         login_denied_reason = nullif(btrim(coalesce(p_reason, '')), ''),
         active = false
   where id = p_target returning * into t;
  insert into public.role_events (target_id, actor_id, old_role, new_role, old_division, new_division, old_active, new_active)
  values (p_target, me.id, t.role, t.role, t.division, t.division, true, false);
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (me.id, 'LOGIN_DENIED', 'profiles', p_target);
  insert into public.notifications (user_id, type, payload)
  values (p_target, 'login_denied', jsonb_build_object(
    'reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Your portal access has been denied.'),
    'actor_id', me.id, 'actor_name', me.display_name));
  return t;
end $function$
;

CREATE OR REPLACE FUNCTION public.document_ack_summary(p_document uuid)
 RETURNS TABLE(user_id uuid, display_name text, acknowledged_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.document_reading_campaigns;
begin
  if not private.can_manage_required_reading() then raise exception 'not authorized'; end if;
  select * into c from public.document_reading_campaigns
   where document_id = p_document and status = 'active'
   order by created_at desc limit 1;
  if not found then return; end if;
  return query
    select r.user_id, p.display_name, a.acknowledged_at
      from private.document_campaign_recipients(p_document, c.audience, c.targets, c.created_by) r
      join public.profiles p on p.id = r.user_id
      left join public.document_acknowledgements a
        on a.document_id = p_document and a.user_id = r.user_id
       and a.document_version_id = c.document_version_id
     order by a.acknowledged_at nulls first, p.display_name;
end $function$
;

CREATE OR REPLACE FUNCTION public.document_record_review(p_document uuid, p_outcome text, p_note text DEFAULT NULL::text, p_next_due timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.documents; v_uid uuid := (select auth.uid());
begin
  select * into d from public.documents where id = p_document for update;
  if not found then raise exception 'document not found'; end if;
  if not (private.can_approve_document(d.category, d.classification)
          or (d.owner_user_id = v_uid and private.is_active())) then
    raise exception 'not authorized to record a review for this document';
  end if;
  if p_outcome not in ('no_change', 'editorial_update', 'material_update',
                       'legal_review', 'supersede', 'archive') then
    raise exception 'invalid review outcome';
  end if;
  update public.documents
     set reviewed_at = now(), reviewed_by = v_uid,
         review_outcome = p_outcome, review_note = p_note,
         review_due_at = p_next_due
   where id = d.id returning * into d;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_REVIEWED', 'documents', d.id,
          jsonb_build_object('outcome', p_outcome, 'note', p_note, 'next_due', p_next_due));
  return d;
end $function$
;

CREATE OR REPLACE FUNCTION public.document_restore_version(p_document uuid, p_version uuid, p_reason text)
 RETURNS documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.documents; v public.documents_versions;
  v_uid uuid := (select auth.uid()); v_next int;
begin
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a restore reason is required'; end if;
  select * into d from public.documents where id = p_document for update;
  if not found then raise exception 'document not found'; end if;
  if not private.can_edit_document_for_bureau(d.classification, d.owner_user_id, d.folder, d.bureau) then
    raise exception 'not authorized to edit this document';
  end if;
  if d.status = 'published' and d.approval_required
     and not private.can_approve_document(d.category, d.classification) then
    raise exception 'restoring a published, approval-gated document requires approval authority';
  end if;
  select * into v from public.documents_versions
   where id = p_version and document_id = p_document;
  if not found then raise exception 'version not found'; end if;

  v_next := d.current_version_number + 1;
  update public.documents
     set name = coalesce(v.name, d.name),
         content = coalesce(d.content, '{}'::jsonb)
                   || jsonb_build_object('body', coalesce(v.content ->> 'body', '')),
         modified_label = to_char(now(), 'DD/MM/YYYY'),
         current_version_number = v_next,
         sync_status = case when d.canonical_source = 'google_drive'
                            then 'portal_newer' else d.sync_status end
   where id = d.id returning * into d;
  insert into public.documents_versions
    (document_id, name, kind, content, modified_label, saved_by,
     version_number, change_type, change_summary, restored_from,
     source_system, metadata)
  values (d.id, d.name, d.kind, d.content, d.modified_label, v_uid,
          v_next, 'restore', p_reason, v.id, 'portal',
          jsonb_build_object('status', d.status, 'restored_version_number', v.version_number));
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_RESTORED', 'documents', d.id,
          jsonb_build_object('reason', p_reason, 'from_version', v.version_number,
                             'new_version', v_next));
  return d;
end $function$
;

CREATE OR REPLACE FUNCTION public.document_save(p_document uuid, p_name text, p_body text, p_change_type text DEFAULT 'editorial'::text, p_change_summary text DEFAULT NULL::text, p_requires_reack boolean DEFAULT false)
 RETURNS documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.documents; v_uid uuid := (select auth.uid()); v_next int;
begin
  select * into d from public.documents where id = p_document for update;
  if not found then raise exception 'document not found'; end if;
  if not private.can_edit_document_for_bureau(d.classification, d.owner_user_id, d.folder, d.bureau) then
    raise exception 'not authorized to edit this document';
  end if;
  if p_change_type not in ('editorial', 'clarification', 'procedural', 'legal',
                           'emergency', 'deprecation') then
    raise exception 'invalid change type';
  end if;
  if p_change_type not in ('editorial', 'clarification')
     and btrim(coalesce(p_change_summary, '')) = '' then
    raise exception 'a change summary is required for material changes';
  end if;
  if btrim(coalesce(p_name, '')) = '' then raise exception 'a title is required'; end if;
  if btrim(coalesce(p_body, '')) = '' then raise exception 'document text is required'; end if;

  v_next := d.current_version_number + 1;
  update public.documents
     set name = p_name,
         content = coalesce(d.content, '{}'::jsonb) || jsonb_build_object('body', p_body),
         modified_label = to_char(now(), 'DD/MM/YYYY'),
         current_version_number = v_next,
         sync_status = case when d.canonical_source = 'google_drive'
                            then 'portal_newer' else d.sync_status end
   where id = d.id returning * into d;
  insert into public.documents_versions
    (document_id, name, kind, content, modified_label, saved_by,
     version_number, change_type, change_summary, requires_reack,
     source_system, effective_at, metadata)
  values (d.id, d.name, d.kind, d.content, d.modified_label, v_uid,
          v_next, p_change_type, p_change_summary, p_requires_reack,
          'portal', d.effective_at,
          jsonb_build_object('status', d.status, 'classification', d.classification));
  return d;
end $function$
;

CREATE OR REPLACE FUNCTION public.document_sections_index(p_document uuid, p_headings jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.documents;
  v_body text;
  v_hash text;
  h jsonb;
  v_ord int := 0;
  v_from int := 1;
  v_at int;
  v_next int;
  v_head text;
  v_anchor text;
  v_count int := 0;
  v_starts int[] := '{}';
  v_heads text[] := '{}';
  v_anchors text[] := '{}';
  v_depths int[] := '{}';
  i int;
  j int;
begin
  select * into d from public.documents where id = p_document;
  if not found then raise exception 'no such document'; end if;

  if not (private.doc_class_visible(d.classification, d.owner_user_id)
          and (d.status in ('published', 'superseded', 'archived')
               or private.can_edit_document_for_bureau(d.classification, d.owner_user_id, d.folder, d.bureau)
               or private.can_approve_document(d.category, d.classification))) then
    raise exception 'not authorized';
  end if;

  v_body := coalesce(d.content ->> 'body', '');
  v_hash := d.content_hash;

  if jsonb_typeof(p_headings) is distinct from 'array' then
    raise exception 'headings must be an array';
  end if;
  if jsonb_array_length(p_headings) > 2000 then
    raise exception 'too many headings';
  end if;

  for h in select * from jsonb_array_elements(p_headings) loop
    v_anchor := btrim(coalesce(h ->> 'anchor', ''));
    v_head := btrim(coalesce(h ->> 'heading', ''));
    if v_anchor = '' then continue; end if;
    v_ord := v_ord + 1;
    v_at := case when v_head = '' then 0
                 else position(v_head in substr(v_body, v_from)) end;
    if v_at > 0 then
      v_at := v_at + v_from - 1;
      v_from := v_at + length(v_head);
    else
      v_at := 0;
    end if;
    v_starts := v_starts || v_at;
    v_heads := v_heads || v_head;
    v_anchors := v_anchors || v_anchor;
    v_depths := v_depths || greatest(2, least(6, coalesce((h ->> 'depth')::int, 2)));
  end loop;

  delete from public.document_sections where document_id = p_document;

  for i in 1 .. coalesce(array_length(v_starts, 1), 0) loop
    v_next := null;
    for j in i + 1 .. coalesce(array_length(v_starts, 1), 0) loop
      if v_starts[j] > 0 then v_next := v_starts[j]; exit; end if;
    end loop;

    insert into public.document_sections
      (document_id, version_number, ordinal, depth, anchor, heading, body, content_hash)
    values (
      p_document, d.current_version_number, i, v_depths[i], v_anchors[i], v_heads[i],
      case
        when v_starts[i] = 0 then ''
        when v_next is null then substr(v_body, v_starts[i])
        else substr(v_body, v_starts[i], v_next - v_starts[i])
      end,
      v_hash);
    v_count := v_count + 1;
  end loop;

  return v_count;
end $function$
;

CREATE OR REPLACE FUNCTION public.document_sections_stale(p_document uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case
    when (select 1 from public.documents d where d.id = p_document) is null then false
    else (select d.content_hash from public.documents d where d.id = p_document)
           is distinct from
         (select s.content_hash from public.document_sections s
           where s.document_id = p_document order by s.ordinal limit 1)
  end
$function$
;

CREATE OR REPLACE FUNCTION public.document_workflow(p_document uuid, p_action text, p_reason text DEFAULT NULL::text, p_effective_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_replacement uuid DEFAULT NULL::uuid)
 RETURNS documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.documents;
  v_uid uuid := (select auth.uid());
  v_from text;
begin
  select * into d from public.documents where id = p_document for update;
  if not found then raise exception 'document not found'; end if;
  if not private.doc_class_visible(d.classification, d.owner_user_id) then
    raise exception 'document not found';
  end if;
  v_from := d.status;

  if p_action = 'submit' then
    if not private.can_edit_document_for_bureau(d.classification, d.owner_user_id, d.folder, d.bureau) then
      raise exception 'not authorized to submit this document';
    end if;
    if d.status not in ('draft') then raise exception 'only drafts can be submitted for review'; end if;
    update public.documents set status = 'in_review' where id = d.id returning * into d;

  elsif p_action = 'approve' then
    if not private.can_approve_document(d.category, d.classification) then
      raise exception 'not authorized to approve this document';
    end if;
    if d.status <> 'in_review' then raise exception 'document is not awaiting review'; end if;
    update public.documents
       set status = 'approved', approved_by = v_uid, approved_at = now()
     where id = d.id returning * into d;

  elsif p_action = 'reject' then
    if not private.can_approve_document(d.category, d.classification) then
      raise exception 'not authorized to review this document';
    end if;
    if d.status <> 'in_review' then raise exception 'document is not awaiting review'; end if;
    if btrim(coalesce(p_reason, '')) = '' then raise exception 'a rejection reason is required'; end if;
    update public.documents set status = 'draft' where id = d.id returning * into d;

  elsif p_action in ('publish', 'publish_emergency') then
    if not private.can_approve_document(d.category, d.classification) then
      raise exception 'not authorized to publish this document';
    end if;
    if p_action = 'publish_emergency' then
      if btrim(coalesce(p_reason, '')) = '' then
        raise exception 'a reason is required for emergency publication';
      end if;
    elsif d.approval_required and d.status <> 'approved' then
      raise exception 'this document requires approval before publication';
    elsif d.status not in ('draft', 'approved') then
      raise exception 'only draft or approved documents can be published';
    end if;
    update public.documents
       set status = 'published',
           effective_at = coalesce(p_effective_at, now()),
           approved_by = case when d.status = 'approved' then approved_by else v_uid end,
           approved_at = case when d.status = 'approved' then approved_at else now() end
     where id = d.id returning * into d;

  elsif p_action = 'supersede' then
    if not private.can_approve_document(d.category, d.classification) then
      raise exception 'not authorized to supersede this document';
    end if;
    if d.status <> 'published' then raise exception 'only published documents can be superseded'; end if;
    if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required to supersede'; end if;
    update public.documents set status = 'superseded' where id = d.id returning * into d;
    if p_replacement is not null then
      if p_replacement = d.id then raise exception 'a document cannot supersede itself'; end if;
      insert into public.document_relations
        (document_id, relation, target_kind, target_document_id, label, created_by)
      values (d.id, 'supersedes', 'document', p_replacement, 'Replaced by', v_uid)
      on conflict do nothing;
    end if;

  elsif p_action = 'archive' then
    if not private.can_approve_document(d.category, d.classification) then
      raise exception 'not authorized to archive this document';
    end if;
    if d.status = 'archived' then return d; end if;
    if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required to archive'; end if;
    update public.documents set status = 'archived' where id = d.id returning * into d;

  else
    raise exception 'invalid action';
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_' || upper(p_action), 'documents', d.id,
          jsonb_build_object('from', v_from, 'to', d.status, 'reason', p_reason,
                             'replacement', p_replacement));
  return d;
end $function$
;

CREATE OR REPLACE FUNCTION public.doj_bureau_coverage()
 RETURNS TABLE(bureau bureau, primary_ada_id uuid, primary_ada_name text, acting_id uuid, acting_name text, acting_role text, supporting jsonb, covered boolean, primary_since timestamp with time zone, acting_since timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with b as (select unnest(array['major_crimes','street_crimes']::public.bureau[]) as bureau),
  live as (
    select a.*, p.display_name, private.justice_role_of(a.prosecutor_id) as jrole
      from public.prosecutor_bureau_assignments a
      join public.profiles p on p.id = a.prosecutor_id
     where a.ends_at is null and a.starts_at <= now()
       and private.is_justice_active(a.prosecutor_id))
  select b.bureau,
         pr.prosecutor_id, pr.display_name,
         ac.prosecutor_id, ac.display_name, ac.jrole,
         coalesce((select jsonb_agg(jsonb_build_object('id', s.prosecutor_id, 'name', s.display_name)
                                    order by s.display_name)
                     from live s where s.bureau = b.bureau and s.assignment_type = 'supporting'),
                  '[]'::jsonb),
         (private.get_routing_ada_for_bureau(b.bureau) is not null),
         pr.starts_at, ac.starts_at
    from b
    left join live pr on pr.bureau = b.bureau and pr.assignment_type = 'primary'
    left join live ac on ac.bureau = b.bureau and ac.assignment_type = 'acting'
   where private.justice_role() is not null or private.is_active()
      or coalesce((select is_owner from public.profiles where id = (select auth.uid())), false)
$function$
;

CREATE OR REPLACE FUNCTION public.end_ada_bureau_assignment(p_assignment uuid, p_note text DEFAULT NULL::text)
 RETURNS prosecutor_bureau_assignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); a public.prosecutor_bureau_assignments;
        v_actor_name text; v_is_test boolean;
        v_actor_is_test boolean := coalesce((select is_test from public.profiles where id = (select auth.uid())), false);
begin
  if not private.can_manage_prosecutors() then
    raise exception 'only a District Attorney, Attorney General, or the Owner may manage ADA assignments';
  end if;
  select * into a from public.prosecutor_bureau_assignments where id = p_assignment for update;
  if not found then raise exception 'assignment not found'; end if;
  if a.ends_at is not null then raise exception 'assignment already ended'; end if;
  if v_actor_is_test
     and not coalesce((select is_test from public.profiles where id = a.prosecutor_id), false) then
    raise exception 'test fixtures may not end a real prosecutor''s assignment';
  end if;
  update public.prosecutor_bureau_assignments
     set ends_at = now(),
         assignment_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), assignment_note)
   where id = p_assignment returning * into a;
  select display_name into v_actor_name from public.profiles where id = v_uid;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'ADA_ASSIGNMENT_ENDED', 'prosecutor_bureau_assignments', a.id,
          jsonb_build_object('prosecutor_id', a.prosecutor_id, 'bureau', a.bureau, 'type', a.assignment_type));
  select email like 'rls-test-%@cidportal.test' into v_is_test from auth.users where id = a.prosecutor_id;
  if not coalesce(v_is_test, false) then
    insert into public.notifications (user_id, type, payload)
    values (a.prosecutor_id, 'ada_assignment', jsonb_build_object(
      'assignment_id', a.id, 'bureau', a.bureau, 'assignment_type', a.assignment_type, 'ended', true,
      'reason', 'Your ' || a.assignment_type || ' assignment for ' || a.bureau || ' has ended.',
      'actor_id', v_uid, 'actor_name', v_actor_name));
  end if;
  return a;
end $function$
;

CREATE OR REPLACE FUNCTION public.end_field_officer(p_user uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_id uuid;
begin
  if not private.is_command() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'ending an appointment needs a reason';
  end if;

  update public.field_officers
     set active = false, ended_by = v_actor, ended_at = now(),
         end_reason = btrim(p_reason), updated_at = now()
   where user_id = p_user and active
  returning id into v_id;
  if v_id is null then raise exception 'that account holds no active appointment'; end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_OFFICER_ENDED', 'field_officers', v_id,
          jsonb_build_object('user_id', p_user, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.extraction_add_fact(p_extraction uuid, p_fact_type text, p_value text, p_source_location text, p_platform text DEFAULT NULL::text, p_owner_person uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS record_extraction_facts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_ext public.record_extractions;
  v_type text := btrim(coalesce(p_fact_type, ''));
  v_value text := btrim(coalesce(p_value, ''));
  v_loc text := btrim(coalesce(p_source_location, ''));
  v_platform text := nullif(btrim(coalesce(p_platform, '')), '');
  v_indicator_id uuid;
  v_account_id uuid;
  v_link_id uuid;
  v_fact public.record_extraction_facts;
begin
  select * into v_ext from public.record_extractions where id = p_extraction;
  if v_ext.id is null then
    raise exception 'record extraction not found';
  end if;
  if not private.can_access_case(v_ext.case_id) then
    raise exception 'you do not have access to this extraction''s case';
  end if;
  if v_value = '' then
    raise exception 'a non-blank value is required for every extracted fact';
  end if;
  if v_loc = '' then
    raise exception 'a source location is required for every extracted fact';
  end if;
  if v_type not in ('account', 'phone', 'email', 'address', 'ownership', 'property', 'other') then
    raise exception 'invalid fact_type: %', p_fact_type;
  end if;
  if p_owner_person is not null and not exists (select 1 from public.persons where id = p_owner_person) then
    raise exception 'owner person not found';
  end if;
  if v_type = 'ownership' and p_owner_person is null then
    raise exception 'an ownership fact requires an owner person';
  end if;
  if v_type = 'ownership' and v_platform is null then
    raise exception 'an ownership fact requires the account platform';
  end if;

  if v_type in ('account', 'phone', 'email', 'address') then
    insert into public.indicators (case_id, kind, value, note, created_by)
    values (v_ext.case_id, v_type, v_value,
            'From extraction “' || v_ext.source_label || '” @ ' || v_loc, v_uid)
    returning id into v_indicator_id;
  end if;

  if v_type in ('account', 'ownership') and v_platform is not null then
    select id into v_account_id from public.accounts
      where platform = v_platform
        and handle_normalized = lower(btrim(v_value))
        and lifecycle <> 'merged'
      order by created_at
      limit 1;
    if v_account_id is null then
      insert into public.accounts (platform, handle, created_by)
      values (v_platform, v_value, v_uid)
      returning id into v_account_id;
    end if;

    if p_owner_person is not null then
      select id into v_link_id from public.account_links
        where account_id = v_account_id and subject_kind = 'person' and subject_id = p_owner_person;
      if v_link_id is null then
        insert into public.account_links
          (account_id, subject_kind, subject_id, person_id, ownership_confidence, source, created_by)
        values (v_account_id, 'person', p_owner_person, p_owner_person, 'suspected',
                'record extraction auto-link', v_uid)
        returning id into v_link_id;
      end if;
    end if;
  end if;

  insert into public.record_extraction_facts
    (extraction_id, fact_type, value, source_location,
     linked_indicator_id, linked_account_id, linked_link_id, note, created_by)
  values (p_extraction, v_type, v_value, v_loc,
          v_indicator_id, v_account_id, v_link_id, nullif(btrim(coalesce(p_note, '')), ''), v_uid)
  returning * into v_fact;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'EXTRACTION_FACT_ADDED', 'record_extraction_facts', v_fact.id, jsonb_build_object(
    'extraction_id', p_extraction, 'case_id', v_ext.case_id, 'fact_type', v_type,
    'source_location', left(v_loc, 200),
    'indicator_id', v_indicator_id, 'account_id', v_account_id, 'link_id', v_link_id,
    'owner_person', p_owner_person, 'auto_link_confidence',
      case when v_link_id is not null then 'suspected' else null end));

  return v_fact;
end $function$
;

CREATE OR REPLACE FUNCTION public.field_access_decide(p_request uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); r public.field_access_requests;
begin
  if not private.is_command() then raise exception 'not authorized'; end if;

  select * into r from public.field_access_requests where id = p_request for update;
  if not found then raise exception 'no such request'; end if;
  if r.status <> 'pending' then
    raise exception 'that request was already %', r.status;
  end if;
  if not p_approve and coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'declining a request needs a reason the applicant can read';
  end if;

  update public.field_access_requests
     set status = case when p_approve then 'approved' else 'denied' end,
         decided_by = v_actor, decided_at = now(),
         decision_reason = nullif(btrim(coalesce(p_reason, '')), ''),
         updated_at = now()
   where id = p_request;

  if p_approve then
    perform public.assign_field_officer(
      r.user_id, r.agency, r.callsign, r.officer_rank, r.unit);
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor,
          case when p_approve then 'FIELD_ACCESS_APPROVED' else 'FIELD_ACCESS_DENIED' end,
          'field_access_requests', p_request,
          jsonb_build_object('user_id', r.user_id, 'agency', r.agency,
                             'reason', nullif(btrim(coalesce(p_reason, '')), '')));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_access_roster()
 RETURNS TABLE(user_id uuid, display_name text, email text, agency text, callsign text, officer_rank text, unit text, standing_active boolean, self_served boolean, appointed_by uuid, appointed_at timestamp with time zone, ended_at timestamp with time zone, end_reason text, removed_at timestamp with time zone, login_denied boolean, first_seen timestamp with time zone, last_seen timestamp with time zone, submissions integer, last_submission_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_command boolean := private.is_command();
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  return query
  select
    f.user_id,
    p.display_name,
    case when v_command then p.email end,
    f.agency,
    f.callsign,
    f.officer_rank,
    f.unit,
    f.active,
    f.appointed_by is null,
    f.appointed_by,
    f.appointed_at,
    f.ended_at,
    f.end_reason,
    p.removed_at,
    p.login_denied,
    u.created_at,
    case when v_command then u.last_sign_in_at end,
    (select count(*) from public.field_submissions s
      where s.officer_id = f.user_id and s.status <> 'draft')::int,
    (select max(s.submitted_at) from public.field_submissions s
      where s.officer_id = f.user_id and s.status <> 'draft')
  from public.field_officers f
  join public.profiles p on p.id = f.user_id
  left join auth.users u on u.id = f.user_id
  order by f.active desc, f.appointed_at desc;
end $function$
;

CREATE OR REPLACE FUNCTION public.field_access_self_serve(p_agency text, p_callsign text DEFAULT NULL::text, p_rank text DEFAULT NULL::text, p_unit text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_profile public.profiles;
  v_id uuid;
begin
  if v_actor is null then raise exception 'not signed in'; end if;

  select * into v_profile from public.profiles where id = v_actor;
  if not found then raise exception 'no such account'; end if;

  if v_profile.login_denied then
    raise exception 'this account has been denied access to the portal';
  end if;
  if v_profile.removed_at is not null then
    raise exception 'this account has been removed from the portal';
  end if;

  if private.is_active() then
    raise exception 'your account already has portal access';
  end if;
  if private.is_field_officer() then
    raise exception 'you already have Field Intelligence access';
  end if;

  if p_agency not in ('SAHP', 'BCSO', 'LSPD') then
    raise exception 'choose your agency';
  end if;

  insert into public.field_officers
    (user_id, agency, callsign, officer_rank, unit, active)
  values (v_actor, p_agency,
          nullif(btrim(coalesce(p_callsign, '')), ''),
          nullif(btrim(coalesce(p_rank, '')), ''),
          nullif(btrim(coalesce(p_unit, '')), ''),
          true)
  on conflict (user_id) do update
     set agency = excluded.agency,
         callsign = excluded.callsign,
         officer_rank = excluded.officer_rank,
         unit = excluded.unit,
         active = true,
         ended_at = null, ended_by = null, end_reason = null,
         updated_at = now()
  returning id into v_id;

  update public.field_access_requests
     set status = 'withdrawn',
         decision_reason = 'Superseded: the officer created access directly.',
         updated_at = now()
   where user_id = v_actor and status = 'pending';

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_ACCESS_SELF_SERVED', 'field_officers', v_id,
          jsonb_build_object('agency', p_agency,
                             'callsign', nullif(btrim(coalesce(p_callsign, '')), ''),
                             'rank', nullif(btrim(coalesce(p_rank, '')), ''),
                             'unit', nullif(btrim(coalesce(p_unit, '')), '')));

  return jsonb_build_object('id', v_id, 'agency', p_agency);
end $function$
;

CREATE OR REPLACE FUNCTION public.field_claim_decide(p_kind text, p_claim uuid, p_verdict text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_submission uuid; v_prev text; v_id uuid;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if p_verdict not in ('verified', 'unverified', 'disputed', 'rejected') then
    raise exception 'unknown verdict: %', p_verdict;
  end if;

  v_submission := case p_kind
    when 'person'   then (select submission_id from public.field_submission_persons where id = p_claim)
    when 'vehicle'  then (select submission_id from public.field_submission_vehicles where id = p_claim)
    when 'org'      then (select submission_id from public.field_submission_orgs where id = p_claim)
    when 'location' then (select submission_id from public.field_submission_locations where id = p_claim)
    when 'item'     then (select submission_id from public.field_submission_items where id = p_claim)
    else null end;
  if v_submission is null then
    raise exception 'no such claim: % %', p_kind, p_claim;
  end if;

  if (select status from public.field_submissions where id = v_submission) = 'draft' then
    raise exception 'that report has not been sent yet';
  end if;

  select id, verdict into v_id, v_prev from public.field_claim_verdicts
   where (p_kind = 'person'   and person_id   = p_claim)
      or (p_kind = 'vehicle'  and vehicle_id  = p_claim)
      or (p_kind = 'org'      and org_id      = p_claim)
      or (p_kind = 'location' and location_id = p_claim)
      or (p_kind = 'item'     and item_id     = p_claim);

  if v_id is null then
    insert into public.field_claim_verdicts
      (submission_id, person_id, vehicle_id, org_id, location_id, item_id,
       verdict, note, decided_by)
    values (v_submission,
            case when p_kind = 'person'   then p_claim end,
            case when p_kind = 'vehicle'  then p_claim end,
            case when p_kind = 'org'      then p_claim end,
            case when p_kind = 'location' then p_claim end,
            case when p_kind = 'item'     then p_claim end,
            p_verdict, nullif(btrim(coalesce(p_note, '')), ''), v_actor);
  else
    update public.field_claim_verdicts
       set verdict = p_verdict,
           note = nullif(btrim(coalesce(p_note, '')), ''),
           decided_by = v_actor, decided_at = now()
     where id = v_id;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_CLAIM_DECIDED', 'field_claim_verdicts', v_submission,
          jsonb_build_object('claim_kind', p_kind, 'claim_id', p_claim,
                             'from_verdict', v_prev, 'to_verdict', p_verdict));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_claim_link(p_kind text, p_claim uuid, p_target_kind text, p_target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_submission uuid;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  v_submission := case p_kind
    when 'person'   then (select submission_id from public.field_submission_persons where id = p_claim)
    when 'vehicle'  then (select submission_id from public.field_submission_vehicles where id = p_claim)
    when 'org'      then (select submission_id from public.field_submission_orgs where id = p_claim)
    when 'location' then (select submission_id from public.field_submission_locations where id = p_claim)
    else null end;
  if v_submission is null then raise exception 'no such claim: % %', p_kind, p_claim; end if;
  if (select status from public.field_submissions where id = v_submission) = 'draft' then
    raise exception 'that report has not been sent yet';
  end if;

  if not (case p_target_kind
            when 'person'  then exists (select 1 from public.persons where id = p_target)
            when 'vehicle' then exists (select 1 from public.vehicles where id = p_target)
            when 'gang'    then exists (select 1 from public.gangs where id = p_target)
            when 'place'   then exists (select 1 from public.places where id = p_target)
            else false end) then
    raise exception 'no such %: %', p_target_kind, p_target;
  end if;

  insert into public.field_claim_links
    (submission_id, claim_person_id, claim_vehicle_id, claim_org_id, claim_location_id,
     person_id, vehicle_id, gang_id, place_id, linked_by)
  values (v_submission,
          case when p_kind = 'person'   then p_claim end,
          case when p_kind = 'vehicle'  then p_claim end,
          case when p_kind = 'org'      then p_claim end,
          case when p_kind = 'location' then p_claim end,
          case when p_target_kind = 'person'  then p_target end,
          case when p_target_kind = 'vehicle' then p_target end,
          case when p_target_kind = 'gang'    then p_target end,
          case when p_target_kind = 'place'   then p_target end,
          v_actor);

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_CLAIM_LINKED', 'field_claim_links', v_submission,
          jsonb_build_object('claim_kind', p_kind, 'claim_id', p_claim,
                             'target_kind', p_target_kind, 'target_id', p_target));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_claim_matches(p_kind text, p_claim uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_matches jsonb := '[]'::jsonb;
  v_also int := 0;
  v_plate text; v_name text; v_alias text; v_org text; v_postal text;
begin
  if not private.is_active() then
    raise exception 'not authorized';
  end if;

  if p_kind = 'vehicle' then
    select private.norm_plate(plate) into v_plate
      from public.field_submission_vehicles where id = p_claim;
    if v_plate is not null then
      select coalesce(jsonb_agg(jsonb_build_object(
               'kind', 'vehicle', 'id', v.id,
               'label', concat_ws(' ', v.plate, v.color, v.model),
               'exact', private.norm_plate(v.plate) = v_plate)), '[]'::jsonb)
        into v_matches
        from public.vehicles v
       where private.norm_plate(v.plate) = v_plate;
      select count(distinct submission_id) into v_also
        from public.field_submission_vehicles
       where private.norm_plate(plate) = v_plate and id <> p_claim;
    end if;

  elsif p_kind = 'person' then
    select full_name, alias into v_name, v_alias
      from public.field_submission_persons where id = p_claim;
    if coalesce(v_name, v_alias) is not null then
      select coalesce(jsonb_agg(jsonb_build_object(
               'kind', 'person', 'id', p.id,
               'label', concat_ws(' / ', p.name, p.alias),
               'exact', lower(p.name) = lower(coalesce(v_name, '')))), '[]'::jsonb)
        into v_matches
        from public.persons p
       where (v_name is not null and (p.name ilike v_name or p.alias ilike v_name))
          or (v_alias is not null and (p.alias ilike v_alias or p.name ilike v_alias));
      select count(distinct submission_id) into v_also
        from public.field_submission_persons
       where id <> p_claim
         and ((v_name is not null and (full_name ilike v_name or alias ilike v_name))
           or (v_alias is not null and (alias ilike v_alias or full_name ilike v_alias)));
    end if;

  elsif p_kind = 'org' then
    select private.norm_org(name) into v_org
      from public.field_submission_orgs where id = p_claim;
    if v_org is not null then
      select coalesce(jsonb_agg(jsonb_build_object(
               'kind', 'gang', 'id', g.id, 'label', g.name,
               'exact', private.norm_org(g.name) = v_org)), '[]'::jsonb)
        into v_matches
        from public.gangs g
       where private.norm_org(g.name) = v_org;
      select count(distinct submission_id) into v_also
        from public.field_submission_orgs
       where private.norm_org(name) = v_org and id <> p_claim;
    end if;

  elsif p_kind = 'location' then
    select postal into v_postal
      from public.field_submission_locations where id = p_claim;
    if coalesce(btrim(v_postal), '') <> '' then
      select coalesce(jsonb_agg(jsonb_build_object(
               'kind', 'place', 'id', pl.id,
               'label', concat_ws(' - ', pl.name, pl.area),
               'exact', true)), '[]'::jsonb)
        into v_matches
        from public.places pl
       where pl.area ilike '%' || btrim(v_postal) || '%'
          or pl.name ilike '%' || btrim(v_postal) || '%';
      select count(distinct submission_id) into v_also
        from public.field_submission_locations
       where btrim(coalesce(postal, '')) = btrim(v_postal) and id <> p_claim;
    end if;

  else
    return jsonb_build_object('matches', '[]'::jsonb, 'also_reported', 0,
                              'matchable', false);
  end if;

  return jsonb_build_object('matches', v_matches, 'also_reported', v_also,
                            'matchable', true);
end $function$
;

CREATE OR REPLACE FUNCTION public.field_claim_progress(p_submission uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with claims as (
    select id from public.field_submission_persons   where submission_id = p_submission
    union all select id from public.field_submission_vehicles  where submission_id = p_submission
    union all select id from public.field_submission_orgs      where submission_id = p_submission
    union all select id from public.field_submission_locations where submission_id = p_submission
    union all select id from public.field_submission_items     where submission_id = p_submission
  ), decided as (
    select verdict from public.field_claim_verdicts where submission_id = p_submission
  )
  select jsonb_build_object(
    'claims',     (select count(*) from claims),
    'decided',    (select count(*) from decided),
    'verified',   (select count(*) from decided where verdict = 'verified'),
    'unverified', (select count(*) from decided where verdict = 'unverified'),
    'disputed',   (select count(*) from decided where verdict = 'disputed'),
    'rejected',   (select count(*) from decided where verdict = 'rejected'))
$function$
;

CREATE OR REPLACE FUNCTION public.field_siu_designate_target(p_submission uuid, p_case uuid, p_entity_type text, p_entity_id uuid, p_designation text, p_priority text DEFAULT 'medium'::text, p_role text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions; v_id uuid;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission;
  if not found then raise exception 'no such submission'; end if;
  if v.siu_state is distinct from 'accepted' then
    raise exception 'SIB has not taken that report yet';
  end if;

  v_id := public.siu_designate_target(
    p_case, p_entity_type, p_entity_id, p_designation, p_priority,
    p_role, p_notes, p_label);

  update public.siu_targets
     set field_submission_id = p_submission
   where id = v_id;

  insert into public.field_siu_actions (submission_id, action, actor_id, reason)
  values (p_submission, 'target_designated', v_actor,
          nullif(btrim(coalesce(p_role, '')), ''));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_TARGET_DESIGNATED', 'siu_targets', v_id,
          jsonb_build_object('submission_no', v.submission_no, 'case', p_case,
                             'entity_type', p_entity_type, 'entity_id', p_entity_id,
                             'designation', p_designation));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.field_siu_followup_add(p_submission uuid, p_kind text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions; v_id uuid;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission;
  if not found then raise exception 'no such submission'; end if;
