  insert into public.field_siu_followups (submission_id, kind, note, created_by)
  values (p_submission, p_kind, nullif(btrim(coalesce(p_note, '')), ''), v_actor)
  returning id into v_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_FOLLOWUP_ADDED', 'field_siu_followups', v_id,
          jsonb_build_object('submission_no', v.submission_no, 'kind', p_kind));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.field_siu_followup_clear(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); f public.field_siu_followups;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why it is no longer a candidate';
  end if;

  select * into f from public.field_siu_followups where id = p_id for update;
  if not found then raise exception 'no such follow-up'; end if;
  if f.cleared_at is not null then raise exception 'that one is already cleared'; end if;

  update public.field_siu_followups
     set cleared_by = v_actor, cleared_at = now(), clear_reason = btrim(p_reason)
   where id = p_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_FOLLOWUP_CLEARED', 'field_siu_followups', p_id,
          jsonb_build_object('kind', f.kind, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_siu_link_case(p_submission uuid, p_case uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if not private.siu_case_access(p_case) then
    raise exception 'not authorized for that investigation';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such submission'; end if;
  if v.siu_state is distinct from 'accepted' then
    raise exception 'SIB has not taken that report yet';
  end if;
  if v.siu_case_id = p_case then
    raise exception 'that report is already linked to this investigation';
  end if;

  update public.field_submissions
     set siu_case_id = p_case, updated_at = now()
   where id = p_submission;

  insert into public.field_siu_actions (submission_id, action, actor_id, reason)
  values (p_submission, 'case_linked', v_actor,
          nullif(btrim(coalesce(p_reason, '')), ''));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_CASE_LINKED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no, 'case', p_case,
                             'previous_case', v.siu_case_id));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_siu_map_add(p_submission uuid, p_layer text, p_role text DEFAULT NULL::text, p_label text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_claim_kind text DEFAULT NULL::text, p_claim_id uuid DEFAULT NULL::uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v public.field_submissions;
  v_id uuid;
  v_exists boolean;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission;
  if not found then raise exception 'no such submission'; end if;
  if v.status = 'draft' then raise exception 'that report has not been sent yet'; end if;

  if p_claim_kind is not null and p_claim_kind not in
     ('person', 'vehicle', 'org', 'location', 'item') then
    raise exception 'unknown claim kind';
  end if;
  if (p_claim_kind is null) <> (p_claim_id is null) then
    raise exception 'name both the claim and its kind, or neither';
  end if;
  if p_entity_type is not null and p_entity_type not in
     ('person', 'vehicle', 'gang', 'place') then
    raise exception 'unknown record type';
  end if;
  if (p_entity_type is null) <> (p_entity_id is null) then
    raise exception 'name both the record and its type, or neither';
  end if;
  if coalesce(btrim(coalesce(p_label, '')), '') = ''
     and p_claim_id is null and p_entity_id is null then
    raise exception 'say who or what this is: a name, a claim from the report, or a record';
  end if;

  if p_claim_id is not null then
    select case p_claim_kind
      when 'person' then exists (select 1 from public.field_submission_persons x
                                  where x.id = p_claim_id and x.submission_id = p_submission)
      when 'vehicle' then exists (select 1 from public.field_submission_vehicles x
                                   where x.id = p_claim_id and x.submission_id = p_submission)
      when 'org' then exists (select 1 from public.field_submission_orgs x
                               where x.id = p_claim_id and x.submission_id = p_submission)
      when 'location' then exists (select 1 from public.field_submission_locations x
                                    where x.id = p_claim_id and x.submission_id = p_submission)
      else exists (select 1 from public.field_submission_items x
                    where x.id = p_claim_id and x.submission_id = p_submission)
    end into v_exists;
    if not v_exists then raise exception 'that claim is not part of this report'; end if;
  end if;

  if p_entity_id is not null then
    select case p_entity_type
      when 'person' then exists (select 1 from public.persons x where x.id = p_entity_id)
      when 'vehicle' then exists (select 1 from public.vehicles x where x.id = p_entity_id)
      when 'gang' then exists (select 1 from public.gangs x where x.id = p_entity_id)
      else exists (select 1 from public.places x where x.id = p_entity_id)
    end into v_exists;
    if not v_exists then raise exception 'that record is not in the registry'; end if;
  end if;

  insert into public.field_siu_enterprise (
    submission_id, layer, role, label, note,
    claim_person_id, claim_vehicle_id, claim_org_id, claim_location_id, claim_item_id,
    person_id, vehicle_id, gang_id, place_id, created_by)
  values (
    p_submission, p_layer,
    nullif(btrim(coalesce(p_role, '')), ''),
    nullif(btrim(coalesce(p_label, '')), ''),
    nullif(btrim(coalesce(p_note, '')), ''),
    case when p_claim_kind = 'person' then p_claim_id end,
    case when p_claim_kind = 'vehicle' then p_claim_id end,
    case when p_claim_kind = 'org' then p_claim_id end,
    case when p_claim_kind = 'location' then p_claim_id end,
    case when p_claim_kind = 'item' then p_claim_id end,
    case when p_entity_type = 'person' then p_entity_id end,
    case when p_entity_type = 'vehicle' then p_entity_id end,
    case when p_entity_type = 'gang' then p_entity_id end,
    case when p_entity_type = 'place' then p_entity_id end,
    v_actor)
  returning id into v_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_MAPPED', 'field_siu_enterprise', v_id,
          jsonb_build_object('submission_no', v.submission_no, 'layer', p_layer,
                             'role', p_role));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.field_siu_map_remove(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); e public.field_siu_enterprise;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why this reading was wrong';
  end if;

  select * into e from public.field_siu_enterprise where id = p_id for update;
  if not found then raise exception 'no such entry'; end if;
  if e.removed_at is not null then raise exception 'that entry is already removed'; end if;

  update public.field_siu_enterprise
     set removed_by = v_actor, removed_at = now(), remove_reason = btrim(p_reason)
   where id = p_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_MAP_REMOVED', 'field_siu_enterprise', p_id,
          jsonb_build_object('layer', e.layer, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_siu_unlink_case(p_submission uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why it no longer belongs to that investigation';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such submission'; end if;
  if v.siu_case_id is null then raise exception 'that report is not linked to an investigation'; end if;
  if not private.siu_case_access(v.siu_case_id) then
    raise exception 'not authorized for that investigation';
  end if;

  update public.field_submissions
     set siu_case_id = null, updated_at = now()
   where id = p_submission;

  insert into public.field_siu_actions (submission_id, action, actor_id, reason)
  values (p_submission, 'case_unlinked', v_actor, btrim(p_reason));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_CASE_UNLINKED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'case', v.siu_case_id, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_archive(p_submission uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why this is being archived';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such record'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;
  if v.status = 'draft' then raise exception 'that record has not been sent yet'; end if;
  if v.status = 'archived' then raise exception 'that record is already archived'; end if;

  update public.field_submissions
     set status = 'archived',
         archived_at = now(), archived_by = v_actor,
         archive_reason = btrim(p_reason),
         updated_at = now()
   where id = p_submission;

  insert into public.field_submission_reviews (submission_id, author_id, note)
  values (p_submission, v_actor, 'Archived: ' || btrim(p_reason));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_ARCHIVED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'from_status', v.status, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_ask(p_submission uuid, p_question text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_question), '') = '' then
    raise exception 'ask an actual question';
  end if;
  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such submission'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that report is not in your jurisdiction';
  end if;
  if v.status = 'draft' then raise exception 'that report has not been sent yet'; end if;
  if not private.field_submission_transition_ok(v.status, 'needs_info')
     and v.status <> 'needs_info' then
    raise exception 'a submission cannot go from % to needs_info', v.status;
  end if;

  insert into public.field_submission_messages (submission_id, body)
  values (p_submission, btrim(p_question));

  update public.field_submissions set status = 'needs_info', updated_at = now()
   where id = p_submission;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_INFO_REQUESTED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no, 'from_status', v.status));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_assign(p_submission uuid, p_user uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v public.field_submissions;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_action text;
begin
  if not private.is_command() then
    raise exception 'only a Bureau Lead or above can assign a record';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such record'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;
  if v.status = 'draft' then raise exception 'that record has not been sent yet'; end if;
  if p_user is null then raise exception 'choose an investigator'; end if;
  if v.assigned_to = p_user then
    raise exception 'that record is already assigned to them';
  end if;
  if not private.field_jurisdiction_visible_for(p_user, v.jurisdiction) then
    raise exception 'that investigator cannot see records from this jurisdiction';
  end if;

  v_action := case when v.assigned_to is null then 'assigned' else 'reassigned' end;
  if v_action = 'reassigned' and v_reason is null then
    raise exception 'say why you are taking it off the current investigator';
  end if;

  update public.field_submissions
     set assigned_to = p_user,
         assigned_at = now(),
         status = case when status = 'new' then 'reviewing' else status end,
         updated_at = now()
   where id = p_submission;

  insert into public.field_assignments
    (submission_id, action, actor_id, from_user, to_user, reason)
  values (p_submission, v_action, v_actor, v.assigned_to, p_user, v_reason);

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor,
          case when v_action = 'assigned'
               then 'FIELD_SUBMISSION_ASSIGNED' else 'FIELD_SUBMISSION_REASSIGNED' end,
          'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'from_user', v.assigned_to, 'to_user', p_user,
                             'reason', v_reason));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_claim(p_submission uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such record'; end if;

  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;
  if v.status = 'draft' then raise exception 'that record has not been sent yet'; end if;

  if v.assigned_to = v_actor then
    raise exception 'you already have this record';
  end if;
  if v.assigned_to is not null then
    raise exception 'that record is already assigned. A Bureau Lead can reassign it.';
  end if;

  update public.field_submissions
     set assigned_to = v_actor,
         assigned_at = now(),
         status = case when status = 'new' then 'reviewing' else status end,
         updated_at = now()
   where id = p_submission;

  insert into public.field_assignments (submission_id, action, actor_id, to_user)
  values (p_submission, 'claimed', v_actor, v_actor);

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_CLAIMED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no, 'from_status', v.status));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_counts()
 RETURNS TABLE(submission_id uuid, persons integer, vehicles integer, orgs integer, locations integer, items integer, evidence integer)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select s.id,
    (select count(*) from public.field_submission_persons x where x.submission_id = s.id)::int,
    (select count(*) from public.field_submission_vehicles x where x.submission_id = s.id)::int,
    (select count(*) from public.field_submission_orgs x where x.submission_id = s.id)::int,
    (select count(*) from public.field_submission_locations x where x.submission_id = s.id)::int,
    (select count(*) from public.field_submission_items x where x.submission_id = s.id)::int,
    (select count(*) from public.field_submission_evidence x where x.submission_id = s.id)::int
  from public.field_submissions s
$function$
;

CREATE OR REPLACE FUNCTION public.field_submission_create_case(p_submission uuid, p_bureau text, p_title text, p_summary text DEFAULT NULL::text, p_lead uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v public.field_submissions;
  v_case uuid;
  v_no text;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission;
  if not found then raise exception 'no such record'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;
  if v.status = 'draft' then raise exception 'that record has not been sent yet'; end if;

  if coalesce(btrim(coalesce(p_title, '')), '') = '' then
    raise exception 'the case needs a title';
  end if;
  if p_bureau not in ('major_crimes', 'street_crimes', 'JTF') then
    raise exception 'unknown bureau';
  end if;

  v_no := public.next_case_number(p_bureau);
  if coalesce(v_no, '') = '' then raise exception 'could not allocate a case number'; end if;

  insert into public.cases (case_number, bureau, title, summary, lead_detective_id, created_by)
  values (v_no, p_bureau::public.bureau, btrim(p_title),
          nullif(btrim(coalesce(p_summary, '')), ''),
          coalesce(p_lead, v_actor), v_actor)
  returning id into v_case;

  insert into public.field_submission_cases
    (submission_id, case_id, relation, submission_no, linked_by)
  values (p_submission, v_case, 'originated', v.submission_no, v_actor);

  if private.field_submission_transition_ok(v.status, 'actionable') then
    update public.field_submissions
       set status = 'actionable', updated_at = now()
     where id = p_submission;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_CASE_OPENED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'case_id', v_case, 'case_number', v_no));
  return v_case;
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_create_observation(p_submission uuid, p_case uuid, p_activity text, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location text DEFAULT NULL::text, p_confidence text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v public.field_submissions;
  v_obs uuid;
  v_conf text;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission;
  if not found then raise exception 'no such record'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;
  if not private.field_case_visible(p_case) then
    raise exception 'no such case, or it is not one you have access to';
  end if;
  if not private.field_submission_on_case(p_submission, p_case) then
    raise exception 'link this record to that case first';
  end if;
  if coalesce(btrim(coalesce(p_activity, '')), '') = '' then
    raise exception 'say what was seen';
  end if;

  v_conf := coalesce(p_confidence, v.reliability, 'unverified');
  if v_conf not in ('probable', 'possible', 'unverified', 'disproven') then
    v_conf := 'unverified';
  end if;

  insert into public.surveillance_observations
    (case_id, observed_at, source_type, source_ref, location_text, activity,
     confidence, created_by, field_submission_id)
  values (p_case,
          coalesce(p_observed_at, v.observed_at, now()),
          'patrol_submission',
          v.submission_no,
          nullif(btrim(coalesce(p_location, '')), ''),
          btrim(p_activity),
          v_conf, v_actor, p_submission)
  returning id into v_obs;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_OBSERVATION_CREATED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'case_id', p_case, 'observation_id', v_obs));
  return v_obs;
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_decide(p_submission uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such submission'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that report is not in your jurisdiction';
  end if;
  if not private.field_submission_transition_ok(v.status, p_status) then
    raise exception 'a submission cannot go from % to %', v.status, p_status;
  end if;

  update public.field_submissions
     set status = p_status, updated_at = now()
   where id = p_submission;

  if coalesce(btrim(p_note), '') <> '' then
    insert into public.field_submission_reviews (submission_id, author_id, note)
    values (p_submission, v_actor, btrim(p_note));
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_DECIDED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'from_status', v.status, 'to_status', p_status));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_delete(p_submission uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v public.field_submissions;
  v_deps jsonb;
begin
  if not private.is_command() then
    raise exception 'only a Bureau Lead or above can delete an intelligence record';
  end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why this record should not exist';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such record'; end if;
  if v.deleted_at is not null then raise exception 'that record is already deleted'; end if;

  v_deps := private.field_submission_dependencies(p_submission);
  if v_deps <> '{}'::jsonb then
    raise exception
      'other work depends on this record (%) -- archive it instead, which keeps everything and can be undone',
      (select string_agg(key || ': ' || value, ', ' order by key)
         from jsonb_each_text(v_deps));
  end if;

  update public.field_submissions
     set deleted_at = now(), deleted_by = v_actor,
         delete_reason = btrim(p_reason),
         updated_at = now()
   where id = p_submission;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_DELETED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'status', v.status, 'reason', btrim(p_reason),
                             'officer_id', v.officer_id));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_grade(p_submission uuid, p_urgency text DEFAULT NULL::text, p_reliability text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such record'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;
  if v.status = 'draft' then raise exception 'that record has not been sent yet'; end if;

  if p_urgency is not null and p_urgency not in ('low', 'medium', 'high', 'critical') then
    raise exception 'unknown urgency';
  end if;
  if p_reliability is not null and p_reliability not in
     ('confirmed', 'probable', 'possible', 'unverified', 'disproven') then
    raise exception 'unknown reliability';
  end if;

  update public.field_submissions
     set urgency = coalesce(p_urgency, urgency),
         reliability = coalesce(p_reliability, reliability),
         updated_at = now()
   where id = p_submission;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_GRADED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'urgency', p_urgency, 'reliability', p_reliability));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_link_case(p_submission uuid, p_case uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v public.field_submissions;
  v_link uuid;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission;
  if not found then raise exception 'no such record'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;
  if v.status = 'draft' then raise exception 'that record has not been sent yet'; end if;
  if not private.field_case_visible(p_case) then
    raise exception 'no such case, or it is not one you have access to';
  end if;

  if exists (select 1 from public.field_submission_cases
              where submission_id = p_submission and case_id = p_case
                and unlinked_at is null) then
    raise exception 'that record is already linked to that case';
  end if;

  insert into public.field_submission_cases
    (submission_id, case_id, relation, submission_no, note, linked_by)
  values (p_submission, p_case, 'linked', v.submission_no,
          nullif(btrim(coalesce(p_note, '')), ''), v_actor)
  returning id into v_link;

  if private.field_submission_transition_ok(v.status, 'actionable') then
    update public.field_submissions
       set status = 'actionable', updated_at = now()
     where id = p_submission;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_CASE_LINKED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no, 'case_id', p_case));
  return v_link;
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_link_observation(p_submission uuid, p_observation uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v public.field_submissions;
  o public.surveillance_observations;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission;
  if not found then raise exception 'no such record'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;

  select * into o from public.surveillance_observations where id = p_observation for update;
  if not found then raise exception 'no such observation'; end if;
  if not private.field_case_visible(o.case_id) then
    raise exception 'no such observation, or it is not one you have access to';
  end if;
  if o.restricted and not private.is_command() then
    raise exception 'that observation is restricted';
  end if;
  if not private.field_submission_on_case(p_submission, o.case_id) then
    raise exception 'link this record to that case first';
  end if;
  if o.field_submission_id is not null then
    if o.field_submission_id = p_submission then
      raise exception 'that observation already cites this record';
    end if;
    raise exception 'that observation already cites a different record';
  end if;

  update public.surveillance_observations
     set field_submission_id = p_submission,
         source_ref = coalesce(source_ref, v.submission_no)
   where id = p_observation;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_OBSERVATION_LINKED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'observation_id', p_observation, 'case_id', o.case_id));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_release(p_submission uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such submission'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that report is not in your jurisdiction';
  end if;
  if v.assigned_to is null then raise exception 'that report is not assigned'; end if;
  if v.assigned_to <> v_actor and not private.is_command() then
    raise exception 'only the assigned investigator or a Bureau Lead can release it';
  end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why you are releasing it';
  end if;

  update public.field_submissions
     set assigned_to = null, assigned_at = null, updated_at = now()
   where id = p_submission;

  insert into public.field_assignments
    (submission_id, action, actor_id, from_user, reason)
  values (p_submission, 'released', v_actor, v.assigned_to, btrim(p_reason));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_RELEASED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'from_user', v.assigned_to, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_repeats(p_submission uuid)
 RETURNS TABLE(kind text, label text, basis text, others integer, records text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;

  return query
  with mine as (
    select 'person' as kind, lower(btrim(p.full_name)) as key, btrim(p.full_name) as label
      from public.field_submission_persons p
     where p.submission_id = p_submission and length(btrim(coalesce(p.full_name, ''))) > 1
    union
    select 'person', lower(btrim(p.alias)), btrim(p.alias)
      from public.field_submission_persons p
     where p.submission_id = p_submission and length(btrim(coalesce(p.alias, ''))) > 1
    union
    select 'vehicle', lower(btrim(v.plate)), btrim(v.plate)
      from public.field_submission_vehicles v
     where v.submission_id = p_submission and length(btrim(coalesce(v.plate, ''))) > 1
    union
    select 'organisation', lower(btrim(o.name)), btrim(o.name)
      from public.field_submission_orgs o
     where o.submission_id = p_submission and length(btrim(coalesce(o.name, ''))) > 1
  ),
  named as (
    select m.kind, m.label, 'named'::text as basis, x.submission_id
      from mine m
      join (
        select 'person' as kind, lower(btrim(p.full_name)) as key, p.submission_id
          from public.field_submission_persons p
        union all
        select 'person', lower(btrim(p.alias)), p.submission_id
          from public.field_submission_persons p
        union all
        select 'vehicle', lower(btrim(v.plate)), v.submission_id
          from public.field_submission_vehicles v
        union all
        select 'organisation', lower(btrim(o.name)), o.submission_id
          from public.field_submission_orgs o
      ) x on x.kind = m.kind and x.key = m.key
     where x.submission_id <> p_submission
  ),
  pins as (
    select l.submission_id, 'person' as kind, l.person_id as ref
      from public.field_claim_links l where l.person_id is not null
    union all
    select l.submission_id, 'vehicle', l.vehicle_id
      from public.field_claim_links l where l.vehicle_id is not null
    union all
    select l.submission_id, 'organisation', l.gang_id
      from public.field_claim_links l where l.gang_id is not null
    union all
    select l.submission_id, 'place', l.place_id
      from public.field_claim_links l where l.place_id is not null
  ),
  linked as (
    select a.kind,
           coalesce(pe.name, ve.plate, ga.name, pl.name, 'a matched record') as label,
           'linked'::text as basis,
           b.submission_id
      from pins a
      join pins b on b.kind = a.kind and b.ref = a.ref
                 and b.submission_id <> a.submission_id
      left join public.persons pe on a.kind = 'person' and pe.id = a.ref
      left join public.vehicles ve on a.kind = 'vehicle' and ve.id = a.ref
      left join public.gangs ga on a.kind = 'organisation' and ga.id = a.ref
      left join public.places pl on a.kind = 'place' and pl.id = a.ref
     where a.submission_id = p_submission
  ),
  signals as (select * from named union all select * from linked)
  select b.kind, b.label, b.basis,
         count(distinct b.submission_id)::int,
         array_agg(distinct coalesce(s.submission_no, 'a draft'))
    from signals b
    join public.field_submissions s on s.id = b.submission_id
   where private.field_submission_readable(b.submission_id)
   group by b.kind, b.label, b.basis
   order by 4 desc, 2;
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_restore(p_submission uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such record'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;
  if v.status <> 'archived' then raise exception 'that record is not archived'; end if;

  update public.field_submissions
     set status = 'reviewing',
         archived_at = null, archived_by = null,
         updated_at = now()
   where id = p_submission;

  insert into public.field_submission_reviews (submission_id, author_id, note)
  values (p_submission, v_actor,
          'Restored from the archive' ||
          coalesce(': ' || nullif(btrim(coalesce(p_reason, '')), ''), ''));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_RESTORED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'archive_reason', v.archive_reason,
                             'reason', nullif(btrim(coalesce(p_reason, '')), '')));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_search(p_query text, p_limit integer DEFAULT 100)
 RETURNS TABLE(submission_id uuid, matched text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with q as (
    select '%' || replace(replace(replace(
             lower(btrim(coalesce(p_query, ''))),
             '\', '\\'), '%', '\%'), '_', '\_') || '%' as pat,
           length(btrim(coalesce(p_query, ''))) as len
  ),
  hits as (
    select s.id, 'the report' as what
      from public.field_submissions s, q
     where q.len > 1
       and lower(concat_ws(' ', s.summary, s.details, s.submission_no,
                           s.mdt_reference, s.snap_officer_name, s.snap_callsign,
                           s.snap_agency, s.snap_rank, s.snap_unit,
                           s.source_codename)) like q.pat escape '\'
    union all
    select p.submission_id, 'a person' from public.field_submission_persons p, q
     where q.len > 1
       and lower(concat_ws(' ', p.full_name, p.alias, p.description, p.phone,
                           p.org_name, p.org_role, p.reason, p.note)) like q.pat escape '\'
    union all
    select v.submission_id, 'a vehicle' from public.field_submission_vehicles v, q
     where q.len > 1
       and lower(concat_ws(' ', v.plate, v.make, v.model, v.color, v.secondary_color,
                           v.description, v.registered_owner, v.occupants, v.org_name,
                           v.reason, v.note)) like q.pat escape '\'
    union all
    select o.submission_id, 'an organisation' from public.field_submission_orgs o, q
     where q.len > 1
       and lower(concat_ws(' ', o.name, o.org_type, o.colors, o.symbols, o.clothing,
                           o.territory, o.leadership, o.members, o.note)) like q.pat escape '\'
    union all
    select l.submission_id, 'a place' from public.field_submission_locations l, q
     where q.len > 1
       and lower(concat_ws(' ', l.kind, l.postal, l.street, l.description,
                           l.org_name, l.observed_what, l.note)) like q.pat escape '\'
    union all
    select i.submission_id, 'an item' from public.field_submission_items i, q
     where q.len > 1
       and lower(concat_ws(' ', i.category, i.description, i.suspected_substance,
                           i.packaging, i.seized_from_person, i.seized_from_vehicle,
                           i.seized_from_location, i.note)) like q.pat escape '\'
    union all
    select m.submission_id, 'the thread' from public.field_submission_messages m, q
     where q.len > 1 and lower(m.body) like q.pat escape '\'
  )
  select h.id, array_agg(distinct h.what)
    from hits h
   where private.field_submission_readable(h.id)
   group by h.id
   limit greatest(1, least(coalesce(p_limit, 100), 500))
$function$
;

CREATE OR REPLACE FUNCTION public.field_submission_set_source(p_submission uuid, p_codename text, p_name text DEFAULT NULL::text, p_contact text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_handler uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v public.field_submissions;
  v_handler uuid;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such record'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that record is not in your jurisdiction';
  end if;
  if coalesce(btrim(coalesce(p_codename, '')), '') = '' then
    raise exception 'the source needs a codename';
  end if;

  v_handler := coalesce(p_handler, v_actor);
  if not exists (select 1 from public.profiles p where p.id = v_handler and p.active) then
    raise exception 'the handler must be an active investigator';
  end if;
  if v_handler <> v_actor and not private.is_command() then
    raise exception 'only command can register a source against another handler';
  end if;

  insert into public.field_submission_sources
    (submission_id, codename, source_name, source_contact, handler_notes,
     handler_id, created_by)
  values (p_submission, btrim(p_codename),
          nullif(btrim(coalesce(p_name, '')), ''),
          nullif(btrim(coalesce(p_contact, '')), ''),
          nullif(btrim(coalesce(p_notes, '')), ''),
          v_handler, v_actor)
  on conflict (submission_id) do update
    set codename = excluded.codename,
        source_name = coalesce(excluded.source_name, public.field_submission_sources.source_name),
        source_contact = coalesce(excluded.source_contact, public.field_submission_sources.source_contact),
        handler_notes = coalesce(excluded.handler_notes, public.field_submission_sources.handler_notes),
        handler_id = excluded.handler_id,
        updated_at = now();

  update public.field_submissions
     set source_type = 'confidential',
         source_codename = btrim(p_codename),
         updated_at = now()
   where id = p_submission;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_SOURCE_REGISTERED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'codename', btrim(p_codename), 'handler_id', v_handler));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_siu_assign(p_submission uuid, p_user uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v public.field_submissions;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_action text;
begin
  if not private.siu_is_command() then
    raise exception 'only the Special Agent in Charge can assign SIB work';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such submission'; end if;
  if v.siu_state is distinct from 'accepted' then
    raise exception 'SIB has not taken that report yet';
  end if;
  if p_user is null then raise exception 'choose a Special Agent'; end if;
  if v.siu_assigned_to = p_user then
    raise exception 'that report is already with them';
  end if;
  if not coalesce(private.siu_standing(p_user) in
       ('owner', 'special_agent_in_charge', 'senior_special_agent', 'special_agent'),
     false) then
    raise exception 'that account is not an SIB Special Agent';
  end if;

  v_action := case when v.siu_assigned_to is null then 'assigned' else 'reassigned' end;
  if v_action = 'reassigned' and v_reason is null then
    raise exception 'say why you are moving it';
  end if;

  update public.field_submissions
     set siu_assigned_to = p_user, siu_assigned_at = now(), updated_at = now()
   where id = p_submission;

  insert into public.field_siu_actions
    (submission_id, action, actor_id, category, reason, from_user, to_user)
  values (p_submission, v_action, v_actor, v.siu_category, v_reason,
          v.siu_assigned_to, p_user);

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_ASSIGNED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'from_user', v.siu_assigned_to, 'to_user', p_user,
                             'reason', v_reason));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_siu_decide(p_submission uuid, p_accept boolean, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.siu_is_agent() then
    raise exception 'only SIB can answer a referral';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such submission'; end if;
  if v.siu_state not in ('referred', 'accepted') then
    raise exception 'that report has not been referred to SIB';
  end if;
  if v.siu_state = 'accepted' and p_accept then
    raise exception 'SIB has already taken that report';
  end if;
  if not p_accept and coalesce(btrim(coalesce(p_note, '')), '') = '' then
    raise exception 'say why SIB is not taking it';
  end if;

  update public.field_submissions
     set siu_state = case when p_accept then 'accepted' else 'declined' end,
         siu_assigned_to = case when p_accept then siu_assigned_to else null end,
         siu_assigned_at = case when p_accept then siu_assigned_at else null end,
         updated_at = now()
   where id = p_submission;

  insert into public.field_siu_actions
    (submission_id, action, actor_id, category, reason, from_user)
  values (p_submission, case when p_accept then 'accepted' else 'declined' end,
          v_actor, v.siu_category, nullif(btrim(coalesce(p_note, '')), ''),
          v.siu_assigned_to);

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor,
          case when p_accept then 'FIELD_SIU_ACCEPTED' else 'FIELD_SIU_DECLINED' end,
          'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'category', v.siu_category,
                             'note', nullif(btrim(coalesce(p_note, '')), '')));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_siu_flag(p_submission uuid, p_category text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that report is not yours to read';
  end if;
  if not private.field_siu_category_ok(p_category) then
    raise exception 'choose one of the SIB categories';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if v.status = 'draft' then raise exception 'that report has not been sent yet'; end if;
  if v.siu_state in ('referred', 'accepted') then
    raise exception 'that report is already with SIB';
  end if;

  update public.field_submissions
     set siu_state = 'flagged', siu_category = p_category, updated_at = now()
   where id = p_submission;

  insert into public.field_siu_actions
    (submission_id, action, actor_id, category, reason)
  values (p_submission, 'flagged', v_actor, p_category,
          nullif(btrim(coalesce(p_note, '')), ''));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_FLAGGED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no, 'category', p_category));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_siu_refer(p_submission uuid, p_category text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that report is not yours to read';
  end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why this needs SIB';
  end if;
  if not private.field_siu_category_ok(p_category) then
    raise exception 'choose one of the SIB categories';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if v.status = 'draft' then raise exception 'that report has not been sent yet'; end if;
  if v.siu_state in ('referred', 'accepted') then
    raise exception 'that report is already with SIB';
  end if;

  update public.field_submissions
     set siu_state = 'referred',
         siu_category = p_category,
         siu_reason = btrim(p_reason),
         siu_referred_by = v_actor,
         siu_referred_at = now(),
         siu_sensitive = siu_sensitive or p_category = 'public_corruption',
         updated_at = now()
   where id = p_submission;

  insert into public.field_siu_actions
    (submission_id, action, actor_id, category, reason)
  values (p_submission, 'referred', v_actor, p_category, btrim(p_reason));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_REFERRED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'category', p_category, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_siu_sensitive(p_submission uuid, p_on boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.siu_is_agent() then
    raise exception 'only SIB can change handling on a report';
  end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such submission'; end if;
  if v.siu_sensitive = p_on then
    raise exception 'that report is already handled that way';
  end if;

  update public.field_submissions
     set siu_sensitive = p_on, updated_at = now()
   where id = p_submission;

  insert into public.field_siu_actions (submission_id, action, actor_id, reason)
  values (p_submission,
          case when p_on then 'sensitive_on' else 'sensitive_off' end,
          v_actor, btrim(p_reason));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor,
          case when p_on then 'FIELD_SIU_RESTRICTED' else 'FIELD_SIU_UNRESTRICTED' end,
          'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_siu_unflag(p_submission uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if not private.field_submission_readable(p_submission) then
    raise exception 'that report is not yours to read';
  end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why the SIB angle is gone';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if v.siu_state is distinct from 'flagged' then
    raise exception 'only a flag can be removed here';
  end if;

  update public.field_submissions
     set siu_state = null, siu_category = null, updated_at = now()
   where id = p_submission;

  insert into public.field_siu_actions (submission_id, action, actor_id, reason)
  values (p_submission, 'unflagged', v_actor, btrim(p_reason));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SIU_UNFLAGGED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_source_reveal(p_submission uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  s public.field_submission_sources;
  v_owner boolean := coalesce((select p.is_owner from public.profiles p
                                where p.id = (select auth.uid())), false);
begin
  select * into s from public.field_submission_sources where submission_id = p_submission;
  if not found then raise exception 'no source is registered against that record'; end if;
  if s.handler_id <> v_actor and not v_owner then
    raise exception 'only the handler can see who this source is';
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_SOURCE_REVEALED', 'field_submissions', p_submission,
          jsonb_build_object('codename', s.codename, 'handler_id', s.handler_id));

  return jsonb_build_object(
    'codename', s.codename,
    'source_name', s.source_name,
    'source_contact', s.source_contact,
    'handler_notes', s.handler_notes,
    'handler_id', s.handler_id,
    'created_at', s.created_at);
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_undelete(p_submission uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.field_submissions;
begin
  if not coalesce((select is_owner from public.profiles where id = v_actor), false) then
    raise exception 'only the Owner can restore a deleted record';
  end if;

  select * into v from public.field_submissions where id = p_submission for update;
  if not found then raise exception 'no such record'; end if;
  if v.deleted_at is null then raise exception 'that record is not deleted'; end if;

  update public.field_submissions
     set deleted_at = null, deleted_by = null, delete_reason = null, updated_at = now()
   where id = p_submission;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_UNDELETED', 'field_submissions', p_submission,
          jsonb_build_object('submission_no', v.submission_no,
                             'was_deleted_by', v.deleted_by,
                             'was_reason', v.delete_reason));
end $function$
;

CREATE OR REPLACE FUNCTION public.field_submission_unlink_case(p_link uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); l public.field_submission_cases;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if coalesce(btrim(coalesce(p_reason, '')), '') = '' then
    raise exception 'say why this link is being removed';
  end if;

  select * into l from public.field_submission_cases where id = p_link for update;
  if not found then raise exception 'no such link'; end if;
  if l.unlinked_at is not null then raise exception 'that link is already removed'; end if;
  if l.relation = 'originated' then
    raise exception 'this case was opened from this record -- that cannot be unlinked';
  end if;
  if not private.field_submission_readable(l.submission_id)
     and not private.field_case_visible(l.case_id) then
    raise exception 'not authorized';
  end if;

  update public.field_submission_cases
     set unlinked_at = now(), unlinked_by = v_actor, unlink_reason = btrim(p_reason)
   where id = p_link;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'FIELD_SUBMISSION_CASE_UNLINKED', 'field_submissions', l.submission_id,
          jsonb_build_object('case_id', l.case_id, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.gang_member_add(p_gang uuid, p_person uuid, p_rank text DEFAULT NULL::text, p_callsign text DEFAULT NULL::text, p_status text DEFAULT 'Under review'::text, p_confidence text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_case uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_name text;
  v_id uuid;
begin
  if v_uid is null or not private.is_active() then
    raise exception 'gang_member_add: not authorized';
  end if;
  select name into v_name from public.persons
    where id = p_person and lifecycle is distinct from 'merged';
  if v_name is null then
    raise exception 'gang_member_add: person not found or merged';
  end if;
  if p_status is not null and p_status not in
    ('Confirmed member','Probable member','Associate','Former member','Leadership','Under review','Disputed') then
    raise exception 'gang_member_add: invalid status %', p_status;
  end if;
  if exists (
    select 1 from public.gang_members
    where gang_id = p_gang and person_id = p_person
      and status is distinct from 'Former member'
  ) then
    raise exception 'gang_member_add: this person is already on the gang roster';
  end if;
  insert into public.gang_members
    (gang_id, person_id, name, rank, callsign, status, confidence, note, case_id, created_by)
  values
    (p_gang, p_person, v_name, nullif(btrim(coalesce(p_rank,'')),''),
     nullif(btrim(coalesce(p_callsign,'')),''), coalesce(p_status,'Under review'),
     nullif(btrim(coalesce(p_confidence,'')),''), nullif(btrim(coalesce(p_note,'')),''),
     p_case, v_uid)
  returning id into v_id;
  return v_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.gang_member_review(p_member uuid, p_status text DEFAULT NULL::text, p_confidence text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_gang uuid;
  v_person uuid;
begin
  if v_uid is null or not private.is_active() then
    raise exception 'gang_member_review: not authorized';
  end if;
  select gang_id, person_id into v_gang, v_person
    from public.gang_members where id = p_member;
  if not found then
    raise exception 'gang_member_review: member not found';
  end if;
  if p_status is not null and p_status not in
    ('Confirmed member','Probable member','Associate','Former member','Leadership','Under review','Disputed') then
    raise exception 'gang_member_review: invalid status %', p_status;
  end if;
  if p_status = 'Former member' then
    raise exception 'gang_member_review: use gang_member_update to retire a member';
  end if;
  if p_status is not null and v_person is not null and exists (
    select 1 from public.gang_members
    where gang_id = v_gang and person_id = v_person and id <> p_member
      and status is distinct from 'Former member'
  ) then
    raise exception 'gang_member_review: this person already has an active membership in this gang';
  end if;
  update public.gang_members set
    status      = coalesce(p_status, status),
    confidence  = coalesce(nullif(btrim(coalesce(p_confidence,'')),''), confidence),
    reviewed_by = v_uid,
    reviewed_at = now(),
    updated_at  = now()
  where id = p_member;
end
$function$
;

CREATE OR REPLACE FUNCTION public.gang_member_update(p_member uuid, p_rank text DEFAULT NULL::text, p_callsign text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_confidence text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_case uuid DEFAULT NULL::uuid, p_joined_at date DEFAULT NULL::date, p_left_at date DEFAULT NULL::date, p_mark_reviewed boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_gang uuid;
  v_person uuid;
  v_cur_status text;
  v_status text;
  v_left date;
begin
  if v_uid is null or not private.is_active() then
    raise exception 'gang_member_update: not authorized';
  end if;
  select gang_id, person_id, status into v_gang, v_person, v_cur_status
    from public.gang_members where id = p_member;
  if not found then
    raise exception 'gang_member_update: member not found';
  end if;
  v_status := coalesce(p_status, v_cur_status);
  if v_status is not null and v_status not in
    ('Confirmed member','Probable member','Associate','Former member','Leadership','Under review','Disputed') then
    raise exception 'gang_member_update: invalid status %', v_status;
  end if;
  if v_status = 'Former member' then
    v_left := coalesce(p_left_at, current_date);
  else
    v_left := null;
    if v_person is not null and exists (
      select 1 from public.gang_members
      where gang_id = v_gang and person_id = v_person and id <> p_member
        and status is distinct from 'Former member'
    ) then
      raise exception 'gang_member_update: this person already has an active membership in this gang';
    end if;
  end if;
  update public.gang_members set
    rank        = nullif(btrim(coalesce(p_rank,'')),''),
    callsign    = nullif(btrim(coalesce(p_callsign,'')),''),
    status      = v_status,
    confidence  = nullif(btrim(coalesce(p_confidence,'')),''),
    note        = nullif(btrim(coalesce(p_note,'')),''),
    case_id     = p_case,
    joined_at   = p_joined_at,
    left_at     = v_left,
    reviewed_by = case when p_mark_reviewed then v_uid else reviewed_by end,
    reviewed_at = case when p_mark_reviewed then now() else reviewed_at end,
    updated_at  = now()
  where id = p_member;
end
$function$
;

CREATE OR REPLACE FUNCTION public.has_restricted_packet_approval(p_case uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select private.is_active() and private.can_access_case(p_case) and exists (
    select 1 from public.restricted_access_log l
    where l.entity_type = 'media' and l.entity_id = p_case and l.action = 'packet_export'
      and l.created_at > now() - interval '1 hour')
$function$
;

CREATE OR REPLACE FUNCTION public.import_legal_warrant(p_case uuid, p_subtype text, p_title text, p_priority text, p_form jsonb, p_narrative text, p_person uuid, p_classification text, p_source_submitted_at timestamp with time zone, p_source_submitter uuid, p_import_key text, p_exhibits jsonb DEFAULT '[]'::jsonb)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  r public.legal_requests; c public.cases; v_person public.persons;
  v_bureau public.bureau; v_ver uuid; ex jsonb; v_type text; v_url text; v_existing public.legal_requests;
begin
  if not private.is_owner_maintenance() then raise exception 'import is restricted to the owner'; end if;
  if btrim(coalesce(p_import_key, '')) = '' then raise exception 'an import_key is required'; end if;
  if p_subtype not in ('arrest_warrant', 'search_warrant') then
    raise exception 'import_legal_warrant handles warrant subtypes only';
  end if;
  select * into v_existing from public.legal_requests where import_key = p_import_key;
  if found then return v_existing; end if;
  select * into c from public.cases where id = p_case;
  if not found then raise exception 'case not found'; end if;
  if p_source_submitter is null
     or not exists (select 1 from public.profiles where id = p_source_submitter) then
    raise exception 'a valid historical source submitter is required';
  end if;
  if p_person is not null then
    select * into v_person from public.persons where id = p_person;
    if not found then raise exception 'person not found'; end if;
  end if;
  if p_subtype = 'arrest_warrant' and p_person is null then
    raise exception 'an arrest warrant requires a suspect from the Persons registry';
  end if;
  if p_subtype = 'search_warrant'
     and p_person is null
     and nullif(btrim(coalesce(p_form->>'search_targets', '')), '') is null then
    raise exception 'a search warrant requires a subject or at least one search target';
  end if;
  if p_classification is not null
     and p_classification not in ('standard', 'restricted', 'classified', 'sealed') then
    raise exception 'invalid classification';
  end if;
  v_bureau := private.legal_resolve_bureau(p_case);
  insert into public.legal_requests
    (request_type, subtype, case_id, created_by, responsible_bureau, classification,
     priority, title, form_data, narrative, person_id, person_name_snapshot,
     case_number_snapshot, case_title_snapshot, approval_route,
     document_status, review_status,
     submitted_to_cid_at, submitted_to_doj_at, created_at,
     source_system, source_submitted_at, source_submitter_id, imported_by, imported_at, import_key)
  values
    ('warrant', p_subtype, p_case, p_source_submitter, v_bureau,
     coalesce(p_classification, private.legal_default_classification('warrant', p_subtype)),
     p_priority, btrim(p_title), coalesce(p_form, '{}'::jsonb), p_narrative,
     p_person, v_person.name, c.case_number, c.title,
     private.legal_default_route('warrant', p_subtype),
     'finalized', 'submitted_to_doj',
     p_source_submitted_at, p_source_submitted_at, coalesce(p_source_submitted_at, now()),
     'in_city_classified_warrants', p_source_submitted_at, p_source_submitter, v_uid, now(), p_import_key)
  returning * into r;
  for ex in select * from jsonb_array_elements(coalesce(p_exhibits, '[]'::jsonb)) loop
    v_type := ex->>'type';
    v_url := btrim(coalesce(ex->>'url', ''));
    if v_type is null then continue; end if;
    if v_type = 'external_link' then
      if v_url = '' or v_url !~* '^https?://' then
        raise exception 'external-link exhibit % has a non-http(s) url', coalesce(ex->>'source_label', '?');
      end if;
    end if;
    insert into public.legal_request_exhibits
      (legal_request_id, exhibit_type, source_id, display_title, snapshot_metadata, added_by)
    values (r.id, v_type, nullif(ex->>'source_id', '')::uuid,
            coalesce(nullif(btrim(coalesce(ex->>'title', '')), ''), 'Exhibit'),
            jsonb_strip_nulls(jsonb_build_object('url', nullif(v_url, ''), 'source_label', ex->>'source_label',
              'source_system', 'in_city_classified_warrants', 'imported', true)), v_uid);
  end loop;
  v_ver := private.legal_freeze_version(r.id, 'cid_supervisor_review');
  perform private.legal_add_participant(r.id, p_source_submitter, 'requesting_investigator');
  perform private.legal_log(r.id, v_ver, 'imported', null, 'submitted_to_doj',
    'Imported from the in-city Classified Warrants system; placed in DOJ intake pending assignment.', null);
  perform private.legal_audit(r.id, 'LEGAL_IMPORTED', jsonb_build_object(
    'source_system', 'in_city_classified_warrants', 'source_submitted_at', p_source_submitted_at,
    'source_submitter_id', p_source_submitter, 'imported_by', v_uid, 'import_key', p_import_key,
    'subtype', p_subtype, 'case_id', p_case));
  select * into r from public.legal_requests where id = r.id;
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.import_rollback_by_key(p_import_key text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); rid uuid; n integer := 0;
begin
  if not private.is_owner_maintenance() then raise exception 'rollback is restricted to the owner'; end if;
  if btrim(coalesce(p_import_key, '')) = '' then raise exception 'an import_key is required'; end if;
  for rid in select id from public.legal_requests where import_key = p_import_key loop
    perform private.legal_audit(rid, 'LEGAL_IMPORT_ROLLBACK',
      jsonb_build_object('import_key', p_import_key, 'rolled_back_by', v_uid));
    delete from public.legal_request_signatures  where legal_request_id = rid;
    delete from public.legal_request_actions     where legal_request_id = rid;
    delete from public.legal_request_exhibits    where legal_request_id = rid;
    delete from public.legal_request_participants where legal_request_id = rid;
    delete from public.mdt_wanted_projections    where legal_request_id = rid;
    update public.legal_requests set current_version_id = null where id = rid;
    delete from public.legal_request_versions    where legal_request_id = rid;
    delete from public.legal_requests            where id = rid;
    n := n + 1;
  end loop;
  return n;
end $function$
;

CREATE OR REPLACE FUNCTION public.issue_legal_request(p_request uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_response_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_ver uuid;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'approved' then
    raise exception 'only an approved request can be issued';
  end if;
  if r.fulfilment_status <> 'unissued' then raise exception 'request is already issued'; end if;
  if not private.can_fulfil_legal(p_request, v_uid) then
    raise exception 'only an authorized CID member on this case may record issue';
  end if;
  update public.legal_requests
     set fulfilment_status = 'issued', issued_by = v_uid, issued_at = now(),
         expires_at = coalesce(expires_at, p_expires_at),
         response_deadline = coalesce(p_response_deadline, response_deadline)
   where id = p_request returning * into r;
  v_ver := private.legal_freeze_version(p_request, 'issued');
  select * into r from public.legal_requests where id = p_request;
  perform private.legal_log(p_request, v_ver, 'issued', 'unissued', 'issued', null, null);
  perform private.legal_audit(p_request, 'LEGAL_ISSUED',
    jsonb_build_object('expires_at', r.expires_at, 'response_deadline', r.response_deadline));
  perform private.mdt_project(p_request, 'wanted');
  perform private.legal_notify(r.created_by, p_request, 'legal_update',
    'Your ' || r.request_type || ' has been issued.');
  perform private.legal_notify(r.assigned_ada_id, p_request, 'legal_update',
    'An approved ' || r.request_type || ' has been issued.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.joint_case_add_members(p_case uuid, p_members jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); v_n int;
begin
  if not private.can_manage_joint(p_case) then raise exception 'not permitted to manage this case'; end if;
  if not exists (select 1 from public.cases where id = p_case and is_joint_case) then
    raise exception 'not a joint case';
  end if;
  v_n := private.joint_apply_members(p_case, p_members, v_uid);
  return jsonb_build_object('case_id', p_case, 'members_added', v_n);
end $function$
;

CREATE OR REPLACE FUNCTION public.joint_case_end(p_case uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); c public.cases; rec record;
begin
  if not private.can_manage_joint(p_case) then raise exception 'not permitted to manage this case'; end if;
  select * into c from public.cases where id = p_case for update;
  if not found then raise exception 'case not found'; end if;
  if not c.is_joint_case then raise exception 'not a joint case'; end if;
  for rec in select * from public.case_assignments
              where case_id = p_case and assignment_source = 'joint_case' and removed_at is null loop
    update public.case_assignments
       set removed_at = now(), removed_by = v_uid,
           removal_reason = coalesce(p_note, 'joint case ended')
     where id = rec.id;
    insert into public.notifications (user_id, type, payload)
    values (rec.officer_id, 'joint_case_ended', jsonb_build_object(
      'case_id', p_case, 'case_number', c.case_number,
      'reason', 'Joint case ' || coalesce(c.case_number, '') || ' has ended — temporary access closed.',
      'actor_id', v_uid, 'actor_name', (select display_name from public.profiles where id = v_uid)));
  end loop;
  -- The bureau never moved (see header note), so nothing to restore there;
  -- originating/created/ended fields preserve the joint history.
  update public.cases
     set is_joint_case = false, joint_case_ended_by = v_uid, joint_case_ended_at = now()
   where id = p_case;
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, 'JOINT_CASE_ENDED', 'cases', p_case);
end $function$
;

CREATE OR REPLACE FUNCTION public.joint_case_remove_member(p_case uuid, p_officer uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); a public.case_assignments; v_cn text;
begin
  if not private.can_manage_joint(p_case) then raise exception 'not permitted to manage this case'; end if;
  select * into a from public.case_assignments
   where case_id = p_case and officer_id = p_officer and assignment_source = 'joint_case'
     and removed_at is null for update;
  if not found then raise exception 'no active joint assignment for that member'; end if;
  update public.case_assignments
     set removed_at = now(), removed_by = v_uid, removal_reason = p_reason
   where id = a.id;
  select case_number into v_cn from public.cases where id = p_case;
  insert into public.notifications (user_id, type, payload)
  values (p_officer, 'joint_case_removed', jsonb_build_object(
    'case_id', p_case, 'case_number', v_cn,
    'reason', 'Your joint-case access to ' || coalesce(v_cn, 'the case') || ' was removed'
      || case when p_reason is not null then ': ' || p_reason else '.' end,
    'actor_id', v_uid, 'actor_name', (select display_name from public.profiles where id = v_uid)));
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, 'JOINT_MEMBER_REMOVED', 'case_assignments', p_case);
end $function$
;

CREATE OR REPLACE FUNCTION public.justice_appoint(p_user uuid, p_role text, p_reason text DEFAULT NULL::text, p_bureau bureau DEFAULT NULL::bureau)
 RETURNS justice_memberships
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); m public.justice_memberships;
        me public.profiles; t public.profiles; v_cid_authority boolean;
        v_ag boolean; v_tr uuid; v_led int := 0; v_is_test boolean; rec record;
begin
  if p_role not in ('prosecutor', 'judge', 'attorney_general') then
    raise exception 'role must be prosecutor, judge, or attorney_general';
  end if;
  if p_role = 'prosecutor' and (p_bureau is null or p_bureau not in ('major_crimes', 'street_crimes')) then
    raise exception 'a prosecutor needs a home bureau: Major Crimes or Street Crimes';
  end if;
  if p_role <> 'prosecutor' and p_bureau is not null then
    raise exception 'only prosecutors carry a home bureau';
  end if;
  select * into me from public.profiles where id = v_uid;
  v_ag := coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false);
  v_cid_authority := coalesce(me.is_owner, false)
    or (coalesce(me.active, false) and me.role in ('deputy_director', 'director'));
  if p_role = 'attorney_general' then
    if not coalesce(me.is_owner, false) then
      raise exception 'only the Owner may appoint an Attorney General';
    end if;
  elsif not (v_ag or v_cid_authority) then
    raise exception 'only the Attorney General, Deputy Director+, or Owner may appoint DOJ members';
  end if;
  if p_user = v_uid and not coalesce(me.is_owner, false) then
    raise exception 'you cannot appoint yourself';
  end if;
  select * into t from public.profiles where id = p_user;
  if t.id is null or t.removed_at is not null or coalesce(t.login_denied, false)
     or coalesce(t.is_test, false) or coalesce(t.is_system, false) then
    raise exception 'target account is not eligible for a DOJ appointment';
  end if;

  if coalesce(t.active, false) then
    if not v_cid_authority then
      raise exception 'moving an active CID member into the DOJ requires Deputy Director+ or Owner';
    end if;
    select count(*) into v_led from public.cases c
     where c.lead_detective_id = p_user and c.status <> 'closed' and c.archived_at is null;
    insert into public.member_transfers
      (user_id, direction, status, requested_role, target_bureau, from_role, from_division,
       reason, requested_by, cid_decided_by, cid_decided_at,
       doj_decided_by, doj_decided_at, effective_by, effective_at,
       handover)
    values (p_user, 'cid_to_doj', 'effective', p_role, p_bureau, t.role::text, t.division::text,
            coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Direct DOJ assignment'),
            v_uid, v_uid, now(), v_uid, now(), v_uid, now(),
            jsonb_build_object('direct', true, 'led_cases_open', v_led,
                               'led_cases_interim_lead', case when v_led > 0 then v_uid end))
    returning id into v_tr;
    update public.profiles set active = false where id = p_user;
    insert into public.role_events
      (target_id, actor_id, old_role, new_role, old_division, new_division,
       old_active, new_active, reason, source, source_id)
    values (p_user, v_uid, t.role, t.role, t.division, t.division,
            true, false, 'Assigned to DOJ: ' || p_role, 'doj_transfer', v_tr);
    update public.case_assignments
       set removed_at = now(), removed_by = v_uid, removal_reason = 'Assigned to DOJ'
     where officer_id = p_user and removed_at is null;
    if v_led > 0 then
      select u.email like 'rls-test-%@cidportal.test' into v_is_test
        from auth.users u where u.id = v_uid;
      for rec in select c.id, c.case_number from public.cases c
                  where c.lead_detective_id = p_user and c.status <> 'closed' and c.archived_at is null
      loop
        update public.cases set lead_detective_id = v_uid where id = rec.id;
        insert into public.audit_log (actor_id, action, entity, entity_id, detail)
        values (v_uid, 'CASE_LEAD_INTERIM', 'cases', rec.id,
                jsonb_build_object('from', p_user, 'to', v_uid, 'transfer', v_tr,
                                   'reason', 'Previous lead assigned to DOJ'));
      end loop;
      insert into public.notifications (user_id, type, payload)
      select p.id, 'membership_update', jsonb_build_object(
        'reason', coalesce(t.display_name, 'A member') || ' was assigned to the DOJ — '
          || v_led || ' open case(s) they led were handed to '
          || coalesce(me.display_name, 'the assigning authority') || ' as interim lead.')
        from public.profiles p
       where p.active and p.removed_at is null and p.id <> v_uid
         and p.role in ('deputy_director', 'director')
         and (not coalesce(v_is_test, false)
              or exists (select 1 from auth.users u
                          where u.id = p.id and u.email like 'rls-test-%@cidportal.test'));
    end if;
  end if;

  insert into public.justice_memberships
    (user_id, agency, justice_role, active, approved_by, approved_at,
     ended_at, expires_at, prosecutor_bureau)
  values (p_user, case when p_role = 'judge' then 'judiciary' else 'doj' end,
          p_role, true, v_uid, now(), null, null,
          case when p_role = 'prosecutor' then p_bureau end)
  on conflict (user_id) do update
    set agency = excluded.agency, justice_role = excluded.justice_role,
        active = true, approved_by = excluded.approved_by, approved_at = excluded.approved_at,
        ended_at = null, expires_at = null,
        prosecutor_bureau = excluded.prosecutor_bureau;
  select * into m from public.justice_memberships where user_id = p_user;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'JUSTICE_APPOINTED', 'justice_memberships', p_user,
          jsonb_build_object('role', p_role, 'bureau', p_bureau,
                             'direct', coalesce(t.active, false),
                             'transfer', v_tr, 'led_cases_open', v_led,
                             'reason', left(coalesce(p_reason, ''), 300)));
  insert into public.notifications (user_id, type, payload)
  values (p_user, 'justice_membership_update', jsonb_build_object(
    'reason', 'You were appointed ' || replace(p_role, '_', ' ')
      || coalesce(' (' || private.bureau_label(p_bureau::text) || ' queue)', '')
      || case when coalesce(t.active, false)
              then ' — your CID membership has ended and your DOJ access is active now.'
              else ' in the DOJ legal-review workspace.' end));
  return m;
end $function$
;

CREATE OR REPLACE FUNCTION public.justice_directory()
 RETURNS TABLE(user_id uuid, display_name text, agency text, justice_role text, active boolean, justice_identifier text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select m.user_id, p.display_name, m.agency, m.justice_role, m.active, m.justice_identifier
    from public.justice_memberships m
    join public.profiles p on p.id = m.user_id
   where p.removed_at is null
     and (not p.is_test or private.is_test_user((select auth.uid())))
     and (private.justice_role() is not null
          or private.is_active()
          or private.owner_flag((select auth.uid())))
   order by p.display_name
$function$
;

CREATE OR REPLACE FUNCTION public.justice_end_coverage(p_coverage uuid, p_reason text DEFAULT NULL::text)
 RETURNS prosecutor_coverage
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); c public.prosecutor_coverage;
begin
  if not (coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)
          or private.owner_flag(v_uid)) then
    raise exception 'only the Attorney General or Owner may manage coverage';
  end if;
  select * into c from public.prosecutor_coverage where id = p_coverage for update;
  if not found then raise exception 'coverage not found'; end if;
  if c.ended_at is not null then raise exception 'coverage already ended'; end if;
  update public.prosecutor_coverage
     set ended_at = now(), ended_by = v_uid where id = p_coverage returning * into c;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'PROSECUTOR_COVERAGE_ENDED', 'prosecutor_coverage', c.id,
          jsonb_build_object('prosecutor', c.prosecutor_id, 'bureau', c.bureau,
                             'reason', left(coalesce(p_reason, ''), 300)));
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.justice_membership_request_submit(p_request uuid)
 RETURNS justice_membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.justice_membership_requests; v_uid uuid := (select auth.uid()); v_action text;
begin
  if exists (select 1 from public.profiles p where p.id = v_uid and p.login_denied) then
    raise exception 'your portal access has been denied';
  end if;
  select * into r from public.justice_membership_requests where id = p_request for update;
  if not found or r.applicant_id is distinct from v_uid then raise exception 'not your request'; end if;
  if r.status not in ('draft', 'correction_requested') then raise exception 'request is not editable'; end if;
  if btrim(coalesce(r.display_name, '')) = '' or btrim(coalesce(r.reason, '')) = '' then
    raise exception 'display name and reason are required';
  end if;
  v_action := case when r.status = 'correction_requested' then 'resubmitted' else 'submitted' end;
  update public.justice_membership_requests
     set status = 'pending', submitted_at = now(), applicant_visible_decision_note = null
   where id = p_request returning * into r;
  perform private.jmr_history(p_request, v_action,
    case when v_action = 'resubmitted' then 'correction_requested' else 'draft' end,
    'pending', null, false);
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, upper(v_action), 'justice_membership_requests', p_request);
  if not private.is_test_user(v_uid) then
    insert into public.notifications (user_id, type, payload)
    select p.id, 'justice_membership_request',
           jsonb_build_object('request_id', p_request, 'applicant_name', r.display_name,
             'requested_role', r.requested_justice_role,
             'reason', 'Justice membership request awaiting review: ' || r.display_name,
             'actor_id', v_uid, 'actor_name', r.display_name)
      from public.profiles p
     where p.removed_at is null and not p.is_test
       and private.can_review_justice_role(p.id, r.requested_justice_role);
  end if;
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.justice_membership_request_withdraw(p_request uuid)
 RETURNS justice_membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.justice_membership_requests; v_uid uuid := (select auth.uid()); v_from text;
begin
  select * into r from public.justice_membership_requests where id = p_request for update;
  if not found or r.applicant_id is distinct from v_uid then raise exception 'not your request'; end if;
  if r.status not in ('draft', 'pending', 'correction_requested') then raise exception 'request cannot be withdrawn'; end if;
  v_from := r.status;
  update public.justice_membership_requests set status = 'withdrawn' where id = p_request returning * into r;
  perform private.jmr_history(p_request, 'withdrawn', v_from, 'withdrawn', null, false);
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, 'WITHDRAWN', 'justice_membership_requests', p_request);
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.justice_migration_review()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when not (private.owner_flag((select auth.uid()))
              or coalesce(private.justice_role_effective((select auth.uid())) = 'attorney_general', false))
    then jsonb_build_object('error', 'owner or attorney general only')
    else jsonb_build_object(
      'legacy_roles', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', m.user_id, 'name', p.display_name, 'role', m.justice_role,
          'active', m.active, 'effective', case m.justice_role
            when 'assistant_district_attorney' then 'prosecutor'
            when 'district_attorney' then 'prosecutor' else m.justice_role end)), '[]')
        from public.justice_memberships m
        left join public.profiles p on p.id = m.user_id
        where m.justice_role in ('assistant_district_attorney', 'district_attorney')),
      'prosecutors_without_bureau', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', m.user_id, 'name', p.display_name, 'role', m.justice_role)), '[]')
        from public.justice_memberships m
        left join public.profiles p on p.id = m.user_id
        where m.active and m.prosecutor_bureau is null
          and m.justice_role in ('prosecutor', 'assistant_district_attorney', 'district_attorney')),
      'dual_identity', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', m.user_id, 'name', p.display_name,
          'justice_role', m.justice_role, 'cid_role', p.role, 'cid_active', p.active)), '[]')
        from public.justice_memberships m
        join public.profiles p on p.id = m.user_id
        where m.active and coalesce(p.active, false)),
      'requests_in_retired_states', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'id', r.id, 'number', r.request_number, 'status', r.review_status)), '[]')
        from public.legal_requests r
        where r.review_status in ('submitted_to_doj', 'ada_review', 'da_review', 'ag_review')),
      'requests_assigned_to_inactive', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'id', r.id, 'number', r.request_number, 'status', r.review_status)), '[]')
        from public.legal_requests r
        where (r.assigned_prosecutor_id is not null
               and not private.is_justice_active(r.assigned_prosecutor_id)
               and r.review_status = 'prosecutor_review')
           or (r.assigned_judge_id is not null
               and not private.is_justice_active(r.assigned_judge_id)
               and r.review_status = 'judicial_review')),
      'cases_missing_responsible_bureau', (
        select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'number', c.case_number)), '[]')
        from public.cases c
        where c.bureau = 'JTF' and c.originating_bureau is null),
      'self_review_conflicts', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'id', r.id, 'number', r.request_number,
          'holder', coalesce(r.assigned_prosecutor_id, r.assigned_judge_id))), '[]')
        from public.legal_requests r
        where (r.assigned_prosecutor_id is not null
               and private.legal_is_conflicted(r.id, r.assigned_prosecutor_id))
           or (r.assigned_judge_id is not null
               and private.legal_is_conflicted(r.id, r.assigned_judge_id))))
  end
$function$
;

CREATE OR REPLACE FUNCTION public.justice_set_coverage(p_user uuid, p_bureau bureau, p_reason text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS prosecutor_coverage
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); c public.prosecutor_coverage;
begin
  if not (coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)
          or private.owner_flag(v_uid)) then
    raise exception 'only the Attorney General or Owner may manage coverage';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  if p_bureau not in ('major_crimes', 'street_crimes') then
    raise exception 'coverage bureau must be Major Crimes or Street Crimes';
  end if;
  if coalesce(private.justice_role_effective(p_user) = 'prosecutor', false) is not true then
    raise exception 'coverage can only be granted to an active Prosecutor';
  end if;
  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'the expiry must be in the future';
  end if;
  insert into public.prosecutor_coverage (prosecutor_id, bureau, reason, authorized_by, expires_at)
  values (p_user, p_bureau, btrim(p_reason), v_uid, p_expires_at)
  returning * into c;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'PROSECUTOR_COVERAGE_GRANTED', 'prosecutor_coverage', c.id,
          jsonb_build_object('prosecutor', p_user, 'bureau', p_bureau,
                             'expires_at', p_expires_at, 'reason', left(p_reason, 300)));
  insert into public.notifications (user_id, type, payload)
  values (p_user, 'justice_membership_update', jsonb_build_object(
    'reason', 'You were granted temporary prosecutor coverage for ' || private.bureau_label(p_bureau::text)
      || coalesce(' until ' || to_char(p_expires_at, 'YYYY-MM-DD HH24:MI'), '') || '.'));
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_admin_cancel(p_request uuid, p_reason text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
begin
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status in ('approved', 'denied', 'withdrawn', 'declined', 'cancelled', 'superseded') then
    raise exception 'decided or terminal requests cannot be cancelled';
  end if;
  if not (private.can_approve_legal(p_request, v_uid)
          or coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)
          or private.owner_flag(v_uid)) then
    raise exception 'not authorized to cancel this request';
  end if;
  update public.legal_requests
     set review_status = 'cancelled',
         assigned_prosecutor_id = null, prosecutor_claimed_at = null,
         assigned_judge_id = null
   where id = p_request returning * into r;
  perform private.legal_log(p_request, r.current_version_id, 'cancelled', null, 'cancelled', p_reason, null);
  perform private.legal_audit(p_request, 'LEGAL_CANCELLED', jsonb_build_object('reason', left(p_reason, 300)));
  perform private.legal_notify(r.created_by, p_request, 'legal_update',
    'Your ' || r.request_type || ' request was cancelled: ' || p_reason);
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_assign_prosecutor(p_request uuid, p_prosecutor uuid, p_reason text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_cap text;
begin
  if not (coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)
          or private.owner_flag(v_uid)) then
    raise exception 'only the Attorney General may assign prosecutors';
  end if;
  if private.justice_role_effective(p_prosecutor) is distinct from 'prosecutor' then
    raise exception 'the assignee must be an active Prosecutor';
  end if;
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status not in ('prosecutor_queue', 'prosecutor_review') then
    raise exception 'request is not at the prosecutorial stage';
  end if;
  if not (r.responsible_bureau = any (private.prosecutor_bureaus_of(p_prosecutor))) then
    raise exception 'the assignee does not cover the % queue — grant temporary coverage first (justice_set_coverage)', r.responsible_bureau;
  end if;
  if p_prosecutor = r.created_by then
    raise exception 'conflict of interest: the assignee created this request';
  end if;
  if private.legal_is_conflicted(p_request, p_prosecutor) then
    raise exception 'conflict of interest: the assignee participated in this case as an investigator — recusal required';
  end if;
  if r.assigned_prosecutor_id = p_prosecutor then
    raise exception 'this prosecutor already holds the request';
  end if;
  if r.assigned_prosecutor_id is not null and btrim(coalesce(p_reason, '')) = '' then
    raise exception 'a reason is required to reassign a claimed request';
  end if;
  v_cap := private.legal_capacity(v_uid, 'doj');
  if r.assigned_prosecutor_id is not null then
    perform private.legal_end_participant(p_request, r.assigned_prosecutor_id, 'prosecutor');
  end if;
  update public.legal_requests
     set review_status = 'prosecutor_review',
         assigned_prosecutor_id = p_prosecutor, prosecutor_claimed_at = now()
   where id = p_request returning * into r;
  perform private.legal_add_participant(p_request, p_prosecutor, 'prosecutor');
  perform private.legal_log(p_request, r.current_version_id, 'prosecutor_assigned',
    null, 'prosecutor_review', p_reason, 'capacity: ' || v_cap);
  perform private.legal_audit(p_request, 'LEGAL_PROSECUTOR_ASSIGNED',
    jsonb_build_object('prosecutor', p_prosecutor, 'reason', left(coalesce(p_reason, ''), 300),
                       'capacity', v_cap, 'bureau', r.responsible_bureau));
  perform private.legal_notify(p_prosecutor, p_request, 'legal_request',
    'The Attorney General assigned you a ' || r.request_type || ' request for review.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_claim_prosecutor(p_request uuid)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_cap text;
begin
  if private.justice_role_effective(v_uid) is distinct from 'prosecutor' then
    raise exception 'only an active Prosecutor may claim from the queue';
  end if;
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'prosecutor_queue' then
    raise exception 'request is no longer in the prosecutor queue';
  end if;
  if not (r.responsible_bureau = any (private.prosecutor_bureaus_of(v_uid))) then
    raise exception 'this request belongs to the % queue — outside your bureau (the Attorney General can grant temporary coverage)', r.responsible_bureau;
  end if;
  if r.classification = 'sealed' then
    raise exception 'sealed requests require formal assignment by the Attorney General';
  end if;
  if r.created_by = v_uid then
    raise exception 'conflict of interest: you created this request';
  end if;
  if private.legal_is_conflicted(p_request, v_uid) then
    raise exception 'conflict of interest: you participated in this case as an investigator — recusal required';
  end if;
  v_cap := private.legal_capacity(v_uid, 'doj');
  update public.legal_requests
     set review_status = 'prosecutor_review',
         assigned_prosecutor_id = v_uid, prosecutor_claimed_at = now()
   where id = p_request returning * into r;
  perform private.legal_add_participant(p_request, v_uid, 'prosecutor');
  perform private.legal_log(p_request, r.current_version_id, 'prosecutor_claimed',
    'prosecutor_queue', 'prosecutor_review', null, 'capacity: ' || v_cap);
  perform private.legal_audit(p_request, 'LEGAL_PROSECUTOR_CLAIMED',
    jsonb_build_object('capacity', v_cap, 'bureau', r.responsible_bureau));
  perform private.legal_notify(r.created_by, p_request, 'legal_update',
    'A prosecutor claimed your ' || r.request_type || ' request for review.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_hold_lift(p_hold uuid, p_reason text DEFAULT NULL::text)
 RETURNS legal_holds
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h public.legal_holds; v_uid uuid := (select auth.uid());
begin
  if not private.is_command() then raise exception 'lifting a legal hold is a command action'; end if;
  select * into h from public.legal_holds where id = p_hold for update;
  if not found then raise exception 'legal hold not found'; end if;
  if h.lifted_at is not null then raise exception 'this legal hold has already been lifted'; end if;
  update public.legal_holds
     set lifted_at = now(), lifted_by = v_uid, lift_reason = nullif(btrim(coalesce(p_reason, '')), '')
   where id = p_hold returning * into h;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'LEGAL_HOLD_LIFTED', 'legal_holds', h.id,
          jsonb_build_object('case_id', h.case_id, 'legal_request_id', h.legal_request_id, 'reason', h.lift_reason));
  return h;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_hold_place(p_case uuid, p_legal_request uuid, p_reason text)
 RETURNS legal_holds
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h public.legal_holds; v_uid uuid := (select auth.uid());
begin
  if not private.is_command() then raise exception 'placing a legal hold is a command action'; end if;
  if num_nonnulls(p_case, p_legal_request) <> 1 then
    raise exception 'specify exactly one target — a case or a legal request'; end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  if p_case is not null and not exists (select 1 from public.cases where id = p_case) then
    raise exception 'case not found'; end if;
  if p_legal_request is not null and not exists (select 1 from public.legal_requests where id = p_legal_request) then
    raise exception 'legal request not found'; end if;
  insert into public.legal_holds (case_id, legal_request_id, reason, placed_by)
  values (p_case, p_legal_request, btrim(p_reason), v_uid)
  returning * into h;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'LEGAL_HOLD_PLACED', 'legal_holds', h.id,
          jsonb_build_object('case_id', p_case, 'legal_request_id', p_legal_request, 'reason', btrim(p_reason)));
  return h;
exception when unique_violation then
  raise exception 'this target is already under an active legal hold';
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_internal_notes(p_request uuid)
 RETURNS TABLE(id uuid, actor_id uuid, action text, internal_note text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
begin
  select * into r from public.legal_requests where id = p_request;
  if not found then raise exception 'request not found'; end if;
  if not (coalesce(r.assigned_ada_id = v_uid, false)
          or coalesce(r.assigned_judge_id = v_uid, false)
          or coalesce(private.justice_role_of(v_uid) in ('district_attorney', 'attorney_general'), false)
          or private.owner_flag(v_uid)) then
    raise exception 'not authorized';
  end if;
  return query
    select a.id, a.actor_id, a.action, a.internal_note, a.created_at
      from public.legal_request_actions a
     where a.legal_request_id = p_request and a.internal_note is not null
     order by a.created_at;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_mark_superseded(p_old uuid, p_new uuid, p_reason text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); o public.legal_requests; n public.legal_requests;
begin
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  if p_old = p_new then raise exception 'a request cannot supersede itself'; end if;
  select * into o from public.legal_requests where id = p_old for update;
  if not found then raise exception 'original request not found'; end if;
  select * into n from public.legal_requests where id = p_new;
  if not found then raise exception 'replacement request not found'; end if;
  if o.review_status not in ('approved', 'denied', 'declined') then
    raise exception 'only decided requests can be superseded';
  end if;
  if n.review_status <> 'approved' then
    raise exception 'the replacement must be an approved request';
  end if;
  if n.case_id is distinct from o.case_id then
    raise exception 'the replacement must belong to the same case';
  end if;
  if not (private.can_approve_legal(p_old, v_uid)
          or coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)
          or private.owner_flag(v_uid)) then
    raise exception 'not authorized to supersede this request';
  end if;
  update public.legal_requests
     set review_status = 'superseded', superseded_by_id = p_new,
         fulfilment_status = case when fulfilment_status = 'issued' then 'revoked' else fulfilment_status end,
         revoked_at = case when fulfilment_status = 'issued' then now() else revoked_at end,
         revoked_by = case when fulfilment_status = 'issued' then v_uid else revoked_by end,
         revoke_reason = case when fulfilment_status = 'issued'
                              then 'Superseded: ' || left(p_reason, 280) else revoke_reason end
   where id = p_old returning * into o;
  update public.legal_requests set amends_request_id = p_old where id = p_new and amends_request_id is null;
  perform private.legal_log(p_old, o.current_version_id, 'superseded', null, 'superseded', p_reason, null);
  perform private.legal_audit(p_old, 'LEGAL_SUPERSEDED',
    jsonb_build_object('by', p_new, 'reason', left(p_reason, 300)));
  return o;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_request_case_brief(p_request uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when not private.can_view_legal_request(p_request, (select auth.uid()))
    then jsonb_build_object('error', 'request not found or not accessible')
    else (
      select jsonb_build_object(
        'case', jsonb_build_object(
          'number', c.case_number, 'title', c.title, 'status', c.status,
          'stage', c.investigative_stage, 'assigned_unit', c.bureau,
          'responsible_bureau', r.responsible_bureau),
        'exhibits', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'id', e.id, 'type', e.exhibit_type, 'title', e.display_title,
            'rationale', e.rationale) order by e.created_at), '[]')
          from public.legal_request_exhibits e where e.legal_request_id = r.id),
        'referenced_reports', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'id', rp.id, 'template', rp.template, 'finalized', rp.finalized,
            'author_id', rp.author_id, 'fields', rp.fields) order by rp.created_at), '[]')
          from public.legal_request_exhibits e
          join public.reports rp on rp.id = e.source_id
          where e.legal_request_id = r.id and e.exhibit_type = 'finalized_report'),
        'referenced_media', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'id', m.id, 'title', m.title, 'type', m.type,
            'external_url', m.external_url, 'uploaded_by', m.uploaded_by,
            'evidence_ref', m.evidence_ref) order by m.created_at), '[]')
          from public.legal_request_exhibits e
          join public.media m on m.id = e.source_id
          where e.legal_request_id = r.id and e.exhibit_type in ('case_media', 'evidence')))
      from public.legal_requests r
      join public.cases c on c.id = r.case_id
      where r.id = p_request)
  end
$function$
;

CREATE OR REPLACE FUNCTION public.legal_request_people(p_request uuid)
 RETURNS TABLE(id uuid, display_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.can_view_legal_request(p_request, (select auth.uid())) then
    raise exception 'not authorized';
  end if;
  return query
    select distinct p.id, p.display_name
      from public.profiles p
     where p.id in (
       select r.created_by from public.legal_requests r where r.id = p_request
       union select r.cid_reviewed_by from public.legal_requests r where r.id = p_request
       union select r.assigned_ada_id from public.legal_requests r where r.id = p_request
       union select r.assigned_judge_id from public.legal_requests r where r.id = p_request
       union select r.decided_by from public.legal_requests r where r.id = p_request
       union select r.issued_by from public.legal_requests r where r.id = p_request
       union select r.executed_by from public.legal_requests r where r.id = p_request
       union select r.served_by from public.legal_requests r where r.id = p_request
       union select pa.user_id from public.legal_request_participants pa where pa.legal_request_id = p_request
       union select a.actor_id from public.legal_request_actions a where a.legal_request_id = p_request);
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_return_to_prosecutor_queue(p_request uuid, p_reason text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'prosecutor_review' then
    raise exception 'request is not under prosecutorial review';
  end if;
  if not (r.assigned_prosecutor_id = v_uid
          or coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)
          or private.owner_flag(v_uid)) then
    raise exception 'only the holding prosecutor or the Attorney General may return this to the queue';
  end if;
  if r.assigned_prosecutor_id is not null then
    perform private.legal_end_participant(p_request, r.assigned_prosecutor_id, 'prosecutor');
  end if;
  update public.legal_requests
     set review_status = 'prosecutor_queue',
         assigned_prosecutor_id = null, prosecutor_claimed_at = null,
         queue_entered_at = now()
   where id = p_request returning * into r;
  perform private.legal_log(p_request, r.current_version_id, 'prosecutor_unassigned',
    'prosecutor_review', 'prosecutor_queue', p_reason, null);
  perform private.legal_audit(p_request, 'LEGAL_PROSECUTOR_UNASSIGNED',
    jsonb_build_object('reason', left(coalesce(p_reason, ''), 300)));
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_search(q text)
 RETURNS SETOF legal_requests
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select r.* from public.legal_requests r
  where btrim(coalesce(q, '')) <> ''
    and (r.request_number ilike '%' || q || '%'
      or r.case_number_snapshot ilike '%' || q || '%'
      or r.title ilike '%' || q || '%'
      or r.person_name_snapshot ilike '%' || q || '%'
      or r.recipient_name ilike '%' || q || '%'
      or r.responsible_bureau::text ilike q
      or r.review_status ilike q
      or r.fulfilment_status ilike q)
  order by r.created_at desc
  limit 50
$function$
;

CREATE OR REPLACE FUNCTION public.legal_seized_item_add(p_request uuid, p_item text, p_quantity text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_evidence uuid DEFAULT NULL::uuid, p_person uuid DEFAULT NULL::uuid, p_vehicle uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_evidence_bag text DEFAULT NULL::text, p_storage_location text DEFAULT NULL::text, p_media uuid DEFAULT NULL::uuid, p_report uuid DEFAULT NULL::uuid, p_disposition text DEFAULT 'held'::text)
 RETURNS legal_seized_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); s public.legal_seized_items; r public.legal_requests;
begin
  select * into r from public.legal_requests where id = p_request;
  if not found then raise exception 'request not found'; end if;
  if r.request_type <> 'warrant' then raise exception 'seized items belong to a warrant'; end if;
  if not private.can_fulfil_legal(p_request, v_uid) then
    raise exception 'only an authorized CID member on this case may log seized items';
  end if;
  if btrim(coalesce(p_item, '')) = '' then raise exception 'an item description is required'; end if;
  if p_category is not null and p_category not in
     ('weapon', 'narcotics', 'currency', 'electronics', 'document', 'vehicle', 'other') then
    raise exception 'invalid category';
  end if;
  if coalesce(p_disposition, 'held') not in ('held', 'returned', 'destroyed', 'forfeited', 'other') then
    raise exception 'invalid disposition';
  end if;
  if p_media is not null and (r.case_id is null or not exists (
     select 1 from public.media m where m.id = p_media and m.case_id = r.case_id)) then
    raise exception 'linked media must belong to this warrant''s case';
  end if;
  if p_report is not null and (r.case_id is null or not exists (
     select 1 from public.reports rp where rp.id = p_report and rp.case_id = r.case_id)) then
    raise exception 'linked report must belong to this warrant''s case';
  end if;
  insert into public.legal_seized_items
    (legal_request_id, item, quantity, category, evidence_id, person_id, vehicle_id, notes, added_by,
     evidence_bag, storage_location, media_id, report_id, disposition)
  values (p_request, btrim(p_item), nullif(btrim(coalesce(p_quantity, '')), ''), p_category,
          p_evidence, p_person, p_vehicle, nullif(btrim(coalesce(p_notes, '')), ''), v_uid,
          nullif(btrim(coalesce(p_evidence_bag, '')), ''), nullif(btrim(coalesce(p_storage_location, '')), ''),
          p_media, p_report, coalesce(p_disposition, 'held'))
  returning * into s;
  perform private.legal_audit(p_request, 'LEGAL_SEIZED_ITEM_ADDED',
    jsonb_build_object('item', btrim(p_item), 'category', p_category,
                       'quantity', nullif(btrim(coalesce(p_quantity, '')), ''),
                       'disposition', coalesce(p_disposition, 'held'),
                       'evidence_bag', nullif(btrim(coalesce(p_evidence_bag, '')), '')));
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_seized_item_remove(p_item uuid, p_reason text)
 RETURNS legal_seized_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); s public.legal_seized_items;
begin
  select * into s from public.legal_seized_items where id = p_item;
  if not found then raise exception 'seized item not found'; end if;
  if not private.can_fulfil_legal(s.legal_request_id, v_uid) then
    raise exception 'only an authorized CID member on this case may strike seized items';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required to strike a seized item'; end if;
  update public.legal_seized_items
     set removed_at = now(), removed_by = v_uid, removal_reason = btrim(p_reason)
   where id = p_item returning * into s;
  perform private.legal_audit(s.legal_request_id, 'LEGAL_SEIZED_ITEM_STRUCK',
    jsonb_build_object('item', s.item, 'reason', btrim(p_reason)));
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.legal_seized_item_set_disposition(p_item uuid, p_disposition text, p_note text DEFAULT NULL::text)
 RETURNS legal_seized_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); s public.legal_seized_items;
begin
  select * into s from public.legal_seized_items where id = p_item;
  if not found then raise exception 'seized item not found'; end if;
  if not private.can_fulfil_legal(s.legal_request_id, v_uid) then
    raise exception 'only an authorized CID member on this case may set a disposition';
  end if;
  if coalesce(p_disposition, '') not in ('held', 'returned', 'destroyed', 'forfeited', 'other') then
    raise exception 'invalid disposition';
  end if;
  update public.legal_seized_items
     set disposition = p_disposition
   where id = p_item returning * into s;
  perform private.legal_audit(s.legal_request_id, 'LEGAL_SEIZED_ITEM_DISPOSITION',
    jsonb_build_object('item', s.item, 'disposition', p_disposition,
                       'note', nullif(btrim(coalesce(p_note, '')), '')));
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.link_document_suggestion_implementation(p_suggestion uuid, p_version uuid)
 RETURNS document_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.document_suggestions; d public.documents; ver public.documents_versions;
        v_uid uuid := (select auth.uid()); v_from text;
begin
  select * into s from public.document_suggestions where id = p_suggestion for update;
  if not found then raise exception 'suggestion not found'; end if;
  if s.document_id is null then raise exception 'this suggestion has no target document'; end if;
  if s.status not in ('accepted','partially_accepted') then
    raise exception 'only accepted suggestions can be marked implemented';
  end if;
  select * into d from public.documents where id = s.document_id;
  if not private.can_manage_document_suggestions(d.classification, d.owner_user_id, d.folder, d.bureau) then
    raise exception 'not authorized';
  end if;
  select * into ver from public.documents_versions where id = p_version and document_id = s.document_id;
  if not found then raise exception 'version not found for this document'; end if;

  v_from := s.status;
  update public.document_suggestions
     set status = 'implemented', implemented_version_id = p_version, implemented_at = now()
   where id = s.id returning * into s;

  insert into public.document_suggestion_events
    (suggestion_id, event_type, from_status, to_status, note, actor_id)
  values (s.id, 'implemented', v_from, 'implemented',
          'Implemented in version ' || ver.version_number, v_uid);

  if s.created_by <> v_uid then
    insert into public.notifications (user_id, type, payload)
    values (s.created_by, 'document_suggestion', jsonb_build_object(
        'suggestion_id', s.id, 'document_id', s.document_id, 'title', s.title,
        'status', 'implemented', 'actor_id', v_uid,
        'reason', 'Your suggestion was implemented: ' || s.title));
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_SUGGESTION_IMPLEMENTED', 'document_suggestions', s.id,
          jsonb_build_object('version_id', p_version));
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.log_restricted_view(p_entity_type text, p_entity uuid, p_action text DEFAULT 'view'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid());
begin
  if v_uid is null or not private.is_active() then return; end if;
  if p_entity_type not in ('media', 'observation') or p_action not in ('view', 'download') then
    return;
  end if;
  if p_entity_type = 'media'
     and not exists (select 1 from public.media m where m.id = p_entity and m.restricted) then
    return;
  end if;
  if p_entity_type = 'observation'
     and not exists (select 1 from public.surveillance_observations o
                      where o.id = p_entity and o.restricted) then
    return;
  end if;
  if exists (select 1 from public.restricted_access_log l
              where l.entity_type = p_entity_type and l.entity_id = p_entity
                and l.actor_id = v_uid and l.action = p_action
                and l.created_at > now() - interval '1 hour') then
    return;
  end if;
  insert into public.restricted_access_log (entity_type, entity_id, actor_id, action)
  values (p_entity_type, p_entity, v_uid, p_action);
end $function$
;

CREATE OR REPLACE FUNCTION public.mark_document_suggestion_duplicate(p_suggestion uuid, p_original uuid, p_note text DEFAULT NULL::text)
 RETURNS document_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.document_suggestions; d public.documents; orig public.document_suggestions;
        v_uid uuid := (select auth.uid()); v_from text;
begin
  if p_original is null then raise exception 'the original suggestion is required'; end if;
  if p_original = p_suggestion then raise exception 'a suggestion cannot duplicate itself'; end if;
  select * into s from public.document_suggestions where id = p_suggestion for update;
  if not found then raise exception 'suggestion not found'; end if;
  select * into orig from public.document_suggestions where id = p_original;
  if not found then raise exception 'original suggestion not found'; end if;

  if s.document_id is not null then
    select * into d from public.documents where id = s.document_id;
    if not private.can_manage_document_suggestions(d.classification, d.owner_user_id, d.folder, d.bureau) then
      raise exception 'not authorized';
    end if;
  else
    if not (private.is_owner() or coalesce((select active and role in ('deputy_director','director')
             from public.profiles where id = v_uid), false)) then
      raise exception 'not authorized';
    end if;
  end if;

  v_from := s.status;
  update public.document_suggestions
     set status = 'duplicate', duplicate_of = p_original,
         decided_by = v_uid, decided_at = now(),
         decision_note = coalesce(nullif(btrim(p_note), ''), decision_note)
   where id = s.id returning * into s;

  insert into public.document_suggestion_events
    (suggestion_id, event_type, from_status, to_status, note, actor_id)
  values (s.id, 'duplicate', v_from, 'duplicate',
          coalesce(nullif(btrim(p_note), ''), 'Marked duplicate'), v_uid);

  if s.created_by <> v_uid then
    insert into public.notifications (user_id, type, payload)
    values (s.created_by, 'document_suggestion', jsonb_build_object(
        'suggestion_id', s.id, 'document_id', s.document_id, 'title', s.title,
        'status', 'duplicate', 'actor_id', v_uid,
        'reason', 'Your suggestion was marked a duplicate: ' || s.title));
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_SUGGESTION_DUPLICATE', 'document_suggestions', s.id,
          jsonb_build_object('original', p_original));
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.mdt_bridge_ack(p_kind text, p_id uuid, p_result text, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_result not in ('synced', 'failed', 'retryable', 'pending') then
    raise exception 'invalid result — synced, failed, retryable, or pending';
  end if;
  if p_kind = 'export' then
    update public.mdt_exports
       set sync_status = p_result,
           sync_attempts = sync_attempts + 1,
           last_sync_at = case when p_result = 'synced' then now() else last_sync_at end,
           last_sync_error = case when p_result = 'synced' then null else p_error end
     where id = p_id;
  elsif p_kind = 'wanted' then
    update public.mdt_wanted_projections
       set sync_status = p_result,
           sync_attempts = sync_attempts + 1,
           last_sync_at = case when p_result = 'synced' then now() else last_sync_at end,
           last_sync_error = case when p_result = 'synced' then null else p_error end
     where id = p_id;
  else
    raise exception 'invalid kind — export or wanted';
  end if;
  if not found then raise exception 'row not found'; end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (null, 'MDT_SYNC_ACK', case when p_kind = 'export' then 'mdt_exports' else 'mdt_wanted_projections' end,
          p_id, jsonb_build_object('result', p_result, 'error', p_error));
end $function$
;

CREATE OR REPLACE FUNCTION public.mdt_export_approve(p_export uuid)
 RETURNS mdt_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); e public.mdt_exports;
begin
  if not private.is_command() then raise exception 'approving an MDT export is a command action'; end if;
  select * into e from public.mdt_exports where id = p_export for update;
  if not found then raise exception 'export not found'; end if;
  if e.status <> 'proposed' then raise exception 'only a proposed export can be approved'; end if;
  if e.proposed_by = v_uid then raise exception 'an MDT export cannot be approved by its proposer'; end if;
  update public.mdt_exports
     set status = 'exported', exported_by = v_uid, exported_at = now(), sync_status = 'pending', updated_at = now()
   where id = p_export returning * into e;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'MDT_EXPORT_APPROVED', 'mdt_exports', e.id,
          jsonb_build_object('kind', e.kind, 'subject', e.subject_snapshot));
  return e;
end $function$
;

CREATE OR REPLACE FUNCTION public.mdt_export_clear(p_export uuid, p_reason text DEFAULT NULL::text)
 RETURNS mdt_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); e public.mdt_exports;
begin
  if not private.is_command() then raise exception 'clearing an MDT export is a command action'; end if;
  select * into e from public.mdt_exports where id = p_export for update;
  if not found then raise exception 'export not found'; end if;
  if e.status = 'cleared' then raise exception 'this export is already cleared'; end if;
  update public.mdt_exports
     set status = 'cleared', cleared_by = v_uid, cleared_at = now(),
         clear_reason = nullif(btrim(coalesce(p_reason, '')), ''), sync_status = 'pending', updated_at = now()
   where id = p_export returning * into e;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'MDT_EXPORT_CLEARED', 'mdt_exports', e.id,
          jsonb_build_object('kind', e.kind, 'subject', e.subject_snapshot, 'reason', e.clear_reason));
  return e;
end $function$
;

CREATE OR REPLACE FUNCTION public.mdt_export_propose(p_kind text, p_person uuid, p_vehicle uuid, p_snapshot text, p_wanted_status text DEFAULT NULL::text, p_risk text DEFAULT NULL::text, p_instructions text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_case uuid DEFAULT NULL::uuid, p_account uuid DEFAULT NULL::uuid, p_patrol_visible boolean DEFAULT true, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS mdt_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  e public.mdt_exports;
  v_patrol boolean := (p_kind <> 'account') and coalesce(p_patrol_visible, true);
begin
  if not private.is_active() then raise exception 'only an active CID member may propose an MDT export'; end if;
  if p_kind not in ('person_bolo', 'vehicle_bolo', 'caution', 'arrest_warrant',
                    'person_record', 'vehicle_record', 'account') then
    raise exception 'invalid export kind';
  end if;
  if p_risk is not null and p_risk not in ('low', 'medium', 'high', 'critical') then raise exception 'invalid risk level'; end if;
  if btrim(coalesce(p_snapshot, '')) = '' then raise exception 'a subject label is required'; end if;
  if p_kind in ('vehicle_bolo', 'vehicle_record') then
    if p_vehicle is null then raise exception 'a vehicle BOLO needs a vehicle'; end if;
    if p_person is not null then raise exception 'a vehicle BOLO targets a vehicle, not a person'; end if;
    if p_account is not null then raise exception 'a vehicle export targets a vehicle, not an account'; end if;
    if not exists (select 1 from public.vehicles where id = p_vehicle) then raise exception 'vehicle not found'; end if;
  elsif p_kind = 'account' then
    if p_account is null then raise exception 'an account export needs an account'; end if;
    if p_person is not null or p_vehicle is not null then
      raise exception 'an account export targets an account, not a person or vehicle';
    end if;
    if not exists (select 1 from public.accounts where id = p_account and lifecycle <> 'merged') then
      raise exception 'account not found (or merged into another account)';
    end if;
  else
    if p_person is null then raise exception 'a person BOLO / caution needs a person'; end if;
    if p_vehicle is not null then raise exception 'a person BOLO / caution targets a person, not a vehicle'; end if;
    if p_account is not null then raise exception 'a person export targets a person, not an account'; end if;
    if not exists (select 1 from public.persons where id = p_person) then raise exception 'person not found'; end if;
  end if;
  insert into public.mdt_exports
    (kind, person_id, vehicle_id, account_id, subject_snapshot, wanted_status, risk_level,
     instructions, reason, source_case_id, status, proposed_by, patrol_visible, expires_at)
  values (p_kind, p_person, p_vehicle, p_account, btrim(p_snapshot),
          nullif(btrim(coalesce(p_wanted_status, '')), ''), p_risk,
          nullif(btrim(coalesce(p_instructions, '')), ''), nullif(btrim(coalesce(p_reason, '')), ''),
          p_case, 'proposed', v_uid, v_patrol, p_expires_at)
  returning * into e;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'MDT_EXPORT_PROPOSED', 'mdt_exports', e.id,
          jsonb_build_object('kind', p_kind, 'subject', btrim(p_snapshot), 'risk', p_risk,
                             'account', p_account, 'patrol_visible', v_patrol,
                             'expires_at', p_expires_at));
  return e;
exception when unique_violation then
  raise exception 'this subject already has a live MDT export';
end $function$
;

CREATE OR REPLACE FUNCTION public.mdt_patrol_feed()
 RETURNS TABLE(export_id uuid, kind text, subject text, wanted_status text, risk_level text, instructions text, status text, expires_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select e.id, e.kind, e.subject_snapshot, e.wanted_status, e.risk_level,
         e.instructions, e.status, e.expires_at, e.updated_at
    from public.mdt_exports e
   where e.status = 'exported' and e.patrol_visible and e.kind <> 'account'
  union all
  select w.id, 'arrest_warrant', w.person_name_snapshot, w.wanted_status,
         null::text, w.classification_safe_warning, 'exported', w.expires_at, w.updated_at
    from public.mdt_wanted_projections w
   where w.wanted_status = 'wanted'
$function$
;

CREATE OR REPLACE FUNCTION public.mdt_wanted_current()
 RETURNS TABLE(legal_request_id uuid, person_id uuid, person_name_snapshot text, wanted_status text, effective_status text, warrant_reference text, warrant_type text, issuing_judge_name text, issue_date timestamp with time zone, expires_at timestamp with time zone, classification_safe_warning text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select m.legal_request_id, m.person_id, m.person_name_snapshot,
         m.wanted_status,
         case when m.wanted_status = 'wanted' and m.expires_at is not null and m.expires_at < now()
              then 'expired' else m.wanted_status end,
         m.warrant_reference, m.warrant_type, m.issuing_judge_name,
         m.issue_date, m.expires_at, m.classification_safe_warning
    from public.mdt_wanted_projections m
$function$
;

CREATE OR REPLACE FUNCTION public.media_designate_evidence(p_media uuid, p_ref text DEFAULT NULL::text, p_clear boolean DEFAULT false)
 RETURNS media
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); m public.media; me public.profiles;
begin
  select * into m from public.media where id = p_media for update;
  if not found then raise exception 'media not found'; end if;
  if m.case_id is null or not private.can_access_case(m.case_id) then
    raise exception 'media not found or not accessible';
  end if;
  select * into me from public.profiles where id = v_uid;
  if not (coalesce(me.is_owner, false)
          or (coalesce(me.active, false)
              and (me.role in ('senior_detective', 'bureau_lead', 'deputy_director', 'director')
                   or m.uploaded_by = v_uid))) then
    raise exception 'only the uploader or a supervisor may designate evidence';
  end if;
  if p_clear then
    update public.media
       set evidence_ref = null, evidence_designated_by = null, evidence_designated_at = null
     where id = p_media returning * into m;
    insert into public.audit_log (actor_id, action, entity, entity_id, detail)
    values (v_uid, 'MEDIA_EVIDENCE_CLEARED', 'media', p_media,
            jsonb_build_object('case_id', m.case_id));
    return m;
  end if;
  update public.media
     set evidence_ref = coalesce(nullif(btrim(coalesce(p_ref, '')), ''),
                                 'EV-' || upper(substr(p_media::text, 1, 8))),
         evidence_designated_by = v_uid, evidence_designated_at = now()
   where id = p_media returning * into m;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'MEDIA_EVIDENCE_DESIGNATED', 'media', p_media,
          jsonb_build_object('case_id', m.case_id, 'evidence_ref', m.evidence_ref));
  return m;
end $function$
;

CREATE OR REPLACE FUNCTION public.membership_request_submit(p_request uuid)
 RETURNS membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.membership_requests; v_uid uuid := (select auth.uid()); v_action text;
begin
  if exists (select 1 from public.profiles p where p.id = v_uid and p.login_denied) then
    raise exception 'your portal access has been denied';
  end if;
  select * into r from public.membership_requests where id = p_request for update;
  if not found or r.applicant_id is distinct from v_uid then raise exception 'not your request'; end if;
  if r.status not in ('draft', 'correction_requested') then raise exception 'request is not editable'; end if;
  if btrim(coalesce(r.display_name, '')) = '' or btrim(coalesce(r.reason, '')) = '' then
    raise exception 'display name and reason are required';
  end if;
  v_action := case when r.status = 'correction_requested' then 'resubmitted' else 'submitted' end;
  update public.membership_requests
     set status = 'pending', submitted_at = now(), applicant_visible_decision_note = null
   where id = p_request returning * into r;
  perform private.mr_history(p_request, v_action, case when v_action = 'resubmitted' then 'correction_requested' else 'draft' end, 'pending', null, false);
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, upper(v_action), 'membership_requests', p_request);
  if not private.is_test_user(v_uid) then
    insert into public.notifications (user_id, type, payload)
    select p.id, 'membership_request',
           jsonb_build_object('request_id', p_request, 'applicant_name', r.display_name,
             'reason', 'Membership request awaiting review: ' || r.display_name,
             'actor_id', v_uid, 'actor_name', r.display_name)
      from public.profiles p
     where p.active and p.removed_at is null and not p.is_test
       and (p.role in ('bureau_lead', 'deputy_director', 'director') or p.is_owner);
  end if;
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.membership_request_withdraw(p_request uuid)
 RETURNS membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.membership_requests; v_uid uuid := (select auth.uid()); v_from text;
begin
  select * into r from public.membership_requests where id = p_request for update;
  if not found or r.applicant_id is distinct from v_uid then raise exception 'not your request'; end if;
  if r.status not in ('draft', 'pending', 'correction_requested') then raise exception 'request cannot be withdrawn'; end if;
  v_from := r.status;
  update public.membership_requests set status = 'withdrawn' where id = p_request returning * into r;
  perform private.mr_history(p_request, 'withdrawn', v_from, 'withdrawn', null, false);
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, 'WITHDRAWN', 'membership_requests', p_request);
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.merge_narcotics(p_survivor uuid, p_merged uuid, p_reason text)
 RETURNS narcotics
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_reason text := btrim(coalesce(p_reason, ''));
  s public.narcotics;
  m public.narcotics;
  n_alias int; n_pl int; n_pe int; n_ga int; n_ve int; n_sz int;
  n_media int; n_hot int; n_pre int; n_plc int; n_cil int;
begin
  if not private.can_manage_narcotics() then
    raise exception 'narcotic merge is restricted to Bureau Lead or higher';
  end if;
  if v_reason = '' then
    raise exception 'a reason is required to merge narcotic records';
  end if;
  if p_survivor is null or p_merged is null then
    raise exception 'both the survivor and the merged record are required';
  end if;
  if p_survivor = p_merged then
    raise exception 'a record cannot be merged into itself';
  end if;

  select * into s from public.narcotics where id = p_survivor for update;
  if s.id is null then raise exception 'survivor narcotic not found'; end if;
  if s.status = 'merged' then
    raise exception 'the survivor is already merged into another record — merge into its survivor instead';
  end if;
  select * into m from public.narcotics where id = p_merged for update;
  if m.id is null then raise exception 'merged narcotic not found'; end if;
  if m.status = 'merged' then
    raise exception 'narcotic % is already merged and cannot be merged again', p_merged;
  end if;

  -- aliases: UNIQUE(narcotic_id, lower(alias)) — drop would-be collisions,
  -- repoint the rest.
  delete from public.narcotic_aliases a
   where a.narcotic_id = p_merged
     and exists (select 1 from public.narcotic_aliases d
                  where d.narcotic_id = p_survivor and lower(d.alias) = lower(a.alias));
  update public.narcotic_aliases set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_alias = row_count;

  -- narcotic_places: UNIQUE(narcotic_id, place_id, role).
  delete from public.narcotic_places l
   where l.narcotic_id = p_merged
     and exists (select 1 from public.narcotic_places d
                  where d.narcotic_id = p_survivor and d.place_id = l.place_id and d.role = l.role);
  update public.narcotic_places set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_pl = row_count;

  -- narcotic_persons: UNIQUE(narcotic_id, person_id, role).
  delete from public.narcotic_persons l
   where l.narcotic_id = p_merged
     and exists (select 1 from public.narcotic_persons d
                  where d.narcotic_id = p_survivor and d.person_id = l.person_id and d.role = l.role);
  update public.narcotic_persons set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_pe = row_count;

  -- narcotic_gangs: UNIQUE(narcotic_id, gang_id, role).
  delete from public.narcotic_gangs l
   where l.narcotic_id = p_merged
     and exists (select 1 from public.narcotic_gangs d
                  where d.narcotic_id = p_survivor and d.gang_id = l.gang_id and d.role = l.role);
  update public.narcotic_gangs set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_ga = row_count;

  -- narcotic_vehicles: UNIQUE(narcotic_id, vehicle_id, role).
  delete from public.narcotic_vehicles l
   where l.narcotic_id = p_merged
     and exists (select 1 from public.narcotic_vehicles d
                  where d.narcotic_id = p_survivor and d.vehicle_id = l.vehicle_id and d.role = l.role);
  update public.narcotic_vehicles set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_ve = row_count;

  -- Plain repoints (no UNIQUE constraints involve narcotic_id here).
  update public.narcotic_seizures set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_sz = row_count;
  update public.media set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_media = row_count;
  update public.narcotic_hotspots set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_hot = row_count;
  update public.narcotic_precursors set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_pre = row_count;
  update public.places set narcotic_id = p_survivor where narcotic_id = p_merged;
  get diagnostics n_plc = row_count;
  update public.narcotic_sale_series set narcotic_id = p_survivor where narcotic_id = p_merged;
  update public.narcotic_sale_observations set narcotic_id = p_survivor where narcotic_id = p_merged;

  -- case_intel_links: UNIQUE(case_id, kind, ref_id) — drop the merged-side
  -- link where the survivor is already linked to the same case, repoint the
  -- rest.
  delete from public.case_intel_links l
   where l.kind = 'narcotic' and l.ref_id = p_merged
     and exists (select 1 from public.case_intel_links d
                  where d.case_id = l.case_id and d.kind = 'narcotic' and d.ref_id = p_survivor);
  update public.case_intel_links set ref_id = p_survivor
   where kind = 'narcotic' and ref_id = p_merged;
  get diagnostics n_cil = row_count;

  -- Keep the merged record's name findable on the survivor.
  if btrim(m.name) <> '' and not exists (
       select 1 from public.narcotic_aliases d
        where d.narcotic_id = p_survivor
          and lower(d.alias) = lower(left(btrim(m.name), 120))) then
    insert into public.narcotic_aliases (narcotic_id, alias, alias_type, created_by)
    values (p_survivor, left(btrim(m.name), 120), 'variant', v_uid);
  end if;

  -- Tombstone the merged row (kept, never deleted).
  update public.narcotics
     set status = 'merged', merged_into = p_survivor
   where id = p_merged;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'NARCOTIC_MERGED', 'narcotics', p_merged, jsonb_build_object(
    'survivor_id', p_survivor, 'merged_id', p_merged, 'merged_name', m.name,
    'reason', left(v_reason, 500),
    'repointed', jsonb_build_object(
      'narcotic_aliases', n_alias, 'narcotic_places', n_pl,
      'narcotic_persons', n_pe, 'narcotic_gangs', n_ga,
      'narcotic_vehicles', n_ve, 'narcotic_seizures', n_sz,
      'media', n_media, 'narcotic_hotspots', n_hot,
      'narcotic_precursors', n_pre, 'places', n_plc,
      'case_intel_links', n_cil)));

  select * into s from public.narcotics where id = p_survivor;
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.mo_crossref(terms text[])
 RETURNS TABLE(case_id uuid, case_number text, bureau bureau, shared text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with tagged as (
    select m.case_id, c.case_number, c.bureau,
           array(select jsonb_array_elements_text(
             coalesce(m.indicators->'names','[]'::jsonb) ||
             coalesce(m.indicators->'entry','[]'::jsonb) ||
             coalesce(m.indicators->'vehicles','[]'::jsonb) ||
             coalesce(m.indicators->'weapons','[]'::jsonb))) as tags
    from public.mo_profiles m join public.cases c on c.id = m.case_id
    where private.is_active() and not private.can_access_case(c.id)
  )
  select case_id, case_number, bureau,
         array(select distinct t from unnest(tags) t where t = any(terms)) as shared
  from tagged
  where exists (select 1 from unnest(tags) t where t = any(terms));
$function$
;

CREATE OR REPLACE FUNCTION public.my_field_access()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'standing',
      (select jsonb_build_object(
         'agency', f.agency, 'callsign', f.callsign, 'officer_rank', f.officer_rank,
         'unit', f.unit, 'active', f.active, 'appointed_at', f.appointed_at)
         from public.field_officers f where f.user_id = (select auth.uid())),
    'request',
      (select jsonb_build_object(
         'id', r.id, 'status', r.status, 'agency', r.agency,
         'decision_reason', r.decision_reason, 'created_at', r.created_at)
         from public.field_access_requests r
        where r.user_id = (select auth.uid())
        order by r.created_at desc limit 1))
$function$
;

CREATE OR REPLACE FUNCTION public.next_case_number(p_bureau text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with base as (
    select private.case_number_base(p_bureau) as lo
  ),
  candidates as (
    select (regexp_replace(c.case_number, '^[A-Z]+-', ''))::bigint as n
    from public.cases c
    where c.bureau::text = p_bureau
      and c.case_number ~ '^[A-Z]+-[0-9]+$'
  )
  select private.bureau_prefix(p_bureau) || '-' || (
    coalesce(
      (select max(n) from candidates, base where n between base.lo and base.lo + 999999),
      (select lo from base)
    ) + 1
  )::text
$function$
;

CREATE OR REPLACE FUNCTION public.next_siu_case_number()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select 'SIB-' || (
    coalesce(
      (select max((regexp_replace(c.case_number, '^SI[UB]-', ''))::bigint)
         from public.cases c
        where c.case_authority = 'siu' and c.case_number ~ '^SI[UB]-[0-9]+$'),
      8000000::bigint)
    + 1)::text
$function$
;

CREATE OR REPLACE FUNCTION public.observation_promote(p_observation uuid, p_note text DEFAULT NULL::text)
 RETURNS surveillance_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); o public.surveillance_observations;
begin
  select * into o from public.surveillance_observations where id = p_observation for update;
  if not found then raise exception 'observation not found'; end if;
  if not private.is_active() or not private.can_access_case(o.case_id) then
    raise exception 'not permitted to promote observations on this case';
  end if;
  if o.verification_status <> 'verified' then
    raise exception 'only a VERIFIED observation can be promoted to the case record';
  end if;
  if o.promoted_at is not null then raise exception 'observation is already promoted'; end if;
  update public.surveillance_observations
     set promoted_at = now(), promoted_by = v_uid
   where id = p_observation returning * into o;
  update public.media
     set case_id = coalesce(case_id, o.case_id),
         category = coalesce(category, 'surveillance')
   where observation_id = p_observation;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'SURV_OBS_PROMOTED', 'surveillance_observations', p_observation,
          jsonb_build_object('case_id', o.case_id, 'note', p_note));
  return o;
end $function$
;

CREATE OR REPLACE FUNCTION public.observation_review(p_observation uuid, p_decision text, p_notes text DEFAULT NULL::text)
 RETURNS surveillance_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); o public.surveillance_observations; v_from text; v_to text;
begin
  select * into o from public.surveillance_observations where id = p_observation for update;
  if not found then raise exception 'observation not found'; end if;
  if not private.is_active() or not private.can_access_case(o.case_id) then
    raise exception 'not permitted to review observations on this case';
  end if;
  v_from := o.verification_status;
  v_to := case p_decision
    when 'verify' then 'verified'
    when 'reject' then 'rejected'
    when 'needs_information' then 'needs_information'
    when 'reopen' then 'unverified'
    else null end;
  if v_to is null then
    raise exception 'invalid decision — verify, reject, needs_information, or reopen';
  end if;
  if v_from = v_to then raise exception 'observation is already %', v_to; end if;
  if p_decision in ('reject', 'needs_information') and btrim(coalesce(p_notes, '')) = '' then
    raise exception 'rejecting or requesting information requires notes';
  end if;
  update public.surveillance_observations
     set verification_status = v_to,
         reviewed_by = case when p_decision = 'reopen' then null else v_uid end,
         reviewed_at = case when p_decision = 'reopen' then null else now() end,
         review_notes = case when p_decision = 'reopen' then null else coalesce(p_notes, review_notes) end,
         confidence = case when p_decision = 'verify' and confidence = 'unverified'
                           then 'probable' else confidence end
   where id = p_observation returning * into o;
  insert into public.surveillance_review_history
    (observation_id, action, from_status, to_status, actor_id, notes)
  values (p_observation, p_decision, v_from, v_to, v_uid, p_notes);
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'SURV_OBS_' || upper(p_decision), 'surveillance_observations', p_observation,
          jsonb_build_object('from', v_from, 'to', v_to, 'case_id', o.case_id));
  return o;
end $function$
;

CREATE OR REPLACE FUNCTION public.operation_add_bureau(p_op uuid, p_bureau bureau)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); o public.operations;
begin
  if not private.can_manage_operation(p_op) then raise exception 'not permitted to manage this operation'; end if;
  select * into o from public.operations where id = p_op for update;
  if o.op_type <> 'jtf' then raise exception 'not a JTF operation'; end if;
  if o.status <> 'active' then raise exception 'operation is not active'; end if;
  if p_bureau is null or p_bureau = 'JTF' then raise exception 'invalid bureau'; end if;
  if private.op_has_bureau(p_op, p_bureau) then raise exception 'bureau is already participating'; end if;
  insert into public.operation_bureaus (operation_id, bureau, joined_by)
  values (p_op, p_bureau, v_uid);
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'OP_BUREAU_ADDED', 'operations', p_op, jsonb_build_object('bureau', p_bureau));
end $function$
;

CREATE OR REPLACE FUNCTION public.operation_convert_to_jtf(p_op uuid, p_lead bureau, p_bureaus bureau[])
 RETURNS operations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  o public.operations;
  b public.bureau;
  v_missing text;
begin
  if not (select private.is_command()) and not coalesce((select is_owner from public.profiles where id = v_uid), false) then
    raise exception 'converting an operation to JTF requires command authority';
  end if;
  select * into o from public.operations where id = p_op for update;
  if not found then raise exception 'operation not found'; end if;
  if o.op_type = 'jtf' then raise exception 'operation is already a JTF operation'; end if;
  if o.status <> 'active' then raise exception 'only an active operation can be converted to JTF'; end if;
  if p_lead is null or p_lead = 'JTF' then raise exception 'a lead bureau is required'; end if;
  if p_bureaus is null or array_length(p_bureaus, 1) is null or array_length(p_bureaus, 1) < 2 then
    raise exception 'a JTF operation needs at least two participating bureaus';
  end if;
  if not (p_lead = any(p_bureaus)) then
    raise exception 'the lead bureau must be one of the participating bureaus';
  end if;
  foreach b in array p_bureaus loop
    if b is null or b = 'JTF' then raise exception 'invalid participating bureau'; end if;
  end loop;
  select string_agg(distinct c.bureau::text, ', ') into v_missing
    from public.cases c
   where c.operation_id = p_op and c.bureau <> 'JTF' and not (c.bureau = any(p_bureaus));
  if v_missing is not null then
    raise exception 'linked cases from % must be covered — add those bureaus or unlink the cases first', v_missing;
  end if;

  update public.operations
     set op_type = 'jtf', lead_bureau = p_lead, bureau = null,
         jtf_converted_at = now(), jtf_converted_by = v_uid
   where id = p_op returning * into o;

  insert into public.operation_bureaus (operation_id, bureau, joined_by)
  select p_op, x, v_uid from unnest(p_bureaus) as x
  on conflict (operation_id, bureau) where left_at is null do nothing;

  update public.operation_case_links
     set was_jtf = true
   where operation_id = p_op and removed_at is null;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'OP_CONVERTED_JTF', 'operations', p_op,
          jsonb_build_object('lead_bureau', p_lead, 'bureaus', to_jsonb(p_bureaus)));
  return o;
end $function$
;

CREATE OR REPLACE FUNCTION public.operation_remove_bureau(p_op uuid, p_bureau bureau, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); o public.operations; v_n int;
begin
  if not private.can_manage_operation(p_op) then raise exception 'not permitted to manage this operation'; end if;
  select * into o from public.operations where id = p_op for update;
  if o.op_type <> 'jtf' then raise exception 'not a JTF operation'; end if;
  if p_bureau = o.lead_bureau then raise exception 'the lead bureau cannot be removed — reassign the lead first'; end if;
  select count(*) into v_n from public.cases c
   where c.operation_id = p_op and c.bureau = p_bureau;
  if v_n > 0 then
    raise exception 'bureau % still has % linked case(s) — unlink them first', p_bureau, v_n;
  end if;
  update public.operation_bureaus
     set left_at = now(), left_by = v_uid
   where operation_id = p_op and bureau = p_bureau and left_at is null;
  if not found then raise exception 'bureau is not an active participant'; end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'OP_BUREAU_REMOVED', 'operations', p_op,
          jsonb_build_object('bureau', p_bureau, 'reason', p_reason));
end $function$
;

CREATE OR REPLACE FUNCTION public.operation_revert_to_normal(p_op uuid)
 RETURNS operations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); o public.operations; v_n int;
begin
  if not private.can_manage_operation(p_op) then raise exception 'not permitted to manage this operation'; end if;
  select * into o from public.operations where id = p_op for update;
  if o.op_type <> 'jtf' then raise exception 'not a JTF operation'; end if;
  select count(*) into v_n from public.cases c
   where c.operation_id = p_op and c.bureau <> o.lead_bureau;
  if v_n > 0 then
    raise exception '% linked case(s) belong to other bureaus — unlink them (or transfer the operation) before reverting to a single-bureau operation', v_n;
  end if;
  update public.operation_bureaus
     set left_at = now(), left_by = v_uid
   where operation_id = p_op and left_at is null;
  update public.operations
     set op_type = 'normal', bureau = o.lead_bureau, lead_bureau = null
   where id = p_op returning * into o;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'OP_REVERTED_NORMAL', 'operations', p_op,
          jsonb_build_object('bureau', o.bureau));
  return o;
end $function$
;

CREATE OR REPLACE FUNCTION public.operation_set_lead(p_op uuid, p_bureau bureau)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); o public.operations;
begin
  if not private.can_manage_operation(p_op) then raise exception 'not permitted to manage this operation'; end if;
  select * into o from public.operations where id = p_op for update;
  if o.op_type <> 'jtf' then raise exception 'not a JTF operation'; end if;
  if not private.op_has_bureau(p_op, p_bureau) then
    raise exception 'the lead bureau must be an active participating bureau';
  end if;
  update public.operations set lead_bureau = p_bureau where id = p_op;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'OP_LEAD_CHANGED', 'operations', p_op,
          jsonb_build_object('from', o.lead_bureau, 'to', p_bureau));
end $function$
;

CREATE OR REPLACE FUNCTION public.owner_grant_justice_membership(p_target uuid, p_agency text, p_justice_role text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  me public.profiles;
  t public.profiles;
begin
  select * into me from public.profiles where id = v_uid;
  if not private.is_owner() then
    raise exception 'granting justice memberships directly is restricted to the owner';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  if p_agency not in ('doj', 'judiciary')
     or (p_agency = 'doj' and p_justice_role not in ('assistant_district_attorney', 'district_attorney', 'attorney_general'))
     or (p_agency = 'judiciary' and p_justice_role <> 'judge') then
    raise exception 'invalid agency/role combination';
  end if;
  select * into t from public.profiles where id = p_target for update;
  if t.id is null then raise exception 'member not found'; end if;
  if t.removed_at is not null or t.login_denied then raise exception 'member is removed or login-denied'; end if;
  if t.is_test then raise exception 'test fixtures cannot be granted justice memberships'; end if;

  insert into public.justice_memberships (user_id, agency, justice_role, active, approved_by, approved_at)
  values (p_target, p_agency, p_justice_role, true, v_uid, now())
  on conflict (user_id) do update
    set agency = excluded.agency, justice_role = excluded.justice_role,
        active = true, approved_by = excluded.approved_by, approved_at = excluded.approved_at;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'JUSTICE_GRANTED', 'justice_memberships', p_target,
    jsonb_build_object('agency', p_agency, 'justice_role', p_justice_role, 'reason', p_reason,
      'dual_with_cid', t.active));
  insert into public.notifications (user_id, type, payload)
  values (p_target, 'justice_membership_update', jsonb_build_object(
    'status', 'granted', 'justice_role', p_justice_role,
    'reason', 'You have been appointed ' ||
      case p_justice_role
        when 'assistant_district_attorney' then 'a department prosecutor (Assistant District Attorney)'
        when 'district_attorney' then 'District Attorney'
        when 'attorney_general' then 'Attorney General'
        else 'Judge' end || '. Reason: ' || p_reason,
    'actor_id', v_uid, 'actor_name', me.display_name));
end $function$
;

CREATE OR REPLACE FUNCTION public.owner_security_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_runs jsonb;
  v_fixtures jsonb;
  v_leftovers jsonb;
  test_ids uuid[];
begin
  if not private.is_owner() then raise exception 'not authorized'; end if;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc), '[]'::jsonb) into v_runs
    from (select id, suite, passed, failed, skipped, total, failures, commit_sha,
                 branch, release, source, duration_ms, created_at
            from public.security_test_runs
           order by created_at desc limit 20) r;

  -- Expected fixture roster (kept in sync with tests/rls/README.md).
  with expected(email, kind, exp_role, exp_division, exp_cid_active, exp_justice_role, exp_justice_active) as (values
    ('rls-test-lsb@cidportal.test', 'cid', 'detective', 'major_crimes', true, null, null),
    ('rls-test-bcb@cidportal.test', 'cid', 'detective', 'street_crimes', true, null, null),
    ('rls-test-inactive@cidportal.test', 'cid', null, null, false, null, null),
    ('rls-test-owner@cidportal.test', 'cid', 'detective', 'major_crimes', true, null, null),
    ('rls-test-lead@cidportal.test', 'cid', 'bureau_lead', 'major_crimes', true, null, null),
    ('rls-test-director@cidportal.test', 'cid', 'director', 'major_crimes', true, null, null),
    ('rls-test-target@cidportal.test', 'cid', 'detective', 'major_crimes', true, null, null),
    ('rls-test-applicant@cidportal.test', 'cid', null, null, false, null, null),
    ('rls-test-ada-lsb@cidportal.test', 'justice', null, null, false, 'assistant_district_attorney', true),
    ('rls-test-ada-bcb@cidportal.test', 'justice', null, null, false, 'assistant_district_attorney', true),
    ('rls-test-ada-sab@cidportal.test', 'justice', null, null, false, 'assistant_district_attorney', true),
    ('rls-test-da@cidportal.test', 'justice', null, null, false, 'district_attorney', true),
    ('rls-test-ag@cidportal.test', 'justice', null, null, false, 'attorney_general', true),
    ('rls-test-judge@cidportal.test', 'justice', null, null, false, 'judge', true),
    ('rls-test-judge2@cidportal.test', 'justice', null, null, false, 'judge', true),
    ('rls-test-justice@cidportal.test', 'justice', null, null, false, null, null))
  select coalesce(jsonb_agg(jsonb_build_object(
           'email', e.email,
           'present', u.id is not null,
           'issues', (
             select coalesce(jsonb_agg(issue), '[]'::jsonb) from (
               select 'missing account' as issue where u.id is null
               union all select 'missing profile' where u.id is not null and p.id is null
               union all select 'unexpected CID role: ' || p.role::text
                 where p.id is not null and e.exp_role is not null and p.role::text is distinct from e.exp_role
               union all select 'unexpected bureau: ' || p.division::text
                 where p.id is not null and e.exp_division is not null and p.division::text is distinct from e.exp_division
               union all select 'CID active flag is ' || p.active::text
                 where p.id is not null and e.exp_cid_active is not null and p.active is distinct from e.exp_cid_active
               union all select 'login denied' where coalesce(p.login_denied, false)
               union all select 'removed' where p.removed_at is not null
               union all select 'unexpected justice role: ' || coalesce(jm.justice_role, 'none')
                 where u.id is not null and e.kind = 'justice'
                   and coalesce(jm.justice_role, '') is distinct from coalesce(e.exp_justice_role, '')
               union all select 'justice membership inactive'
                 where e.exp_justice_active is true and coalesce(jm.active, false) = false
             ) issues)) order by e.email), '[]'::jsonb)
    into v_fixtures
    from expected e
    left join auth.users u on u.email = e.email
    left join public.profiles p on p.id = u.id
    left join public.justice_memberships jm on jm.user_id = u.id;

  select coalesce(array_agg(id), '{}') into test_ids
    from auth.users where email like 'rls-test-%@cidportal.test';
  select jsonb_build_object(
    'cases', (select count(*) from public.cases where created_by = any(test_ids)),
    'legal_requests', (select count(*) from public.legal_requests where created_by = any(test_ids)),
    'prosecutor_assignments', (select count(*) from public.prosecutor_bureau_assignments
                                where (prosecutor_id = any(test_ids) or assigned_by = any(test_ids)) and ends_at is null),
    'announcements', (select count(*) from public.announcements where author_id = any(test_ids)),
    'membership_requests', (select count(*) from public.membership_requests where applicant_id = any(test_ids)),
    'justice_requests', (select count(*) from public.justice_membership_requests where applicant_id = any(test_ids)),
    'persons', (select count(*) from public.persons where created_by = any(test_ids)))
    into v_leftovers;

  insert into public.audit_log (actor_id, action, entity, entity_id)
  values ((select auth.uid()), 'SECURITY_OVERVIEW_VIEWED', 'security_test_runs', null);

  return jsonb_build_object('runs', v_runs, 'fixtures', v_fixtures, 'leftovers', v_leftovers);
end $function$
;

CREATE OR REPLACE FUNCTION public.packet_export_approve_restricted(p_case uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid());
begin
  if not private.is_active() or not private.is_command() then
    raise exception 'packet-export approval is restricted to command (Bureau Lead or higher)';
  end if;
  if not private.can_access_case(p_case) then raise exception 'not authorized'; end if;
  if not exists (select 1 from public.cases where id = p_case) then
    raise exception 'case not found';
  end if;
  insert into public.restricted_access_log (entity_type, entity_id, actor_id, action, reason)
  values ('media', p_case, v_uid, 'packet_export', nullif(btrim(coalesce(p_note, '')), ''));
end $function$
;

CREATE OR REPLACE FUNCTION public.penal_admin_overview()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    -- Asked of the same helper the policies use, so the screen and the
    -- database cannot disagree about who is an administrator.
    'is_admin', private.penal_is_admin(),
    'versions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', v.id,
               'name', v.name,
               'status', v.status,
               'effective_date', v.effective_date,
               'source_file', v.source_file,
               'change_summary', v.change_summary,
               'published_at', v.published_at,
               'superseded_at', v.superseded_at,
               -- Counted through penal_charges_sel as the caller.
               'active_charges', (select count(*) from public.penal_charges c
                                   where c.version_id = v.id and c.lifecycle = 'active'),
               'draft_charges', (select count(*) from public.penal_charges c
                                  where c.version_id = v.id and c.lifecycle = 'draft'),
               'archived_charges', (select count(*) from public.penal_charges c
                                     where c.version_id = v.id and c.lifecycle = 'archived'),
               -- The number that must be shown before anyone publishes: a
               -- charge with no code cannot be selected, so publishing a
               -- version with these silently ships an incomplete code.
               'needs_code', (select count(*) from public.penal_charges c
                               where c.version_id = v.id and c.needs_code),
               'rules', (select count(*) from public.penal_rules r where r.version_id = v.id),
               'schedules', (select count(*) from public.penal_substance_schedules s
                              where s.version_id = v.id))
             order by v.effective_date desc, v.created_at desc)
        from public.penal_code_versions v), '[]'::jsonb))
$function$
;

CREATE OR REPLACE FUNCTION public.penal_archive_charge(p_charge uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); c public.penal_charges;
begin
  if not private.penal_is_admin() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  select * into c from public.penal_charges where id = p_charge for update;
  if not found then raise exception 'charge not found'; end if;
  if c.lifecycle = 'archived' then raise exception 'already archived'; end if;

  update public.penal_charges
     set lifecycle = 'archived', archived_by = v_actor, archived_at = now(),
         archive_reason = btrim(p_reason), updated_at = now()
   where id = p_charge;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'PENAL_CHARGE_ARCHIVED', 'penal_charges', p_charge,
          jsonb_build_object('code', c.code, 'offense', c.offense,
                             'version', c.version_id, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.penal_current_charges()
 RETURNS TABLE(id uuid, version_id uuid, version_name text, code text, offense text, penal_title text, charge_class text, stackable boolean, fine numeric, jail_months numeric, judge_set_fine boolean, judge_set_jail boolean, pd_exempt boolean, definition text, is_modifier boolean, is_rico boolean, is_rico_predicate boolean, arrest_required boolean, substance_schedule integer, special_notes text, lifecycle text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select c.id, c.version_id, v.name, c.code, c.offense,
         c.penal_title, c.charge_class, c.stackable,
         c.fine, c.jail_months, c.judge_set_fine, c.judge_set_jail,
         c.pd_exempt, c.definition, c.is_modifier, c.is_rico,
         c.is_rico_predicate, c.arrest_required,
         c.substance_schedule, c.special_notes, c.lifecycle
    from public.penal_charges c
    join public.penal_code_versions v on v.id = c.version_id
   where v.status = 'published' and c.lifecycle = 'active'
   order by c.penal_title nulls last, c.code nulls last, c.offense
$function$
;

CREATE OR REPLACE FUNCTION public.penal_current_reference()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when v.id is null then null else jsonb_build_object(
    'version', jsonb_build_object(
      'id', v.id, 'name', v.name, 'effective_date', v.effective_date,
      'source_file', v.source_file, 'published_at', v.published_at),
    'limits', (select jsonb_build_object(
        'max_total_months', l.max_total_months, 'note', l.max_total_months_note)
      from public.penal_limits l where l.version_id = v.id),
    'schedules', coalesce((select jsonb_agg(jsonb_build_object(
        'schedule', s.schedule, 'substances', s.substances, 'notes', s.notes)
        order by s.schedule)
      from public.penal_substance_schedules s where s.version_id = v.id), '[]'::jsonb),
    'rules', coalesce((select jsonb_agg(jsonb_build_object(
        'section', r.section, 'heading', r.heading, 'body', r.body)
        order by r.section, r.ordinal)
      from public.penal_rules r where r.version_id = v.id), '[]'::jsonb),
    'counts', jsonb_build_object(
      'active', (select count(*) from public.penal_charges c
                  where c.version_id = v.id and c.lifecycle = 'active'),
      'archived', (select count(*) from public.penal_charges c
                    where c.version_id = v.id and c.lifecycle = 'archived'))
  ) end
  from (select * from public.penal_code_versions
         where status = 'published' limit 1) v
$function$
;

CREATE OR REPLACE FUNCTION public.penal_publish_version(p_version uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.penal_code_versions;
        v_prev uuid; v_active int; v_drafts int;
begin
  if not private.penal_is_admin() then raise exception 'not authorized'; end if;
  select * into v from public.penal_code_versions where id = p_version for update;
  if not found then raise exception 'version not found'; end if;
  if v.status = 'published' then raise exception 'that version is already published'; end if;

  select count(*) into v_active from public.penal_charges
   where version_id = p_version and lifecycle = 'active';
  if v_active = 0 then raise exception 'a version with no active charges cannot be published'; end if;
  select count(*) into v_drafts from public.penal_charges
   where version_id = p_version and needs_code;

  select id into v_prev from public.penal_code_versions where status = 'published';
  if v_prev is not null then
    update public.penal_code_versions
       set status = 'superseded', superseded_at = now(), updated_at = now()
     where id = v_prev;
  end if;
  update public.penal_code_versions
     set status = 'published', published_by = v_actor, published_at = now(),
         change_summary = coalesce(nullif(btrim(coalesce(p_note, '')), ''), change_summary),
         superseded_at = null, updated_at = now()
   where id = p_version;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'PENAL_VERSION_PUBLISHED', 'penal_code_versions', p_version,
          jsonb_build_object('name', v.name, 'effective_date', v.effective_date,
                             'previous_version', v_prev, 'active_charges', v_active,
                             'charges_needing_codes', v_drafts, 'note', p_note));

  return jsonb_build_object('published', p_version, 'superseded', v_prev,
                            'active_charges', v_active, 'charges_needing_codes', v_drafts);
end $function$
;

CREATE OR REPLACE FUNCTION public.penal_restore_charge(p_charge uuid, p_reason text, p_code text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); c public.penal_charges; v_code text;
begin
  if not private.penal_is_admin() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  select * into c from public.penal_charges where id = p_charge for update;
  if not found then raise exception 'charge not found'; end if;
  if c.lifecycle = 'active' then raise exception 'already active'; end if;

  v_code := coalesce(nullif(btrim(coalesce(p_code, '')), ''), c.code);
  if v_code is null then
    raise exception 'this charge has no code yet - supply one to bring it into force';
  end if;

  update public.penal_charges
     set lifecycle = 'active', needs_code = false, code = v_code,
         archived_by = null, archived_at = null, archive_reason = null,
         updated_at = now()
   where id = p_charge;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'PENAL_CHARGE_RESTORED', 'penal_charges', p_charge,
          jsonb_build_object('code', v_code, 'previous_code', c.code,
                             'offense', c.offense, 'was', c.lifecycle,
                             'version', c.version_id, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.penal_rollback_to(p_version uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v public.penal_code_versions; v_prev uuid;
begin
  if not private.penal_is_admin() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'a rollback needs a reason - it changes the law in force';
  end if;
  select * into v from public.penal_code_versions where id = p_version for update;
  if not found then raise exception 'version not found'; end if;
  if v.status = 'draft' then
    raise exception 'a draft has never been in force; publish it instead of rolling back to it';
  end if;
  if v.status = 'published' then raise exception 'that version is already in force'; end if;

  select id into v_prev from public.penal_code_versions where status = 'published';
  if v_prev is not null then
    update public.penal_code_versions
       set status = 'superseded', superseded_at = now(), updated_at = now()
     where id = v_prev;
  end if;
  update public.penal_code_versions
     set status = 'published', superseded_at = null, updated_at = now()
   where id = p_version;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_actor, 'PENAL_VERSION_ROLLED_BACK', 'penal_code_versions', p_version,
          jsonb_build_object('restored', v.name, 'rolled_back_from', v_prev,
                             'reason', btrim(p_reason)));

  return jsonb_build_object('published', p_version, 'superseded', v_prev);
end $function$
;

CREATE OR REPLACE FUNCTION public.permanent_delete_arm(p_target uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_tombstone constant uuid := '00000000-0000-4000-a000-000000000001';
  t public.profiles;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_map jsonb;
  v_token public.deletion_tokens;
begin
  if not private.is_owner() then
    raise exception 'permanent deletion is restricted to the owner';
  end if;
  perform private.assert_fresh_session();
  if v_reason = '' then
    raise exception 'a reason is required to arm a permanent deletion';
  end if;
  select * into t from public.profiles where id = p_target for update;
  if not found then raise exception 'member not found'; end if;
  if p_target = v_uid then raise exception 'you cannot permanently delete yourself'; end if;
  if p_target = v_tombstone or t.is_system then
    raise exception 'system accounts cannot be permanently deleted';
  end if;
  if t.is_owner then raise exception 'owner accounts cannot be permanently deleted'; end if;
  v_map := private.permanent_delete_refmap(p_target);
  if (v_map->>'blocker_total')::bigint > 0 then
    raise exception 'permanent deletion blocked — this member is still referenced by immutable records or active work: % — reassign the active work; immutable-record references can never be cleared (deactivate/remove remains the default)',
      (v_map->'blockers') || (v_map->'active_work');
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'PERMANENT_DELETE_ARMED', 'profiles', p_target, jsonb_build_object(
    'reason', left(v_reason, 500),
    'display_name', t.display_name,
    'preview', v_map));

  insert into public.deletion_tokens (target_id, created_by, expires_at)
  values (p_target, v_uid, now() + interval '5 minutes')
  returning * into v_token;

  return jsonb_build_object(
    'token', v_token.id,
    'expires_at', v_token.expires_at,
    'display_name', t.display_name);
end $function$
;

CREATE OR REPLACE FUNCTION public.permanent_delete_execute(p_token uuid, p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_tombstone constant uuid := '00000000-0000-4000-a000-000000000001';
  tok public.deletion_tokens;
  t public.profiles;
  v_map jsonb;
  v_refs jsonb;
  v_role_events jsonb;
  v_ledger_id uuid;
  r record;
begin
  if not private.is_owner() then
    raise exception 'permanent deletion is restricted to the owner';
  end if;
  perform private.assert_fresh_session();

  select * into tok from public.deletion_tokens where id = p_token for update;
  if not found then raise exception 'invalid deletion token -- arm the deletion again'; end if;
  if tok.created_by is distinct from v_uid then
    raise exception 'this deletion token was issued to a different owner session -- arm the deletion again';
  end if;
  if tok.used_at is not null then
    raise exception 'this deletion token was already used -- the member was already permanently deleted';
  end if;
  if tok.expires_at <= now() then
    raise exception 'this deletion token has expired -- arm the deletion again';
  end if;

  select * into t from public.profiles where id = tok.target_id for update;
  if not found then
    raise exception 'this member was already permanently deleted (or never existed)';
  end if;
  if t.is_system or t.is_owner then
    raise exception 'system and owner accounts cannot be permanently deleted';
  end if;
  if p_confirm is distinct from 'DELETE ' || t.display_name then
    raise exception 'confirmation text mismatch -- type exactly: DELETE %', t.display_name;
  end if;

  v_map := private.permanent_delete_refmap(tok.target_id);
  if (v_map->>'blocker_total')::bigint > 0 then
    raise exception 'permanent deletion blocked -- references appeared after arming: %',
      (v_map->'blockers') || (v_map->'active_work');
  end if;

  select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at), '[]'::jsonb)
    into v_role_events
    from public.role_events e where e.target_id = tok.target_id;
  v_refs := (v_map - 'blockers' - 'active_work' - 'blocker_total')
            || jsonb_build_object('role_events', v_role_events);

  insert into public.deleted_member_ledger
    (target_id, display_name, badge_number, role, division, email, reason,
     deleted_by, armed_at, executed_at, "references")
  values
    (t.id, t.display_name, t.badge_number, t.role::text, t.division::text, t.email,
     coalesce((select a.detail->>'reason' from public.audit_log a
                where a.action = 'PERMANENT_DELETE_ARMED' and a.entity_id = t.id
                order by a.created_at desc limit 1), '(reason unavailable)'),
     v_uid, tok.created_at, now(), v_refs)
  returning id into v_ledger_id;

  for r in select tbl, col from private.permanent_delete_plan()
            where bucket = 'repoint' order by ref loop
    execute format('update public.%I set %I = $1 where %I = $2', r.tbl, r.col, r.col)
      using v_tombstone, t.id;
  end loop;

  for r in select tbl, col from private.permanent_delete_plan()
            where bucket = 'deleted' order by ref loop
    execute format('delete from public.%I where %I = $1', r.tbl, r.col) using t.id;
  end loop;

  delete from public.justice_membership_request_history h
   where h.request_id in (select r2.id from public.justice_membership_requests r2
                           where r2.applicant_id = t.id);
  delete from public.justice_membership_requests where applicant_id = t.id;

  delete from public.profiles where id = t.id;
  delete from auth.users where id = t.id;

  update public.deletion_tokens set used_at = now() where id = p_token;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'PERMANENT_DELETE_EXECUTED', 'profiles', t.id, jsonb_build_object(
    'ledger_id', v_ledger_id,
    'display_name', t.display_name,
    'references', v_map - 'blockers' - 'active_work' - 'blocker_total'));

  return jsonb_build_object(
    'ledger_id', v_ledger_id,
    'target_id', t.id,
    'display_name', t.display_name,
    'references', v_refs - 'role_events');
end $function$
;

CREATE OR REPLACE FUNCTION public.permanent_delete_preview(p_target uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  t public.profiles;
  v_map jsonb;
  v_reasons text[] := '{}';
begin
  if not private.is_owner() then
    raise exception 'permanent deletion is restricted to the owner';
  end if;
  select * into t from public.profiles where id = p_target;
  if not found then raise exception 'member not found'; end if;
  v_map := private.permanent_delete_refmap(p_target);
  if p_target = (select auth.uid()) then v_reasons := v_reasons || 'target is the caller'; end if;
  if t.is_owner then v_reasons := v_reasons || 'target is an owner account'; end if;
  if t.is_system then v_reasons := v_reasons || 'target is a system account'; end if;
  if (v_map->>'blocker_total')::bigint > 0 then v_reasons := v_reasons || 'blocking references exist'; end if;
  return v_map || jsonb_build_object(
    'target', jsonb_build_object(
      'id', t.id, 'display_name', t.display_name, 'badge_number', t.badge_number,
      'role', t.role, 'division', t.division, 'active', t.active,
      'removed_at', t.removed_at, 'is_test', t.is_test, 'is_system', t.is_system),
    'eligible', cardinality(v_reasons) = 0,
    'ineligible_reasons', to_jsonb(v_reasons));
end $function$
;

CREATE OR REPLACE FUNCTION public.person_merge(p_survivor uuid, p_victims uuid[], p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_reason text := btrim(coalesce(p_reason, ''));
  s public.persons;
  v public.persons;
  v_victim uuid;
  n_gm int; n_media int; n_legal int; n_mdt int; n_veh int;
  n_cil int; n_pp int; n_pv int; n_rel_a int; n_rel_b int; n_wl int;
begin
  if not private.can_delete() then
    raise exception 'person merge is restricted to command (Bureau Lead or higher)';
  end if;
  if v_reason = '' then
    raise exception 'a reason is required to merge person records';
  end if;
  if p_victims is null or cardinality(p_victims) = 0 then
    raise exception 'at least one merge victim is required';
  end if;
  if p_survivor = any (p_victims) then
    raise exception 'the survivor cannot also be a merge victim';
  end if;

  select * into s from public.persons where id = p_survivor for update;
  if s.id is null then raise exception 'survivor person not found'; end if;
  if s.lifecycle = 'merged' then
    raise exception 'the survivor is already merged into another record — merge into its survivor instead';
  end if;

  -- Lock and validate every victim before mutating anything.
  foreach v_victim in array p_victims loop
    select * into v from public.persons where id = v_victim for update;
    if v.id is null then raise exception 'merge victim % not found', v_victim; end if;
    if v.lifecycle = 'merged' then
      raise exception 'person % is already merged and cannot be merged again', v_victim;
    end if;
  end loop;

  foreach v_victim in array p_victims loop
    select * into v from public.persons where id = v_victim;

    -- Plain repoints (no UNIQUE constraints involve person_id here).
    update public.gang_members set person_id = p_survivor where person_id = v_victim;
    get diagnostics n_gm = row_count;
    update public.media set person_id = p_survivor where person_id = v_victim;
    get diagnostics n_media = row_count;
    update public.legal_requests set person_id = p_survivor where person_id = v_victim;
    get diagnostics n_legal = row_count;
    update public.mdt_wanted_projections set person_id = p_survivor where person_id = v_victim;
    get diagnostics n_mdt = row_count;
    update public.vehicles set owner_id = p_survivor where owner_id = v_victim;
    get diagnostics n_veh = row_count;

    -- case_intel_links: UNIQUE(case_id, kind, ref_id) — drop the victim link
    -- where the survivor is already linked to the same case, repoint the rest.
    delete from public.case_intel_links l
     where l.kind = 'person' and l.ref_id = v_victim
       and exists (select 1 from public.case_intel_links d
                    where d.case_id = l.case_id and d.kind = 'person' and d.ref_id = p_survivor);
    update public.case_intel_links set ref_id = p_survivor
     where kind = 'person' and ref_id = v_victim;
    get diagnostics n_cil = row_count;

    -- person_places: UNIQUE(person_id, place_id).
    delete from public.person_places l
     where l.person_id = v_victim
       and exists (select 1 from public.person_places d
                    where d.person_id = p_survivor and d.place_id = l.place_id);
    update public.person_places set person_id = p_survivor where person_id = v_victim;
    get diagnostics n_pp = row_count;

    -- person_vehicles: UNIQUE(person_id, vehicle_id).
    delete from public.person_vehicles l
     where l.person_id = v_victim
       and exists (select 1 from public.person_vehicles d
                    where d.person_id = p_survivor and d.vehicle_id = l.vehicle_id);
    update public.person_vehicles set person_id = p_survivor where person_id = v_victim;
    get diagnostics n_pv = row_count;

    -- person_relationships: drop rows a repoint would turn into self-links,
    -- drop rows whose canonical pair (least, greatest, relationship) would
    -- collide with an existing survivor-side row, then repoint the rest.
    delete from public.person_relationships r
     where (r.person_a = v_victim and r.person_b = p_survivor)
        or (r.person_b = v_victim and r.person_a = p_survivor);
    delete from public.person_relationships r
     where r.person_a = v_victim
       and exists (select 1 from public.person_relationships d
                    where d.id <> r.id and d.relationship = r.relationship
                      and least(d.person_a, d.person_b) = least(p_survivor, r.person_b)
                      and greatest(d.person_a, d.person_b) = greatest(p_survivor, r.person_b));
    delete from public.person_relationships r
     where r.person_b = v_victim
       and exists (select 1 from public.person_relationships d
                    where d.id <> r.id and d.relationship = r.relationship
                      and least(d.person_a, d.person_b) = least(r.person_a, p_survivor)
                      and greatest(d.person_a, d.person_b) = greatest(r.person_a, p_survivor));
    update public.person_relationships set person_a = p_survivor where person_a = v_victim;
    get diagnostics n_rel_a = row_count;
    update public.person_relationships set person_b = p_survivor where person_b = v_victim;
    get diagnostics n_rel_b = row_count;

    -- watchlist: UNIQUE(user_id, target_type, target_id).
    delete from public.watchlist w
     where w.target_type = 'person' and w.target_id = v_victim
       and exists (select 1 from public.watchlist d
                    where d.user_id = w.user_id and d.target_type = 'person'
                      and d.target_id = p_survivor);
    delete from public.narcotic_persons np
     where np.person_id = v_victim
       and exists (select 1 from public.narcotic_persons keep
                   where keep.narcotic_id = np.narcotic_id and keep.person_id = p_survivor
                     and keep.role is not distinct from np.role);
    update public.narcotic_persons set person_id = p_survivor where person_id = v_victim;

    update public.watchlist set target_id = p_survivor
     where target_type = 'person' and target_id = v_victim;
    get diagnostics n_wl = row_count;

    -- Conservative scalar merge: the survivor keeps its own values.
    if (s.alias is null or btrim(s.alias) = '')
       and v.alias is not null and btrim(v.alias) <> '' then
      update public.persons set alias = v.alias where id = p_survivor;
      s.alias := v.alias;
    end if;
    if v.notes is not null and btrim(v.notes) <> '' then
      update public.persons
         set notes = case when notes is null or btrim(notes) = '' then '' else notes || e'\n\n' end
                     || '── merged from ' || v.name || ' ──' || e'\n' || v.notes
       where id = p_survivor;
    end if;
    if v.bolo and not s.bolo then
      update public.persons
         set bolo = true, bolo_reason = v.bolo_reason, bolo_risk = v.bolo_risk,
             bolo_instructions = v.bolo_instructions, bolo_issued_by = v.bolo_issued_by,
             bolo_issued_at = v.bolo_issued_at, bolo_expires_at = v.bolo_expires_at,
             bolo_case_id = v.bolo_case_id
       where id = p_survivor;
      s.bolo := true;
    end if;

    -- Tombstone the victim (kept, never deleted).
    update public.persons
       set lifecycle = 'merged', merged_into = p_survivor, bolo = false, gang_id = null
     where id = v_victim;

    insert into public.audit_log (actor_id, action, entity, entity_id, detail)
    values (v_uid, 'PERSON_MERGED', 'persons', v_victim, jsonb_build_object(
      'survivor_id', p_survivor, 'victim_id', v_victim, 'victim_name', v.name,
      'reason', left(v_reason, 500),
      'repointed', jsonb_build_object(
        'gang_members', n_gm, 'media', n_media, 'legal_requests', n_legal,
        'mdt_wanted_projections', n_mdt, 'vehicles', n_veh,
        'case_intel_links', n_cil, 'person_places', n_pp,
        'person_vehicles', n_pv, 'person_relationships', n_rel_a + n_rel_b,
        'watchlist', n_wl)));
  end loop;
end $function$
;

CREATE OR REPLACE FUNCTION public.publish_announcement(p_title text, p_body text, p_audience text, p_mentions jsonb DEFAULT '[]'::jsonb, p_links jsonb DEFAULT '[]'::jsonb, p_pinned boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); v_id uuid; v_n int := 0; rec record;
begin
  if not (private.is_active() and private.can_announce()) then raise exception 'not authorized to announce'; end if;
  if not private.can_post_audience(p_audience) then raise exception 'not authorized for this audience'; end if;
  if btrim(coalesce(p_title, '')) = '' or btrim(coalesce(p_body, '')) = '' then
    raise exception 'title and body are required';
  end if;
  insert into public.announcements (title, body, audience, pinned, mentions, links)
  values (p_title, p_body, p_audience, coalesce(p_pinned, false),
          coalesce(p_mentions, '[]'::jsonb), coalesce(p_links, '[]'::jsonb))
  returning id into v_id;
  for rec in select * from private.announcement_recipients(p_audience, p_mentions, v_uid) loop
    insert into public.notifications (user_id, type, payload)
    values (rec.user_id, 'announcement', jsonb_build_object(
      'announce_id', v_id, 'title', p_title,
      'reason', case when rec.mentioned then 'You were mentioned: ' || p_title
                     else 'New announcement: ' || p_title end,
      'actor_id', v_uid,
      'actor_name', (select display_name from public.profiles where id = v_uid)));
    v_n := v_n + 1;
  end loop;
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, 'ANNOUNCEMENT_PUBLISHED', 'announcements', v_id);
  return jsonb_build_object('announce_id', v_id, 'recipients', v_n);
end $function$
;

CREATE OR REPLACE FUNCTION public.publish_reading_campaign(p_document uuid, p_audience text, p_targets jsonb DEFAULT '[]'::jsonb, p_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text)
 RETURNS document_reading_campaigns
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.documents; c public.document_reading_campaigns;
  v_uid uuid := (select auth.uid()); v_version uuid; v_name text;
begin
  if not private.can_manage_required_reading() then raise exception 'not authorized'; end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  select * into d from public.documents where id = p_document for update;
  if not found then raise exception 'document not found'; end if;
  if d.status <> 'published' then
    raise exception 'only published documents can be required reading';
  end if;
  select id into v_version from public.documents_versions
   where document_id = d.id and version_number = d.current_version_number;
  if v_version is null then raise exception 'no version row for the current content'; end if;

  update public.documents
     set mandatory = true, acknowledgement_required = true,
         acknowledgement_deadline = p_deadline
   where id = d.id;
  insert into public.document_reading_campaigns
    (document_id, document_version_id, audience, targets, deadline, reason, created_by)
  values (d.id, v_version, p_audience, coalesce(p_targets, '[]'::jsonb),
          p_deadline, p_reason, v_uid)
  returning * into c;

  v_name := regexp_replace(d.name, '\.(docx?|pdf|sheet)$', '', 'i');
  insert into public.notifications (user_id, type, payload)
  select r.user_id, 'document_required', jsonb_build_object(
      'document_id', d.id, 'campaign_id', c.id, 'title', v_name,
      'deadline', p_deadline,
      'reason', 'Required reading: ' || v_name,
      'actor_id', v_uid)
    from private.document_campaign_recipients(d.id, p_audience, p_targets, v_uid) r;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_REQUIRED_READING', 'documents', d.id,
          jsonb_build_object('campaign_id', c.id, 'audience', p_audience,
                             'deadline', p_deadline, 'reason', p_reason));
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.reassign_legal_ada(p_request uuid, p_new_ada uuid, p_reason text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
        v_old uuid; v_same_bureau boolean; v_role text;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if not private.can_manage_legal_assignment(p_request, v_uid) then
    raise exception 'only a District Attorney, Attorney General, or the Owner may reassign requests';
  end if;
  if r.review_status not in ('submitted_to_doj', 'ada_review', 'returned_by_ada') then
    raise exception 'request is not in a reassignable state';
  end if;
  v_role := private.justice_role_of(p_new_ada);
  if v_role not in ('assistant_district_attorney', 'district_attorney') then
    raise exception 'the new reviewer must be an active ADA or DA';
  end if;
  if p_new_ada = r.assigned_judge_id then
    raise exception 'the assigned Judge cannot act as prosecutor on the same request';
  end if;
  v_same_bureau := exists (
    select 1 from public.prosecutor_bureau_assignments a
    where a.prosecutor_id = p_new_ada and a.bureau = r.responsible_bureau and a.ends_at is null);
  if not v_same_bureau and btrim(coalesce(p_reason, '')) = '' then
    raise exception 'cross-bureau or override assignment requires a reason';
  end if;
  v_old := r.assigned_ada_id;
  if v_old is not null then
    perform private.legal_end_participant(p_request, v_old, 'assigned_ada');
  end if;
  update public.legal_requests
     set assigned_ada_id = p_new_ada,
         review_status = case when review_status = 'submitted_to_doj' then 'ada_review' else review_status end
   where id = p_request returning * into r;
  perform private.legal_add_participant(p_request, p_new_ada, 'assigned_ada');
  perform private.legal_log(p_request, r.current_version_id, 'ada_reassigned', null, r.review_status,
    p_reason, null);
  perform private.legal_audit(p_request, 'LEGAL_ADA_REASSIGNED', jsonb_build_object(
    'old_ada', v_old, 'new_ada', p_new_ada, 'cross_bureau', not v_same_bureau,
    'reason', left(coalesce(p_reason, ''), 200)));
  perform private.legal_notify(p_new_ada, p_request, 'legal_request',
    'A ' || r.request_type || ' request was assigned to you.');
  if v_old is not null then
    perform private.legal_notify(v_old, p_request, 'legal_update',
      'A ' || r.request_type || ' request was reassigned away from you.');
  end if;
  perform private.legal_notify(r.created_by, p_request, 'legal_update',
    'Your ' || r.request_type || ' request has a new assigned prosecutor.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.record_subpoena_compliance(p_request uuid, p_status text, p_notes text DEFAULT NULL::text, p_non_compliance_reason text DEFAULT NULL::text, p_date timestamp with time zone DEFAULT now())
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_fulfil text;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.request_type <> 'subpoena' then raise exception 'not a subpoena'; end if;
  if r.fulfilment_status not in ('compliance_pending', 'records_received',
                                 'testimony_completed', 'non_compliance') then
    raise exception 'compliance is recorded after service';
  end if;
  if not private.can_fulfil_legal(p_request, v_uid) then
    raise exception 'only an authorized CID member on this case may record compliance';
  end if;
  if p_status not in ('pending', 'partial', 'complete', 'non_compliant', 'cancelled', 'return_recorded') then
    raise exception 'invalid compliance status';
  end if;
  if p_status = 'non_compliant' and btrim(coalesce(p_non_compliance_reason, '')) = '' then
    raise exception 'a non-compliance reason is required';
  end if;
  v_fulfil := case
    when p_status = 'return_recorded' then 'return_recorded'
    when p_status = 'complete' and r.subtype = 'testimony' then 'testimony_completed'
    when p_status = 'complete' then 'records_received'
    when p_status = 'non_compliant' then 'non_compliance'
    else r.fulfilment_status end;
  update public.legal_requests
     set compliance_status = case when p_status = 'return_recorded' then compliance_status else p_status end,
         compliance_date = coalesce(p_date, now()),
         compliance_notes = coalesce(nullif(btrim(coalesce(p_notes, '')), ''), compliance_notes),
         non_compliance_reason = coalesce(nullif(btrim(coalesce(p_non_compliance_reason, '')), ''), non_compliance_reason),
         fulfilment_status = v_fulfil
   where id = p_request returning * into r;
  perform private.legal_log(p_request, r.current_version_id,
    case when p_status = 'return_recorded' then 'return_filed' else 'compliance_recorded' end,
    null, v_fulfil, p_notes, null);
  perform private.legal_audit(p_request, 'LEGAL_COMPLIANCE_RECORDED', jsonb_build_object('status', p_status));
  perform private.legal_notify(r.assigned_ada_id, p_request, 'legal_update',
    'Subpoena compliance was recorded (' || p_status || ').');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.record_subpoena_service(p_request uuid, p_status text, p_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_acknowledged boolean DEFAULT NULL::boolean, p_served_at timestamp with time zone DEFAULT now())
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.request_type <> 'subpoena' then raise exception 'not a subpoena'; end if;
  if r.fulfilment_status not in ('issued', 'served') then
    raise exception 'service is recorded on an issued subpoena';
  end if;
  if not private.can_fulfil_legal(p_request, v_uid) then
    raise exception 'only an authorized CID member on this case may record service';
  end if;
  if p_status not in ('not_served', 'service_attempted', 'served', 'service_failed', 'waived') then
    raise exception 'invalid service status';
  end if;
  update public.legal_requests
     set service_status = p_status,
         served_at = case when p_status = 'served' then coalesce(p_served_at, now()) else served_at end,
         served_by = case when p_status = 'served' then v_uid else served_by end,
         service_method = coalesce(nullif(btrim(coalesce(p_method, '')), ''), service_method),
         service_notes = coalesce(nullif(btrim(coalesce(p_notes, '')), ''), service_notes),
         recipient_acknowledged = coalesce(p_acknowledged, recipient_acknowledged),
         fulfilment_status = case when p_status in ('served', 'waived')
                                  then 'compliance_pending' else fulfilment_status end
   where id = p_request returning * into r;
  perform private.legal_log(p_request, r.current_version_id, 'served', null, p_status, p_notes, null);
  perform private.legal_audit(p_request, 'LEGAL_SERVICE_RECORDED', jsonb_build_object('status', p_status));
  perform private.legal_notify(r.assigned_ada_id, p_request, 'legal_update',
    'Subpoena service was recorded (' || p_status || ').');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.record_warrant_execution(p_request uuid, p_incident_number text, p_officers uuid[], p_outcome text, p_notes text DEFAULT NULL::text, p_result text DEFAULT 'full'::text, p_executed_at timestamp with time zone DEFAULT now())
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_report uuid; v_seq integer;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.request_type <> 'warrant' then raise exception 'not a warrant'; end if;
  if r.fulfilment_status <> 'issued' then raise exception 'only an issued warrant can be executed'; end if;
  if not private.can_fulfil_legal(p_request, v_uid) then
    raise exception 'only an authorized CID member on this case may record execution';
  end if;
  if coalesce(p_result, 'full') not in ('full', 'partial', 'unable') then
    raise exception 'invalid execution result';
  end if;
  if r.expires_at is not null and r.expires_at < now() then
    raise exception 'this warrant has expired — record expiry via close';
  end if;
  -- Custody-grade requirement for EVERY result: an incident number, at least
  -- one executing officer (each a known profile), and a non-blank result note.
  if btrim(coalesce(p_incident_number, '')) = '' then
    raise exception 'an incident number is required to record execution';
  end if;
  if p_officers is null or array_length(p_officers, 1) is null or array_length(p_officers, 1) < 1 then
    raise exception 'at least one executing officer is required';
  end if;
  if exists (
    select 1 from unnest(p_officers) o
    where not exists (select 1 from public.profiles pr where pr.id = o)) then
    raise exception 'every executing officer must be a known profile';
  end if;
  if btrim(coalesce(p_outcome, '')) = '' then
    raise exception 'a result note is required to record execution';
  end if;

  -- "unable" is NOT an execution: the warrant stays 'issued'. Record the failed
  -- attempt and auto-open a follow-up task on the case.
  if p_result = 'unable' then
    update public.legal_requests
       set execution_result = 'unable',
           execution_outcome = btrim(p_outcome),
           execution_notes = nullif(btrim(coalesce(p_notes, '')), ''),
           execution_incident_number = btrim(p_incident_number),
           execution_officers = p_officers
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'execution_attempt', 'issued', 'issued', p_outcome, null);
    perform private.legal_audit(p_request, 'LEGAL_EXECUTION_UNABLE',
      jsonb_build_object('reason', btrim(p_outcome), 'incident_number', btrim(p_incident_number)));
    if r.case_id is not null then
      insert into public.case_tasks (case_id, title, created_by)
      values (r.case_id,
              'Warrant ' || r.request_number || ': unable to execute — follow up',
              v_uid);
    end if;
    perform private.legal_notify(r.assigned_ada_id, p_request, 'legal_update', 'A warrant could not be executed.');
    return r;
  end if;

  -- full / partial advance to 'executed'.
  update public.legal_requests
     set fulfilment_status = 'executed', executed_by = v_uid,
         executed_at = coalesce(p_executed_at, now()),
         execution_result = p_result,
         execution_outcome = btrim(p_outcome),
         execution_notes = nullif(btrim(coalesce(p_notes, '')), ''),
         execution_incident_number = btrim(p_incident_number),
         execution_officers = p_officers
   where id = p_request returning * into r;

  -- Automation: seed the warrant-return report DRAFT (finalized=false) that
  -- command later reviews + seals via report_finalize; link it on the request.
  if r.case_id is not null then
    select coalesce(max(seq), 0) + 1 into v_seq
      from public.reports
     where case_id = r.case_id and template = 'warrant_return' and kind = 'supplemental';
    insert into public.reports (case_id, template, kind, seq, fields, author_id, finalized)
    values (r.case_id, 'warrant_return', 'supplemental', v_seq,
            jsonb_build_object(
              'request_number', r.request_number,
              'incident_number', btrim(p_incident_number),
              'officers', to_jsonb(p_officers),
              'outcome', btrim(p_outcome),
              'result', p_result,
              'executed_at', coalesce(p_executed_at, now())),
            v_uid, false)
    returning id into v_report;
    update public.legal_requests set return_report_id = v_report where id = p_request returning * into r;
  end if;

  perform private.legal_log(p_request, r.current_version_id, 'executed', 'issued', 'executed', p_outcome, null);
  perform private.legal_audit(p_request, 'LEGAL_EXECUTED',
    jsonb_build_object('outcome', p_outcome, 'result', p_result,
                       'incident_number', btrim(p_incident_number), 'return_report_id', v_report));
  perform private.mdt_project(p_request, 'executed');
  perform private.legal_notify(r.assigned_ada_id, p_request, 'legal_update', 'A warrant was executed.');
  perform private.legal_notify(r.assigned_judge_id, p_request, 'legal_update', 'A warrant you approved was executed.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.record_warrant_return(p_request uuid, p_narrative text, p_report_id uuid DEFAULT NULL::uuid)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.request_type <> 'warrant' then raise exception 'not a warrant'; end if;
  if r.fulfilment_status not in ('executed', 'expired', 'revoked') then
    raise exception 'a return is filed after execution, expiry, or revocation';
  end if;
  if not private.can_fulfil_legal(p_request, v_uid) then
    raise exception 'only an authorized CID member on this case may file the return';
  end if;
  if btrim(coalesce(p_narrative, '')) = '' then raise exception 'a return narrative is required'; end if;
  if p_report_id is not null and (r.case_id is null or not exists (
     select 1 from public.reports rp where rp.id = p_report_id and rp.case_id = r.case_id)) then
    raise exception 'the linked return report must belong to this warrant''s case';
  end if;
  update public.legal_requests
     set fulfilment_status = 'returned', return_narrative = p_narrative,
         returned_at = now(), return_filed_by = v_uid,
         return_report_id = coalesce(p_report_id, return_report_id)
   where id = p_request returning * into r;
  perform private.legal_log(p_request, r.current_version_id, 'return_filed', null, 'returned', null, null);
  perform private.legal_audit(p_request, 'LEGAL_RETURN_FILED',
    jsonb_build_object('report_id', p_report_id));
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.reject_transfer(p_id uuid, p_note text DEFAULT NULL::text)
 RETURNS transfer_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles; r public.transfer_requests;
begin
  select * into me from public.profiles where id = (select auth.uid());
  select * into r from public.transfer_requests where id = p_id for update;
  if r.id is null then raise exception 'transfer not found'; end if;
  if r.status not in ('pending_source', 'pending_target', 'approved') then
    raise exception 'transfer is not open';
  end if;
  if r.target_id = me.id then raise exception 'you cannot decide your own transfer'; end if;
  if not (private.can_decide_transfer_side(r.from_bureau)
          or private.can_decide_transfer_side(r.to_bureau)) then
    raise exception 'not authorized to reject this transfer';
  end if;
  update public.transfer_requests
     set status = 'rejected',
         decision_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), decision_note)
   where id = p_id returning * into r;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (me.id, 'TRANSFER_REJECTED', 'transfer_requests', r.id,
    jsonb_build_object('target_id', r.target_id, 'note', p_note));
  perform private.transfer_notify(r, me, 'Transfer to ' || r.to_bureau || ' was rejected.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.remove_legal_exhibit(p_exhibit uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); e public.legal_request_exhibits;
begin
  select * into e from public.legal_request_exhibits where id = p_exhibit for update;
  if not found then raise exception 'exhibit not found'; end if;
  if not private.can_edit_legal_draft(e.legal_request_id, v_uid) then
    raise exception 'exhibits can only change while the request is editable';
  end if;
  delete from public.legal_request_exhibits where id = p_exhibit;
  perform private.legal_log(e.legal_request_id, null, 'exhibit_removed', null, null, e.display_title, null);
  perform private.legal_audit(e.legal_request_id, 'LEGAL_EXHIBIT_REMOVED',
    jsonb_build_object('exhibit_id', p_exhibit, 'type', e.exhibit_type));
end $function$
;

CREATE OR REPLACE FUNCTION public.report_create(p_case uuid, p_template text, p_kind text DEFAULT NULL::text, p_fields jsonb DEFAULT '{}'::jsonb)
 RETURNS reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  r public.reports;
  v_kind public.report_kind;
  v_seq int;
  v_rt text;
begin
  if not private.is_active() or not private.can_access_case(p_case) then
    raise exception 'case not found or not accessible';
  end if;
  if nullif(btrim(coalesce(p_template, '')), '') is null then
    raise exception 'a report template is required';
  end if;
  if p_kind is not null then
    if p_kind not in ('initial', 'supplemental', 'followup') then
      raise exception 'invalid report kind';
    end if;
    v_kind := p_kind::public.report_kind;
  else
    v_rt := lower(coalesce(p_fields->>'report_type', ''));
    v_kind := (case when v_rt like 'supplemental%' then 'supplemental'
                    when v_rt like 'follow%' then 'followup'
                    else 'initial' end)::public.report_kind;
  end if;

  perform pg_advisory_xact_lock(hashtext('report_seq:' || p_case::text));
  select coalesce(max(x.seq), 0) + 1 into v_seq
    from public.reports x
   where x.case_id = p_case and x.template = btrim(p_template) and x.kind = v_kind;

  insert into public.reports (case_id, template, kind, seq, fields, author_id)
  values (p_case, btrim(p_template), v_kind, v_seq,
          coalesce(p_fields, '{}'::jsonb), v_uid)
  returning * into r;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'REPORT_CREATED', 'reports', r.id,
          jsonb_build_object('case_id', p_case, 'template', r.template,
                             'kind', r.kind, 'seq', r.seq));
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.report_finalize(p_report uuid, p_badge text DEFAULT NULL::text)
 RETURNS reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.reports; v_uid uuid := (select auth.uid()); v_name text; v_num integer;
begin
  select * into r from public.reports where id = p_report for update;
  if not found then raise exception 'report not found'; end if;
  if r.finalized then raise exception 'report already finalized'; end if;
  if not (private.is_active() and private.can_access_case(r.case_id)) then
    raise exception 'not permitted to finalize this report'; end if;
  select display_name into v_name from public.profiles where id = v_uid;
  update public.reports
    set finalized = true,
        signature = jsonb_build_object(
          'officer', coalesce(v_name, 'Officer'),
          'signer_id', v_uid,
          'badge', nullif(btrim(coalesce(p_badge,'')), ''),
          'signed_at', now()
        ),
        updated_at = now()
    where id = p_report returning * into r;
  select coalesce(max(version_number), 0) + 1 into v_num
    from public.report_versions where report_id = p_report;
  insert into public.report_versions (report_id, version_number, fields, signature, created_by)
  values (p_report, v_num, r.fields, r.signature, v_uid);
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.report_reopen(p_report uuid)
 RETURNS reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.reports;
  v_uid uuid := (select auth.uid());
  v_role text;
  v_div text;
begin
  select * into r from public.reports where id = p_report;
  if not found then raise exception 'report not found'; end if;
  select role::text, division::text into v_role, v_div
    from public.profiles where id = v_uid and active;
  if v_role is null or v_role not in ('bureau_lead', 'deputy_director', 'director') then
    raise exception 'only bureau lead and above may reopen a finalized report';
  end if;
  -- Bureau leads unseal only their own bureau's reports (JTF cases are
  -- shared, mirroring can_access_case); deputy director+ are unrestricted.
  if v_role = 'bureau_lead'
     and (select bureau::text from public.cases where id = r.case_id) not in ('JTF', v_div) then
    raise exception 'bureau leads may only reopen reports in their own bureau';
  end if;
  if not r.finalized then raise exception 'report is not finalized'; end if;
  update public.reports
     set finalized = false,
         signature = null,
         fields = coalesce(fields, '{}'::jsonb) || jsonb_build_object(
           '_reopen_log',
           coalesce(fields->'_reopen_log', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
             'at', now(),
             'by', v_uid,
             'prev_signature', signature
           ))
         ),
         updated_at = now()
   where id = p_report
  returning * into r;
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.request_transfer(p_target uuid, p_to_bureau bureau, p_reason text, p_to_role app_role DEFAULT NULL::app_role)
 RETURNS transfer_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  me public.profiles;
  t public.profiles;
  r public.transfer_requests;
  v_to_role public.app_role;
begin
  select * into me from public.profiles where id = v_uid;
  if me.id is null or not (me.active and (me.role in ('bureau_lead','deputy_director','director') or me.is_owner)) then
    raise exception 'not authorized to request transfers';
  end if;
  if p_target = v_uid then raise exception 'you cannot transfer yourself'; end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;

  select * into t from public.profiles where id = p_target for update;
  if t.id is null then raise exception 'member not found'; end if;
  if t.removed_at is not null then raise exception 'member has been removed'; end if;
  if not t.active then raise exception 'member is not active'; end if;
  if t.login_denied then raise exception 'member login is denied'; end if;
  if p_to_bureau = t.division then raise exception 'member is already in %', p_to_bureau; end if;

  v_to_role := coalesce(p_to_role, t.role);
  if v_to_role not in ('detective','senior_detective','bureau_lead','deputy_director','director') then
    raise exception 'invalid role';
  end if;
  if me.role = 'bureau_lead' and not me.is_owner then
    if t.division <> me.division and p_to_bureau <> me.division then
      raise exception 'bureau leads may only request transfers touching their own bureau';
    end if;
    if t.role in ('bureau_lead','deputy_director','director') then
      raise exception 'bureau leads cannot transfer command staff';
    end if;
  end if;
  if v_to_role is distinct from t.role and not private.can_assign_cid_role(v_to_role, p_to_bureau) then
    raise exception 'you are not authorized to assign % in %', v_to_role, p_to_bureau;
  end if;
  if t.is_owner and not me.is_owner then
    raise exception 'only the owner may transfer an owner account';
  end if;

  insert into public.transfer_requests
    (target_id, from_bureau, to_bureau, from_role, to_role, reason, status, requested_by,
     source_approved_by, source_approved_at, target_approved_by, target_approved_at)
  values
    (p_target, t.division, p_to_bureau, t.role, v_to_role, btrim(p_reason), 'approved', v_uid,
     v_uid, now(), v_uid, now())
  returning * into r;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'TRANSFER_REQUESTED', 'transfer_requests', r.id,
    jsonb_build_object('target_id', p_target, 'from', r.from_bureau, 'to', r.to_bureau,
      'from_role', r.from_role, 'to_role', r.to_role, 'reason', r.reason, 'initial_status', 'approved'));

  return private.transfer_apply(r.id, me, false);
end $function$
;

CREATE OR REPLACE FUNCTION public.resolve_case_originating_bureau(p_case uuid, p_bureau bureau, p_reason text DEFAULT NULL::text)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); c public.cases; me public.profiles;
        v_old public.bureau; v_reason text := btrim(coalesce(p_reason, ''));
begin
  select * into me from public.profiles where id = v_uid;
  if me.id is null or not coalesce(me.active, false)
     or not (me.role in ('senior_detective', 'bureau_lead', 'deputy_director', 'director')
             or coalesce(me.is_owner, false)) then
    raise exception 'only a CID supervisor may set the responsible bureau';
  end if;
  select * into c from public.cases where id = p_case for update;
  if not found or not private.can_access_case(p_case) then
    raise exception 'case not found or not accessible';
  end if;
  if p_bureau not in ('major_crimes', 'street_crimes') then
    raise exception 'the responsible bureau must be Major Crimes or Street Crimes';
  end if;
  if c.bureau in ('major_crimes', 'street_crimes') then
    raise exception 'this case''s responsible bureau is its own bureau (%) — use the reassign-bureau workflow to move it', private.bureau_label(c.bureau::text);
  end if;
  v_old := c.originating_bureau;
  if v_old in ('major_crimes', 'street_crimes') then
    if v_old = p_bureau then
      raise exception 'the responsible bureau is already %', private.bureau_label(p_bureau::text);
    end if;
    if not (me.role in ('deputy_director', 'director') or coalesce(me.is_owner, false)) then
      raise exception 'the responsible bureau is already set to % — only a Deputy Director or higher may change it', private.bureau_label(v_old::text);
    end if;
    if v_reason = '' then
      raise exception 'a reason is required to change the responsible bureau';
    end if;
  end if;
  update public.cases set originating_bureau = p_bureau where id = p_case returning * into c;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid,
          case when v_old in ('major_crimes', 'street_crimes')
               then 'ORIGINATING_BUREAU_CHANGED' else 'ORIGINATING_BUREAU_SET' end,
          'cases', p_case,
          jsonb_build_object('bureau', p_bureau, 'previous', v_old, 'source', 'manual',
                             'reason', nullif(left(v_reason, 500), '')));
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.resolve_document_sync(p_document uuid, p_resolution text, p_reason text)
 RETURNS documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  d public.documents; cand public.documents_versions;
  v_uid uuid := (select auth.uid()); v_next int;
begin
  if not private.can_resolve_doc_sync() then raise exception 'not authorized'; end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a resolution reason is required'; end if;
  if p_resolution not in ('keep_portal', 'accept_drive') then
    raise exception 'invalid resolution';
  end if;
  select * into d from public.documents where id = p_document for update;
  if not found then raise exception 'document not found'; end if;
  if d.sync_status is distinct from 'conflict' then raise exception 'document has no sync conflict'; end if;

  if p_resolution = 'accept_drive' then
    select * into cand from public.documents_versions
     where document_id = d.id and source_system = 'google_drive'
       and metadata ->> 'conflict' = 'true'
     order by saved_at desc limit 1;
    if not found then raise exception 'no Drive conflict candidate is stored for this document'; end if;
    v_next := d.current_version_number + 1;
    update public.documents
       set content = coalesce(d.content, '{}'::jsonb)
                     || jsonb_build_object('body', coalesce(cand.content ->> 'body', '')),
           name = coalesce(cand.name, d.name),
           modified_label = cand.modified_label,
           current_version_number = v_next,
           sync_status = 'synced', sync_error = null,
           last_synced_at = now(),
           source_modified_at = coalesce(nullif(cand.source_revision, '')::timestamptz,
                                         d.source_modified_at)
     where id = d.id returning * into d;
    update public.documents_versions
       set version_number = v_next
     where id = cand.id;
  else
    update public.documents
       set sync_status = 'portal_newer', sync_error = null
     where id = d.id returning * into d;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_SYNC_RESOLVED', 'documents', d.id,
          jsonb_build_object('resolution', p_resolution, 'reason', p_reason));
  return d;
end $function$
;

CREATE OR REPLACE FUNCTION public.resolve_provisional_narcotic(p_provisional uuid, p_action text, p_canonical uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS narcotics
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.narcotics;
  v_uid uuid := (select auth.uid());
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_from text;
begin
  if not private.can_manage_narcotics() then
    raise exception 'resolving narcotic records is restricted to Bureau Lead or higher';
  end if;
  if p_action not in ('confirm', 'merge_into', 'disprove', 'archive') then
    raise exception 'invalid action';
  end if;

  select * into r from public.narcotics where id = p_provisional for update;
  if r.id is null then raise exception 'narcotic not found'; end if;
  if r.status = 'merged' then
    raise exception 'this record is already merged and cannot be resolved again';
  end if;
  v_from := r.status;

  if p_action = 'merge_into' then
    if p_canonical is null then
      raise exception 'a canonical record is required to merge into';
    end if;
    r := public.merge_narcotics(p_canonical, p_provisional,
           coalesce(v_note, 'Provisional record resolved as a duplicate'));
  elsif p_action = 'confirm' then
    update public.narcotics
       set status = 'confirmed', last_confirmed_at = now(),
           reviewed_at = now(), reviewed_by = v_uid
     where id = p_provisional returning * into r;
  elsif p_action = 'disprove' then
    update public.narcotics
       set status = 'disproven',
           reviewed_at = now(), reviewed_by = v_uid
     where id = p_provisional returning * into r;
  else  -- archive
    update public.narcotics
       set status = 'archived',
           reviewed_at = now(), reviewed_by = v_uid
     where id = p_provisional returning * into r;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'NARCOTIC_PROVISIONAL_RESOLVED', 'narcotics', p_provisional,
          jsonb_build_object('action', p_action, 'from', v_from,
                             'canonical', p_canonical, 'note', v_note));
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.restore_member_login(p_target uuid)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles; t public.profiles;
begin
  select * into me from public.profiles where id = (select auth.uid());
  if me.id is null or not me.active or not (me.role in ('bureau_lead', 'deputy_director', 'director') or me.is_owner) then
    raise exception 'not authorized to restore login';
  end if;
  select * into t from public.profiles where id = p_target for update;
  if t.id is null then raise exception 'member not found'; end if;
  if me.role = 'bureau_lead' and not me.is_owner and t.division <> me.division then
    raise exception 'bureau leads may only restore members in their own bureau';
  end if;
  update public.profiles
     set login_denied = false, login_denied_at = null, login_denied_by = null, login_denied_reason = null
   where id = p_target returning * into t;
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (me.id, 'LOGIN_RESTORED', 'profiles', p_target);
  insert into public.notifications (user_id, type, payload)
  values (p_target, 'login_restored', jsonb_build_object(
    'reason', 'Your portal access was restored — you can submit a membership request.',
    'actor_id', me.id, 'actor_name', me.display_name));
  return t;
end $function$
;

CREATE OR REPLACE FUNCTION public.restricted_media_break_glass(p_case uuid, p_reason text)
 RETURNS restricted_access_grants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); g public.restricted_access_grants; c public.cases; rec record;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if not private.can_access_case(p_case) then
    raise exception 'you can only break-glass restricted media in a case you have access to';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  select * into c from public.cases where id = p_case;
  if not found then raise exception 'case not found'; end if;
  if private.can_edit_narcotics_intel() then
    raise exception 'you already have clearance to view this restricted media';
  end if;
  insert into public.restricted_access_grants (case_id, user_id, reason)
  values (p_case, v_uid, btrim(p_reason)) returning * into g;
  insert into public.restricted_access_log (entity_type, entity_id, actor_id, action, reason)
  values ('media', p_case, v_uid, 'break_glass', btrim(p_reason));
  for rec in select id from public.profiles where active and role in ('bureau_lead', 'deputy_director', 'director') loop
    insert into public.notifications (user_id, type, payload)
    values (rec.id, 'restricted_break_glass', jsonb_build_object(
      'case_id', p_case, 'case_number', c.case_number, 'actor_id', v_uid, 'reason', btrim(p_reason)));
  end loop;
  return g;
end $function$
;

CREATE OR REPLACE FUNCTION public.restricted_media_count(p_case uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case when private.can_access_case(p_case)
              then (select count(*)::int from public.media where case_id = p_case and restricted)
              else 0 end
$function$
;

CREATE OR REPLACE FUNCTION public.restricted_media_decide_access(p_grant uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS restricted_access_grants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_type text;
  g public.restricted_access_grants;
  c public.cases;
begin
  if not private.is_active() or not private.is_command() then
    raise exception 'restricted-access decisions are restricted to command (Bureau Lead or higher)';
  end if;
  if p_decision not in ('grant', 'deny') then
    raise exception 'invalid decision (grant or deny)';
  end if;
  select * into g from public.restricted_access_grants where id = p_grant for update;
  if not found then raise exception 'request not found'; end if;
  if g.status <> 'pending' then raise exception 'this request has already been decided'; end if;
  if g.user_id = v_uid then
    raise exception 'you cannot decide your own restricted-access request';
  end if;
  if not private.can_access_case(g.case_id) then raise exception 'not authorized'; end if;
  if p_decision = 'deny' and v_note is null then
    raise exception 'a note is required to deny a request';
  end if;
  select * into c from public.cases where id = g.case_id;
  if p_decision = 'grant' then
    update public.restricted_access_grants
       set status = 'granted', decided_by = v_uid, decided_at = now(),
           decision_note = v_note, expires_at = now() + interval '24 hours'
     where id = p_grant returning * into g;
    v_type := 'restricted_access_granted';
  else
    update public.restricted_access_grants
       set status = 'denied', decided_by = v_uid, decided_at = now(), decision_note = v_note
     where id = p_grant returning * into g;
    v_type := 'restricted_access_denied';
  end if;
  insert into public.restricted_access_log (entity_type, entity_id, actor_id, action, reason)
  values ('media', g.case_id, v_uid,
          case when p_decision = 'grant' then 'grant' else 'deny' end, v_note);
  insert into public.notifications (user_id, type, payload)
  values (g.user_id, v_type, jsonb_build_object(
    'case_id', g.case_id, 'case_number', c.case_number, 'grant_id', g.id,
    'actor_id', v_uid, 'note', left(coalesce(v_note, ''), 200),
    'expires_at', case when p_decision = 'grant' then to_jsonb(g.expires_at) else 'null'::jsonb end));
  if c.lead_detective_id is not null
     and c.lead_detective_id <> v_uid and c.lead_detective_id <> g.user_id then
    insert into public.notifications (user_id, type, payload)
    values (c.lead_detective_id, v_type, jsonb_build_object(
      'case_id', g.case_id, 'case_number', c.case_number, 'grant_id', g.id,
      'actor_id', v_uid, 'note', left(coalesce(v_note, ''), 200)));
  end if;
  return g;
end $function$
;

CREATE OR REPLACE FUNCTION public.restricted_media_request_access(p_case uuid, p_reason text)
 RETURNS restricted_access_grants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  g public.restricted_access_grants;
  c public.cases;
  rec record;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if not private.can_access_case(p_case) then
    raise exception 'you can only request restricted-media access in a case you have access to';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  if private.can_edit_narcotics_intel() then
    raise exception 'you already have clearance to view this restricted media';
  end if;
  select * into c from public.cases where id = p_case;
  if not found then raise exception 'case not found'; end if;
  if exists (select 1 from public.restricted_access_grants x
              where x.case_id = p_case and x.user_id = v_uid and x.revoked_at is null
                and (x.status = 'pending'
                     or (x.status = 'granted' and x.expires_at > now()))) then
    raise exception 'you already have a pending request or a live grant for this case';
  end if;
  insert into public.restricted_access_grants (case_id, user_id, reason)
  values (p_case, v_uid, btrim(p_reason))
  returning * into g;
  insert into public.restricted_access_log (entity_type, entity_id, actor_id, action, reason)
  values ('media', p_case, v_uid, 'request', btrim(p_reason));
  for rec in select id from public.profiles
             where active and role in ('bureau_lead', 'deputy_director', 'director') loop
    if rec.id <> v_uid then
      insert into public.notifications (user_id, type, payload)
      values (rec.id, 'restricted_access_requested', jsonb_build_object(
        'case_id', p_case, 'case_number', c.case_number, 'grant_id', g.id,
        'actor_id', v_uid, 'reason', left(btrim(p_reason), 200)));
    end if;
  end loop;
  if c.lead_detective_id is not null and c.lead_detective_id <> v_uid and not exists (
       select 1 from public.profiles
       where id = c.lead_detective_id and active
         and role in ('bureau_lead', 'deputy_director', 'director')) then
    insert into public.notifications (user_id, type, payload)
    values (c.lead_detective_id, 'restricted_access_requested', jsonb_build_object(
      'case_id', p_case, 'case_number', c.case_number, 'grant_id', g.id,
      'actor_id', v_uid, 'reason', left(btrim(p_reason), 200)));
  end if;
  return g;
exception when unique_violation then
  raise exception 'you already have a pending request for this case';
end $function$
;

CREATE OR REPLACE FUNCTION public.restricted_media_revoke_access(p_grant uuid, p_reason text)
 RETURNS restricted_access_grants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_reason text := btrim(coalesce(p_reason, ''));
  g public.restricted_access_grants;
  c public.cases;
begin
  if not private.is_active() or not private.is_command() then
    raise exception 'restricted-access revocation is restricted to command (Bureau Lead or higher)';
  end if;
  if v_reason = '' then raise exception 'a reason is required'; end if;
  select * into g from public.restricted_access_grants where id = p_grant for update;
  if not found then raise exception 'grant not found'; end if;
  if g.status <> 'granted' or g.revoked_at is not null or g.expires_at <= now() then
    raise exception 'only a live grant can be revoked';
  end if;
  if not private.can_access_case(g.case_id) then raise exception 'not authorized'; end if;
  select * into c from public.cases where id = g.case_id;
  update public.restricted_access_grants
     set status = 'revoked', revoked_at = now(), revoked_by = v_uid, revoke_reason = v_reason
   where id = p_grant returning * into g;
  insert into public.restricted_access_log (entity_type, entity_id, actor_id, action, reason)
  values ('media', g.case_id, v_uid, 'revoke', v_reason);
  if g.user_id <> v_uid then
    insert into public.notifications (user_id, type, payload)
    values (g.user_id, 'restricted_access_revoked', jsonb_build_object(
      'case_id', g.case_id, 'case_number', c.case_number, 'grant_id', g.id,
      'actor_id', v_uid, 'reason', left(v_reason, 200)));
  end if;
  if c.lead_detective_id is not null
     and c.lead_detective_id <> v_uid and c.lead_detective_id <> g.user_id then
    insert into public.notifications (user_id, type, payload)
    values (c.lead_detective_id, 'restricted_access_revoked', jsonb_build_object(
      'case_id', g.case_id, 'case_number', c.case_number, 'grant_id', g.id,
      'actor_id', v_uid, 'reason', left(v_reason, 200)));
  end if;
  return g;
end $function$
;

CREATE OR REPLACE FUNCTION public.review_justice_membership_request(p_request uuid, p_decision text, p_final_agency text DEFAULT NULL::text, p_final_role text DEFAULT NULL::text, p_applicant_note text DEFAULT NULL::text, p_internal_note text DEFAULT NULL::text)
 RETURNS justice_membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.justice_membership_requests;
  v_uid uuid := (select auth.uid());
  v_reviewer_name text;
  v_status text;
begin
  select display_name into v_reviewer_name from public.profiles
   where id = v_uid and removed_at is null;
  if v_reviewer_name is null then raise exception 'not authorized'; end if;
  select * into r from public.justice_membership_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.status <> 'pending' then raise exception 'request is not awaiting review'; end if;
  if r.applicant_id = v_uid then raise exception 'you cannot review your own request'; end if;
  if p_decision not in ('approve', 'approve_with_changes', 'request_correction', 'reject') then
    raise exception 'invalid decision';
  end if;
  -- Authority is checked against the requested role for return/reject and
  -- against the FINAL role for approval (both, when they differ).
  if not private.can_review_justice_role(v_uid, r.requested_justice_role) then
    raise exception 'not authorized to review this justice request';
  end if;

  if p_decision = 'request_correction' then
    update public.justice_membership_requests
       set status = 'correction_requested',
           applicant_visible_decision_note = p_applicant_note,
           internal_decision_note = coalesce(p_internal_note, internal_decision_note)
     where id = p_request returning * into r;
    perform private.jmr_history(p_request, 'correction_requested', 'pending', 'correction_requested', p_applicant_note, false);
    if p_internal_note is not null then
      perform private.jmr_history(p_request, 'internal_note', null, null, p_internal_note, true);
    end if;
    insert into public.audit_log (actor_id, action, entity, entity_id)
    values (v_uid, 'CORRECTION_REQUESTED', 'justice_membership_requests', p_request);
    insert into public.notifications (user_id, type, payload)
    values (r.applicant_id, 'justice_membership_update', jsonb_build_object(
      'request_id', p_request, 'status', 'correction_requested',
      'reason', 'Your justice membership request needs a correction.',
      'actor_id', v_uid, 'actor_name', v_reviewer_name));
    return r;
  end if;

  if p_decision = 'reject' then
    update public.justice_membership_requests
       set status = 'rejected', decided_by = v_uid, decided_at = now(),
           applicant_visible_decision_note = p_applicant_note,
           internal_decision_note = coalesce(p_internal_note, internal_decision_note)
     where id = p_request returning * into r;
    perform private.jmr_history(p_request, 'rejected', 'pending', 'rejected', p_applicant_note, false);
    if p_internal_note is not null then
      perform private.jmr_history(p_request, 'internal_note', null, null, p_internal_note, true);
    end if;
    insert into public.audit_log (actor_id, action, entity, entity_id)
    values (v_uid, 'REJECTED', 'justice_membership_requests', p_request);
    insert into public.notifications (user_id, type, payload)
    values (r.applicant_id, 'justice_membership_update', jsonb_build_object(
      'request_id', p_request, 'status', 'rejected',
      'reason', 'Your justice membership request was rejected.',
      'actor_id', v_uid, 'actor_name', v_reviewer_name));
    return r;
  end if;

  -- approve / approve_with_changes
  if p_final_agency is null or p_final_role is null then
    raise exception 'a final agency and justice role are required to approve';
  end if;
  if not ((p_final_agency = 'doj' and p_final_role in
            ('assistant_district_attorney', 'district_attorney', 'attorney_general'))
          or (p_final_agency = 'judiciary' and p_final_role = 'judge')) then
    raise exception 'invalid agency/role combination';
  end if;
  if not private.can_review_justice_role(v_uid, p_final_role) then
    raise exception 'not authorized to approve into that justice role';
  end if;
  if exists (select 1 from public.profiles t
             where t.id = r.applicant_id and (t.removed_at is not null or t.login_denied)) then
    raise exception 'applicant profile unavailable';
  end if;
  -- One person, one active organization: an active CID member cannot be
  -- granted a justice membership on top (the inverse of assign_member's
  -- justice guard). Organization correction (Move to DOJ/Judiciary) is the
  -- sanctioned path — it deactivates the CID side in the same transaction.
  if exists (select 1 from public.profiles t
             where t.id = r.applicant_id and t.active) then
    raise exception 'applicant is an active CID member — use organization correction (Move to DOJ/Judiciary) instead of approving a second membership';
  end if;

  v_status := case when p_decision = 'approve'
                    and p_final_agency = r.requested_agency
                    and p_final_role = r.requested_justice_role
              then 'approved' else 'approved_with_changes' end;
  update public.justice_membership_requests
     set status = v_status, decided_by = v_uid, decided_at = now(),
         decided_agency = p_final_agency, decided_justice_role = p_final_role,
         applicant_visible_decision_note = p_applicant_note,
         internal_decision_note = coalesce(p_internal_note, internal_decision_note)
   where id = p_request returning * into r;

  insert into public.justice_memberships
    (user_id, agency, justice_role, active, justice_identifier, approved_by, approved_at)
  values (r.applicant_id, p_final_agency, p_final_role, true, r.justice_identifier, v_uid, now())
  on conflict (user_id) do update
    set agency = excluded.agency, justice_role = excluded.justice_role,
        active = true, justice_identifier = excluded.justice_identifier,
        approved_by = excluded.approved_by, approved_at = excluded.approved_at;

  perform private.jmr_history(p_request, v_status, 'pending', v_status, p_applicant_note, false);
  if p_internal_note is not null then
    perform private.jmr_history(p_request, 'internal_note', null, null, p_internal_note, true);
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, upper(v_status), 'justice_membership_requests', p_request,
          jsonb_build_object('agency', p_final_agency, 'justice_role', p_final_role));
  insert into public.notifications (user_id, type, payload)
  values (r.applicant_id, 'justice_membership_update', jsonb_build_object(
    'request_id', p_request, 'status', v_status,
    'reason', case when v_status = 'approved' then 'Your justice membership request was approved.'
                   else 'Your justice membership request was approved with changes.' end,
    'actor_id', v_uid, 'actor_name', v_reviewer_name));
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.review_legal_request_as_ada(p_request uuid, p_decision text, p_note text DEFAULT NULL::text, p_judge uuid DEFAULT NULL::uuid, p_signature text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_ver uuid;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'ada_review' then raise exception 'request is not in ADA review'; end if;
  if not private.can_review_as_ada(p_request, v_uid) then
    raise exception 'only the assigned prosecutor may review this request';
  end if;
  if v_uid = r.assigned_judge_id then
    raise exception 'you cannot act as prosecutor and Judge on the same request';
  end if;
  if p_decision not in ('return', 'submit_to_judge', 'submit_to_da', 'submit_to_ag', 'note') then
    raise exception 'invalid decision';
  end if;

  if p_decision = 'note' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a note is required'; end if;
    perform private.legal_log(p_request, r.current_version_id, 'ada_review_note', null, null, null, p_note);
    return r;
  end if;

  if p_decision = 'return' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a return requires a note'; end if;
    update public.legal_requests
       set review_status = 'returned_by_ada', document_status = 'reopened'
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'returned_by_ada',
      'ada_review', 'returned_by_ada', p_note, null);
    perform private.legal_audit(p_request, 'LEGAL_RETURNED_BY_ADA', jsonb_build_object('note', left(p_note, 200)));
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' request was returned by the prosecutor.');
    return r;
  end if;

  if p_decision = 'submit_to_da' then
    if r.approval_route not in ('da', 'ag') then
      raise exception 'this request''s approval route does not include DA review';
    end if;
    update public.legal_requests set review_status = 'da_review' where id = p_request returning * into r;
    v_ver := private.legal_freeze_version(p_request, 'submitted_to_da');
    select * into r from public.legal_requests where id = p_request;
    perform private.legal_sign(p_request, v_ver, 'ada_submission', p_signature);
    perform private.legal_add_participant(p_request, v_uid, 'assigned_ada');
    perform private.legal_log(p_request, v_ver, 'submitted_to_da', 'ada_review', 'da_review', p_note, null);
    perform private.legal_audit(p_request, 'LEGAL_SUBMITTED_TO_DA', jsonb_build_object('version', v_ver));
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' request advanced to DA review.');
    return r;
  end if;

  if p_decision = 'submit_to_ag' then
    if r.approval_route <> 'ag' then
      raise exception 'this request''s approval route does not include AG review';
    end if;
    update public.legal_requests set review_status = 'ag_review' where id = p_request returning * into r;
    v_ver := private.legal_freeze_version(p_request, 'submitted_to_ag');
    select * into r from public.legal_requests where id = p_request;
    perform private.legal_sign(p_request, v_ver, 'ada_submission', p_signature);
    perform private.legal_log(p_request, v_ver, 'submitted_to_ag', 'ada_review', 'ag_review', p_note, null);
    perform private.legal_audit(p_request, 'LEGAL_SUBMITTED_TO_AG', jsonb_build_object('version', v_ver));
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' request advanced to AG review.');
    return r;
  end if;

  -- submit_to_judge
  if r.approval_route <> 'judge' then
    raise exception 'this request''s approval route is % — it is not submitted to a Judge', r.approval_route;
  end if;
  update public.legal_requests
     set review_status = 'submitted_to_judge', submitted_to_judge_at = now()
   where id = p_request returning * into r;
  v_ver := private.legal_freeze_version(p_request, 'submitted_to_judge');
  select * into r from public.legal_requests where id = p_request;
  perform private.legal_sign(p_request, v_ver, 'ada_submission', p_signature);
  perform private.legal_log(p_request, v_ver, 'submitted_to_judge',
    'ada_review', 'submitted_to_judge', p_note, null);
  perform private.legal_audit(p_request, 'LEGAL_SUBMITTED_TO_JUDGE', jsonb_build_object('version', v_ver));
  perform private.legal_notify(r.created_by, p_request, 'legal_update',
    'Your ' || r.request_type || ' request was submitted for judicial review.');
  if p_judge is not null then
    return public.assign_judge(p_request, p_judge);
  end if;
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.review_legal_request_as_ag(p_request uuid, p_decision text, p_note text DEFAULT NULL::text, p_signature text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_ver uuid;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'ag_review' then raise exception 'request is not in AG review'; end if;
  if not private.can_review_as_ag(p_request, v_uid) then
    raise exception 'only the Attorney General may perform AG review';
  end if;
  if v_uid = r.assigned_judge_id then
    raise exception 'you cannot act as prosecutor and Judge on the same request';
  end if;
  if p_decision not in ('approve', 'deny', 'return', 'forward_to_judge') then
    raise exception 'invalid decision';
  end if;
  perform private.legal_add_participant(p_request, v_uid, 'attorney_general');

  if p_decision = 'return' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a return requires a note'; end if;
    update public.legal_requests
       set review_status = 'returned_by_ag', document_status = 'reopened'
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'returned_by_ag',
      'ag_review', 'returned_by_ag', p_note, null);
    perform private.legal_audit(p_request, 'LEGAL_RETURNED_BY_AG', jsonb_build_object('note', left(p_note, 200)));
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' request was returned by the Attorney General.');
    return r;
  end if;

  if p_decision = 'forward_to_judge' then
    if r.approval_route <> 'judge' then raise exception 'this request''s route does not include judicial review'; end if;
    update public.legal_requests
       set review_status = 'submitted_to_judge', submitted_to_judge_at = now()
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'submitted_to_judge',
      'ag_review', 'submitted_to_judge', p_note, null);
    return r;
  end if;

  -- approve / deny — valid ONLY on the AG route; never judicial approval.
  if r.approval_route <> 'ag' then
    raise exception 'AG approval applies only when the approval route is ag (never to warrants)';
  end if;
  if p_decision = 'deny' and btrim(coalesce(p_note, '')) = '' then
    raise exception 'a denial requires a note';
  end if;
  update public.legal_requests
     set review_status = case p_decision when 'approve' then 'approved' else 'denied' end,
         decision = case p_decision when 'approve' then 'approved' else 'denied' end,
         decision_note = p_note, decided_by = v_uid, decided_at = now()
   where id = p_request returning * into r;
  v_ver := private.legal_freeze_version(p_request, r.review_status);
  select * into r from public.legal_requests where id = p_request;
  perform private.legal_sign(p_request, v_ver, 'ag_decision', p_signature);
  perform private.legal_log(p_request, v_ver, case p_decision when 'approve' then 'approved' else 'denied' end,
    'ag_review', r.review_status, p_note, null);
  perform private.legal_audit(p_request, 'LEGAL_AG_DECISION',
    jsonb_build_object('decision', p_decision, 'version', v_ver));
  perform private.legal_notify(r.created_by, p_request, 'legal_decision',
    'Your ' || r.request_type || ' request was ' || r.review_status || ' by the Attorney General.');
  perform private.legal_notify(r.assigned_ada_id, p_request, 'legal_decision',
    'A request you prosecuted was ' || r.review_status || ' by the Attorney General.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.review_legal_request_as_cid(p_request uuid, p_decision text, p_note text DEFAULT NULL::text, p_override_reason text DEFAULT NULL::text, p_signature text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_ver uuid;
        v_exhibits integer; v_prosecutors integer := 0; rec record;
        me public.profiles; c public.cases; v_fallback boolean; v_jtf_any boolean;
        v_siu boolean; v_stage text; v_returned text; v_ags integer := 0;
        v_rank text;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  v_siu := private.legal_is_siu(p_request);
  v_stage := case when v_siu then 'siu_command_review' else 'cid_supervisor_review' end;
  v_returned := case when v_siu then 'returned_by_siu_command' else 'returned_by_cid' end;
  if r.review_status <> v_stage then
    raise exception 'request is not awaiting % review', case when v_siu then 'SIB command' else 'CID' end;
  end if;
  if not private.can_approve_legal(p_request, v_uid) then
    raise exception 'only % may decide this request',
      case when v_siu then 'SIB command' else 'Bureau Lead or above' end;
  end if;
  if p_decision not in ('approve', 'deny', 'return') then raise exception 'invalid decision'; end if;
  select * into me from public.profiles where id = v_uid;
  select * into c from public.cases where id = r.case_id;
  v_rank := case when coalesce(me.is_owner, false) and me.role is null then 'owner'
                 else me.role end;
  v_jtf_any := (not v_siu) and (me.role = 'bureau_lead' and c.bureau = 'JTF' and me.division <> r.responsible_bureau);
  v_fallback := (not v_siu) and not (me.role = 'bureau_lead' and me.division = r.responsible_bureau) and not v_jtf_any;

  if p_decision = 'return' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a return requires a note'; end if;
    update public.legal_requests
       set review_status = v_returned, document_status = 'reopened'
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, v_returned,
      v_stage, v_returned, p_note, null);
    perform private.legal_audit(p_request,
      case when v_siu then 'LEGAL_RETURNED_BY_SIU_COMMAND' else 'LEGAL_RETURNED_BY_CID' end,
      jsonb_build_object('note', left(p_note, 200), 'fallback', v_fallback,
                         'jtf_any_lead', v_jtf_any, 'actor_rank', v_rank));
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' request was returned by '
      || case when v_siu then 'SIB command' else 'CID review' end || '.');
    return r;
  end if;

  if p_decision = 'deny' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a denial requires a note'; end if;
    update public.legal_requests
       set decision = 'denied', decision_note = p_note,
           decided_by = v_uid, decided_at = now(),
           review_status = 'denied',
           cid_reviewed_role = v_rank
     where id = p_request returning * into r;
    v_ver := private.legal_freeze_version(p_request, 'denied');
    select * into r from public.legal_requests where id = p_request;
    perform private.legal_log(p_request, v_ver, 'denied', v_stage, 'denied', p_note, null);
    perform private.legal_audit(p_request, 'LEGAL_DENIED_BY_COMMAND',
      jsonb_build_object('version', v_ver, 'note', left(p_note, 200),
                         'siu', v_siu, 'fallback', v_fallback,
                         'jtf_any_lead', v_jtf_any, 'actor_rank', v_rank));
    perform private.legal_notify(r.created_by, p_request, 'legal_decision',
      'Your ' || r.request_type || ' request was denied by command.');
    return r;
  end if;

  if r.source_report_id is not null
     and not exists (select 1 from public.reports rp where rp.id = r.source_report_id and rp.finalized) then
    raise exception 'the source report must be finalized before approval';
  end if;
  select count(*) into v_exhibits from public.legal_request_exhibits where legal_request_id = p_request;
  if v_exhibits = 0 and btrim(coalesce(p_override_reason, '')) = '' then
    raise exception 'at least one supporting item is required (or record an override reason)';
  end if;

  if v_siu then
    update public.legal_requests
       set cid_reviewed_by = v_uid, cid_reviewed_at = now(),
           cid_reviewed_role = v_rank,
           review_status = 'ag_review',
           submitted_to_doj_at = coalesce(submitted_to_doj_at, now()),
           queue_entered_at = now(),
           assigned_prosecutor_id = null, prosecutor_claimed_at = null
     where id = p_request returning * into r;
    v_ver := private.legal_freeze_version(p_request, 'siu_command_approved');
    select * into r from public.legal_requests where id = p_request;
    perform private.legal_sign(p_request, v_ver, 'siu_command_approval', p_signature);
    perform private.legal_add_participant(p_request, v_uid, 'cid_supervisor');
    perform private.legal_log(p_request, v_ver, 'siu_command_approved',
      'siu_command_review', 'ag_review', p_note,
      nullif(btrim(coalesce(p_override_reason, '')), ''));
    if v_exhibits = 0 then
      perform private.legal_log(p_request, v_ver, 'packet_override', null, null,
        'Approved without supporting items: ' || p_override_reason, null);
    end if;
    perform private.legal_audit(p_request, 'LEGAL_APPROVED_BY_SIU_COMMAND',
      jsonb_build_object('version', v_ver, 'packet_override', v_exhibits = 0,
                         'to', 'ag_review', 'actor_rank', v_rank));
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' request passed SIB command review and is with the Attorney General.');
    for rec in
      select p.id from public.profiles p
       where coalesce(private.justice_role_effective(p.id) = 'attorney_general', false)
    loop
      v_ags := v_ags + 1;
      perform private.legal_notify(rec.id, p_request, 'legal_request',
        'An SIB ' || r.request_type || ' request awaits Attorney General review.');
    end loop;
    if v_ags = 0 then
      for rec in
        select p.id from public.profiles p where p.is_owner and p.removed_at is null
      loop
        perform private.legal_notify(rec.id, p_request, 'legal_coverage',
          'An SIB legal request is with the Attorney General, and no Attorney General is seated.');
      end loop;
      perform private.legal_audit(p_request, 'LEGAL_AG_UNCOVERED',
        jsonb_build_object('version', v_ver));
    end if;
    return r;
  end if;

  update public.legal_requests
     set cid_reviewed_by = v_uid, cid_reviewed_at = now(),
         cid_reviewed_role = v_rank,
         review_status = 'prosecutor_queue',
         submitted_to_doj_at = coalesce(submitted_to_doj_at, now()),
         queue_entered_at = now(),
         assigned_prosecutor_id = null, prosecutor_claimed_at = null
   where id = p_request returning * into r;
  v_ver := private.legal_freeze_version(p_request, 'cid_approved');
  select * into r from public.legal_requests where id = p_request;
  perform private.legal_sign(p_request, v_ver, 'cid_supervisor_approval', p_signature);
  perform private.legal_add_participant(p_request, v_uid, 'cid_supervisor');
  perform private.legal_log(p_request, v_ver, 'cid_approved',
    'cid_supervisor_review', 'prosecutor_queue', p_note,
    nullif(btrim(coalesce(p_override_reason, '')), ''));
  if v_jtf_any then
    perform private.legal_log(p_request, v_ver, 'command_fallback', null, null,
      'Approved by a Bureau Lead from another bureau, permitted because the case is JTF.', null);
  elsif v_fallback then
    perform private.legal_log(p_request, v_ver, 'command_fallback', null, null,
      'Approved by command standing in for the ' || private.bureau_label(r.responsible_bureau::text) || ' Bureau Lead.', null);
  end if;
  if v_exhibits = 0 then
    perform private.legal_log(p_request, v_ver, 'packet_override', null, null,
      'Approved without supporting items: ' || p_override_reason, null);
  end if;
  perform private.legal_audit(p_request, 'LEGAL_APPROVED_BY_COMMAND',
    jsonb_build_object('version', v_ver, 'bureau', r.responsible_bureau,
                       'packet_override', v_exhibits = 0, 'to', 'prosecutor_queue',
                       'fallback', v_fallback, 'jtf_any_lead', v_jtf_any,
                       'actor_rank', v_rank));
  perform private.legal_notify(r.created_by, p_request, 'legal_update',
    'Your ' || r.request_type || ' request passed CID review and entered the ' || private.bureau_label(r.responsible_bureau::text) || ' prosecutor queue.');
  if r.classification <> 'sealed' then
    for rec in
      select m.user_id from public.justice_memberships m
       where m.active and (m.expires_at is null or m.expires_at > now())
         and m.justice_role in ('prosecutor', 'assistant_district_attorney', 'district_attorney')
         and r.responsible_bureau = any (private.prosecutor_bureaus_of(m.user_id))
    loop
      v_prosecutors := v_prosecutors + 1;
      perform private.legal_notify(rec.user_id, p_request, 'legal_request',
        'A ' || r.request_type || ' request entered the ' || private.bureau_label(r.responsible_bureau::text) || ' prosecutor queue.');
    end loop;
  end if;
  if v_prosecutors = 0 then
    for rec in
      select p.id from public.profiles p
       where (p.is_owner and p.removed_at is null)
          or coalesce(private.justice_role_effective(p.id) = 'attorney_general', false)
    loop
      perform private.legal_notify(rec.id, p_request, 'legal_coverage',
        'The ' || private.bureau_label(r.responsible_bureau::text) || ' prosecutor queue has no covering prosecutor.');
    end loop;
  end if;
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.review_legal_request_as_da(p_request uuid, p_decision text, p_note text DEFAULT NULL::text, p_signature text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_ver uuid;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'da_review' then raise exception 'request is not in DA review'; end if;
  if not private.can_review_as_da(p_request, v_uid) then
    raise exception 'only a District Attorney may perform DA review';
  end if;
  if v_uid = r.assigned_judge_id then
    raise exception 'you cannot act as prosecutor and Judge on the same request';
  end if;
  if p_decision not in ('approve', 'deny', 'return', 'forward_to_ag', 'forward_to_judge') then
    raise exception 'invalid decision';
  end if;
  perform private.legal_add_participant(p_request, v_uid, 'district_attorney');

  if p_decision = 'return' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a return requires a note'; end if;
    update public.legal_requests
       set review_status = 'returned_by_da', document_status = 'reopened'
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'returned_by_da',
      'da_review', 'returned_by_da', p_note, null);
    perform private.legal_audit(p_request, 'LEGAL_RETURNED_BY_DA', jsonb_build_object('note', left(p_note, 200)));
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' request was returned by the District Attorney.');
    return r;
  end if;

  if p_decision = 'forward_to_ag' then
    if r.approval_route <> 'ag' then raise exception 'this request''s route does not include AG review'; end if;
    update public.legal_requests set review_status = 'ag_review' where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'submitted_to_ag', 'da_review', 'ag_review', p_note, null);
    return r;
  end if;

  if p_decision = 'forward_to_judge' then
    if r.approval_route <> 'judge' then raise exception 'this request''s route does not include judicial review'; end if;
    update public.legal_requests
       set review_status = 'submitted_to_judge', submitted_to_judge_at = now()
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'submitted_to_judge',
      'da_review', 'submitted_to_judge', p_note, null);
    return r;
  end if;

  -- approve / deny — valid ONLY on the DA route; never a judicial approval.
  if r.approval_route <> 'da' then
    raise exception 'DA approval applies only when the approval route is da (never to warrants)';
  end if;
  if p_decision = 'deny' and btrim(coalesce(p_note, '')) = '' then
    raise exception 'a denial requires a note';
  end if;
  update public.legal_requests
     set review_status = case p_decision when 'approve' then 'approved' else 'denied' end,
         decision = case p_decision when 'approve' then 'approved' else 'denied' end,
         decision_note = p_note, decided_by = v_uid, decided_at = now()
   where id = p_request returning * into r;
  v_ver := private.legal_freeze_version(p_request, r.review_status);
  select * into r from public.legal_requests where id = p_request;
  perform private.legal_sign(p_request, v_ver, 'da_decision', p_signature);
  perform private.legal_log(p_request, v_ver, case p_decision when 'approve' then 'approved' else 'denied' end,
    'da_review', r.review_status, p_note, null);
  perform private.legal_audit(p_request, 'LEGAL_DA_DECISION',
    jsonb_build_object('decision', p_decision, 'version', v_ver));
  perform private.legal_notify(r.created_by, p_request, 'legal_decision',
    'Your ' || r.request_type || ' request was ' || r.review_status || ' by the District Attorney.');
  perform private.legal_notify(r.assigned_ada_id, p_request, 'legal_decision',
    'A request you prosecuted was ' || r.review_status || ' by the District Attorney.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.review_legal_request_as_prosecutor(p_request uuid, p_decision text, p_note text DEFAULT NULL::text, p_signature text DEFAULT NULL::text, p_capacity text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_ver uuid; v_cap text;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'prosecutor_review' then
    raise exception 'request is not under prosecutorial review';
  end if;
  if r.assigned_prosecutor_id is distinct from v_uid then
    raise exception 'only the assigned prosecutor may act on this request';
  end if;
  if p_decision not in ('approve', 'return', 'decline', 'note') then
    raise exception 'invalid decision';
  end if;
  v_cap := private.legal_capacity(v_uid, coalesce(p_capacity, 'doj'));

  if p_decision = 'note' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a note is required'; end if;
    perform private.legal_log(p_request, r.current_version_id, 'prosecutor_review_note',
      null, null, null, p_note);
    return r;
  end if;

  if p_decision = 'return' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a return requires corrections in the note'; end if;
    perform private.legal_end_participant(p_request, v_uid, 'prosecutor');
    update public.legal_requests
       set review_status = 'returned_by_prosecutor', document_status = 'reopened',
           assigned_prosecutor_id = null, prosecutor_claimed_at = null
     where id = p_request returning * into r;
    perform private.legal_log(p_request, r.current_version_id, 'returned_by_prosecutor',
      'prosecutor_review', 'returned_by_prosecutor', p_note, 'capacity: ' || v_cap);
    perform private.legal_audit(p_request, 'LEGAL_RETURNED_BY_PROSECUTOR',
      jsonb_build_object('note', left(p_note, 200), 'capacity', v_cap));
    perform private.legal_notify(r.created_by, p_request, 'legal_update',
      'Your ' || r.request_type || ' request was returned by the prosecutor with required corrections.');
    return r;
  end if;

  if p_decision = 'decline' then
    if btrim(coalesce(p_note, '')) = '' then raise exception 'a decline requires a recorded reason'; end if;
    update public.legal_requests
       set review_status = 'declined',
           decision = 'denied', decision_note = p_note,
           decided_by = v_uid, decided_at = now()
     where id = p_request returning * into r;
    v_ver := private.legal_freeze_version(p_request, 'declined');
    select * into r from public.legal_requests where id = p_request;
    perform private.legal_sign(p_request, v_ver, 'prosecutor_decision', p_signature);
    perform private.legal_log(p_request, v_ver, 'declined',
      'prosecutor_review', 'declined', p_note, 'capacity: ' || v_cap);
    perform private.legal_audit(p_request, 'LEGAL_DECLINED_BY_PROSECUTOR',
      jsonb_build_object('version', v_ver, 'note', left(p_note, 200), 'capacity', v_cap));
    perform private.legal_notify(r.created_by, p_request, 'legal_decision',
      'Your ' || r.request_type || ' request was declined by the prosecutor.');
    return r;
  end if;

  -- approve → judicial queue
  update public.legal_requests
     set review_status = 'submitted_to_judge',
         submitted_to_judge_at = now(),
         approval_route = 'judge'
   where id = p_request returning * into r;
  v_ver := private.legal_freeze_version(p_request, 'prosecutor_approved');
  select * into r from public.legal_requests where id = p_request;
  perform private.legal_sign(p_request, v_ver, 'prosecutor_decision', p_signature);
  perform private.legal_log(p_request, v_ver, 'prosecutor_approved',
    'prosecutor_review', 'submitted_to_judge', p_note, 'capacity: ' || v_cap);
  perform private.legal_audit(p_request, 'LEGAL_PROSECUTOR_APPROVED',
    jsonb_build_object('version', v_ver, 'capacity', v_cap));
  perform private.legal_notify(r.created_by, p_request, 'legal_update',
    'Your ' || r.request_type || ' request was approved for judicial review.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.review_membership_request(p_request uuid, p_decision text, p_final_bureau bureau DEFAULT NULL::bureau, p_final_role app_role DEFAULT NULL::app_role, p_applicant_note text DEFAULT NULL::text, p_internal_note text DEFAULT NULL::text)
 RETURNS membership_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.membership_requests;
  v_uid uuid := (select auth.uid());
  me public.profiles;
  target public.profiles;
  v_status text;
begin
  select * into me from public.profiles where id = v_uid;
  if me.id is null or not me.active or not (me.role in ('bureau_lead', 'deputy_director', 'director') or me.is_owner) then
    raise exception 'not authorized to review membership requests';
  end if;
  select * into r from public.membership_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.status not in ('pending', 'rejected', 'withdrawn') then
    raise exception 'request is not awaiting review';
  end if;
  if r.applicant_id = v_uid then raise exception 'you cannot review your own request'; end if;
  if p_decision not in ('approve', 'approve_with_changes', 'request_correction', 'reject') then
    raise exception 'invalid decision';
  end if;

  if p_decision = 'request_correction' then
    update public.membership_requests
       set status = 'correction_requested',
           applicant_visible_decision_note = p_applicant_note,
           internal_decision_note = coalesce(p_internal_note, internal_decision_note)
     where id = p_request returning * into r;
    perform private.mr_history(p_request, 'correction_requested', r.status, 'correction_requested', p_applicant_note, false);
    if p_internal_note is not null then
      perform private.mr_history(p_request, 'internal_note', null, null, p_internal_note, true);
    end if;
    insert into public.audit_log (actor_id, action, entity, entity_id)
    values (v_uid, 'CORRECTION_REQUESTED', 'membership_requests', p_request);
    insert into public.notifications (user_id, type, payload)
    values (r.applicant_id, 'membership_update', jsonb_build_object(
      'request_id', p_request, 'status', 'correction_requested',
      'reason', 'Your membership request needs a correction.',
      'actor_id', v_uid, 'actor_name', me.display_name));
    return r;
  end if;

  if p_decision = 'reject' then
    update public.membership_requests
       set status = 'rejected', decided_by = v_uid, decided_at = now(),
           applicant_visible_decision_note = p_applicant_note,
           internal_decision_note = coalesce(p_internal_note, internal_decision_note)
     where id = p_request returning * into r;
    perform private.mr_history(p_request, 'rejected', r.status, 'rejected', p_applicant_note, false);
    if p_internal_note is not null then
      perform private.mr_history(p_request, 'internal_note', null, null, p_internal_note, true);
    end if;
    insert into public.audit_log (actor_id, action, entity, entity_id)
    values (v_uid, 'REJECTED', 'membership_requests', p_request);
    insert into public.notifications (user_id, type, payload)
    values (r.applicant_id, 'membership_update', jsonb_build_object(
      'request_id', p_request, 'status', 'rejected',
      'reason', 'Your membership request was rejected.',
      'actor_id', v_uid, 'actor_name', me.display_name));
    return r;  -- profile stays inactive
  end if;

  -- approve / approve_with_changes
  if p_final_bureau is null or p_final_role is null then
    raise exception 'a final department and role are required to approve';
  end if;
  if p_final_bureau not in ('major_crimes', 'street_crimes') then
    raise exception 'members join Major Crimes or Street Crimes — JTF is a temporary joint-case designation and SIB membership is appointed through its own process';
  end if;
  if p_final_role not in ('detective', 'senior_detective', 'bureau_lead', 'deputy_director', 'director') then
    raise exception 'invalid role';
  end if;
  if not private.can_assign_cid_role(p_final_role, p_final_bureau) then
    raise exception 'you are not authorized to assign % in %', p_final_role, private.bureau_label(p_final_bureau::text);
  end if;
  select * into target from public.profiles where id = r.applicant_id for update;
  if target.id is null or target.removed_at is not null then raise exception 'applicant profile unavailable'; end if;
  if target.login_denied then raise exception 'applicant login is denied — restore login before approving'; end if;

  v_status := case when p_decision = 'approve'
                    and p_final_bureau = r.requested_bureau
                    and p_final_role = r.requested_role
              then 'approved' else 'approved_with_changes' end;
  if v_status = 'approved_with_changes' and btrim(coalesce(p_applicant_note, '')) = '' then
    raise exception 'approving with changes requires a reason for the applicant';
  end if;
  update public.membership_requests
     set status = v_status, decided_by = v_uid, decided_at = now(),
         decided_bureau = p_final_bureau, decided_role = p_final_role,
         applicant_visible_decision_note = p_applicant_note,
         internal_decision_note = coalesce(p_internal_note, internal_decision_note)
   where id = p_request returning * into r;

  update public.profiles
     set role = p_final_role, division = p_final_bureau, active = true
   where id = r.applicant_id;
  insert into public.role_events (target_id, actor_id, old_role, new_role,
    old_division, new_division, old_active, new_active, reason, source, source_id)
  values (r.applicant_id, v_uid, target.role, p_final_role,
    target.division, p_final_bureau, target.active, true,
    p_applicant_note, 'membership_approval', p_request);

  perform private.mr_history(p_request, v_status, r.status, v_status, p_applicant_note, false);
  if p_internal_note is not null then
    perform private.mr_history(p_request, 'internal_note', null, null, p_internal_note, true);
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (v_uid, upper(v_status), 'membership_requests', p_request);
  insert into public.notifications (user_id, type, payload)
  values (r.applicant_id, 'member_approved', jsonb_build_object(
    'request_id', p_request, 'status', v_status,
    'reason', case when v_status = 'approved' then 'Your membership request was approved.'
                   else 'Your membership request was approved with changes.' end,
    'actor_id', v_uid, 'actor_name', me.display_name));
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.rls_test_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ids uuid[];
  caller uuid := (select auth.uid());
  case_ids uuid[];
  legal_ids uuid[];
  disp_ids uuid[];
  blocked_disp uuid[];
  leaked jsonb := '[]'::jsonb;
  n int;
  n_cases int; n_reports int; n_evidence int; n_feedback int; n_requests int;
  n_legal int; n_justice int; n_transfers int; n_tokens int; n_ledger int; n_disposables int;
  n_operations int; n_siu int; n_siu_rows int; n_siu_intake int; n_siu_watch int; n_siu_grants int;
begin
  select array_agg(id) into ids from auth.users where email like 'rls-test-%@cidportal.test';
  if caller is null or ids is null or not (caller = any(ids)) then
    raise exception 'rls_test_cleanup: caller is not an RLS test account';
  end if;

  select coalesce(array_agg(id), '{}') into case_ids from public.cases where created_by = any(ids);
  select coalesce(array_agg(id), '{}') into legal_ids
    from public.legal_requests where created_by = any(ids) or case_id = any(case_ids);

  leaked := leaked || private.rls_test_cleanup_surveillance(ids, case_ids);

  delete from public.mdt_wanted_projections where legal_request_id = any(legal_ids);
  delete from public.legal_request_signatures where legal_request_id = any(legal_ids);
  delete from public.legal_request_exhibits where legal_request_id = any(legal_ids);
  delete from public.legal_request_participants where legal_request_id = any(legal_ids);
  delete from public.legal_request_actions where legal_request_id = any(legal_ids);
  update public.legal_requests set current_version_id = null where id = any(legal_ids);
  delete from public.legal_request_versions where legal_request_id = any(legal_ids);
  delete from public.legal_requests where id = any(legal_ids);
  get diagnostics n_legal = row_count;

  delete from public.prosecutor_bureau_assignments
    where prosecutor_id = any(ids) or assigned_by = any(ids);
  delete from public.justice_membership_request_history where request_id in
    (select id from public.justice_membership_requests where applicant_id = any(ids));
  delete from public.justice_membership_requests where applicant_id = any(ids);
  get diagnostics n_justice = row_count;
  delete from public.justice_memberships where user_id = any(ids) and approved_by = any(ids);

  delete from public.siu_compartment_members
    where case_id = any(case_ids) or user_id = any(ids);
  delete from public.siu_case_agents
    where case_id = any(case_ids) or user_id = any(ids);
  delete from public.siu_memberships where user_id = any(ids);
  get diagnostics n_siu = row_count;

  select count(*) into n from public.siu_case_notes x
   where x.created_by = any(ids) and not (x.case_id = any(case_ids));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'siu_case_notes on a non-fixture case (removed)', 'rows', n); end if;
  select count(*) into n from public.siu_disclosures x
   where x.released_by = any(ids) and x.target_case_id is not null and not (x.target_case_id = any(case_ids));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'siu_disclosures targeting a non-fixture case (removed)', 'rows', n); end if;

  select count(*) into n from public.siu_referrals r
   where r.submitted_by = any(ids)
     and ((r.subject_user_id is not null and not (r.subject_user_id = any(ids)))
       or (r.related_case_id is not null and not (r.related_case_id = any(case_ids))));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'siu_referrals naming a real subject or case (removed)', 'rows', n); end if;

  select count(*) into n from public.siu_conflicts k
   where k.agent_id = any(ids) and not (k.case_id = any(case_ids));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'siu_conflicts on a non-fixture case (removed)', 'rows', n); end if;

  select count(*) into n from public.siu_temporary_access t
   where (t.user_id = any(ids) or t.granted_by = any(ids))
     and not (t.case_id = any(case_ids));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'siu_temporary_access on a non-fixture investigation (removed)', 'rows', n); end if;

  select count(*) into n from public.siu_watchlist w
   where w.created_by = any(ids)
     and ((w.entity_id is not null and not (w.entity_id = any(ids)))
       or (w.case_id is not null and not (w.case_id = any(case_ids))));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'siu_watchlist naming a real subject or case (removed)', 'rows', n); end if;

  delete from public.siu_temporary_access
    where user_id = any(ids) or granted_by = any(ids) or revoked_by = any(ids);
  get diagnostics n_siu_grants = row_count;
  delete from public.siu_watchlist
    where created_by = any(ids) or removed_by = any(ids);
  get diagnostics n_siu_watch = row_count;

  delete from public.siu_conflicts where agent_id = any(ids) or acknowledged_by = any(ids);
  delete from public.siu_referrals
    where submitted_by = any(ids) or reviewed_by = any(ids) or subject_user_id = any(ids);
  get diagnostics n_siu_intake = row_count;

  delete from public.siu_exports where exported_by = any(ids);
  get diagnostics n_siu_rows = row_count;
  delete from public.siu_disclosures where released_by = any(ids);
  delete from public.siu_integrity_reviews where created_by = any(ids);
  delete from public.siu_comms_intel where created_by = any(ids);
  delete from public.siu_financial_intel where created_by = any(ids);
  delete from public.siu_undercover_operations
    where created_by = any(ids) or handler_id = any(ids) or agent_id = any(ids);
  delete from public.siu_sources
    where created_by = any(ids) or handler_id = any(ids);
  delete from public.siu_case_notes where created_by = any(ids);
  delete from public.siu_targets where created_by = any(ids);

  delete from public.case_messages where case_id = any(case_ids);
  delete from public.case_tasks where case_id = any(case_ids);
  delete from public.case_signoff_history where case_id = any(case_ids);
  delete from public.case_assignments where case_id = any(case_ids);
  delete from public.case_intel_links where case_id = any(case_ids);
  delete from public.case_files where case_number in (select case_number from public.cases where id = any(case_ids));
  delete from public.custody_chain where evidence_id in (select id from public.evidence where case_id = any(case_ids));
  delete from public.evidence where case_id = any(case_ids);
  get diagnostics n_evidence = row_count;
  delete from public.media where case_id = any(case_ids);
  delete from public.predicate_acts where rico_case_id in (select id from public.rico_cases where case_id = any(case_ids));
  delete from public.rico_cases where case_id = any(case_ids);

  delete from public.reports where case_id = any(case_ids);
  get diagnostics n_reports = row_count;
  select count(*) into n from public.reports r
   where r.author_id = any(ids) and not (r.case_id = any(case_ids));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'reports.author_id on a non-fixture case', 'rows', n); end if;

  delete from public.feedback where created_by = any(ids);
  get diagnostics n_feedback = row_count;
  delete from public.notifications where user_id = any(ids);
  delete from public.transfer_requests where target_id = any(ids) or requested_by = any(ids);
  get diagnostics n_transfers = row_count;

  delete from public.role_events where target_id = any(ids);
  select count(*) into n from public.role_events e
   where e.actor_id = any(ids) and not (e.target_id = any(ids));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'role_events.actor_id against a real member', 'rows', n); end if;

  delete from public.client_errors where reporter_id = any(ids);
  delete from public.membership_request_history where request_id in
    (select id from public.membership_requests where applicant_id = any(ids));
  delete from public.membership_requests where applicant_id = any(ids);
  get diagnostics n_requests = row_count;
  delete from public.announcements where author_id = any(ids);
  delete from public.operation_case_links where case_id = any(case_ids);
  delete from public.cases where id = any(case_ids);
  get diagnostics n_cases = row_count;

  delete from public.operations o
   where o.created_by = any(ids)
     and not exists (select 1 from public.operation_case_links l
                      where l.operation_id = o.id and not (l.case_id = any(case_ids)));
  get diagnostics n_operations = row_count;
  select count(*) into n from public.operations o
   where o.created_by = any(ids)
     and exists (select 1 from public.operation_case_links l
                  where l.operation_id = o.id and not (l.case_id = any(case_ids)));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'operations linked to a non-fixture case', 'rows', n); end if;

  delete from public.deletion_tokens where created_by = any(ids) or target_id = any(ids);
  get diagnostics n_tokens = row_count;
  delete from public.deleted_member_ledger where email like 'rls-test-disposable-%@cidportal.test';
  get diagnostics n_ledger = row_count;

  select coalesce(array_agg(id), '{}') into disp_ids
    from auth.users where email like 'rls-test-disposable-%@cidportal.test';
  select coalesce(array_agg(distinct u), '{}') into blocked_disp from (
    select c.lead_detective_id as u from public.cases c
     where c.lead_detective_id = any(disp_ids) and not (c.id = any(case_ids))
    union
    select g.lead_detective_id from public.gangs g where g.lead_detective_id = any(disp_ids)
  ) s;
  if array_length(blocked_disp, 1) > 0 then
    leaked := leaked || jsonb_build_object(
      'surface', 'disposable fixture leads a real case/gang — profile retained, record untouched',
      'rows', array_length(blocked_disp, 1));
  end if;

  update public.cases set lead_detective_id = null
   where lead_detective_id = any(disp_ids) and id = any(case_ids);
  delete from public.profiles where id = any(disp_ids) and not (id = any(blocked_disp));
  delete from auth.users where id = any(disp_ids) and not (id = any(blocked_disp));
  get diagnostics n_disposables = row_count;

  return jsonb_build_object('cases', n_cases, 'reports', n_reports, 'evidence', n_evidence,
    'feedback', n_feedback, 'membership_requests', n_requests,
    'legal_requests', n_legal, 'justice_requests', n_justice, 'transfer_requests', n_transfers,
    'deletion_tokens', n_tokens, 'ledger_rows', n_ledger, 'disposables', n_disposables,
    'operations', n_operations, 'siu_memberships', n_siu, 'siu_exports', n_siu_rows,
    'siu_referrals', n_siu_intake, 'siu_watchlist', n_siu_watch, 'siu_temporary_access', n_siu_grants,
    'leaked', leaked);
end $function$
;

CREATE OR REPLACE FUNCTION public.rls_test_cleanup_visibility()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ids uuid[]; caller uuid := (select auth.uid()); n_rows int; n_events int;
begin
  select array_agg(id) into ids from auth.users
   where email like 'rls-test-%@cidportal.test';
  if caller is null or ids is null or not (caller = any(ids)) then
    raise exception 'rls_test_cleanup_visibility: caller is not an RLS test account';
  end if;

  delete from public.siu_visibility
   where created_by = any(ids) or revealed_by = any(ids);
  get diagnostics n_rows = row_count;
  delete from public.siu_visibility_events where actor_id = any(ids);
  get diagnostics n_events = row_count;

  return jsonb_build_object('siu_visibility', n_rows, 'siu_visibility_events', n_events);
end
$function$
;

CREATE OR REPLACE FUNCTION public.rls_test_reset_member(p_target uuid, p_role app_role, p_division bureau, p_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid := (select auth.uid());
begin
  if caller is null or not exists (
    select 1 from auth.users where id = caller and email like 'rls-test-%@cidportal.test'
  ) then
    raise exception 'rls_test_reset_member: caller is not an RLS test account';
  end if;
  if not exists (
    select 1 from auth.users where id = p_target and email like 'rls-test-%@cidportal.test'
  ) then
    raise exception 'rls_test_reset_member: target is not an RLS test account';
  end if;
  update public.profiles
     set role = p_role, division = p_division, active = p_active,
         email = (select u.email from auth.users u where u.id = p_target)
   where id = p_target;
end $function$
;

CREATE OR REPLACE FUNCTION public.rls_test_set_signoff(p_case uuid, p_status text, p_stage text DEFAULT NULL::text, p_assignee uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); v_email text; v_owner_email text; v_assignee_email text;
begin
  select email into v_email from public.profiles where id = v_uid;
  if v_email is null or v_email not like 'rls-test-%@cidportal.test' then
    raise exception 'rls_test_set_signoff: caller is not a test fixture';
  end if;
  select p.email into v_owner_email from public.cases c join public.profiles p on p.id = c.created_by where c.id = p_case;
  if v_owner_email is null or v_owner_email not like 'rls-test-%@cidportal.test' then
    raise exception 'rls_test_set_signoff: case is not fixture-owned';
  end if;
  if p_assignee is not null then
    select email into v_assignee_email from public.profiles where id = p_assignee;
    if v_assignee_email is null or v_assignee_email not like 'rls-test-%@cidportal.test' then
      raise exception 'rls_test_set_signoff: assignee must be a test fixture';
    end if;
  end if;
  update public.cases
     set signoff_status = p_status,
         signoff_stage = p_stage,
         signoff_assignee_id = p_assignee,
         signoff_submitted_by = coalesce(signoff_submitted_by, v_uid),
         signoff_submitted_at = coalesce(signoff_submitted_at, now()),
         updated_at = now()
   where id = p_case;
end $function$
;

CREATE OR REPLACE FUNCTION public.rls_test_spawn_disposable(p_suffix text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller uuid := (select auth.uid());
  v_suffix text := lower(regexp_replace(coalesce(p_suffix, ''), '[^a-zA-Z0-9-]', '', 'g'));
  v_id uuid := gen_random_uuid();
  v_email text;
begin
  if caller is null or not exists (
    select 1 from auth.users where id = caller and email like 'rls-test-%@cidportal.test'
  ) then
    raise exception 'rls_test_spawn_disposable: caller is not an RLS test account';
  end if;
  if v_suffix = '' then
    raise exception 'rls_test_spawn_disposable: a non-empty suffix is required';
  end if;
  v_email := 'rls-test-disposable-' || v_suffix || '@cidportal.test';
  if exists (select 1 from auth.users where email = v_email) then
    raise exception 'rls_test_spawn_disposable: % already exists — run rls_test_cleanup() first', v_email;
  end if;
  insert into auth.users (
    instance_id, id, aud, role, email, email_confirmed_at, banned_until,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, recovery_token, email_change,
    email_change_token_new, email_change_token_current, is_sso_user)
  values (
    '00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated',
    v_email, now(), 'infinity'::timestamptz,
    '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('full_name', 'RLS Disposable ' || v_suffix),
    now(), now(), '', '', '', '', '', false);
  insert into public.profiles (id, email, display_name, role, division, active, is_test, is_system)
  values (v_id, v_email, 'RLS Disposable ' || v_suffix, 'detective', 'JTF', false, true, false)
  on conflict (id) do update
    set display_name = excluded.display_name, active = false, is_test = true, is_system = false;
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.search_all(q text)
 RETURNS TABLE(kind text, id uuid, label text, sublabel text, term text, rank real)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
 SET "pg_trgm.word_similarity_threshold" TO '0.3'
AS $function$
  with p as (
    select s.lq,
           '%' || s.tq || '%' as lk,
           0.3::real as thr,
           t.toks,
           t.toks[1] as t1,
           '%' || t.toks[1] || '%' as k1
    from (select lower(trim(q)) as lq, trim(q) as tq) s
    cross join lateral (
      select coalesce(array(
               select tok
               from regexp_split_to_table(s.lq, '\s+') as tok
               where tok <> ''
               order by length(tok) desc, tok
             ), array[]::text[]) as toks
    ) t
  )
  select kind, id, label, sublabel, term, rank from (
    select *, row_number() over (partition by kind order by rank desc, label) as rn from (
      select 'case'::text as kind, c.id,
             c.case_number || ' · ' || coalesce(c.title, '') as label,
             (case when private.case_has_active_hold(c.id) then '🔒 Legal hold · ' else '' end
              || left(coalesce(c.summary, ''), 90)) as sublabel, null::text as term,
             greatest(word_similarity(p.lq, lower(coalesce(c.title, ''))),
                      word_similarity(p.lq, lower(c.case_number)),
                      case when c.case_number ilike p.lk or c.title ilike p.lk or c.summary ilike p.lk then 0.95 else 0 end) as rank
      from public.cases c, p
      where p.lq <> ''
        and (c.case_number ilike p.k1 or c.title ilike p.k1 or c.summary ilike p.k1
             or p.t1 <% c.case_number or p.t1 <% c.title)
        and (select bool_and(coalesce(
               c.case_number ilike ('%' || tk || '%') or c.title ilike ('%' || tk || '%')
               or c.summary ilike ('%' || tk || '%')
               or tk <% c.case_number or tk <% c.title, false))
             from unnest(p.toks) tk)
      union all
      select 'person', pe.id, pe.name || coalesce(' “' || pe.alias || '”', ''), coalesce(pe.status, ''), pe.name,
             greatest(word_similarity(p.lq, lower(pe.name)), word_similarity(p.lq, lower(coalesce(pe.alias, ''))),
                      case when pe.name ilike p.lk or pe.alias ilike p.lk or pe.status ilike p.lk then 0.95 else 0 end)
      from public.persons pe, p
      where pe.lifecycle is distinct from 'merged'
        and p.lq <> ''
        and (pe.name ilike p.k1 or pe.alias ilike p.k1 or pe.status ilike p.k1
             or p.t1 <% pe.name or p.t1 <% pe.alias)
        and (select bool_and(coalesce(
               pe.name ilike ('%' || tk || '%') or pe.alias ilike ('%' || tk || '%')
               or pe.status ilike ('%' || tk || '%')
               or tk <% pe.name or tk <% pe.alias, false))
             from unnest(p.toks) tk)
      union all
      select 'gang', g.id, g.name, coalesce(g.colors, ''), g.name,
             greatest(word_similarity(p.lq, lower(g.name)),
                      case when g.name ilike p.lk or g.colors ilike p.lk or g.notes ilike p.lk then 0.95 else 0 end)
      from public.gangs g, p
      where p.lq <> ''
        and (g.name ilike p.k1 or g.colors ilike p.k1 or g.notes ilike p.k1
             or p.t1 <% g.name)
        and (select bool_and(coalesce(
               g.name ilike ('%' || tk || '%') or g.colors ilike ('%' || tk || '%')
               or g.notes ilike ('%' || tk || '%')
               or tk <% g.name, false))
             from unnest(p.toks) tk)
      union all
      select 'place', pl.id, pl.name, coalesce(pl.area, ''), pl.name,
             greatest(word_similarity(p.lq, lower(pl.name)),
                      case when pl.name ilike p.lk or pl.area ilike p.lk then 0.95 else 0 end)
      from public.places pl, p
      where p.lq <> ''
        and (pl.name ilike p.k1 or pl.area ilike p.k1 or p.t1 <% pl.name)
        and (select bool_and(coalesce(
               pl.name ilike ('%' || tk || '%') or pl.area ilike ('%' || tk || '%')
               or tk <% pl.name, false))
             from unnest(p.toks) tk)
      union all
      select 'vehicle', v.id, v.plate || coalesce(' · ' || v.model, ''), coalesce(v.color, ''), v.plate,
             greatest(word_similarity(p.lq, lower(v.plate)),
                      case when v.plate ilike p.lk or v.model ilike p.lk or v.color ilike p.lk or v.notes ilike p.lk then 0.95 else 0 end)
      from public.vehicles v, p
      where p.lq <> ''
        and (v.plate ilike p.k1 or v.model ilike p.k1 or v.color ilike p.k1 or v.notes ilike p.k1
             or p.t1 <% v.plate)
        and (select bool_and(coalesce(
               v.plate ilike ('%' || tk || '%') or v.model ilike ('%' || tk || '%')
               or v.color ilike ('%' || tk || '%') or v.notes ilike ('%' || tk || '%')
               or tk <% v.plate, false))
             from unnest(p.toks) tk)
      union all
      select 'account', a.id, a.platform || ' · @' || a.handle,
             (coalesce(a.display_name, '')
              || case when fh.handle is null then ''
                      else (case when coalesce(a.display_name, '') = '' then '' else ' · ' end)
                           || 'formerly @' || fh.handle end),
             a.handle,
             greatest(word_similarity(p.lq, lower(a.handle)),
                      word_similarity(p.lq, lower(coalesce(a.display_name, ''))),
                      case when a.handle ilike p.lk or a.display_name ilike p.lk or a.external_id ilike p.lk then 0.95 else 0 end,
                      case when fh.handle is not null then 0.9 else 0 end)
      from public.accounts a
      cross join p
      left join lateral (
        select h.handle
        from public.account_handles h
        where h.account_id = a.id and not h.is_current
          and h.handle_normalized <> a.handle_normalized
          and (h.handle ilike p.lk or word_similarity(p.lq, lower(h.handle)) > p.thr
               or h.handle ilike p.k1 or p.t1 <% h.handle)
        order by h.observed_at desc
        limit 1
      ) fh on true
      where a.lifecycle is distinct from 'merged'
        and p.lq <> ''
        and (a.handle ilike p.k1 or a.display_name ilike p.k1 or a.external_id ilike p.k1
             or p.t1 <% a.handle or fh.handle is not null)
        and (select bool_and(coalesce(
               a.handle ilike ('%' || tk || '%') or a.display_name ilike ('%' || tk || '%')
               or a.external_id ilike ('%' || tk || '%') or tk <% a.handle
               or exists (select 1 from public.account_handles h2
                           where h2.account_id = a.id and not h2.is_current
                             and (h2.handle ilike ('%' || tk || '%') or tk <% h2.handle)), false))
             from unnest(p.toks) tk)
      union all
      select 'narcotic', n.id, n.name, coalesce(n.classification, ''), n.name,
             greatest(word_similarity(p.lq, lower(n.name)),
                      case when n.name ilike p.lk or n.classification ilike p.lk then 0.95 else 0 end,
                      case when exists (select 1 from public.narcotic_aliases a
                                         where a.narcotic_id = n.id
                                           and (a.alias ilike p.lk
                                                or word_similarity(p.lq, lower(a.alias)) > p.thr))
                           then 0.9 else 0 end)
      from public.narcotics n, p
      where p.lq <> '' and n.status <> 'merged'
        and (n.name ilike p.k1 or n.classification ilike p.k1
             or p.t1 <% n.name
             or exists (select 1 from public.narcotic_aliases na
                         where na.narcotic_id = n.id
                           and (na.alias ilike p.k1 or p.t1 <% na.alias)))
        and (select bool_and(coalesce(
               n.name ilike ('%' || tk || '%') or n.classification ilike ('%' || tk || '%')
               or tk <% n.name
               or exists (select 1 from public.narcotic_aliases na2
                           where na2.narcotic_id = n.id
                             and (na2.alias ilike ('%' || tk || '%') or tk <% na2.alias)), false))
             from unnest(p.toks) tk)
      union all
      select 'bench', b.id, b.name, coalesce('Tier ' || b.tier, b.bench_type::text, 'bench'), null::text,
             greatest(word_similarity(p.lq, lower(coalesce(b.name, ''))),
                      case when b.name ilike p.lk then 0.95 else 0 end)
      from public.ballistics_benches b, p
      where p.lq <> ''
        and (b.name ilike p.k1 or p.t1 <% b.name)
        and (select bool_and(coalesce(
               b.name ilike ('%' || tk || '%') or tk <% b.name, false))
             from unnest(p.toks) tk)
      union all
      select 'footprint', f.id, f.signature, coalesce(f.weapon, 'footprint'), null::text,
             greatest(word_similarity(p.lq, lower(coalesce(f.signature, ''))), word_similarity(p.lq, lower(coalesce(f.weapon, ''))),
                      case when f.signature ilike p.lk or f.weapon ilike p.lk then 0.95 else 0 end)
      from public.ballistic_footprints f, p
      where p.lq <> ''
        and (f.signature ilike p.k1 or f.weapon ilike p.k1 or p.t1 <% f.signature)
        and (select bool_and(coalesce(
               f.signature ilike ('%' || tk || '%') or f.weapon ilike ('%' || tk || '%')
               or tk <% f.signature, false))
             from unnest(p.toks) tk)
      union all
      select 'document', d.id, d.name, coalesce(d.folder, ''), null::text,
             greatest(word_similarity(p.lq, lower(coalesce(d.name, ''))),
                      case when d.name ilike p.lk then 0.95 else 0 end)
      from public.documents d, p
      where p.lq <> ''
        and (d.name ilike p.k1 or p.t1 <% d.name)
        and (select bool_and(coalesce(
               d.name ilike ('%' || tk || '%') or tk <% d.name, false))
             from unnest(p.toks) tk)
      union all
      select 'legal', lr.id,
             lr.request_number || ' · ' || lr.title,
             initcap(lr.request_type) || ' · ' || replace(lr.review_status, '_', ' '),
             null::text,
             greatest(word_similarity(p.lq, lower(lr.title)),
                      word_similarity(p.lq, lower(lr.request_number)),
                      case when lr.request_number ilike p.lk or lr.title ilike p.lk
                                or lr.person_name_snapshot ilike p.lk or lr.recipient_name ilike p.lk
                                or lr.case_number_snapshot ilike p.lk then 0.95 else 0 end)
      from public.legal_requests lr, p
      where p.lq <> ''
        and (lr.request_number ilike p.k1 or lr.title ilike p.k1
             or lr.person_name_snapshot ilike p.k1 or lr.recipient_name ilike p.k1
             or lr.case_number_snapshot ilike p.k1
             or p.t1 <% lr.request_number or p.t1 <% lr.title)
        and (select bool_and(coalesce(
               lr.request_number ilike ('%' || tk || '%') or lr.title ilike ('%' || tk || '%')
               or lr.person_name_snapshot ilike ('%' || tk || '%')
               or lr.recipient_name ilike ('%' || tk || '%')
               or lr.case_number_snapshot ilike ('%' || tk || '%')
               or tk <% lr.request_number or tk <% lr.title, false))
             from unnest(p.toks) tk)
      union all
      select 'report', r.case_id,
             coalesce(nullif(r.template, ''), 'Report') || ' · ' || c.case_number,
             'Report in ' || coalesce(nullif(c.title, ''), c.case_number),
             null::text,
             greatest(word_similarity(p.lq, lower(coalesce(r.template, ''))),
                      case when r.template ilike p.lk
                                or exists (select 1 from jsonb_each_text(r.fields) kv where kv.value ilike p.lk) then 0.9 else 0 end)
      from public.reports r join public.cases c on c.id = r.case_id, p
      where p.lq <> ''
        and (r.template ilike p.k1
             or (length(p.lq) >= 4
                 and exists (select 1 from jsonb_each_text(r.fields) kv where kv.value ilike p.k1)))
        and (select bool_and(coalesce(
               r.template ilike ('%' || tk || '%')
               or (length(p.lq) >= 4
                   and exists (select 1 from jsonb_each_text(r.fields) kv2 where kv2.value ilike ('%' || tk || '%'))), false))
             from unnest(p.toks) tk)
      union all
      select 'evidence', e.case_id,
             coalesce(nullif(e.item_code, ''), 'Evidence') || coalesce(' · ' || e.type, ''),
             left(coalesce(e.description, ''), 90),
             e.item_code,
             greatest(word_similarity(p.lq, lower(coalesce(e.item_code, ''))),
                      word_similarity(p.lq, lower(coalesce(e.description, ''))),
                      case when e.item_code ilike p.lk or e.description ilike p.lk or e.type ilike p.lk
                                or e.location ilike p.lk or e.notes ilike p.lk then 0.92 else 0 end)
      from public.evidence e join public.cases c on c.id = e.case_id, p
      where p.lq <> ''
        and (e.item_code ilike p.k1 or e.description ilike p.k1 or e.type ilike p.k1
             or e.location ilike p.k1 or e.notes ilike p.k1
             or p.t1 <% e.item_code or p.t1 <% e.description)
        and (select bool_and(coalesce(
               e.item_code ilike ('%' || tk || '%') or e.description ilike ('%' || tk || '%')
               or e.type ilike ('%' || tk || '%') or e.location ilike ('%' || tk || '%')
               or e.notes ilike ('%' || tk || '%')
               or tk <% e.item_code or tk <% e.description, false))
             from unnest(p.toks) tk)
      union all
      select 'operation', o.id, o.name, coalesce(initcap(o.status), 'Operation'), o.name,
             greatest(word_similarity(p.lq, lower(coalesce(o.name, ''))),
                      case when o.name ilike p.lk or o.description ilike p.lk then 0.95 else 0 end)
      from public.operations o, p
      where p.lq <> ''
        and (o.name ilike p.k1 or o.description ilike p.k1 or p.t1 <% o.name)
        and (select bool_and(coalesce(
               o.name ilike ('%' || tk || '%') or o.description ilike ('%' || tk || '%')
               or tk <% o.name, false))
             from unnest(p.toks) tk)
      union all
      select 'bolo', bp.id, bp.name || coalesce(' “' || bp.alias || '”', ''),
             'BOLO · ' || coalesce(bp.bolo_risk, '')
               || case when bp.bolo_expires_at < current_date then ' · expired' else '' end,
             bp.name,
             greatest(word_similarity(p.lq, lower(bp.name)),
                      word_similarity(p.lq, lower(coalesce(bp.alias, ''))),
                      case when bp.name ilike p.lk or bp.alias ilike p.lk
                                or bp.bolo_reason ilike p.lk or bp.bolo_instructions ilike p.lk then 0.95 else 0 end)
      from public.persons bp, p
      where bp.bolo = true
        and bp.lifecycle is distinct from 'merged'
        and p.lq <> ''
        and (bp.name ilike p.k1 or bp.alias ilike p.k1
             or bp.bolo_reason ilike p.k1 or bp.bolo_instructions ilike p.k1
             or p.t1 <% bp.name or p.t1 <% bp.alias)
        and (select bool_and(coalesce(
               bp.name ilike ('%' || tk || '%') or bp.alias ilike ('%' || tk || '%')
               or bp.bolo_reason ilike ('%' || tk || '%')
               or bp.bolo_instructions ilike ('%' || tk || '%')
               or tk <% bp.name or tk <% bp.alias, false))
             from unnest(p.toks) tk)
      union all
      select 'task', t.case_id, t.title,
             c.case_number || ' · '
               || (case when t.done then 'Done' else coalesce('due ' || t.due::text, 'Open') end),
             t.id::text,
             greatest(word_similarity(p.lq, lower(t.title)),
                      case when t.title ilike p.lk then 0.95 else 0 end)
      from public.case_tasks t join public.cases c on c.id = t.case_id, p
      where p.lq <> ''
        and (t.done = false or t.updated_at > now() - interval '30 days')
        and (t.title ilike p.k1 or p.t1 <% t.title)
        and (select bool_and(coalesce(
               t.title ilike ('%' || tk || '%') or tk <% t.title, false))
             from unnest(p.toks) tk)
    ) u
  ) x
  where rn <= 8
  order by rank desc, label
  limit 60;
$function$
;

CREATE OR REPLACE FUNCTION public.search_document_sections(p_query text, p_limit integer DEFAULT 20)
 RETURNS TABLE(document_id uuid, document_name text, category text, document_type text, status text, classification text, version_number integer, effective_at timestamp with time zone, anchor text, heading text, ordinal integer, rank real, headline text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with q as (select websearch_to_tsquery('english', p_query) as tsq)
  select d.id, d.name, d.category, d.document_type, d.status, d.classification,
         s.version_number, d.effective_at, s.anchor, s.heading, s.ordinal,
         greatest(
           ts_rank_cd(s.search_tsv, q.tsq),
           case when s.heading ilike '%' || p_query || '%' then 0.9 else 0 end
         )::real as rank,
         ts_headline('english', s.body, q.tsq,
           'MaxFragments=1, MaxWords=28, MinWords=10, StartSel=[[, StopSel=]]')
    from public.document_sections s
    join public.documents d on d.id = s.document_id, q
   where btrim(coalesce(p_query, '')) <> ''
     and (s.search_tsv @@ q.tsq or s.heading ilike '%' || p_query || '%')
   order by rank desc, d.updated_at desc, s.ordinal
   limit least(greatest(coalesce(p_limit, 20), 1), 50)
$function$
;

CREATE OR REPLACE FUNCTION public.search_documents(p_query text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, name text, category text, document_type text, status text, classification text, mandatory boolean, updated_at timestamp with time zone, rank real, headline text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with q as (
    select websearch_to_tsquery('english', p_query) as tsq,
           lower(p_query) as lq
  )
  select d.id, d.name, d.category, d.document_type, d.status,
         d.classification, d.mandatory, d.updated_at,
         greatest(
           ts_rank_cd(d.search_tsv, q.tsq),
           case when d.name ilike '%' || p_query || '%' then 0.9 else 0 end
         )::real as rank,
         ts_headline('english', coalesce(d.content ->> 'body', ''), q.tsq,
           'MaxFragments=1, MaxWords=24, MinWords=8, StartSel=[[, StopSel=]]') as headline
    from public.documents d, q
   where btrim(coalesce(p_query, '')) <> ''
     and (d.search_tsv @@ q.tsq or d.name ilike '%' || p_query || '%')
   order by rank desc, d.updated_at desc
   limit least(greatest(coalesce(p_limit, 20), 1), 50)
   offset greatest(coalesce(p_offset, 0), 0)
$function$
;

CREATE OR REPLACE FUNCTION public.search_narcotics(p_query text, p_limit integer DEFAULT 30)
 RETURNS TABLE(id uuid, name text, category text, status text, confidence text, restricted boolean, rank real)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with p as (select btrim(coalesce(p_query, '')) as q,
                    '%' || btrim(coalesce(p_query, '')) || '%' as lk,
                    websearch_to_tsquery('english', btrim(coalesce(p_query, ''))) as tsq)
  select n.id, n.name, n.category, n.status, n.confidence, n.restricted,
         greatest(
           case when n.search_tsv @@ p.tsq then ts_rank(n.search_tsv, p.tsq) else 0 end,
           case when n.name ilike p.lk then 0.95 else 0 end,
           case when exists (select 1 from public.narcotic_aliases a
                              where a.narcotic_id = n.id and a.alias ilike p.lk)
                then 0.9 else 0 end)::real as rank
  from public.narcotics n, p
  where length(p.q) >= 2
    and n.status <> 'merged'
    and (n.search_tsv @@ p.tsq
         or n.name ilike p.lk
         or exists (select 1 from public.narcotic_aliases a
                     where a.narcotic_id = n.id and a.alias ilike p.lk))
  order by rank desc, n.name
  limit greatest(coalesce(p_limit, 30), 0);
$function$
;

CREATE OR REPLACE FUNCTION public.search_persons(p_q text, p_limit integer DEFAULT 30, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, rank real)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  with p as (select lower(trim(p_q)) as lq, '%' || trim(p_q) || '%' as lk, 0.3::real as thr)
  select u.id, max(u.rank)::real as rank from (
    -- persons' own columns: name/alias/phone/status/notes at full rank,
    -- the identity jsonb text at a lower rank.
    select pe.id,
           greatest(word_similarity(p.lq, lower(pe.name)),
                    word_similarity(p.lq, lower(coalesce(pe.alias, ''))),
                    word_similarity(p.lq, lower(coalesce(pe.phone, ''))),
                    case when pe.name ilike p.lk or pe.alias ilike p.lk or pe.phone ilike p.lk
                              or pe.status ilike p.lk or pe.notes ilike p.lk then 0.95 else 0 end,
                    case when pe.identity::text ilike p.lk then 0.55 else 0 end)::real as rank
    from public.persons pe, p
    where pe.lifecycle is distinct from 'merged'
      and length(p.lq) >= 2 and (pe.name ilike p.lk or pe.alias ilike p.lk or pe.phone ilike p.lk
          or pe.status ilike p.lk or pe.notes ilike p.lk or pe.identity::text ilike p.lk
          or word_similarity(p.lq, lower(pe.name || ' ' || coalesce(pe.alias, '') || ' ' || coalesce(pe.phone, ''))) > p.thr)
    union all
    -- gang name via the scalar gang_id join.
    select pe.id,
           (greatest(word_similarity(p.lq, lower(g.name)),
                     case when g.name ilike p.lk then 0.9 else 0 end) * 0.85)::real
    from public.persons pe
    join public.gangs g on g.id = pe.gang_id, p
    where length(p.lq) >= 2 and (g.name ilike p.lk or word_similarity(p.lq, lower(g.name)) > p.thr)
    union all
    -- vehicle plate via registered ownership (vehicles.owner_id).
    select v.owner_id,
           (greatest(word_similarity(p.lq, lower(v.plate)),
                     case when v.plate ilike p.lk then 0.9 else 0 end) * 0.85)::real
    from public.vehicles v, p
    where length(p.lq) >= 2 and v.owner_id is not null
      and (v.plate ilike p.lk or word_similarity(p.lq, lower(v.plate)) > p.thr)
    union all
    -- vehicle plate via person_vehicles (non-owner relations).
    select pv.person_id,
           (greatest(word_similarity(p.lq, lower(v.plate)),
                     case when v.plate ilike p.lk then 0.9 else 0 end) * 0.85)::real
    from public.person_vehicles pv
    join public.vehicles v on v.id = pv.vehicle_id, p
    where length(p.lq) >= 2 and (v.plate ilike p.lk or word_similarity(p.lq, lower(v.plate)) > p.thr)
    union all
    -- place name/area via person_places.
    select pp.person_id,
           (greatest(word_similarity(p.lq, lower(pl.name)),
                     case when pl.name ilike p.lk or pl.area ilike p.lk then 0.9 else 0 end) * 0.85)::real
    from public.person_places pp
    join public.places pl on pl.id = pp.place_id, p
    where length(p.lq) >= 2 and (pl.name ilike p.lk or pl.area ilike p.lk
          or word_similarity(p.lq, lower(pl.name)) > p.thr)
    union all
    -- case number via case_intel_links → cases. SECURITY INVOKER: both tables
    -- pass through the caller's case wall, so restricted cases fail closed.
    select l.ref_id,
           (greatest(word_similarity(p.lq, lower(c.case_number)),
                     case when c.case_number ilike p.lk then 0.9 else 0 end) * 0.85)::real
    from public.case_intel_links l
    join public.cases c on c.id = l.case_id, p
    where length(p.lq) >= 2 and l.kind = 'person'
      and (c.case_number ilike p.lk or word_similarity(p.lq, lower(c.case_number)) > p.thr)
  ) u
  group by u.id
  order by max(u.rank) desc, u.id
  limit greatest(coalesce(p_limit, 30), 0) offset greatest(coalesce(p_offset, 0), 0);
$function$
;

CREATE OR REPLACE FUNCTION public.security_test_report(p_suite text, p_passed integer, p_failed integer, p_skipped integer, p_failures jsonb DEFAULT '[]'::jsonb, p_commit text DEFAULT NULL::text, p_branch text DEFAULT NULL::text, p_release text DEFAULT NULL::text, p_source text DEFAULT 'local'::text, p_duration_ms integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_is_test boolean;
  v_failures jsonb := '[]'::jsonb;
  f jsonb;
  v_id uuid;
begin
  select email like 'rls-test-%@cidportal.test' into v_is_test
    from auth.users where id = v_uid;
  if not coalesce(v_is_test, false) then
    raise exception 'security_test_report: caller is not an RLS test account';
  end if;
  if p_suite is null or btrim(p_suite) = '' then raise exception 'a suite name is required'; end if;
  if p_source not in ('ci', 'local') then raise exception 'invalid source'; end if;
  -- Rebuild failures keeping ONLY short name/expected/actual strings (≤30
  -- entries, ≤300 chars each) so sensitive row content can never land here.
  if jsonb_typeof(p_failures) = 'array' then
    for f in select * from jsonb_array_elements(p_failures) limit 30 loop
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'name', left(coalesce(f->>'name', 'unnamed test'), 300),
        'expected', left(coalesce(f->>'expected', ''), 300),
        'actual', left(coalesce(f->>'actual', ''), 300)));
    end loop;
  end if;
  insert into public.security_test_runs
    (suite, passed, failed, skipped, total, failures, commit_sha, branch, release, source, duration_ms, created_by)
  values (btrim(p_suite), greatest(coalesce(p_passed, 0), 0), greatest(coalesce(p_failed, 0), 0),
          greatest(coalesce(p_skipped, 0), 0),
          greatest(coalesce(p_passed, 0), 0) + greatest(coalesce(p_failed, 0), 0) + greatest(coalesce(p_skipped, 0), 0),
          v_failures, left(coalesce(p_commit, ''), 64), left(coalesce(p_branch, ''), 120),
          left(coalesce(p_release, ''), 40), p_source, p_duration_ms, v_uid)
  returning id into v_id;
  -- Retention: keep the newest 50 runs per suite.
  delete from public.security_test_runs s
   where s.suite = btrim(p_suite)
     and s.id not in (select id from public.security_test_runs
                      where suite = btrim(p_suite) order by created_at desc limit 50);
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'SECURITY_TEST_REPORTED', 'security_test_runs', v_id,
          jsonb_build_object('suite', btrim(p_suite), 'passed', p_passed, 'failed', p_failed, 'source', p_source));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.set_acting_ada(p_prosecutor uuid, p_bureau bureau, p_note text DEFAULT NULL::text)
 RETURNS prosecutor_bureau_assignments
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.assign_ada_to_bureau(p_prosecutor, p_bureau, 'acting', p_note, true)
$function$
;

CREATE OR REPLACE FUNCTION public.set_case_closed_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status = 'closed' and (old.status is distinct from 'closed') then
    new.closed_at := now();
  elsif new.status <> 'closed' then
    new.closed_at := null;   -- reopened: clear resolution timestamp
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.set_justice_membership_active(p_target uuid, p_active boolean)
 RETURNS justice_memberships
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); m public.justice_memberships; rec record;
begin
  select * into m from public.justice_memberships where user_id = p_target;
  if not found then raise exception 'no justice membership for that user'; end if;
  if p_target = v_uid then raise exception 'you cannot change your own membership'; end if;
  if not private.can_review_justice_role(v_uid, m.justice_role) then
    raise exception 'not authorized to manage this justice role';
  end if;
  update public.justice_memberships
     set active = p_active,
         ended_at = case when p_active then null else now() end,
         approved_by = case when p_active then v_uid else approved_by end,
         approved_at = case when p_active then now() else approved_at end
   where user_id = p_target returning * into m;
  if not p_active then
    -- Unstick: shared queue gets the prosecutorial work back…
    for rec in select id from public.legal_requests
                where assigned_prosecutor_id = p_target and review_status = 'prosecutor_review'
    loop
      perform private.legal_end_participant(rec.id, p_target, 'prosecutor');
      update public.legal_requests
         set review_status = 'prosecutor_queue',
             assigned_prosecutor_id = null, prosecutor_claimed_at = null,
             queue_entered_at = now()
       where id = rec.id;
      perform private.legal_log(rec.id, null, 'prosecutor_unassigned',
        'prosecutor_review', 'prosecutor_queue', 'Prosecutor membership deactivated.', null);
    end loop;
    -- …and the judicial queue gets the judicial work back.
    for rec in select id from public.legal_requests
                where assigned_judge_id = p_target and review_status = 'judicial_review'
    loop
      perform private.legal_end_participant(rec.id, p_target, 'judicial_reviewer');
      update public.legal_requests
         set review_status = 'submitted_to_judge', assigned_judge_id = null
       where id = rec.id;
      perform private.legal_log(rec.id, null, 'judge_unassigned',
        'judicial_review', 'submitted_to_judge', 'Judge membership deactivated.', null);
    end loop;
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, case when p_active then 'JUSTICE_REACTIVATED' else 'JUSTICE_DEACTIVATED' end,
          'justice_memberships', p_target, jsonb_build_object('role', m.justice_role));
  insert into public.notifications (user_id, type, payload)
  values (p_target, 'justice_membership_update', jsonb_build_object(
    'reason', 'Your justice membership was ' || case when p_active then 'reactivated.' else 'deactivated.' end));
  return m;
end $function$
;

CREATE OR REPLACE FUNCTION public.set_legal_approval_route(p_request uuid, p_route text, p_reason text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if not private.can_manage_legal_assignment(p_request, v_uid) then
    raise exception 'only a District Attorney, Attorney General, or the Owner may change the approval route';
  end if;
  if r.request_type = 'warrant' then raise exception 'warrants always require Judge approval'; end if;
  if p_route not in ('da', 'ag', 'judge') then raise exception 'invalid route'; end if;
  if r.review_status in ('approved', 'denied', 'withdrawn', 'judicial_review', 'submitted_to_judge') then
    raise exception 'the route can no longer change';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  update public.legal_requests set approval_route = p_route where id = p_request returning * into r;
  perform private.legal_log(p_request, r.current_version_id, 'route_changed', null, p_route, p_reason, null);
  perform private.legal_audit(p_request, 'LEGAL_ROUTE_CHANGED',
    jsonb_build_object('route', p_route, 'reason', left(p_reason, 200)));
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.set_primary_ada(p_prosecutor uuid, p_bureau bureau, p_note text DEFAULT NULL::text)
 RETURNS prosecutor_bureau_assignments
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.assign_ada_to_bureau(p_prosecutor, p_bureau, 'primary', p_note, true)
$function$
;

CREATE OR REPLACE FUNCTION public.set_profile_test_flag(p_target uuid, p_is_test boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_owner() then raise exception 'restricted to the owner'; end if;
  update public.profiles set is_test = p_is_test where id = p_target;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'TEST_FLAG_SET', 'profiles', p_target,
    jsonb_build_object('is_test', p_is_test));
end $function$
;

CREATE OR REPLACE FUNCTION public.signoff_command_override(p_case uuid, p_action text, p_reason text)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.cases; v_uid uuid := (select auth.uid()); me public.profiles;
        r_stage text; r_assignee uuid; v_from text;
begin
  select * into me from public.profiles where id = v_uid;
  if not (me.id is not null and coalesce(me.active, false)
          and (coalesce(me.role in ('deputy_director','director'), false) or coalesce(me.is_owner, false))) then
    raise exception 'command override is limited to Deputy Director, Director, or Owner';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'a reason is required for a command override';
  end if;
  select * into c from public.cases where id = p_case for update;
  if not found then raise exception 'case not found'; end if;
  if c.signoff_status <> 'approved_deputy' then
    raise exception 'this case is not at the deputy stop-point (it may have just changed) — reload and retry' using errcode = 'P0001';
  end if;
  v_from := c.signoff_status;
  if p_action = 'complete' then
    update public.cases set signoff_status='approved_complete', updated_at=now() where id=p_case returning * into c;
    insert into public.case_signoff_history(case_id, actor_id, actor_name, action, stage, from_status, to_status, note, source)
      values (p_case, v_uid, me.display_name, 'completed', 'deputy', v_from, 'approved_complete', p_reason, 'command_override');
    perform private.signoff_notify(coalesce(c.signoff_submitted_by, c.lead_detective_id), v_uid, 'signoff_approved', c,
      'Completed at deputy level via command override: ' || p_reason);
  elsif p_action = 'escalate' then
    select stage, assignee into r_stage, r_assignee
      from private.signoff_route(2, c.bureau, array_remove(array[c.signoff_submitted_by, c.lead_detective_id], null));
    if r_stage is null then raise exception 'no active Director available to escalate to'; end if;
    update public.cases set signoff_status='awaiting_director', signoff_stage='director',
      signoff_assignee_id=r_assignee, updated_at=now() where id=p_case returning * into c;
    insert into public.case_signoff_history(case_id, actor_id, actor_name, action, stage, from_status, to_status, note, source)
      values (p_case, v_uid, me.display_name, 'escalated', 'director', v_from, 'awaiting_director', p_reason, 'command_override');
    perform private.signoff_notify(r_assignee, v_uid, 'signoff_waiting', c,
      'Escalated to the Director via command override — awaiting your decision.');
  else
    raise exception 'unknown action %', p_action;
  end if;
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.signoff_decide(p_case uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.cases; v_uid uuid := (select auth.uid()); v_role public.app_role;
        need_role public.app_role; r_stage text; r_assignee uuid; v_from text; v_name text;
        v_owner uuid;
begin
  select * into c from public.cases where id = p_case for update;
  if not found then raise exception 'case not found'; end if;
  if c.signoff_stage is null then
    raise exception 'this case is not awaiting a decision (it may have just been decided) — reload and retry' using errcode = 'P0001';
  end if;
  select role into v_role from public.profiles where id = v_uid;
  need_role := case c.signoff_stage when 'bureau_lead' then 'bureau_lead'
                                    when 'deputy' then 'deputy_director'
                                    when 'director' then 'director' end::public.app_role;
  if not (private.is_active() and (v_role = need_role or v_role = 'director')) then
    raise exception 'you do not hold the % role required to decide this stage', c.signoff_stage;
  end if;
  perform private.signoff_assert_decider(c, v_uid, v_role);
  v_from := c.signoff_status;
  v_owner := coalesce(c.signoff_submitted_by, c.lead_detective_id);
  select display_name into v_name from public.profiles where id = v_uid;
  if p_decision = 'approve' then
    if c.signoff_stage = 'bureau_lead' then
      select stage, assignee into r_stage, r_assignee
        from private.signoff_route(1, c.bureau, array_remove(array[v_owner, c.lead_detective_id], null));
      if r_stage is null then
        update public.cases set signoff_status='approved_complete', signoff_stage=null,
          signoff_assignee_id=null, updated_at=now() where id=p_case returning * into c;
      else
        update public.cases set signoff_status=private.signoff_status_of(r_stage), signoff_stage=r_stage,
          signoff_assignee_id=r_assignee, updated_at=now() where id=p_case returning * into c;
        perform private.signoff_notify(r_assignee, v_uid, 'signoff_waiting', c,
          'Approved at bureau level — now awaiting your decision.');
      end if;
    elsif c.signoff_stage = 'deputy' then
      update public.cases set signoff_status='approved_deputy', signoff_stage=null,
        signoff_assignee_id=null, updated_at=now() where id=p_case returning * into c;
      perform private.signoff_notify(v_owner, v_uid, 'signoff_approved', c,
        'Approved by the Deputy Director — complete at deputy or escalate to the Director.');
    elsif c.signoff_stage = 'director' then
      update public.cases set signoff_status='ready_doj', signoff_stage=null,
        signoff_assignee_id=null, updated_at=now() where id=p_case returning * into c;
      perform private.signoff_notify(v_owner, v_uid, 'signoff_approved', c,
        'Approved by the Director — the case is ready for DOJ.');
    end if;
    insert into public.case_signoff_history(case_id, actor_id, actor_name, action, stage, from_status, to_status, note, source)
      values (p_case, v_uid, v_name, 'approved', need_role::text, v_from, c.signoff_status, p_note, 'reviewer');
  elsif p_decision = 'deny' then
    if coalesce(btrim(p_note),'') = '' then raise exception 'a note is required to deny'; end if;
    update public.cases set signoff_status='denied', signoff_stage=null, signoff_assignee_id=null, updated_at=now()
      where id=p_case returning * into c;
    insert into public.case_signoff_history(case_id, actor_id, actor_name, action, stage, from_status, to_status, note, source)
      values (p_case, v_uid, v_name, 'denied', need_role::text, v_from, 'denied', p_note, 'reviewer');
    perform private.signoff_notify(v_owner, v_uid, 'signoff_denied', c, p_note);
  elsif p_decision = 'changes' then
    if coalesce(btrim(p_note),'') = '' then raise exception 'a note is required to request changes'; end if;
    update public.cases set signoff_status='changes_requested', signoff_stage=null, signoff_assignee_id=null, updated_at=now()
      where id=p_case returning * into c;
    insert into public.case_signoff_history(case_id, actor_id, actor_name, action, stage, from_status, to_status, note, source)
      values (p_case, v_uid, v_name, 'changes_requested', need_role::text, v_from, 'changes_requested', p_note, 'reviewer');
    perform private.signoff_notify(v_owner, v_uid, 'signoff_changes', c, p_note);
  else
    raise exception 'unknown decision %', p_decision;
  end if;
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.signoff_owner_action(p_case uuid, p_action text)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.cases; v_uid uuid := (select auth.uid());
        r_stage text; r_assignee uuid; v_from text; v_name text;
begin
  select * into c from public.cases where id = p_case for update;
  if not found then raise exception 'case not found'; end if;
  if c.signoff_status <> 'approved_deputy' then
    raise exception 'this case is not at the deputy stop-point (it may have just changed) — reload and retry' using errcode = 'P0001';
  end if;
  if not (private.is_active() and private.can_access_case(p_case)
          and (v_uid is not distinct from c.lead_detective_id
               or v_uid is not distinct from c.signoff_submitted_by)) then
    raise exception 'only the case owner (lead detective or original submitter) can decide here';
  end if;
  v_from := c.signoff_status;
  select display_name into v_name from public.profiles where id = v_uid;
  if p_action = 'complete' then
    update public.cases set signoff_status='approved_complete', updated_at=now() where id=p_case returning * into c;
    insert into public.case_signoff_history(case_id, actor_id, actor_name, action, stage, from_status, to_status, source)
      values (p_case, v_uid, v_name, 'completed', 'deputy', v_from, 'approved_complete', 'owner');
  elsif p_action = 'escalate' then
    select stage, assignee into r_stage, r_assignee
      from private.signoff_route(2, c.bureau, array_remove(array[c.signoff_submitted_by, c.lead_detective_id], null));
    if r_stage is null then raise exception 'no active Director available to escalate to'; end if;
    update public.cases set signoff_status='awaiting_director', signoff_stage='director',
      signoff_assignee_id=r_assignee, updated_at=now() where id=p_case returning * into c;
    insert into public.case_signoff_history(case_id, actor_id, actor_name, action, stage, from_status, to_status, source)
      values (p_case, v_uid, v_name, 'escalated', 'director', v_from, 'awaiting_director', 'owner');
    perform private.signoff_notify(r_assignee, v_uid, 'signoff_waiting', c,
      'Escalated to the Director — awaiting your decision.');
  else
    raise exception 'unknown action %', p_action;
  end if;
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.signoff_submit(p_case uuid)
 RETURNS cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.cases; v_uid uuid := (select auth.uid());
        r_stage text; r_assignee uuid; v_from text; v_name text;
begin
  select * into c from public.cases where id = p_case for update;
  if not found then raise exception 'case not found'; end if;
  if not private.is_active() then raise exception 'inactive user'; end if;
  if not (v_uid is not distinct from c.lead_detective_id
          or (c.lead_detective_id is null and v_uid is not distinct from c.created_by))
     then raise exception 'only the case owner (lead detective) can submit this case for sign-off'; end if;
  if coalesce(c.signoff_status,'none') not in ('none','changes_requested','denied')
     then raise exception 'this case is already in review — reload and retry' using errcode = 'P0001'; end if;
  select stage, assignee into r_stage, r_assignee
    from private.signoff_route(0, c.bureau, array_remove(array[v_uid, c.lead_detective_id], null));
  if r_stage is null then raise exception 'no active reviewers in the chain'; end if;
  v_from := coalesce(c.signoff_status,'none');
  select display_name into v_name from public.profiles where id = v_uid;
  update public.cases set signoff_status = private.signoff_status_of(r_stage),
    signoff_stage = r_stage, signoff_assignee_id = r_assignee,
    signoff_submitted_by = v_uid, signoff_submitted_at = now(), updated_at = now()
    where id = p_case returning * into c;
  insert into public.case_signoff_history(case_id, actor_id, actor_name, action, stage, from_status, to_status, source)
    values (p_case, v_uid, v_name, 'submitted', r_stage, v_from, c.signoff_status, 'submit');
  perform private.signoff_notify(r_assignee, v_uid, 'signoff_waiting', c,
    'Submitted for sign-off by ' || coalesce(v_name, 'the case owner') || '.');
  return c;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_acknowledge_disclosure(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_row record;
begin
  select d.id, d.siu_case_id, d.audience, d.target_case_id, d.target_user_id,
         d.revoked_at, d.acknowledged_at, d.item_type
    into v_row from public.siu_disclosures d where d.id = p_id for update;
  if not found or v_row.revoked_at is not null then raise exception 'release not found'; end if;
  if not (case v_row.audience
            when 'cid'          then private.is_active()
            when 'case_members' then private.can_access_case(v_row.target_case_id)
            when 'investigator' then v_row.target_user_id = v_actor
            else false
          end) then
    raise exception 'release not found';
  end if;
  if v_row.acknowledged_at is not null then return; end if;

  update public.siu_disclosures
     set acknowledged_at = now(), acknowledged_by = v_actor
   where id = p_id;

  perform private.siu_audit('SIU_INTEL_ACKNOWLEDGED', v_row.siu_case_id, jsonb_build_object(
    'disclosure_id', p_id, 'item_type', v_row.item_type,
    'audience', v_row.audience, 'acknowledged_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_appoint(p_user uuid, p_role text, p_callsign text DEFAULT NULL::text, p_oversight_only boolean DEFAULT false, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_standing text := private.siu_standing();
  v_target public.profiles%rowtype;
  v_id uuid;
  v_call text := nullif(btrim(coalesce(p_callsign, '')), '');
begin
  if not private.siu_can_appoint() then raise exception 'not authorized'; end if;
  if p_role not in ('special_agent', 'senior_special_agent', 'special_agent_in_charge') then
    raise exception 'unknown SIB role';
  end if;
  if p_role = 'special_agent_in_charge' and v_standing <> 'owner' then
    raise exception 'only the Portal Owner may appoint a Special Agent in Charge';
  end if;
  if p_user = v_actor and v_standing <> 'owner' then
    raise exception 'you cannot appoint yourself';
  end if;

  select * into v_target from public.profiles where id = p_user;
  if not found then raise exception 'member not found'; end if;
  if v_target.is_system then raise exception 'system accounts cannot be appointed'; end if;
  if v_target.removed_at is not null then raise exception 'removed members cannot be appointed'; end if;
  if not v_target.active then raise exception 'only an approved, active portal member can be appointed'; end if;

  insert into public.siu_memberships as m
    (user_id, siu_role, oversight_only, callsign, active, appointed_by, appointed_at, internal_note)
  values (p_user, p_role, coalesce(p_oversight_only, false), v_call, true, v_actor, now(), nullif(btrim(coalesce(p_note, '')), ''))
  on conflict (user_id) do update
    set siu_role = excluded.siu_role,
        oversight_only = excluded.oversight_only,
        callsign = coalesce(excluded.callsign, m.callsign),
        active = true,
        appointed_by = excluded.appointed_by,
        appointed_at = now(),
        ended_by = null, ended_at = null, end_reason = null,
        internal_note = coalesce(excluded.internal_note, m.internal_note),
        updated_at = now()
  returning id into v_id;

  perform private.siu_audit('SIU_APPOINTED', p_user, jsonb_build_object(
    'siu_role', p_role, 'callsign', v_call,
    'oversight_only', coalesce(p_oversight_only, false),
    'actor_standing', v_standing));

  insert into public.notifications (user_id, type, payload)
  values (p_user, 'siu_appointed',
          jsonb_build_object('siu_role', p_role, 'callsign', v_call));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_assign_agent(p_case uuid, p_user uuid, p_agent_role text DEFAULT 'agent'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid());
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.siu_case_command(p_case) then raise exception 'not authorized'; end if;
  if p_agent_role not in ('lead', 'agent') then raise exception 'unknown assignment role'; end if;
  if private.siu_membership_role(p_user) is null and not coalesce(
       (select p.is_owner and p.active from public.profiles p where p.id = p_user), false) then
    raise exception 'only an active SIB agent can be assigned to an investigation';
  end if;

  insert into public.siu_case_agents (case_id, user_id, agent_role, assigned_by)
  values (p_case, p_user, p_agent_role, v_actor)
  on conflict do nothing;

  if p_agent_role = 'lead' then
    update public.cases set lead_detective_id = p_user where id = p_case;
  end if;

  perform private.siu_audit('SIU_AGENT_ASSIGNED', p_case,
    jsonb_build_object('user_id', p_user, 'agent_role', p_agent_role));

  insert into public.notifications (user_id, type, payload)
  values (p_user, 'siu_case_assigned', jsonb_build_object('case_id', p_case));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_assume_control(p_case uuid, p_reason text, p_classification text DEFAULT 'siu_restricted'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_case record;
begin
  if not private.siu_is_command() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  if p_classification not in ('siu', 'siu_restricted', 'siu_command', 'siu_compartmented') then
    raise exception 'unknown SIB classification';
  end if;

  select c.id, c.case_number, c.title, c.bureau, c.originating_bureau, c.status,
         c.case_authority, c.lead_detective_id, c.created_by, c.archived_at
    into v_case
    from public.cases c
   where c.id = p_case
     for update;
  if not found then raise exception 'case not found'; end if;
  if v_case.case_authority = 'siu' then
    raise exception 'this is already an SIB investigation';
  end if;
  if v_case.archived_at is not null then
    raise exception 'an archived case must be restored before SIB can assume control';
  end if;

  update public.cases
     set case_authority       = 'siu',
         siu_classification   = p_classification,
         siu_assumed_at       = now(),
         siu_assumed_by       = v_actor,
         siu_assumption_reason = btrim(p_reason),
         siu_returned_at      = null
   where id = p_case;

  if not exists (select 1 from public.siu_case_agents a
                  where a.case_id = p_case and a.user_id = v_actor and a.removed_at is null) then
    insert into public.siu_case_agents (case_id, user_id, agent_role, assigned_by)
    values (p_case, v_actor, 'lead', v_actor);
  end if;

  if p_classification = 'siu_compartmented' then
    if not exists (select 1 from public.siu_compartment_members m
                    where m.case_id = p_case and m.user_id = v_actor and m.revoked_at is null) then
      insert into public.siu_compartment_members (case_id, user_id, granted_by, reason)
      values (p_case, v_actor, v_actor, 'Assumed SIB control of a CID investigation');
    end if;
  end if;

  perform private.siu_audit('SIU_CASE_ASSUMED', p_case, jsonb_build_object(
    'case_number',        v_case.case_number,
    'title',              v_case.title,
    'reason',             btrim(p_reason),
    'classification',     p_classification,
    'prior_authority',    v_case.case_authority,
    'prior_bureau',       v_case.bureau,
    'prior_originating_bureau', v_case.originating_bureau,
    'prior_status',       v_case.status,
    'cid_lead_detective', v_case.lead_detective_id,
    'cid_created_by',     v_case.created_by,
    'authorized_by',      v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_audit_feed(p_limit integer DEFAULT 100)
 RETURNS TABLE(id bigint, created_at timestamp with time zone, action text, entity_id uuid, actor_id uuid, actor_name text, detail jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select a.id, a.created_at, a.action, a.entity_id, a.actor_id, p.display_name, a.detail
    from public.audit_log a
    left join public.profiles p on p.id = a.actor_id
   where a.entity = 'siu'
     and private.siu_operates()
     and (
       a.action in ('SIU_APPOINTED', 'SIU_REMOVED', 'SIU_CALLSIGN_CHANGED', 'SIU_RELEASE_SET')
       or (a.entity_id is not null and private.siu_case_read(a.entity_id))
     )
   order by a.created_at desc
   limit greatest(1, least(coalesce(p_limit, 100), 500))
$function$
;

CREATE OR REPLACE FUNCTION public.siu_clear_target(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_t record;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'a reason is required - clearing somebody is a finding';
  end if;
  select * into v_t from public.siu_targets where id = p_id for update;
  if not found then raise exception 'designation not found'; end if;
  if not private.siu_case_access(v_t.case_id) then
    raise exception 'not authorized for that investigation';
  end if;
  if v_t.cleared_at is not null then raise exception 'already cleared'; end if;

  update public.siu_targets
     set cleared_at = now(), cleared_by = v_actor,
         clearance_reason = btrim(p_reason), designation = 'cleared'
   where id = p_id;

  perform private.siu_audit('SIU_TARGET_CLEARED', p_id, jsonb_build_object(
    'case', v_t.case_id, 'entity_type', v_t.entity_type, 'entity_id', v_t.entity_id,
    'was', v_t.designation, 'reason', btrim(p_reason), 'cleared_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_close_case(p_case uuid, p_reason text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid());
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.siu_case_command(p_case) then raise exception 'not authorized'; end if;
  if p_reason not in ('arrest_prosecution','referred_to_cid','referred_to_doj',
                      'administrative_action','unfounded','insufficient_evidence',
                      'intelligence_only','merged','inactive','other') then
    raise exception 'unknown closure reason';
  end if;
  if coalesce(btrim(p_note), '') = '' then raise exception 'a closure note is required'; end if;

  update public.cases
     set status = 'closed', closed_at = now(),
         siu_closure_reason = p_reason, siu_closure_note = btrim(p_note)
   where id = p_case;

  perform private.siu_audit('SIU_CASE_CLOSED', p_case, jsonb_build_object(
    'reason', p_reason, 'note', btrim(p_note), 'closed_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_command_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workload jsonb; v_aging jsonb; v_queues jsonb;
begin
  if not private.siu_is_command() then return jsonb_build_object('access', false); end if;

  select coalesce(jsonb_agg(x order by x->>'display_name'), '[]'::jsonb) into v_workload
  from (
    select jsonb_build_object(
      'user_id', m.user_id,
      'display_name', p.display_name,
      'siu_role', m.siu_role,
      'callsign', m.callsign,
      'open_cases', (
        select count(*) from public.siu_case_agents a
          join public.cases c on c.id = a.case_id
         where a.user_id = m.user_id and a.removed_at is null
           and c.status <> 'closed' and private.siu_case_access(c.id)),
      'inquiries', (
        select count(*) from public.siu_case_agents a
          join public.cases c on c.id = a.case_id
         where a.user_id = m.user_id and a.removed_at is null
           and c.siu_stage = 'preliminary_inquiry' and private.siu_case_access(c.id)),
      'leads', (
        select count(*) from public.cases c
         where c.lead_detective_id = m.user_id and c.case_authority = 'siu'
           and c.status <> 'closed' and private.siu_case_access(c.id)),
      'overdue_reviews', (
        select count(*) from public.siu_case_notes n
         where n.created_by = m.user_id and n.resolved_at is null
           and n.review_due_at is not null and n.review_due_at < now()
           and private.siu_can_read_case_note(n.case_id)),
      'recused_from', (
        select count(*) from public.siu_conflicts k
         where k.agent_id = m.user_id and k.status <> 'cleared')
    ) as x
    from public.siu_memberships m
    join public.profiles p on p.id = m.user_id
   where m.active and not m.oversight_only
  ) s;

  select coalesce(jsonb_agg(jsonb_build_object(
           'case_id', c.id, 'case_number', c.case_number, 'title', c.title,
           'stage', coalesce(c.siu_stage, 'investigation'),
           'category', c.siu_category,
           'classification', coalesce(c.siu_classification, 'siu'),
           'opened_at', c.created_at,
           'days_open', extract(day from now() - c.created_at)::int,
           'agents', (select count(*) from public.siu_case_agents a
                       where a.case_id = c.id and a.removed_at is null))
         order by c.created_at), '[]'::jsonb) into v_aging
    from public.cases c
   where c.case_authority = 'siu' and c.status <> 'closed'
     and private.siu_case_access(c.id)
     and c.created_at < now() - interval '60 days';

  select jsonb_build_object(
    'referrals_awaiting', (
      select count(*) from public.siu_referrals r
       where r.status in ('submitted', 'under_review', 'info_requested')),
    'inquiries_open', (
      select count(*) from public.cases c
       where c.case_authority = 'siu' and c.siu_stage = 'preliminary_inquiry'
         and c.status <> 'closed' and private.siu_case_access(c.id)),
    'conflicts_standing', (
      select count(*) from public.siu_conflicts k
       where k.status <> 'cleared' and private.siu_case_access(k.case_id)),
    'watch_expiring_14d', (
      select count(*) from public.siu_watchlist w
       where w.status in ('active', 'monitor', 'review_due', 'suspended')
         and w.expires_at between now() and now() + interval '14 days'),
    'watch_active', (
      select count(*) from public.siu_watchlist w
       where w.status in ('active', 'monitor', 'review_due', 'suspended') and w.expires_at > now()),
    'temp_access_live', (
      select count(*) from public.siu_temporary_access t
       where t.revoked_at is null and t.expires_at > now()
         and private.siu_case_access(t.case_id))
  ) into v_queues;

  return jsonb_build_object(
    'access', true, 'workload', v_workload, 'aging', v_aging, 'queues', v_queues);
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_compartment_add(p_case uuid, p_user uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid());
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if private.siu_case_classification(p_case) <> 'siu_compartmented' then
    raise exception 'this investigation is not compartmented';
  end if;
  if not private.siu_in_compartment(p_case, v_actor) then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  if private.siu_membership_role(p_user) is null and not coalesce(
       (select p.is_owner and p.active from public.profiles p where p.id = p_user), false) then
    raise exception 'only an active SIB agent can enter a compartment';
  end if;

  insert into public.siu_compartment_members (case_id, user_id, granted_by, reason)
  values (p_case, p_user, v_actor, btrim(p_reason))
  on conflict do nothing;

  perform private.siu_audit('SIU_COMPARTMENT_GRANTED', p_case,
    jsonb_build_object('user_id', p_user, 'reason', btrim(p_reason)));

  insert into public.notifications (user_id, type, payload)
  values (p_user, 'siu_compartment_granted', jsonb_build_object('case_id', p_case));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_compartment_remove(p_case uuid, p_user uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid());
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.siu_in_compartment(p_case, v_actor) then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  if p_user = v_actor then raise exception 'you cannot remove yourself from a compartment'; end if;
  if (select count(*) from public.siu_compartment_members
       where case_id = p_case and revoked_at is null) <= 1 then
    raise exception 'a compartment must keep at least one member';
  end if;

  update public.siu_compartment_members
     set revoked_at = now(), revoked_by = v_actor, reason = btrim(p_reason)
   where case_id = p_case and user_id = p_user and revoked_at is null;
  if not found then raise exception 'not in this compartment'; end if;

  perform private.siu_audit('SIU_COMPARTMENT_REVOKED', p_case,
    jsonb_build_object('user_id', p_user, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_create_case(p_title text, p_summary text DEFAULT NULL::text, p_classification text DEFAULT 'siu'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_id uuid;
  v_number text;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_title), '') = '' then raise exception 'a title is required'; end if;
  if p_classification not in ('siu', 'siu_restricted', 'siu_command', 'siu_compartmented') then
    raise exception 'unknown SIB classification';
  end if;

  v_number := public.next_siu_case_number();
  insert into public.cases (case_number, title, summary, bureau, status,
                            lead_detective_id, created_by, case_authority, siu_classification)
  values (v_number, btrim(p_title), nullif(btrim(coalesce(p_summary, '')), ''),
          'special_investigations', 'open', v_actor, v_actor, 'siu', p_classification)
  returning id into v_id;

  insert into public.siu_case_agents (case_id, user_id, agent_role, assigned_by)
  values (v_id, v_actor, 'lead', v_actor);

  if p_classification = 'siu_compartmented' then
    insert into public.siu_compartment_members (case_id, user_id, granted_by, reason)
    values (v_id, v_actor, v_actor, 'Opened the compartmented investigation');
  end if;

  perform private.siu_audit('SIU_CASE_CREATED', v_id, jsonb_build_object(
    'case_number', v_number, 'classification', p_classification));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_create_operation(p_name text, p_category text DEFAULT NULL::text, p_objective text DEFAULT NULL::text, p_case uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_id uuid;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_name), '') = '' then raise exception 'an operation name is required'; end if;
  if p_category is not null and p_category not in (
       'surveillance', 'undercover', 'controlled', 'search_warrant',
       'arrest', 'fugitive', 'gang', 'narcotics', 'firearms') then
    raise exception 'unknown operation category';
  end if;
  if p_case is not null and not private.siu_case_access(p_case) then
    raise exception 'not authorized for that investigation';
  end if;

  insert into public.operations (name, description, status, authority, op_category,
                                 objective, commander_id, created_by)
  values (btrim(p_name), null, 'active', 'siu', p_category,
          nullif(btrim(coalesce(p_objective, '')), ''), v_actor, v_actor)
  returning id into v_id;

  if p_case is not null then
    insert into public.operation_case_links (operation_id, case_id, added_at, was_jtf)
    values (v_id, p_case, now(), false) on conflict do nothing;
  end if;

  perform private.siu_audit('SIU_OPERATION_CREATED', v_id, jsonb_build_object(
    'name', btrim(p_name), 'category', p_category, 'case_id', p_case));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_decide_access_request(p_request uuid, p_decision text, p_note text, p_days integer DEFAULT 7)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_r record; v_case uuid; v_class text; v_grant uuid;
begin
  if not private.siu_is_command() then raise exception 'not authorized'; end if;
  if p_decision not in ('approved', 'denied') then raise exception 'unknown decision'; end if;
  if coalesce(btrim(p_note), '') = '' then
    raise exception 'a note is required — the requester is told what you decided';
  end if;

  select * into v_r from public.siu_access_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if v_r.status <> 'pending' then raise exception 'this request has already been decided'; end if;

  if p_decision = 'approved' then
    select c.id, coalesce(c.siu_classification, 'siu') into v_case, v_class
      from public.cases c
     where upper(c.case_number) = v_r.case_number_requested and c.case_authority = 'siu';
    if v_case is null then
      raise exception 'no SIB investigation has that case number — deny the request instead';
    end if;
    if not private.siu_case_access(v_case) then
      raise exception 'you do not have access to that investigation yourself';
    end if;
    if v_class <> 'siu' then
      raise exception 'that investigation is % — supporting access is standard-classification only. Use siu_compartment_add() if you intend to admit them deliberately.', v_class;
    end if;
    if p_days is null or p_days < 1 or p_days > 30 then
      raise exception 'access runs for between 1 and 30 days';
    end if;

    v_grant := public.siu_grant_temp_access(
      v_case, v_r.requested_by,
      'Access requested by the Director of CID: ' || v_r.reason, p_days);
  end if;

  update public.siu_access_requests
     set status = p_decision, decided_by = v_actor, decided_at = now(),
         decision_note = btrim(p_note), granted_access_id = v_grant
   where id = p_request;

  insert into public.notifications (user_id, type, payload)
  values (v_r.requested_by, 'siu_access_decision',
          jsonb_build_object('request_id', p_request,
                             'case_number', v_r.case_number_requested,
                             'status', p_decision, 'note', btrim(p_note)));

  perform private.siu_audit('SIU_ACCESS_DECIDED', p_request, jsonb_build_object(
    'case_number', v_r.case_number_requested, 'decision', p_decision,
    'note', btrim(p_note), 'decided_by', v_actor,
    'requested_by', v_r.requested_by, 'grant', v_grant, 'days', p_days));
  return v_grant;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_declare_conflict(p_case uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_id uuid;
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.can_read_case(p_case) then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  if private.siu_recused(p_case, v_actor) then
    raise exception 'you have already declared a conflict on this investigation';
  end if;

  insert into public.siu_conflicts (case_id, agent_id, reason)
  values (p_case, v_actor, btrim(p_reason))
  returning id into v_id;

  update public.siu_case_agents
     set removed_at = now(), removed_by = v_actor
   where case_id = p_case and user_id = v_actor and removed_at is null;
  update public.siu_compartment_members
     set revoked_at = now(), revoked_by = v_actor,
         reason = coalesce(reason, '') || ' [conflict declared]'
   where case_id = p_case and user_id = v_actor and revoked_at is null;

  perform private.siu_audit('SIU_CONFLICT_DECLARED', p_case, jsonb_build_object(
    'conflict_id', v_id, 'reason', btrim(p_reason), 'agent', v_actor,
    'was_lead', exists (select 1 from public.cases c
                         where c.id = p_case and c.lead_detective_id = v_actor),
    'was_supporting', private.siu_temp_access(p_case, v_actor)));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_deconflict(p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_visible jsonb;
  v_hidden int;
  v_watch jsonb;
  v_ids uuid[] := '{}';
  v_q text := btrim(coalesce(p_label, ''));
begin
  if not private.siu_is_agent() then
    return jsonb_build_object('access', false);
  end if;
  if p_entity_id is null and v_q = '' then
    raise exception 'name an entity to deconflict';
  end if;

  if p_entity_id is not null then
    v_ids := array[p_entity_id];
  else
    if p_entity_type = 'person' then
      select coalesce(array_agg(p.id), '{}') into v_ids from public.persons p
       where lower(btrim(p.name)) = lower(v_q) or lower(btrim(coalesce(p.alias, ''))) = lower(v_q);
    elsif p_entity_type = 'vehicle' then
      select coalesce(array_agg(v.id), '{}') into v_ids from public.vehicles v
       where lower(btrim(v.plate)) = lower(v_q);
    elsif p_entity_type = 'gang' then
      select coalesce(array_agg(g.id), '{}') into v_ids from public.gangs g
       where lower(btrim(g.name)) = lower(v_q);
    elsif p_entity_type = 'place' then
      select coalesce(array_agg(pl.id), '{}') into v_ids from public.places pl
       where lower(btrim(pl.name)) = lower(v_q);
    elsif p_entity_type = 'account' then
      select coalesce(array_agg(a.id), '{}') into v_ids from public.accounts a
       where lower(btrim(coalesce(a.handle, ''))) = lower(v_q)
          or lower(btrim(coalesce(a.display_name, ''))) = lower(v_q);
    elsif p_entity_type = 'indicator' then
      select coalesce(array_agg(i.id), '{}') into v_ids from public.indicators i
       where lower(btrim(i.value)) = lower(v_q);
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'case_id', c.id, 'case_number', c.case_number, 'title', c.title,
           'designation', t.designation, 'stage', c.siu_stage) order by c.case_number), '[]'::jsonb)
    into v_visible
    from public.siu_targets t
    join public.cases c on c.id = t.case_id
   where t.cleared_at is null
     and private.siu_case_access(t.case_id)
     and (t.entity_id = any(v_ids)
       or (v_q <> '' and t.entity_type = p_entity_type
           and lower(coalesce(t.label, '')) = lower(v_q)));

  select count(distinct t.case_id) into v_hidden
    from public.siu_targets t
    join public.cases c on c.id = t.case_id
   where t.cleared_at is null
     and not private.siu_case_access(t.case_id)
     and coalesce(c.siu_classification, 'siu') <> 'siu_compartmented'
     and (t.entity_id = any(v_ids)
       or (v_q <> '' and t.entity_type = p_entity_type
           and lower(coalesce(t.label, '')) = lower(v_q)));

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', w.id,
           'label', coalesce(p.name, v.plate, g.name, pl.name, a.handle, i.value,
                             w.label, 'Unidentified subject'),
           'entity_type', w.entity_type,
           'priority', w.priority, 'status', w.status,
           'expires_at', w.expires_at) order by w.created_at desc), '[]'::jsonb)
    into v_watch
    from public.siu_watchlist w
    left join public.persons    p  on p.id  = w.person_id
    left join public.vehicles   v  on v.id  = w.vehicle_id
    left join public.gangs      g  on g.id  = w.gang_id
    left join public.places     pl on pl.id = w.place_id
    left join public.accounts   a  on a.id  = w.account_id
    left join public.indicators i  on i.id  = w.indicator_id
   where w.status in ('active', 'monitor', 'review_due', 'suspended')
     and w.expires_at > now()
     and (coalesce(w.person_id, w.vehicle_id, w.gang_id, w.place_id,
                   w.account_id, w.indicator_id) = any(v_ids)
       or (v_q <> '' and w.entity_type = 'unknown'
           and lower(coalesce(w.label, '')) = lower(v_q)));

  return jsonb_build_object(
    'access', true,
    'investigations', v_visible,
    'other_interest', v_hidden,
    'coordinate_with', case when v_hidden > 0 then 'SIB command' end,
    'watchlist', v_watch);
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_department_context()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'department', private.user_department(),
    'siu_available', private.siu_operates(),
    'siu_standing', private.siu_standing(),
    'release_open', private.siu_release_open(),
    'may_switch', coalesce(private.siu_standing() in ('owner', 'oversight'), false),
    'callsign', (select m.callsign from public.siu_memberships m
                  where m.user_id = (select auth.uid()) and m.active),
    'siu_role', private.siu_membership_role((select auth.uid())),
    -- Narrow on purpose: "may restrict and reveal", not "may enter SIB".
    'may_control_visibility', private.siu_may_control_visibility()
  )
$function$
;

CREATE OR REPLACE FUNCTION public.siu_designate_target(p_case uuid, p_entity_type text, p_entity_id uuid, p_designation text, p_priority text DEFAULT 'medium'::text, p_role text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_id uuid; v_exists boolean; v_live uuid;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if not private.siu_case_access(p_case) then
    raise exception 'not authorized for that investigation';
  end if;
  if p_entity_type not in ('person','vehicle','gang','place','account','indicator','unknown') then
    raise exception 'unknown entity type';
  end if;
  if p_designation not in ('person_of_interest','subject','target','priority_target',
                           'fugitive','associate','source','unknown','cleared') then
    raise exception 'unknown designation';
  end if;
  if p_designation = 'cleared' then
    raise exception 'clear a designation with siu_clear_target(), do not open one as cleared';
  end if;
  if p_priority not in ('low','medium','high','critical') then
    raise exception 'unknown priority';
  end if;

  if p_entity_type = 'unknown' then
    if coalesce(btrim(coalesce(p_label, '')), '') = '' then
      raise exception 'describe who or what is being designated';
    end if;
  else
    if p_entity_id is null then raise exception 'choose a record from the registry'; end if;
    execute format('select exists (select 1 from public.%I where id = $1)',
                   case p_entity_type
                     when 'person' then 'persons' when 'vehicle' then 'vehicles'
                     when 'gang' then 'gangs' when 'place' then 'places'
                     when 'account' then 'accounts' else 'indicators' end)
      into v_exists using p_entity_id;
    if not v_exists then raise exception 'that record is not in the registry'; end if;

    execute format('select id from public.siu_targets
                     where case_id = $1 and %I = $2 and cleared_at is null limit 1',
                   p_entity_type || '_id')
      into v_live using p_case, p_entity_id;
    if v_live is not null then
      raise exception 'already designated in this investigation (entry %)', v_live;
    end if;
  end if;

  insert into public.siu_targets (
    case_id, entity_type, entity_id, label, designation, priority,
    role_in_network, notes, created_by,
    person_id, vehicle_id, gang_id, place_id, account_id, indicator_id)
  values (
    p_case, p_entity_type, p_entity_id,
    nullif(btrim(coalesce(p_label, '')), ''), p_designation, p_priority,
    nullif(btrim(coalesce(p_role, '')), ''), nullif(btrim(coalesce(p_notes, '')), ''),
    v_actor,
    case when p_entity_type = 'person'    then p_entity_id end,
    case when p_entity_type = 'vehicle'   then p_entity_id end,
    case when p_entity_type = 'gang'      then p_entity_id end,
    case when p_entity_type = 'place'     then p_entity_id end,
    case when p_entity_type = 'account'   then p_entity_id end,
    case when p_entity_type = 'indicator' then p_entity_id end)
  returning id into v_id;

  perform private.siu_audit('SIU_TARGET_DESIGNATED', v_id, jsonb_build_object(
    'case', p_case, 'entity_type', p_entity_type, 'entity_id', p_entity_id,
    'designation', p_designation, 'priority', p_priority,
    'role', p_role, 'designated_by', v_actor));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_export_case(p_case uuid, p_scope text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_case record;
  v_payload jsonb;
  v_items jsonb := '[]'::jsonb;
  v_withheld jsonb;
  v_count integer := 0;
  v_sources integer;
  v_legends integer;
  v_intercepts integer;
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not (private.siu_case_access(p_case) and private.siu_is_agent()) then
    raise exception 'not authorized';
  end if;
  if p_scope not in ('case_summary', 'investigation_file', 'intelligence_only', 'disclosure_packet') then
    raise exception 'unknown export scope';
  end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;

  select c.id, c.case_number, c.title, c.summary, c.status, c.siu_classification,
         c.created_at, c.siu_assumed_at
    into v_case from public.cases c where c.id = p_case;

  select count(*) into v_sources from public.siu_sources s
   where s.case_id = p_case and private.siu_handler_access(s.case_id, s.handler_id);
  select count(*) into v_legends from public.siu_undercover_operations u
   where u.case_id = p_case
     and (private.siu_handler_access(u.case_id, u.handler_id) or u.agent_id = v_actor);
  select count(*) into v_intercepts from public.siu_comms_intel m
   where m.case_id = p_case and m.content_summary is not null;

  v_withheld := jsonb_build_array(
    jsonb_build_object('category', 'confidential_source_identities', 'count', v_sources),
    jsonb_build_object('category', 'undercover_legends',             'count', v_legends),
    jsonb_build_object('category', 'intercept_content',              'count', v_intercepts));

  if p_scope = 'disclosure_packet' then
    select coalesce(jsonb_agg(jsonb_build_object(
             'released_at', d.released_at, 'item_type', d.item_type,
             'audience', d.audience, 'handling', d.handling,
             'title', d.title, 'body', d.body,
             'revoked_at', d.revoked_at,
             'acknowledged_at', d.acknowledged_at) order by d.released_at), '[]'::jsonb)
      into v_items
      from public.siu_disclosures d where d.siu_case_id = p_case;
  elsif p_scope = 'intelligence_only' then
    select jsonb_build_object(
      'notes', (select coalesce(jsonb_agg(jsonb_build_object(
                  'created_at', n.created_at, 'note_type', n.note_type,
                  'severity', n.severity, 'body', n.body,
                  'resolved_at', n.resolved_at) order by n.created_at), '[]'::jsonb)
                from public.siu_case_notes n where n.case_id = p_case),
      'targets', (select coalesce(jsonb_agg(jsonb_build_object(
                    'label', t.label, 'entity_type', t.entity_type,
                    'designation', t.designation, 'priority', t.priority,
                    'role_in_network', t.role_in_network,
                    'cleared_at', t.cleared_at) order by t.created_at), '[]'::jsonb)
                  from public.siu_targets t where t.case_id = p_case),
      'financial', (select coalesce(jsonb_agg(jsonb_build_object(
                      'record_type', f.record_type, 'institution', f.institution,
                      'identifier', f.identifier, 'amount', f.amount,
                      'currency', f.currency, 'occurred_at', f.occurred_at,
                      'counterparty', f.counterparty, 'description', f.description,
                      'flagged', f.flagged) order by f.occurred_at), '[]'::jsonb)
                    from public.siu_financial_intel f where f.case_id = p_case),
      'communications_metadata', (select coalesce(jsonb_agg(jsonb_build_object(
                      'record_type', m.record_type, 'identifier', m.identifier,
                      'subscriber', m.subscriber, 'carrier', m.carrier,
                      'counterpart', m.counterpart, 'direction', m.direction,
                      'occurred_at', m.occurred_at,
                      'duration_seconds', m.duration_seconds,
                      'legal_authority', m.legal_authority) order by m.occurred_at), '[]'::jsonb)
                    from public.siu_comms_intel m where m.case_id = p_case)
    ) into v_items;
  elsif p_scope = 'investigation_file' then
    select jsonb_build_object(
      'reports', (select coalesce(jsonb_agg(jsonb_build_object(
                    'created_at', r.created_at, 'template', r.template,
                    'kind', r.kind, 'seq', r.seq, 'finalized', r.finalized,
                    'author', (select p.display_name from public.profiles p where p.id = r.author_id),
                    'fields', r.fields) order by r.created_at), '[]'::jsonb)
                  from public.reports r where r.case_id = p_case),
      'evidence', (select coalesce(jsonb_agg(jsonb_build_object(
                     'item_code', e.item_code, 'type', e.type,
                     'description', e.description, 'location', e.location,
                     'collected_at', e.collected_at,
                     'collected_by', (select p.display_name from public.profiles p where p.id = e.collected_by)
                   ) order by e.created_at), '[]'::jsonb)
                   from public.evidence e where e.case_id = p_case),
      'tasks', (select coalesce(jsonb_agg(jsonb_build_object(
                  'title', k.title, 'done', k.done, 'due', k.due) order by k.created_at), '[]'::jsonb)
                from public.case_tasks k where k.case_id = p_case),
      'notes', (select coalesce(jsonb_agg(jsonb_build_object(
                  'created_at', n.created_at, 'note_type', n.note_type,
                  'severity', n.severity, 'body', n.body) order by n.created_at), '[]'::jsonb)
                from public.siu_case_notes n where n.case_id = p_case),
      'targets', (select coalesce(jsonb_agg(jsonb_build_object(
                    'label', t.label, 'designation', t.designation,
                    'priority', t.priority) order by t.created_at), '[]'::jsonb)
                  from public.siu_targets t where t.case_id = p_case)
    ) into v_items;
  end if;

  if jsonb_typeof(v_items) = 'array' then
    v_count := jsonb_array_length(v_items);
  elsif jsonb_typeof(v_items) = 'object' then
    select coalesce(sum(jsonb_array_length(value)), 0) into v_count
      from jsonb_each(v_items) where jsonb_typeof(value) = 'array';
  end if;

  v_payload := jsonb_build_object(
    'case', jsonb_build_object(
      'case_number', v_case.case_number, 'title', v_case.title,
      'summary', v_case.summary, 'status', v_case.status,
      'classification', v_case.siu_classification,
      'opened_at', v_case.created_at,
      'assumed_from_cid_at', v_case.siu_assumed_at),
    'agents', (select coalesce(jsonb_agg(jsonb_build_object(
                 'name', p.display_name, 'role', a.agent_role,
                 'callsign', (select m.callsign from public.siu_memberships m
                               where m.user_id = a.user_id and m.active))
                 order by a.assigned_at), '[]'::jsonb)
               from public.siu_case_agents a
               join public.profiles p on p.id = a.user_id
              where a.case_id = p_case and a.removed_at is null),
    'scope', p_scope,
    'items', v_items,
    'withheld', v_withheld,
    'exported_at', now(),
    'exported_by', (select p.display_name from public.profiles p where p.id = v_actor));

  insert into public.siu_exports (case_id, scope, reason, item_count, withheld, exported_by)
  values (p_case, p_scope, btrim(p_reason), v_count, v_withheld, v_actor);

  perform private.siu_audit('SIU_EXPORTED', p_case, jsonb_build_object(
    'scope', p_scope, 'reason', btrim(p_reason),
    'item_count', v_count, 'withheld', v_withheld, 'exported_by', v_actor));

  return v_payload;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_grade_note(p_note uuid, p_source_type text, p_reliability text, p_credibility text, p_review_due timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_note record; v_case uuid;
begin
  select * into v_note from public.siu_case_notes where id = p_note for update;
  if not found then raise exception 'note not found'; end if;
  v_case := v_note.case_id;
  if not (private.siu_is_agent() and private.siu_can_read_case_note(v_case)) then
    raise exception 'not authorized';
  end if;

  if p_source_type not in ('human_source','officer_observation','surveillance','technical',
                           'documentary','open_source','anonymous','partner_agency','other') then
    raise exception 'unknown source type';
  end if;
  if p_reliability not in ('reliable','usually_reliable','fairly_reliable',
                           'not_usually_reliable','unreliable','untested') then
    raise exception 'unknown source reliability';
  end if;
  if p_credibility not in ('confirmed','probably_true','possibly_true',
                           'doubtful','improbable','cannot_judge') then
    raise exception 'unknown information credibility';
  end if;
  if p_review_due is not null and p_review_due <= now() then
    raise exception 'a review date must be in the future';
  end if;

  update public.siu_case_notes
     set source_type = p_source_type,
         source_reliability = p_reliability,
         info_credibility = p_credibility,
         review_due_at = coalesce(p_review_due, now() + interval '90 days')
   where id = p_note;

  perform private.siu_audit('SIU_INTEL_GRADED', p_note, jsonb_build_object(
    'case', v_case, 'source_type', p_source_type, 'reliability', p_reliability,
    'credibility', p_credibility, 'graded_by', v_actor,
    'previous', jsonb_build_object('reliability', v_note.source_reliability,
                                   'credibility', v_note.info_credibility)));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_grant_temp_access(p_case uuid, p_user uuid, p_reason text, p_days integer DEFAULT 7)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_id uuid;
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.siu_case_command(p_case) then raise exception 'not authorized'; end if;
  if coalesce(private.siu_case_classification(p_case), 'siu') <> 'siu' then
    raise exception 'supporting access is available only on a standard SIB investigation';
  end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  if p_days is null or p_days < 1 or p_days > 30 then
    raise exception 'supporting access runs for between 1 and 30 days';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_user and p.active) then
    raise exception 'that account is not active';
  end if;
  if p_user = v_actor then
    raise exception 'you already have access to this investigation';
  end if;
  if private.siu_temp_access(p_case, p_user) then
    raise exception 'that officer already holds supporting access to this investigation';
  end if;

  insert into public.siu_temporary_access (case_id, user_id, reason, granted_by, expires_at)
  values (p_case, p_user, btrim(p_reason), v_actor, now() + make_interval(days => p_days))
  returning id into v_id;

  perform private.siu_audit('SIU_TEMP_ACCESS_GRANTED', p_case, jsonb_build_object(
    'grant_id', v_id, 'officer', p_user, 'reason', btrim(p_reason),
    'days', p_days, 'granted_by', v_actor));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_intel_quality()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_r jsonb;
begin
  if private.siu_standing() is null then return jsonb_build_object('access', false); end if;

  select jsonb_build_object(
    'access', true,
    'notes', count(*),
    'ungraded', count(*) filter (where n.info_credibility is null),
    'confirmed', count(*) filter (where n.info_credibility = 'confirmed'),
    'doubtful', count(*) filter (where n.info_credibility in ('doubtful', 'improbable')),
    'untested_source', count(*) filter (where n.source_reliability = 'untested'),
    'review_overdue', count(*) filter (
      where n.review_due_at is not null and n.review_due_at < now() and n.resolved_at is null),
    'review_due_30d', count(*) filter (
      where n.review_due_at is not null and n.resolved_at is null
        and n.review_due_at between now() and now() + interval '30 days'),
    'withdrawn', count(*) filter (where n.review_outcome = 'withdrawn')
  ) into v_r
  from public.siu_case_notes n
  where private.siu_can_read_case_note(n.case_id);

  return v_r;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_intelligence_live()
 RETURNS TABLE(id uuid, case_id uuid, case_number text, case_title text, siu_case_id uuid, siu_case_number text, is_about_cid_case boolean, note_type text, body text, severity text, subject_person_id uuid, subject_name text, source_type text, source_reliability text, info_credibility text, review_due_at timestamp with time zone, review_overdue boolean, last_reviewed_at timestamp with time zone, review_outcome text, resolved_at timestamp with time zone, resolution text, created_at timestamp with time zone, created_by uuid, created_by_name text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    n.id, n.case_id, c.case_number, c.title,
    n.siu_case_id, s.case_number,
    coalesce(c.case_authority, 'cid') <> 'siu' as is_about_cid_case,
    n.note_type, n.body, n.severity,
    n.subject_person_id, p.name,
    n.source_type, n.source_reliability, n.info_credibility,
    n.review_due_at,
    (n.review_due_at is not null and n.review_due_at < now()
       and n.resolved_at is null) as review_overdue,
    n.last_reviewed_at, n.review_outcome,
    n.resolved_at, n.resolution,
    n.created_at, n.created_by, a.display_name
  from public.siu_case_notes n
  left join public.cases    c on c.id = n.case_id
  left join public.cases    s on s.id = n.siu_case_id
  left join public.persons  p on p.id = n.subject_person_id
  left join public.profiles a on a.id = n.created_by
  order by
    (n.resolved_at is not null),
    (n.review_due_at is not null and n.review_due_at < now()) desc,
    (n.info_credibility is null) desc,
    n.created_at desc
$function$
;

CREATE OR REPLACE FUNCTION public.siu_mark_origin(p_type text, p_id uuid, p_reason text, p_case_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public.siu_restrict(p_type, p_id, 'record', p_reason, null, false, p_case_id);
end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_member_search(p_q text)
 RETURNS TABLE(id uuid, display_name text, badge_number text, cid_role text, cid_bureau text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select p.id, p.display_name, p.badge_number, p.role::text, p.division::text
    from public.profiles p
   where private.siu_can_appoint()
     and p.active and p.removed_at is null
     and not coalesce(p.is_system, false)
     and not exists (select 1 from public.siu_memberships m where m.user_id = p.id and m.active)
     and (coalesce(btrim(p_q), '') = ''
          or p.display_name ilike '%' || btrim(p_q) || '%'
          or p.badge_number ilike '%' || btrim(p_q) || '%')
   order by p.display_name
   limit 25
$function$
;

CREATE OR REPLACE FUNCTION public.siu_my_access_requests()
 RETURNS TABLE(id uuid, case_number text, reason text, requested_at timestamp with time zone, status text, decided_at timestamp with time zone, decision_note text, access_expires_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select r.id, r.case_number_requested, r.reason, r.requested_at,
         r.status, r.decided_at, r.decision_note,
         (select t.expires_at from public.siu_temporary_access t
           where t.id = r.granted_access_id and t.revoked_at is null)
    from public.siu_access_requests r
   where r.requested_by = (select auth.uid())
   order by r.requested_at desc
   limit 100
$function$
;

CREATE OR REPLACE FUNCTION public.siu_my_referrals()
 RETURNS TABLE(id uuid, category text, summary text, submitted_at timestamp with time zone, acknowledged boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select r.id, r.category, r.summary, r.submitted_at,
         (r.status <> 'submitted') as acknowledged
    from public.siu_referrals r
   where r.submitted_by = (select auth.uid())
   order by r.submitted_at desc
   limit 100
$function$
;

CREATE OR REPLACE FUNCTION public.siu_oversight_report()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case when not private.siu_operates() then jsonb_build_object('access', false)
  else jsonb_build_object(
    'access', true,
    'standing', private.siu_standing(),
    'generated_at', now(),
    'investigations', jsonb_build_object(
      'total',         (select count(*) from public.cases c where c.case_authority = 'siu'),
      'open',          (select count(*) from public.cases c where c.case_authority = 'siu' and c.status <> 'closed'),
      'closed',        (select count(*) from public.cases c where c.case_authority = 'siu' and c.status = 'closed'),
      'standard',      (select count(*) from public.cases c where c.case_authority = 'siu'
                          and coalesce(c.siu_classification, 'siu') = 'siu'),
      'restricted',    (select count(*) from public.cases c where c.case_authority = 'siu'
                          and c.siu_classification = 'siu_restricted'),
      'command',       (select count(*) from public.cases c where c.case_authority = 'siu'
                          and c.siu_classification = 'siu_command'),
      'compartmented', (select count(*) from public.cases c where c.case_authority = 'siu'
                          and c.siu_classification = 'siu_compartmented')),
    'control', jsonb_build_object(
      'assumed_total',   (select count(*) from public.cases c where c.siu_assumed_at is not null),
      'currently_held',  (select count(*) from public.cases c
                            where c.siu_assumed_at is not null and c.case_authority = 'siu'),
      'returned_to_cid', (select count(*) from public.cases c where c.siu_returned_at is not null)),
    'disclosure', jsonb_build_object(
      'released',     (select count(*) from public.siu_disclosures),
      'live',         (select count(*) from public.siu_disclosures d where d.revoked_at is null),
      'revoked',      (select count(*) from public.siu_disclosures d where d.revoked_at is not null),
      'acknowledged', (select count(*) from public.siu_disclosures d where d.acknowledged_at is not null),
      'to_division',  (select count(*) from public.siu_disclosures d where d.audience = 'cid'),
      'to_case',      (select count(*) from public.siu_disclosures d where d.audience = 'case_members'),
      'to_officer',   (select count(*) from public.siu_disclosures d where d.audience = 'investigator')),
    'integrity', jsonb_build_object(
      'total',           (select count(*) from public.siu_integrity_reviews),
      'open',            (select count(*) from public.siu_integrity_reviews r where r.closed_at is null),
      'substantiated',   (select count(*) from public.siu_integrity_reviews r where r.status = 'substantiated'),
      'unsubstantiated', (select count(*) from public.siu_integrity_reviews r where r.status = 'unsubstantiated'),
      'inconclusive',    (select count(*) from public.siu_integrity_reviews r where r.status = 'inconclusive'),
      'referred',        (select count(*) from public.siu_integrity_reviews r where r.status = 'referred'),
      'critical_open',   (select count(*) from public.siu_integrity_reviews r
                            where r.closed_at is null and r.severity = 'critical'),
      'flags_against_cid_cases', (select count(*) from public.siu_case_notes n
                                    join public.cases c on c.id = n.case_id
                                   where c.case_authority = 'cid' and n.resolved_at is null
                                     and n.note_type in ('integrity_concern', 'corruption_flag',
                                                         'compromised_officer', 'leak_concern'))),
    'tradecraft', jsonb_build_object(
      'sources_registered',   (select count(*) from public.siu_sources),
      'sources_active',       (select count(*) from public.siu_sources s where s.status = 'active'),
      'undercover_active',    (select count(*) from public.siu_undercover_operations u
                                 where u.status in ('authorized', 'active')),
      'undercover_compromised', (select count(*) from public.siu_undercover_operations u
                                   where u.status = 'compromised'),
      'financial_records',    (select count(*) from public.siu_financial_intel),
      'comms_records',        (select count(*) from public.siu_comms_intel),
      'comms_with_content',   (select count(*) from public.siu_comms_intel m
                                 where m.content_summary is not null)),
    'exports', jsonb_build_object(
      'total',       (select count(*) from public.siu_exports),
      'last_30_days', (select count(*) from public.siu_exports e
                         where e.exported_at > now() - interval '30 days')),
    'personnel', jsonb_build_object(
      'agents', (select count(*) from public.siu_memberships m where m.active))
  ) end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_oversight_supplement()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if private.siu_standing() is null then return jsonb_build_object('access', false); end if;

  return jsonb_build_object(
    'access', true,
    'referrals_total', (select count(*) from public.siu_referrals),
    'referrals_awaiting', (select count(*) from public.siu_referrals r
                            where r.status in ('submitted','under_review','info_requested')),
    'referrals_accepted', (select count(*) from public.siu_referrals r where r.status = 'accepted'),
    'referrals_declined', (select count(*) from public.siu_referrals r
                            where r.status in ('declined','referred_to_cid','withdrawn')),
    'inquiries_open', (select count(*) from public.cases c
                        where c.case_authority = 'siu'
                          and c.siu_stage = 'preliminary_inquiry' and c.status <> 'closed'),
    'closed_by_reason', (
      select coalesce(jsonb_object_agg(r, n), '{}'::jsonb) from (
        select coalesce(c.siu_closure_reason, 'unrecorded') as r, count(*) as n
          from public.cases c
         where c.case_authority = 'siu' and c.status = 'closed'
         group by 1) z),
    'open_by_category', (
      select coalesce(jsonb_object_agg(r, n), '{}'::jsonb) from (
        select coalesce(c.siu_category, 'uncategorised') as r, count(*) as n
          from public.cases c
         where c.case_authority = 'siu' and c.status <> 'closed'
         group by 1) z),
    'conflicts_declared', (select count(*) from public.siu_conflicts),
    'conflicts_standing', (select count(*) from public.siu_conflicts k where k.status <> 'cleared'),
    'intel_ungraded', (select count(*) from public.siu_case_notes n where n.info_credibility is null),
    'intel_review_overdue', (select count(*) from public.siu_case_notes n
                              where n.resolved_at is null and n.review_due_at is not null
                                and n.review_due_at < now()),
    'watch_active', (select count(*) from public.siu_watchlist w
                      where w.status in ('active', 'monitor', 'review_due', 'suspended') and w.expires_at > now()),
    'temp_access_live', (select count(*) from public.siu_temporary_access t
                          where t.revoked_at is null and t.expires_at > now()),
    'temp_access_granted_total', (select count(*) from public.siu_temporary_access));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_overview()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case when not private.siu_operates() then jsonb_build_object('access', false)
  else jsonb_build_object(
    'access', true,
    'standing', private.siu_standing(),
    'release_open', private.siu_release_open(),
    'investigations', (select count(*) from public.cases c
                        where c.case_authority = 'siu' and private.siu_case_read(c.id)),
    'open_investigations', (select count(*) from public.cases c
                             where c.case_authority = 'siu' and c.status <> 'closed'
                               and private.siu_case_read(c.id)),
    'assigned', (select count(*) from public.cases c
                  where c.case_authority = 'siu' and c.status <> 'closed'
                    and private.siu_case_access(c.id)
                    and private.siu_case_assigned(c.id, (select auth.uid()))),
    'compartmented', (select count(*) from public.cases c
                       where c.case_authority = 'siu'
                         and c.siu_classification = 'siu_compartmented'
                         and private.siu_case_access(c.id)),
    'agents', (select count(*) from public.siu_memberships m where m.active),
    'legal_pending', (select count(*) from public.legal_requests r
                       join public.cases c on c.id = r.case_id
                      where c.case_authority = 'siu'
                        and r.review_status not in ('approved', 'denied', 'declined')
                        and private.siu_case_read(c.id)),
    'priority_targets', (select count(*) from public.siu_targets t
                          where t.cleared_at is null
                            and t.designation in ('target', 'priority_target', 'fugitive')
                            and private.siu_case_read(t.case_id)),
    'active_targets', (select count(*) from public.siu_targets t
                        where t.cleared_at is null and private.siu_case_read(t.case_id)),
    'active_operations', (select count(*) from public.operations o
                           where o.authority = 'siu'
                             and o.status in ('active', 'planning', 'authorized')),
    'open_intel', (select count(*) from public.siu_case_notes n
                    where n.resolved_at is null and private.siu_can_read_case_note(n.case_id)),
    'cid_integrity_flags', (select count(*) from public.siu_case_notes n
                             join public.cases c on c.id = n.case_id
                            where c.case_authority = 'cid' and n.resolved_at is null
                              and n.note_type in ('integrity_concern', 'corruption_flag',
                                                  'compromised_officer', 'leak_concern')
                              and private.siu_can_read_case_note(n.case_id)),
    'surveillance_active', (select count(*) from public.surveillance_targets s
                             join public.cases c on c.id = s.case_id
                            where c.case_authority = 'siu' and s.ended_at is null
                              and private.siu_case_access(s.case_id)),
    'cid_recent_cases', case when private.siu_oversight_read() then (
      select count(*) from public.cases c
       where c.case_authority = 'cid' and c.created_at > now() - interval '7 days') end,
    'cid_open_cases', case when private.siu_oversight_read() then (
      select count(*) from public.cases c
       where c.case_authority = 'cid' and c.status <> 'closed') end
  ) end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_person_dossier(p_person uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with subject as (
    select p.* from public.persons p where p.id = p_person
  )
  select case when not exists (select 1 from subject) then null else jsonb_build_object(

    'person', (select jsonb_build_object(
        'id', s.id, 'name', s.name, 'alias', s.alias, 'dob', s.dob,
        'phone', s.phone, 'status', s.status, 'classification', s.classification,
        'confidence', s.confidence, 'priority', s.priority, 'lifecycle', s.lifecycle,
        'mugshot_url', s.mugshot_url, 'notes', s.notes,
        'ccw', s.ccw, 'vch', s.vch, 'felony_count', s.felony_count,
        'merged_into', s.merged_into,
        'reviewed_at', s.reviewed_at, 'next_review_at', s.next_review_at,
        'identity', s.identity, 'properties', s.properties,
        'intelligence_summary', s.intelligence_summary,
        'bolo', jsonb_build_object(
          'active', s.bolo, 'reason', s.bolo_reason, 'risk', s.bolo_risk,
          'instructions', s.bolo_instructions, 'issued_at', s.bolo_issued_at,
          'expires_at', s.bolo_expires_at, 'case_id', s.bolo_case_id))
      from subject s),

    'gang', (select jsonb_build_object(
        'id', g.id, 'name', g.name, 'threat_level', g.threat_level,
        'classification', g.classification, 'status', g.status,
        'confidence', g.confidence)
      from subject s join public.gangs g on g.id = s.gang_id),

    'gang_memberships', coalesce((select jsonb_agg(jsonb_build_object(
        'id', m.id, 'gang_id', m.gang_id, 'gang_name', g.name,
        'rank', m.rank, 'callsign', m.callsign, 'status', m.status,
        'confidence', m.confidence, 'provenance', m.provenance,
        'joined_at', m.joined_at, 'left_at', m.left_at, 'note', m.note,
        'case_id', m.case_id,
        'reviewed_at', m.reviewed_at) order by m.left_at nulls first, m.joined_at desc)
      from public.gang_members m left join public.gangs g on g.id = m.gang_id
      where m.person_id = p_person), '[]'::jsonb),

    'vehicles_registered', coalesce((select jsonb_agg(jsonb_build_object(
        'id', v.id, 'plate', v.plate, 'model', v.model, 'color', v.color,
        'gang_id', v.gang_id, 'notes', v.notes) order by v.plate)
      from public.vehicles v where v.owner_id = p_person), '[]'::jsonb),

    'vehicles_linked', coalesce((select jsonb_agg(jsonb_build_object(
        'id', pv.id, 'vehicle_id', v.id, 'plate', v.plate, 'model', v.model,
        'color', v.color, 'role', pv.role, 'link_status', pv.link_status,
        'confidence', pv.confidence, 'provenance', pv.provenance,
        'note', pv.note, 'first_observed', pv.first_observed,
        'last_confirmed', pv.last_confirmed)
        order by pv.last_confirmed desc nulls last)
      from public.person_vehicles pv join public.vehicles v on v.id = pv.vehicle_id
      where pv.person_id = p_person), '[]'::jsonb),

    'places', coalesce((select jsonb_agg(jsonb_build_object(
        'id', pp.id, 'place_id', pl.id, 'name', pl.name, 'type', pl.type,
        'area', pl.area, 'role', pp.role, 'link_status', pp.link_status,
        'confidence', pp.confidence, 'provenance', pp.provenance,
        'note', pp.note, 'first_observed', pp.first_observed,
        'last_confirmed', pp.last_confirmed)
        order by pp.last_confirmed desc nulls last)
      from public.person_places pp join public.places pl on pl.id = pp.place_id
      where pp.person_id = p_person), '[]'::jsonb),

    'accounts', coalesce((select jsonb_agg(jsonb_build_object(
        'link_id', al.id, 'account_id', a.id, 'platform', a.platform,
        'handle', a.handle, 'display_name', a.display_name,
        'profile_url', a.profile_url, 'category', a.category, 'state', a.state,
        'restricted', a.restricted, 'lifecycle', a.lifecycle,
        'is_impersonation', a.is_impersonation, 'is_compromised', a.is_compromised,
        'ownership_confidence', al.ownership_confidence, 'source', al.source,
        'notes', al.notes, 'confirmed_at', al.confirmed_at,
        'handles', (select coalesce(jsonb_agg(jsonb_build_object(
              'handle', h.handle, 'is_current', h.is_current,
              'observed_at', h.observed_at, 'source', h.source)
            order by h.is_current desc, h.observed_at desc), '[]'::jsonb)
          from public.account_handles h where h.account_id = a.id))
        order by al.confirmed_at desc nulls last)
      from public.account_links al join public.accounts a on a.id = al.account_id
      where al.person_id = p_person), '[]'::jsonb),

    'relationships', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'other_id', case when r.person_a = p_person then r.person_b else r.person_a end,
        'other_name', o.name,
        'relationship', r.relationship, 'rel_status', r.rel_status,
        'confidence', r.confidence, 'provenance', r.provenance, 'note', r.note,
        'first_observed', r.first_observed, 'last_confirmed', r.last_confirmed)
        order by r.last_confirmed desc nulls last)
      from public.person_relationships r
      join public.persons o
        on o.id = case when r.person_a = p_person then r.person_b else r.person_a end
      where r.person_a = p_person or r.person_b = p_person), '[]'::jsonb),

    'narcotics', coalesce((select jsonb_agg(jsonb_build_object(
        'id', np.id, 'narcotic_id', n.id, 'name', n.name, 'role', np.role,
        'link_status', np.link_status, 'confidence', np.confidence,
        'provenance', np.provenance, 'first_observed', np.first_observed,
        'last_confirmed', np.last_confirmed)
        order by np.last_confirmed desc nulls last)
      from public.narcotic_persons np join public.narcotics n on n.id = np.narcotic_id
      where np.person_id = p_person), '[]'::jsonb),

    'watch', (select jsonb_build_object(
        'id', w.id, 'reason', w.reason, 'priority', w.priority,
        'status', w.status, 'classification', w.classification,
        'source', w.source, 'notes', w.notes, 'case_id', w.case_id,
        'assigned_agent', w.assigned_agent, 'expires_at', w.expires_at,
        'review_due_at', w.review_due_at, 'created_at', w.created_at,
        'live', w.status in ('active','monitor','review_due','suspended')
                and w.expires_at > now())
      from public.siu_watchlist w
      where w.person_id = p_person
        and w.status in ('active','monitor','review_due','suspended')
      order by w.created_at desc limit 1),

    'watch_history', coalesce((select jsonb_agg(jsonb_build_object(
        'id', w.id, 'reason', w.reason, 'priority', w.priority,
        'status', w.status, 'created_at', w.created_at,
        'removed_at', w.removed_at, 'removal_reason', w.removal_reason)
        order by w.created_at desc)
      from public.siu_watchlist w where w.person_id = p_person), '[]'::jsonb),

    'siu_targets', coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.id, 'case_id', t.case_id, 'designation', t.designation,
        'role_in_network', t.role_in_network, 'priority', t.priority,
        'notes', t.notes, 'cleared_at', t.cleared_at,
        'created_at', t.created_at) order by t.created_at desc)
      from public.siu_targets t
      where t.entity_type = 'person' and t.entity_id = p_person), '[]'::jsonb),

    'siu_intelligence', coalesce((select jsonb_agg(jsonb_build_object(
        'id', n.id, 'case_id', coalesce(n.siu_case_id, n.case_id),
        'note_type', n.note_type, 'body', n.body, 'severity', n.severity,
        'source_type', n.source_type,
        'source_reliability', n.source_reliability,
        'info_credibility', n.info_credibility,
        'review_due_at', n.review_due_at, 'last_reviewed_at', n.last_reviewed_at,
        'review_outcome', n.review_outcome,
        'resolved_at', n.resolved_at, 'created_at', n.created_at)
        order by n.created_at desc)
      from public.siu_case_notes n where n.subject_person_id = p_person), '[]'::jsonb),

    'siu_source', (select jsonb_build_object(
        'id', src.id, 'codename', src.codename, 'status', src.status,
        'case_id', src.case_id)
      from public.siu_sources src
      where src.person_id = p_person and src.deactivated_at is null
      order by src.registered_at desc limit 1),

    'surveillance', coalesce((select jsonb_agg(jsonb_build_object(
        'id', so.id, 'case_id', so.case_id, 'observed_at', so.observed_at,
        'place_id', so.place_id, 'location_text', so.location_text,
        'activity', so.activity, 'confidence', so.confidence,
        'verification_status', so.verification_status,
        'restricted', so.restricted) order by so.observed_at desc)
      from (select * from public.surveillance_observations o
             where o.person_id = p_person
             order by o.observed_at desc limit 25) so), '[]'::jsonb)
  ) end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_promote_inquiry(p_case uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_stage text;
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.siu_case_command(p_case) then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  select siu_stage into v_stage from public.cases where id = p_case for update;
  if coalesce(v_stage, 'investigation') <> 'preliminary_inquiry' then
    raise exception 'this is not a preliminary inquiry';
  end if;

  update public.cases set siu_stage = 'investigation' where id = p_case;
  perform private.siu_audit('SIU_INQUIRY_PROMOTED', p_case, jsonb_build_object(
    'reason', btrim(p_reason), 'promoted_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_record_intelligence(p_case uuid, p_note_type text, p_body text, p_severity text DEFAULT 'medium'::text, p_siu_case uuid DEFAULT NULL::uuid, p_subject_person uuid DEFAULT NULL::uuid, p_source_type text DEFAULT NULL::text, p_source_reliability text DEFAULT NULL::text, p_info_credibility text DEFAULT NULL::text, p_review_days integer DEFAULT 90)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_id uuid;
begin
  if not (private.siu_can_read_case_note(p_case) and private.siu_is_agent()) then
    raise exception 'not authorized';
  end if;

  if p_note_type not in ('intelligence','integrity_concern','corruption_flag',
                         'compromised_officer','leak_concern','conflict_of_interest',
                         'surveillance_note','related_investigation') then
    raise exception 'unknown note type';
  end if;
  if p_severity not in ('low','medium','high','critical') then
    raise exception 'unknown severity';
  end if;
  if coalesce(btrim(p_body), '') = '' then
    raise exception 'a note needs a body - what is being recorded';
  end if;
  if p_source_type is not null and p_source_type not in
     ('human_source','officer_observation','surveillance','technical','documentary',
      'open_source','anonymous','partner_agency','other') then
    raise exception 'unknown source type';
  end if;
  if p_source_reliability is not null and p_source_reliability not in
     ('reliable','usually_reliable','fairly_reliable','not_usually_reliable',
      'unreliable','untested') then
    raise exception 'unknown source reliability';
  end if;
  if p_info_credibility is not null and p_info_credibility not in
     ('confirmed','probably_true','possibly_true','doubtful','improbable','cannot_judge') then
    raise exception 'unknown credibility';
  end if;
  if p_review_days is not null and (p_review_days < 1 or p_review_days > 730) then
    raise exception 'a review falls between 1 and 730 days out';
  end if;

  if p_siu_case is not null and not private.siu_case_access(p_siu_case) then
    raise exception 'not authorized for that investigation';
  end if;

  if p_subject_person is not null
     and not exists (select 1 from public.persons p where p.id = p_subject_person) then
    raise exception 'that person is not in the registry';
  end if;

  insert into public.siu_case_notes (
    case_id, siu_case_id, note_type, body, severity, subject_person_id,
    source_type, source_reliability, info_credibility, review_due_at, created_by)
  values (
    p_case, p_siu_case, p_note_type, btrim(p_body), p_severity, p_subject_person,
    p_source_type, p_source_reliability, p_info_credibility,
    case when p_info_credibility is not null and p_review_days is not null
         then now() + make_interval(days => p_review_days) end,
    v_actor)
  returning id into v_id;

  perform private.siu_audit('SIU_INTEL_RECORDED', v_id, jsonb_build_object(
    'case', p_case, 'siu_case', p_siu_case, 'note_type', p_note_type,
    'severity', p_severity, 'subject_person', p_subject_person,
    'graded_at_authorship', p_info_credibility is not null,
    'source_type', p_source_type, 'recorded_by', v_actor));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_registry_search(p_entity_type text, p_q text)
 RETURNS TABLE(id uuid, display_name text, secondary text, already_watched boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select x.id, x.display_name, x.secondary,
         exists (select 1 from public.siu_watchlist w
                  where w.status in ('active','monitor','review_due','suspended')
                    and (case p_entity_type
                           when 'person'  then w.person_id
                           when 'vehicle' then w.vehicle_id
                           when 'gang'    then w.gang_id
                           when 'place'   then w.place_id
                           when 'account' then w.account_id
                           else w.indicator_id end) = x.id) as already_watched
  from (
    select p.id, p.name as display_name,
           nullif(concat_ws(' - ', p.alias, p.status), '') as secondary
      from public.persons p
     where p_entity_type = 'person'
       and (p.name ilike '%' || btrim(coalesce(p_q, '')) || '%'
         or p.alias ilike '%' || btrim(coalesce(p_q, '')) || '%')
    union all
    select v.id, v.plate, nullif(concat_ws(' ', v.color, v.model), '')
      from public.vehicles v
     where p_entity_type = 'vehicle'
       and v.plate ilike '%' || btrim(coalesce(p_q, '')) || '%'
    union all
    select g.id, g.name, g.classification
      from public.gangs g
     where p_entity_type = 'gang'
       and (g.name ilike '%' || btrim(coalesce(p_q, '')) || '%'
         or g.aliases ilike '%' || btrim(coalesce(p_q, '')) || '%')
    union all
    select pl.id, pl.name, pl.area
      from public.places pl
     where p_entity_type = 'place'
       and pl.name ilike '%' || btrim(coalesce(p_q, '')) || '%'
    union all
    select a.id, coalesce(a.handle, a.display_name, a.external_id), a.platform
      from public.accounts a
     where p_entity_type = 'account'
       and (a.handle ilike '%' || btrim(coalesce(p_q, '')) || '%'
         or a.display_name ilike '%' || btrim(coalesce(p_q, '')) || '%')
    union all
    select i.id, i.value, i.kind
      from public.indicators i
     where p_entity_type = 'indicator'
       and i.value ilike '%' || btrim(coalesce(p_q, '')) || '%'
  ) x
  order by x.display_name
  limit 25
$function$
;

CREATE OR REPLACE FUNCTION public.siu_release_control(p_case uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_case record;
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.siu_case_command(p_case) then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;

  select c.case_number, c.siu_assumed_at, c.siu_classification, c.bureau
    into v_case
    from public.cases c
   where c.id = p_case
     for update;
  if v_case.siu_assumed_at is null then
    raise exception 'this investigation originated with SIB and cannot be released to CID; release a specific item with siu_share() instead';
  end if;

  update public.cases
     set case_authority     = 'cid',
         siu_classification = null,
         siu_returned_at    = now()
   where id = p_case;

  perform private.siu_audit('SIU_CASE_RETURNED', p_case, jsonb_build_object(
    'case_number',    v_case.case_number,
    'reason',         btrim(p_reason),
    'held_since',     v_case.siu_assumed_at,
    'classification_at_return', v_case.siu_classification,
    'returned_by',    v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_released_intelligence(p_case uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, item_type text, title text, body text, handling text, audience text, target_case_id uuid, released_at timestamp with time zone, acknowledged_at timestamp with time zone, acknowledged_by uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select d.id, d.item_type, d.title, d.body, d.handling,
         d.audience, d.target_case_id, d.released_at,
         d.acknowledged_at, d.acknowledged_by
    from public.siu_disclosures d
   where d.revoked_at is null
     and (p_case is null or d.target_case_id = p_case)
     and case d.audience
           when 'cid'          then private.is_active()
           when 'case_members' then private.can_access_case(d.target_case_id)
           when 'investigator' then d.target_user_id = (select auth.uid())
           else false
         end
   order by d.released_at desc
   limit 200
$function$
;

CREATE OR REPLACE FUNCTION public.siu_remove(p_user uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_standing text := private.siu_standing();
  v_row public.siu_memberships%rowtype;
begin
  if not private.siu_can_appoint() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;

  select * into v_row from public.siu_memberships where user_id = p_user and active;
  if not found then raise exception 'not an active SIB member'; end if;

  if p_user = v_actor then
    raise exception 'you cannot remove your own SIB membership';
  end if;
  if v_row.siu_role = 'special_agent_in_charge' and v_standing not in ('owner', 'oversight') then
    raise exception 'only the Portal Owner or the Attorney General may remove a Special Agent in Charge';
  end if;

  update public.siu_memberships
     set active = false, ended_by = v_actor, ended_at = now(),
         end_reason = btrim(p_reason), updated_at = now()
   where user_id = p_user;

  update public.siu_case_agents
     set removed_at = now(), removed_by = v_actor
   where user_id = p_user and removed_at is null;
  update public.siu_compartment_members
     set revoked_at = now(), revoked_by = v_actor, reason = coalesce(reason, btrim(p_reason))
   where user_id = p_user and revoked_at is null;

  perform private.siu_audit('SIU_REMOVED', p_user, jsonb_build_object(
    'siu_role', v_row.siu_role, 'callsign', v_row.callsign,
    'reason', btrim(p_reason), 'actor_standing', v_standing));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_request_case_access(p_case_number text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_id uuid; v_num text; x1 record;
begin
  if not private.siu_may_request_access() then raise exception 'not authorized'; end if;
  v_num := upper(btrim(coalesce(p_case_number, '')));
  if v_num = '' then raise exception 'a case number is required'; end if;
  if length(v_num) > 40 then raise exception 'that is not a case number'; end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'a reason is required — X-1 decides on it';
  end if;

  if exists (select 1 from public.siu_access_requests r
              where r.requested_by = v_actor and r.status = 'pending'
                and r.case_number_requested = v_num) then
    raise exception 'you already have a pending request for that case number';
  end if;

  insert into public.siu_access_requests (case_number_requested, reason, requested_by)
  values (v_num, btrim(p_reason), v_actor)
  returning id into v_id;

  for x1 in
    select m.user_id from public.siu_memberships m
     where m.active and m.siu_role = 'special_agent_in_charge' and not m.oversight_only
  loop
    insert into public.notifications (user_id, type, payload)
    values (x1.user_id, 'siu_access_request',
            jsonb_build_object('request_id', v_id, 'case_number', v_num,
                               'requested_by', v_actor));
  end loop;

  perform private.siu_audit('SIU_ACCESS_REQUESTED', v_id, jsonb_build_object(
    'case_number', v_num, 'reason', btrim(p_reason), 'requested_by', v_actor));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_reserve_visibility(p_type text, p_id uuid, p_visibility text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_standing text;
begin
  if not private.siu_may_control_visibility() then
    raise exception 'not authorized to set visibility';
  end if;
  if p_visibility not in ('siu_only', 'cid') then
    raise exception 'choose SIB Only or Shared with CID';
  end if;
  if private.siu_entity_exists(p_type, p_id) then
    raise exception 'that record already exists; restrict it instead of reserving it';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 10 then
    raise exception 'record why, in a sentence';
  end if;

  if p_visibility = 'cid' then return; end if;

  v_standing := private.siu_standing();
  insert into public.siu_visibility
    (entity_type, entity_id, state, scope, created_by)
  values (p_type, p_id, 'siu_only', 'record', (select auth.uid()))
  on conflict (entity_type, entity_id) do nothing;

  insert into public.siu_visibility_events
    (entity_type, entity_id, action, from_state, to_state, scope,
     actor_id, actor_standing, reason)
  values (p_type, p_id, 'marked', 'new', 'siu_only', 'record',
          (select auth.uid()), v_standing, btrim(p_reason));
end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_resolve_conflict(p_conflict uuid, p_status text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_k record;
begin
  if p_status not in ('acknowledged', 'reassigned', 'cleared') then
    raise exception 'unknown conflict resolution';
  end if;
  if coalesce(btrim(p_note), '') = '' then raise exception 'a resolution note is required'; end if;

  select * into v_k from public.siu_conflicts where id = p_conflict for update;
  if not found then raise exception 'conflict not found'; end if;

  if not (private.siu_is_command() or coalesce(private.siu_standing() = 'owner', false)) then
    raise exception 'not authorized';
  end if;
  if not private.is_siu_case(v_k.case_id) then raise exception 'not an SIB investigation'; end if;

  if v_k.agent_id = v_actor then
    raise exception 'a conflict cannot be resolved by the agent who declared it';
  end if;

  update public.siu_conflicts
     set status = p_status, resolution_note = btrim(p_note),
         acknowledged_by = v_actor, acknowledged_at = now()
   where id = p_conflict;

  perform private.siu_audit('SIU_CONFLICT_RESOLVED', v_k.case_id, jsonb_build_object(
    'conflict_id', p_conflict, 'status', p_status, 'note', btrim(p_note),
    'agent', v_k.agent_id, 'resolved_by', v_actor,
    'access_restored', p_status = 'cleared'));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_resolve_review(p_type text, p_id uuid, p_siu_origin boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_standing text;
begin
  v_standing := private.siu_standing();
  if not private.siu_may_control_visibility() then
    raise exception 'only SIB may resolve a compartmentation review';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 10 then
    raise exception 'record the basis for this decision, in a sentence';
  end if;
  if not exists (select 1 from public.siu_visibility
                  where entity_type = p_type and entity_id = p_id and needs_review) then
    raise exception 'that record is not awaiting review';
  end if;

  if p_siu_origin then
    if private.siu_cid_attached(p_type, p_id) then
      raise exception
        'CID already holds this record, so it stays shared. Compartment the SIB intelligence about it instead.';
    end if;
    update public.siu_visibility
       set state = 'siu_only', needs_review = false, review_note = null, updated_at = now()
     where entity_type = p_type and entity_id = p_id;
    insert into public.siu_visibility_events
      (entity_type, entity_id, action, from_state, to_state, actor_id, actor_standing, reason)
    values (p_type, p_id, 'marked', 'unclassified', 'siu_only',
            (select auth.uid()), v_standing, btrim(p_reason));
  else
    delete from public.siu_visibility
     where entity_type = p_type and entity_id = p_id;
    insert into public.siu_visibility_events
      (entity_type, entity_id, action, from_state, to_state, actor_id, actor_standing, reason)
    values (p_type, p_id, 'restricted', 'unclassified', 'cid',
            (select auth.uid()), v_standing, btrim(p_reason));
  end if;
end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_restrict(p_type text, p_id uuid, p_mode text, p_reason text, p_sections text[] DEFAULT NULL::text[], p_acknowledge_cid_impact boolean DEFAULT false, p_case_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_standing text; v_from public.siu_visibility; v_impact jsonb;
begin
  if not private.siu_may_control_visibility() then
    raise exception 'not authorized to restrict a record';
  end if;
  if p_mode not in ('record', 'sections') then
    raise exception 'choose whether to restrict the entire record or selected sections';
  end if;
  if not private.siu_entity_exists(p_type, p_id) then
    raise exception 'no such record to restrict';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 10 then
    raise exception 'record why this is being restricted, in a sentence';
  end if;
  if p_mode = 'sections' and coalesce(array_length(p_sections, 1), 0) = 0 then
    raise exception 'name at least one section to restrict, or restrict the entire record';
  end if;

  v_standing := private.siu_standing();
  v_impact := public.siu_restriction_impact(p_type, p_id);

  if p_mode = 'record'
     and (v_impact->>'cid_authored')::boolean
     and not coalesce(p_acknowledge_cid_impact, false) then
    raise exception
      'This record contains information created or currently used by CID. Restricting the entire record will remove CID access to that information and may affect active investigations. Confirm to continue.';
  end if;

  select * into v_from from public.siu_visibility
   where entity_type = p_type and entity_id = p_id;

  insert into public.siu_visibility as v
    (entity_type, entity_id, state, scope, hidden_sections, siu_case_id,
     created_by, needs_review, review_note)
  values (p_type, p_id, 'siu_only', p_mode,
          case when p_mode = 'sections' then p_sections else '{}'::text[] end,
          p_case_id, (select auth.uid()), false, null)
  on conflict (entity_type, entity_id) do update
    set state = 'siu_only', scope = p_mode,
        hidden_sections = case when p_mode = 'sections' then p_sections else '{}'::text[] end,
        siu_case_id = coalesce(excluded.siu_case_id, v.siu_case_id),
        revealed_sections = '{}', revealed_to_case_id = null, revealed_to_user_id = null,
        revealed_at = null, revealed_by = null, reveal_reason = null,
        needs_review = false, review_note = null, updated_at = now();

  insert into public.siu_visibility_events
    (entity_type, entity_id, action, from_state, to_state, scope, sections,
     actor_id, actor_standing, reason, impact)
  values (p_type, p_id, 'marked', coalesce(v_from.state, 'cid'), 'siu_only', p_mode,
          case when p_mode = 'sections' then p_sections else '{}'::text[] end,
          (select auth.uid()), v_standing, btrim(p_reason), v_impact);

  return v_impact;
end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_restrict_to_siu(p_type text, p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_standing text; v_from text;
begin
  v_standing := private.siu_standing();
  if not private.siu_may_control_visibility() then
    raise exception 'only SIB may restrict a record';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 10 then
    raise exception 'record why this is being pulled back, in a sentence';
  end if;

  select state into v_from from public.siu_visibility
   where entity_type = p_type and entity_id = p_id;
  if v_from is null then
    raise exception 'that record was never SIB material; use mark, which checks whether CID already holds it';
  end if;

  update public.siu_visibility
     set state = 'siu_only', revealed_sections = '{}',
         revealed_to_case_id = null, revealed_to_user_id = null,
         revealed_at = null, revealed_by = null, reveal_reason = null,
         needs_review = false, review_note = null,
         updated_at = now()
   where entity_type = p_type and entity_id = p_id;

  insert into public.siu_visibility_events
    (entity_type, entity_id, action, from_state, to_state,
     actor_id, actor_standing, reason)
  values (p_type, p_id, 'restricted', v_from, 'siu_only',
          (select auth.uid()), v_standing, btrim(p_reason));
end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_restriction_impact(p_type text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text; v_created_by uuid; v_created_at timestamptz;
  v_vis public.siu_visibility;
  v_cases uuid[] := '{}';
  v_reports int := 0; v_evidence int := 0; v_legal int := 0; v_tasks int := 0;
  v_media int := 0; v_watch int := 0; v_edges int := 0;
  v_persons int := 0; v_gangs int := 0; v_vehicles int := 0; v_places int := 0;
  v_cid boolean;
begin
  if not private.siu_may_control_visibility() then
    raise exception 'not authorized to inspect compartmentation';
  end if;

  case p_type
    when 'person' then
      select p.name, p.created_by, p.created_at into v_name, v_created_by, v_created_at
        from public.persons p where p.id = p_id;
      select coalesce(array_agg(distinct c), '{}') into v_cases from (
        select case_id as c from public.legal_requests where person_id = p_id and case_id is not null
        union select case_id from public.media where person_id = p_id and case_id is not null
        union select case_id from public.surveillance_observations where person_id = p_id and case_id is not null
      ) s where c is not null;
      select count(*) into v_legal from public.legal_requests where person_id = p_id;
      select count(*) into v_evidence from public.legal_seized_items where person_id = p_id;
      select count(*) into v_media from public.media where person_id = p_id;
      select count(*) into v_watch from public.siu_watchlist where person_id = p_id;
      select count(*) into v_reports from public.narcotic_persons
        where person_id = p_id and source_report_id is not null;
      select count(*) into v_edges from (
        select 1 from public.person_relationships where person_a = p_id or person_b = p_id
        union all select 1 from public.gang_members    where person_id = p_id
        union all select 1 from public.person_places   where person_id = p_id
        union all select 1 from public.person_vehicles where person_id = p_id
        union all select 1 from public.account_links   where person_id = p_id) e;
      select count(distinct x) into v_persons from (
        select case when person_a = p_id then person_b else person_a end as x
          from public.person_relationships where person_a = p_id or person_b = p_id) t;
      select count(distinct gang_id) into v_gangs    from public.gang_members    where person_id = p_id;
      select count(distinct vehicle_id) into v_vehicles from public.person_vehicles where person_id = p_id;
      select count(distinct place_id) into v_places  from public.person_places   where person_id = p_id;

    when 'gang' then
      select g.name, g.created_by, g.created_at into v_name, v_created_by, v_created_at
        from public.gangs g where g.id = p_id;
      select coalesce(array_agg(distinct case_id), '{}') into v_cases
        from public.media where gang_id = p_id and case_id is not null;
      select count(*) into v_media from public.media where gang_id = p_id;
      select count(*) into v_watch from public.siu_watchlist where gang_id = p_id;
      select count(*) into v_edges from (
        select 1 from public.gang_members where gang_id = p_id
        union all select 1 from public.gang_places where gang_id = p_id
        union all select 1 from public.gang_ranks  where gang_id = p_id
        union all select 1 from public.gang_turf   where gang_id = p_id
        union all select 1 from public.persons     where gang_id = p_id
        union all select 1 from public.vehicles    where gang_id = p_id) e;
      select count(distinct person_id) into v_persons from public.gang_members where gang_id = p_id;
      select count(distinct place_id)  into v_places  from public.gang_places  where gang_id = p_id;
      select count(*) into v_vehicles from public.vehicles where gang_id = p_id;

    when 'vehicle' then
      select v.plate, v.created_by, v.created_at into v_name, v_created_by, v_created_at
        from public.vehicles v where v.id = p_id;
      select coalesce(array_agg(distinct case_id), '{}') into v_cases
        from public.media where vehicle_id = p_id and case_id is not null;
      select count(*) into v_media from public.media where vehicle_id = p_id;
      select count(*) into v_watch from public.siu_watchlist where vehicle_id = p_id;
      select count(*) into v_evidence from public.legal_seized_items where vehicle_id = p_id;
      select count(*) into v_edges from (
        select 1 from public.person_vehicles where vehicle_id = p_id
        union all select 1 from public.narcotic_vehicles where vehicle_id = p_id) e;
      select count(distinct person_id) into v_persons from public.person_vehicles where vehicle_id = p_id;

    when 'place' then
      select pl.name, pl.created_by, pl.created_at into v_name, v_created_by, v_created_at
        from public.places pl where pl.id = p_id;
      select coalesce(array_agg(distinct case_id), '{}') into v_cases from (
        select case_id from public.media where place_id = p_id and case_id is not null
        union select case_id from public.surveillance_observations
          where place_id = p_id and case_id is not null) s where case_id is not null;
      select count(*) into v_media from public.media where place_id = p_id;
      select count(*) into v_watch from public.siu_watchlist where place_id = p_id;
      select count(*) into v_edges from (
        select 1 from public.gang_places where place_id = p_id
        union all select 1 from public.person_places where place_id = p_id
        union all select 1 from public.place_process_steps where place_id = p_id
        union all select 1 from public.narcotic_hotspots where place_id = p_id) e;
      select count(distinct person_id) into v_persons from public.person_places where place_id = p_id;
      select count(distinct gang_id)   into v_gangs   from public.gang_places  where place_id = p_id;

    when 'account' then
      select a.handle, a.created_by, a.created_at into v_name, v_created_by, v_created_at
        from public.accounts a where a.id = p_id;
      select count(*) into v_edges from public.account_links where account_id = p_id;
      select count(distinct person_id) into v_persons from public.account_links where account_id = p_id;

    when 'indicator' then
      select i.value, i.created_by, i.created_at into v_name, v_created_by, v_created_at
        from public.indicators i where i.id = p_id;
      select coalesce(array_agg(distinct case_id), '{}') into v_cases
        from public.indicators where id = p_id and case_id is not null;

    else raise exception 'that is not a compartmentable record type';
  end case;

  if v_created_at is null then
    raise exception 'no such record';
  end if;

  select * into v_vis from public.siu_visibility
   where entity_type = p_type and entity_id = p_id;

  v_cid := private.siu_cid_attached(p_type, p_id);

  return jsonb_build_object(
    'entity_type', p_type,
    'entity_id', p_id,
    'name', v_name,
    'created_by', v_created_by,
    'created_by_name', (select display_name from public.profiles where id = v_created_by),
    'created_at', v_created_at,
    'current_state', coalesce(v_vis.state, 'cid'),
    'current_scope', coalesce(v_vis.scope, 'record'),
    'current_hidden_sections', coalesce(v_vis.hidden_sections, '{}'),
    'cid_authored', v_cid,
    'recommended_mode', case when v_cid then 'sections' else 'record' end,
    'cases', coalesce(array_length(v_cases, 1), 0),
    'case_ids', to_jsonb(v_cases),
    'reports', v_reports, 'evidence', v_evidence, 'legal_requests', v_legal,
    'tasks', v_tasks, 'media', v_media, 'watchlists', v_watch,
    'relationships', v_edges,
    'linked_persons', v_persons, 'linked_gangs', v_gangs,
    'linked_vehicles', v_vehicles, 'linked_places', v_places);
end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_reveal_to_cid(p_type text, p_id uuid, p_reason text, p_sections text[] DEFAULT NULL::text[], p_to_case_id uuid DEFAULT NULL::uuid, p_to_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_standing text; v_row public.siu_visibility; v_to text; v_action text;
  v_secs text[]; v_from_aud int; v_to_aud int;
  v_wider boolean; v_narrower boolean;
begin
  v_standing := private.siu_standing();
  if not private.siu_may_control_visibility() then
    raise exception 'only SIB may release a compartmented record';
  end if;
  if coalesce(length(btrim(p_reason)), 0) < 10 then
    raise exception 'record why this is being released, in a sentence';
  end if;
  if p_to_case_id is not null and p_to_user_id is not null then
    raise exception 'release to a case or to a person, not both';
  end if;

  select * into v_row from public.siu_visibility
   where entity_type = p_type and entity_id = p_id;
  if v_row.entity_id is null then
    raise exception 'that record is not compartmented, so there is nothing to release';
  end if;

  v_to := case when coalesce(array_length(p_sections, 1), 0) > 0
               then 'partial' else 'revealed' end;
  v_secs := case when v_to = 'partial' then p_sections else '{}'::text[] end;

  if v_row.state in ('siu_only', 'unclassified') then
    v_action := 'revealed';
  else
    v_from_aud := private.siu_audience_rank(v_row.revealed_to_case_id, v_row.revealed_to_user_id);
    v_to_aud   := private.siu_audience_rank(p_to_case_id, p_to_user_id);

    v_wider := v_to_aud > v_from_aud
            or (v_row.state = 'partial' and v_to = 'revealed')
            or (v_row.state = 'partial' and v_to = 'partial'
                and not (v_secs <@ v_row.revealed_sections));
    v_narrower := v_to_aud < v_from_aud
               or (v_row.state = 'revealed' and v_to = 'partial')
               or (v_row.state = 'partial' and v_to = 'partial'
                   and not (v_row.revealed_sections <@ v_secs));

    v_action := case
      when v_wider and not v_narrower then 'expanded'
      when v_narrower and not v_wider then 'reduced'
      when v_wider and v_narrower then 'redirected'
      else 'redirected' end;
  end if;

  update public.siu_visibility
     set state = v_to,
         revealed_sections = v_secs,
         revealed_to_case_id = p_to_case_id,
         revealed_to_user_id = p_to_user_id,
         revealed_at = now(), revealed_by = (select auth.uid()),
         reveal_reason = btrim(p_reason),
         needs_review = false, review_note = null,
         updated_at = now()
   where entity_type = p_type and entity_id = p_id;

  insert into public.siu_visibility_events
    (entity_type, entity_id, action, from_state, to_state, sections,
     to_case_id, to_user_id, actor_id, actor_standing, reason)
  values (p_type, p_id, v_action, v_row.state, v_to, v_secs,
          p_to_case_id, p_to_user_id, (select auth.uid()), v_standing, btrim(p_reason));
end
$function$
;

CREATE OR REPLACE FUNCTION public.siu_review_note(p_note uuid, p_outcome text, p_note_text text, p_next_review timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_note record; v_case uuid;
begin
  select * into v_note from public.siu_case_notes where id = p_note for update;
  if not found then raise exception 'note not found'; end if;
  v_case := v_note.case_id;
  if not (private.siu_is_agent() and private.siu_can_read_case_note(v_case)) then
    raise exception 'not authorized';
  end if;
  if p_outcome not in ('revalidated','downgraded','superseded','withdrawn') then
    raise exception 'unknown review outcome';
  end if;
  if coalesce(btrim(p_note_text), '') = '' then
    raise exception 'a review note is required';
  end if;
  if p_next_review is not null and p_next_review <= now() then
    raise exception 'a review date must be in the future';
  end if;

  update public.siu_case_notes
     set last_reviewed_at = now(), last_reviewed_by = v_actor, review_outcome = p_outcome,
         review_due_at = case
           when p_outcome = 'withdrawn' then null
           else coalesce(p_next_review, now() + interval '90 days') end,
         resolved_at = case when p_outcome = 'withdrawn' then now() else resolved_at end,
         resolved_by = case when p_outcome = 'withdrawn' then v_actor else resolved_by end,
         resolution = case when p_outcome = 'withdrawn'
                           then btrim(p_note_text) else resolution end
   where id = p_note;

  perform private.siu_audit('SIU_INTEL_REVIEWED', p_note, jsonb_build_object(
    'case', v_case, 'outcome', p_outcome, 'note', btrim(p_note_text),
    'reviewed_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_review_referral(p_referral uuid, p_disposition text, p_note text, p_open_as text DEFAULT 'preliminary_inquiry'::text, p_classification text DEFAULT 'siu_restricted'::text, p_category text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_ref record;
  v_case uuid;
  v_number text;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if p_disposition not in ('under_review','accepted','declined','referred_to_cid',
                           'info_requested','withdrawn') then
    raise exception 'unknown disposition';
  end if;
  if coalesce(btrim(p_note), '') = '' then raise exception 'a review note is required'; end if;

  select * into v_ref from public.siu_referrals where id = p_referral for update;
  if not found then raise exception 'referral not found'; end if;
  if v_ref.opened_case_id is not null then
    raise exception 'this referral has already been actioned';
  end if;

  if p_disposition = 'accepted' then
    if p_open_as not in ('preliminary_inquiry','investigation') then
      raise exception 'unknown opening stage';
    end if;
    if p_classification not in ('siu','siu_restricted','siu_command','siu_compartmented') then
      raise exception 'unknown SIB classification';
    end if;

    v_number := public.next_siu_case_number();
    insert into public.cases (case_number, title, summary, bureau, status,
                              lead_detective_id, created_by, case_authority,
                              siu_classification, siu_stage, siu_category)
    values (v_number,
            left(v_ref.summary, 200),
            v_ref.detail,
            'special_investigations', 'open', v_actor, v_actor, 'siu',
            p_classification, p_open_as, p_category)
    returning id into v_case;

    insert into public.siu_case_agents (case_id, user_id, agent_role, assigned_by)
    values (v_case, v_actor, 'lead', v_actor);

    if p_classification = 'siu_compartmented' then
      insert into public.siu_compartment_members (case_id, user_id, granted_by, reason)
      values (v_case, v_actor, v_actor, 'Opened from referral');
    end if;
  end if;

  update public.siu_referrals
     set status = p_disposition, review_note = btrim(p_note),
         reviewed_by = v_actor, reviewed_at = now(),
         opened_case_id = coalesce(v_case, opened_case_id)
   where id = p_referral;

  perform private.siu_audit('SIU_REFERRAL_REVIEWED', p_referral, jsonb_build_object(
    'disposition', p_disposition, 'note', btrim(p_note),
    'opened_case', v_case, 'opened_as', case when v_case is not null then p_open_as end,
    'classification', case when v_case is not null then p_classification end,
    'reviewed_by', v_actor));
  return v_case;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_revoke_disclosure(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_row record;
begin
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  select d.id, d.siu_case_id, d.released_by, d.revoked_at, d.item_type, d.audience
    into v_row from public.siu_disclosures d where d.id = p_id for update;
  if not found then raise exception 'release not found'; end if;
  if not private.siu_case_access(v_row.siu_case_id) then raise exception 'release not found'; end if;
  if v_row.revoked_at is not null then raise exception 'this release was already revoked'; end if;
  if not (v_row.released_by = v_actor or private.siu_case_command(v_row.siu_case_id)) then
    raise exception 'not authorized';
  end if;

  update public.siu_disclosures
     set revoked_at = now(), revoked_by = v_actor, revoke_reason = btrim(p_reason)
   where id = p_id;

  perform private.siu_audit('SIU_INTEL_REVOKED', v_row.siu_case_id, jsonb_build_object(
    'disclosure_id', p_id, 'item_type', v_row.item_type, 'audience', v_row.audience,
    'reason', btrim(p_reason), 'revoked_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_revoke_temp_access(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_t record;
begin
  select * into v_t from public.siu_temporary_access where id = p_id for update;
  if not found then raise exception 'grant not found'; end if;
  if not (v_t.user_id = v_actor or private.siu_case_command(v_t.case_id)) then
    raise exception 'not authorized';
  end if;
  if v_t.revoked_at is not null then raise exception 'this grant is already revoked'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;

  update public.siu_temporary_access
     set revoked_at = now(), revoked_by = v_actor, revoke_reason = btrim(p_reason)
   where id = p_id;

  perform private.siu_audit('SIU_TEMP_ACCESS_REVOKED', v_t.case_id, jsonb_build_object(
    'grant_id', p_id, 'officer', v_t.user_id, 'reason', btrim(p_reason),
    'revoked_by', v_actor, 'self_returned', v_t.user_id = v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_roster()
 RETURNS TABLE(user_id uuid, display_name text, badge_number text, siu_role text, callsign text, oversight_only boolean, active boolean, appointed_by uuid, appointed_by_name text, appointed_at timestamp with time zone, ended_at timestamp with time zone, end_reason text, former_cid_role text, former_cid_bureau text, last_activity timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select m.user_id, p.display_name, p.badge_number, m.siu_role, m.callsign,
         m.oversight_only, m.active, m.appointed_by, ap.display_name,
         m.appointed_at, m.ended_at, m.end_reason,
         p.role::text, p.division::text,
         (select max(a.created_at) from public.audit_log a where a.actor_id = m.user_id)
    from public.siu_memberships m
    join public.profiles p on p.id = m.user_id
    left join public.profiles ap on ap.id = m.appointed_by
   where private.siu_operates()
   order by m.active desc, m.siu_role, m.callsign nulls last, p.display_name
$function$
;

CREATE OR REPLACE FUNCTION public.siu_set_callsign(p_user uuid, p_callsign text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_call text := nullif(btrim(coalesce(p_callsign, '')), '');
  v_old text;
begin
  if not private.siu_can_appoint() then raise exception 'not authorized'; end if;
  select callsign into v_old from public.siu_memberships where user_id = p_user and active;
  if not found then raise exception 'not an active SIB member'; end if;
  update public.siu_memberships set callsign = v_call, updated_at = now() where user_id = p_user;
  perform private.siu_audit('SIU_CALLSIGN_CHANGED', p_user,
    jsonb_build_object('from', v_old, 'to', v_call));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_set_case_category(p_case uuid, p_category text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.siu_case_command(p_case) then raise exception 'not authorized'; end if;
  if p_category is not null and p_category not in
     ('public_corruption','law_enforcement_integrity','organized_crime','gang','narcotics',
      'firearms','fugitive','major_crime','internal_leak','other') then
    raise exception 'unknown SIB case category';
  end if;
  update public.cases set siu_category = p_category where id = p_case;
  perform private.siu_audit('SIU_CATEGORY_SET', p_case,
    jsonb_build_object('category', p_category, 'actor', (select auth.uid())));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_set_case_classification(p_case uuid, p_classification text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old text; v_actor uuid := (select auth.uid());
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.siu_case_command(p_case) then raise exception 'not authorized'; end if;
  if p_classification not in ('siu', 'siu_restricted', 'siu_command', 'siu_compartmented') then
    raise exception 'unknown SIB classification';
  end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;

  select siu_classification into v_old from public.cases where id = p_case;
  if v_old = p_classification then raise exception 'already at that classification'; end if;

  update public.cases set siu_classification = p_classification where id = p_case;

  if p_classification = 'siu_compartmented' then
    insert into public.siu_compartment_members (case_id, user_id, granted_by, reason)
    select p_case, u.uid, v_actor, 'Seeded on compartmentation'
      from (select v_actor as uid
            union
            select a.user_id from public.siu_case_agents a
             where a.case_id = p_case and a.removed_at is null) u
    on conflict do nothing;
  end if;

  perform private.siu_audit('SIU_CLASSIFICATION_CHANGED', p_case,
    jsonb_build_object('from', v_old, 'to', p_classification, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_set_release(p_enabled boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_owner() then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  update public.siu_settings
     set enabled_for_non_owner = coalesce(p_enabled, false),
         updated_at = now(), updated_by = (select auth.uid())
   where id;
  perform private.siu_audit('SIU_RELEASE_SET', null,
    jsonb_build_object('enabled', coalesce(p_enabled, false), 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_share(p_case uuid, p_item_type text, p_title text, p_body text, p_audience text, p_reason text, p_target_case uuid DEFAULT NULL::uuid, p_target_user uuid DEFAULT NULL::uuid, p_source_item uuid DEFAULT NULL::uuid, p_handling text DEFAULT 'law_enforcement_sensitive'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_id uuid;
  v_target record;
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not (private.siu_case_access(p_case) and private.siu_is_agent()) then
    raise exception 'not authorized';
  end if;
  if p_item_type not in ('intelligence', 'report', 'evidence', 'media', 'target', 'summary', 'warning') then
    raise exception 'unknown release item type';
  end if;
  if p_audience not in ('cid', 'case_members', 'investigator') then
    raise exception 'unknown release audience';
  end if;
  if p_handling not in ('official_use', 'law_enforcement_sensitive', 'court_disclosable') then
    raise exception 'unknown handling caveat';
  end if;
  if coalesce(btrim(p_title), '') = '' then raise exception 'a title is required'; end if;
  if coalesce(btrim(p_body), '') = '' then raise exception 'released content cannot be empty'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;

  if p_audience = 'case_members' then
    if p_target_case is null then raise exception 'a target case is required to share with case members'; end if;
  end if;
  if p_target_case is not null then
    if not exists (select 1 from public.cases c where c.id = p_target_case) then
      raise exception 'target case not found';
    end if;
    if private.is_siu_case(p_target_case) then
      raise exception 'releases are addressed to CID; an SIB investigation is not a release target';
    end if;
  end if;
  if p_audience = 'investigator' then
    if p_target_user is null then raise exception 'a target investigator is required'; end if;
    select p.active, coalesce(p.is_system, false) as is_system, p.removed_at
      into v_target from public.profiles p where p.id = p_target_user;
    if not found then raise exception 'target investigator not found'; end if;
    if v_target.is_system or v_target.removed_at is not null or not v_target.active then
      raise exception 'releases can only be addressed to an active member';
    end if;
  end if;

  insert into public.siu_disclosures (
    siu_case_id, source_item_id, item_type, audience, target_case_id, target_user_id,
    title, body, handling, reason, released_by)
  values (
    p_case, p_source_item, p_item_type, p_audience,
    p_target_case,
    case when p_audience = 'investigator' then p_target_user end,
    btrim(p_title), btrim(p_body), p_handling, btrim(p_reason), v_actor)
  returning id into v_id;

  perform private.siu_audit('SIU_INTEL_RELEASED', p_case, jsonb_build_object(
    'disclosure_id', v_id,
    'item_type',     p_item_type,
    'audience',      p_audience,
    'target_case',   p_target_case,
    'target_user',   case when p_audience = 'investigator' then p_target_user end,
    'handling',      p_handling,
    'title',         btrim(p_title),
    'reason',        btrim(p_reason),
    'released_by',   v_actor));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_submit_referral(p_category text, p_summary text, p_detail text DEFAULT NULL::text, p_subject_user uuid DEFAULT NULL::uuid, p_subject_description text DEFAULT NULL::text, p_related_case uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_id uuid;
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if p_category not in ('corruption','misconduct','organized_crime','narcotics_trafficking',
                        'firearms_trafficking','criminal_conspiracy','fugitive','internal_leak',
                        'compromised_investigation','other') then
    raise exception 'unknown referral category';
  end if;
  if coalesce(btrim(p_summary), '') = '' then raise exception 'a summary is required'; end if;
  if p_subject_user is not null
     and not exists (select 1 from public.profiles p where p.id = p_subject_user) then
    raise exception 'subject not found';
  end if;

  insert into public.siu_referrals (category, summary, detail, subject_user_id,
                                    subject_description, related_case_id, submitted_by)
  values (p_category, btrim(p_summary), nullif(btrim(coalesce(p_detail,'')), ''),
          p_subject_user, nullif(btrim(coalesce(p_subject_description,'')), ''),
          p_related_case, v_actor)
  returning id into v_id;

  perform private.siu_audit('SIU_REFERRAL_SUBMITTED', v_id, jsonb_build_object(
    'category', p_category, 'has_named_subject', p_subject_user is not null,
    'related_case', p_related_case, 'submitted_by', v_actor));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_targets_live()
 RETURNS TABLE(id uuid, case_id uuid, case_number text, case_title text, entity_type text, entity_id uuid, display_name text, secondary text, designation text, priority text, role_in_network text, notes text, created_at timestamp with time zone, created_by uuid, cleared_at timestamp with time zone, cleared_by uuid, clearance_reason text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    t.id, t.case_id, c.case_number, c.title,
    t.entity_type,
    coalesce(t.person_id, t.vehicle_id, t.gang_id, t.place_id,
             t.account_id, t.indicator_id, t.entity_id) as entity_id,
    coalesce(p.name, v.plate, g.name, pl.name, a.handle, i.value, t.label,
             'Unidentified subject') as display_name,
    coalesce(p.alias, nullif(concat_ws(' ', v.color, v.model), ''), g.classification,
             pl.area, a.platform, i.kind) as secondary,
    t.designation, t.priority, t.role_in_network, t.notes,
    t.created_at, t.created_by, t.cleared_at, t.cleared_by, t.clearance_reason
  from public.siu_targets t
  left join public.cases      c  on c.id  = t.case_id
  left join public.persons    p  on p.id  = t.person_id
  left join public.vehicles   v  on v.id  = t.vehicle_id
  left join public.gangs      g  on g.id  = t.gang_id
  left join public.places     pl on pl.id = t.place_id
  left join public.accounts   a  on a.id  = t.account_id
  left join public.indicators i  on i.id  = t.indicator_id
  order by
    (t.cleared_at is not null),
    case t.priority when 'critical' then 0 when 'high' then 1
                    when 'medium' then 2 else 3 end,
    t.created_at desc
$function$
;

CREATE OR REPLACE FUNCTION public.siu_unassign_agent(p_case uuid, p_user uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid());
begin
  if not private.is_siu_case(p_case) then raise exception 'not an SIB investigation'; end if;
  if not private.siu_case_command(p_case) then raise exception 'not authorized'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;

  update public.siu_case_agents
     set removed_at = now(), removed_by = v_actor
   where case_id = p_case and user_id = p_user and removed_at is null;
  if not found then raise exception 'not assigned to this investigation'; end if;

  perform private.siu_audit('SIU_AGENT_UNASSIGNED', p_case,
    jsonb_build_object('user_id', p_user, 'reason', btrim(p_reason)));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_watch_add(p_entity_type text, p_entity_id uuid, p_reason text, p_priority text DEFAULT 'routine'::text, p_days integer DEFAULT 90, p_review_days integer DEFAULT 30, p_case uuid DEFAULT NULL::uuid, p_classification text DEFAULT NULL::text, p_source text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_id uuid; v_exists boolean; v_live uuid;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if p_entity_type not in ('person','vehicle','gang','place','account','indicator','unknown') then
    raise exception 'unknown entity type';
  end if;
  if p_priority not in ('routine','priority','high_priority','critical') then
    raise exception 'unknown priority';
  end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  if p_days is null or p_days < 1 or p_days > 365 then
    raise exception 'a watch runs for between 1 and 365 days';
  end if;
  if p_review_days is null or p_review_days < 1 or p_review_days > p_days then
    raise exception 'the review must fall within the life of the watch';
  end if;
  if p_classification is not null
     and p_classification not in ('siu','siu_restricted','siu_command','siu_compartmented') then
    raise exception 'unknown classification';
  end if;
  if p_case is not null and not private.siu_case_access(p_case) then
    raise exception 'not authorized for that investigation';
  end if;

  if p_entity_type = 'unknown' then
    if coalesce(btrim(coalesce(p_label, '')), '') = '' then
      raise exception 'describe what is being watched';
    end if;
  else
    if p_entity_id is null then raise exception 'choose a record from the registry'; end if;
    execute format('select exists (select 1 from public.%I where id = $1)',
                   case p_entity_type
                     when 'person' then 'persons' when 'vehicle' then 'vehicles'
                     when 'gang' then 'gangs' when 'place' then 'places'
                     when 'account' then 'accounts' else 'indicators' end)
      into v_exists using p_entity_id;
    if not v_exists then raise exception 'that record is not in the registry'; end if;

    execute format('select id from public.siu_watchlist
                     where %I = $1 and status in (''active'',''monitor'',''review_due'',''suspended'')
                     limit 1', p_entity_type || '_id')
      into v_live using p_entity_id;
    if v_live is not null then
      raise exception 'already on the watchlist (entry %)', v_live;
    end if;
  end if;

  insert into public.siu_watchlist (
    entity_type, entity_id, label, reason, case_id, priority,
    expires_at, review_due_at, created_by, assigned_agent,
    classification, source, notes,
    person_id, vehicle_id, gang_id, place_id, account_id, indicator_id)
  values (
    p_entity_type, p_entity_id,
    nullif(btrim(coalesce(p_label, '')), ''), btrim(p_reason), p_case, p_priority,
    now() + make_interval(days => p_days), now() + make_interval(days => p_review_days),
    v_actor, v_actor,
    p_classification, nullif(btrim(coalesce(p_source, '')), ''),
    nullif(btrim(coalesce(p_notes, '')), ''),
    case when p_entity_type = 'person'    then p_entity_id end,
    case when p_entity_type = 'vehicle'   then p_entity_id end,
    case when p_entity_type = 'gang'      then p_entity_id end,
    case when p_entity_type = 'place'     then p_entity_id end,
    case when p_entity_type = 'account'   then p_entity_id end,
    case when p_entity_type = 'indicator' then p_entity_id end)
  returning id into v_id;

  perform private.siu_audit('SIU_WATCH_ADDED', v_id, jsonb_build_object(
    'entity_type', p_entity_type, 'entity_id', p_entity_id,
    'reason', btrim(p_reason), 'priority', p_priority,
    'days', p_days, 'review_days', p_review_days, 'case', p_case,
    'classification', p_classification, 'added_by', v_actor));
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_watch_extend(p_id uuid, p_days integer, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_w record;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  select * into v_w from public.siu_watchlist where id = p_id for update;
  if not found then raise exception 'watch entry not found'; end if;
  if v_w.status not in ('active', 'monitor', 'review_due', 'suspended') then
    raise exception 'this watch has already been closed';
  end if;
  if p_days is null or p_days < 1 or p_days > 365 then
    raise exception 'a watch runs for between 1 and 365 days';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'a reason is required to extend a watch';
  end if;

  update public.siu_watchlist
     set expires_at = greatest(expires_at, now()) + make_interval(days => p_days),
         review_due_at = now() + make_interval(days => greatest(p_days / 2, 1))
   where id = p_id;

  perform private.siu_audit('SIU_WATCH_EXTENDED', p_id, jsonb_build_object(
    'entity_type', v_w.entity_type, 'entity_id', v_w.entity_id,
    'days', p_days, 'reason', btrim(p_reason),
    'previous_expiry', v_w.expires_at, 'extended_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_watch_remove(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_w record;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  select * into v_w from public.siu_watchlist where id = p_id for update;
  if not found then raise exception 'watch entry not found'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;

  update public.siu_watchlist
     set status = 'cleared', review_due_at = null, removed_at = now(),
         removed_by = v_actor, removal_reason = btrim(p_reason)
   where id = p_id;

  perform private.siu_audit('SIU_WATCH_REMOVED', p_id, jsonb_build_object(
    'entity_type', v_w.entity_type, 'entity_id', v_w.entity_id,
    'reason', btrim(p_reason), 'removed_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_watch_review(p_id uuid, p_outcome text, p_note text, p_priority text DEFAULT NULL::text, p_review_days integer DEFAULT 30, p_extend_days integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_w record;
begin
  if not private.siu_is_agent() then raise exception 'not authorized'; end if;
  if p_outcome not in ('continue','monitor','suspend','clear','archive') then
    raise exception 'unknown review outcome';
  end if;
  if coalesce(btrim(p_note), '') = '' then
    raise exception 'a review note is required - it is the record that somebody looked';
  end if;
  select * into v_w from public.siu_watchlist where id = p_id for update;
  if not found then raise exception 'watch entry not found'; end if;
  if v_w.status in ('cleared','archived') then
    raise exception 'this watch has already been closed';
  end if;
  if p_priority is not null
     and p_priority not in ('routine','priority','high_priority','critical') then
    raise exception 'unknown priority';
  end if;
  if p_extend_days is not null and (p_extend_days < 1 or p_extend_days > 365) then
    raise exception 'a watch runs for between 1 and 365 days';
  end if;

  update public.siu_watchlist
     set status = case p_outcome
                    when 'continue' then 'active' when 'monitor' then 'monitor'
                    when 'suspend' then 'suspended' when 'clear' then 'cleared'
                    else 'archived' end,
         priority = coalesce(p_priority, priority),
         expires_at = case when p_extend_days is not null
                           then greatest(expires_at, now()) + make_interval(days => p_extend_days)
                           else expires_at end,
         review_due_at = case when p_outcome in ('clear','archive') then null
                              else now() + make_interval(days => coalesce(p_review_days, 30)) end,
         removed_at = case when p_outcome in ('clear','archive') then now() else removed_at end,
         removed_by = case when p_outcome in ('clear','archive') then v_actor else removed_by end,
         removal_reason = case when p_outcome in ('clear','archive')
                               then btrim(p_note) else removal_reason end
   where id = p_id;

  perform private.siu_audit('SIU_WATCH_REVIEWED', p_id, jsonb_build_object(
    'outcome', p_outcome, 'note', btrim(p_note), 'priority', p_priority,
    'extended_days', p_extend_days, 'reviewed_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.siu_watchlist_live()
 RETURNS TABLE(id uuid, entity_type text, entity_id uuid, display_name text, secondary text, reason text, priority text, status text, classification text, source text, notes text, case_id uuid, case_number text, assigned_agent uuid, assigned_agent_name text, expires_at timestamp with time zone, review_due_at timestamp with time zone, created_at timestamp with time zone, created_by uuid, removed_at timestamp with time zone, removal_reason text, review_overdue boolean, days_left integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    w.id, w.entity_type,
    coalesce(w.person_id, w.vehicle_id, w.gang_id, w.place_id,
             w.account_id, w.indicator_id) as entity_id,
    coalesce(p.name, v.plate, g.name, pl.name, a.handle, i.value, w.label,
             'Unidentified subject') as display_name,
    coalesce(p.alias, nullif(concat_ws(' ', v.color, v.model), ''), g.classification,
             pl.area, a.platform, i.kind) as secondary,
    w.reason, w.priority, w.status, w.classification, w.source, w.notes,
    w.case_id, c.case_number, w.assigned_agent, ag.display_name,
    w.expires_at, w.review_due_at, w.created_at, w.created_by,
    w.removed_at, w.removal_reason,
    (w.review_due_at is not null and w.review_due_at <= now()
       and w.status in ('active','monitor','review_due','suspended')) as review_overdue,
    greatest(0, extract(day from (w.expires_at - now()))::int) as days_left
  from public.siu_watchlist w
  left join public.persons    p  on p.id  = w.person_id
  left join public.vehicles   v  on v.id  = w.vehicle_id
  left join public.gangs      g  on g.id  = w.gang_id
  left join public.places     pl on pl.id = w.place_id
  left join public.accounts   a  on a.id  = w.account_id
  left join public.indicators i  on i.id  = w.indicator_id
  left join public.cases      c  on c.id  = w.case_id
  left join public.profiles   ag on ag.id = w.assigned_agent
  order by
    case w.status when 'review_due' then 0 when 'active' then 1 when 'monitor' then 2
                  when 'suspended' then 3 else 4 end,
    case w.priority when 'critical' then 0 when 'high_priority' then 1
                    when 'priority' then 2 else 3 end,
    w.review_due_at nulls last, w.created_at desc
$function$
;

CREATE OR REPLACE FUNCTION public.siu_withdraw_access_request(p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_r record;
begin
  select * into v_r from public.siu_access_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if v_r.requested_by <> v_actor then raise exception 'not authorized'; end if;
  if v_r.status <> 'pending' then raise exception 'this request has already been decided'; end if;
  update public.siu_access_requests set status = 'withdrawn' where id = p_request;
  perform private.siu_audit('SIU_ACCESS_WITHDRAWN', p_request, jsonb_build_object(
    'case_number', v_r.case_number_requested, 'requested_by', v_actor));
end $function$
;

CREATE OR REPLACE FUNCTION public.stamp_author_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid());
begin
  if v_uid is not null then
    new.author_id := v_uid;
    new.author_name := coalesce(
      (select display_name from public.profiles where id = v_uid),
      new.author_name
    );
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.submit_document_suggestion(p_document uuid, p_type text, p_title text, p_explanation text, p_section_id text DEFAULT NULL::text, p_section_title text DEFAULT NULL::text, p_proposed_text text DEFAULT NULL::text, p_related_case uuid DEFAULT NULL::uuid, p_source_url text DEFAULT NULL::text)
 RETURNS document_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.documents; s public.document_suggestions; v_uid uuid := (select auth.uid());
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if p_type not in ('unclear','outdated','incorrect','missing_procedure','new_section',
                    'legal_concern','broken_link','formatting','new_document','other') then
    raise exception 'invalid suggestion type';
  end if;
  if btrim(coalesce(p_title, '')) = '' then raise exception 'a title is required'; end if;
  if btrim(coalesce(p_explanation, '')) = '' then raise exception 'an explanation is required'; end if;

  if p_document is not null then
    select * into d from public.documents where id = p_document;
    if not found then raise exception 'document not found'; end if;
    if not private.can_view_document(d.classification, d.owner_user_id) then
      raise exception 'document not found';
    end if;
  end if;

  insert into public.document_suggestions
    (document_id, document_version_number, section_id, section_title, source_url,
     related_case_id, suggestion_type, title, explanation, proposed_text,
     status, created_by)
  values (p_document,
          case when p_document is not null then d.current_version_number else null end,
          nullif(btrim(p_section_id), ''), nullif(btrim(p_section_title), ''),
          nullif(btrim(p_source_url), ''), p_related_case, p_type,
          btrim(p_title), btrim(p_explanation), nullif(btrim(p_proposed_text), ''),
          'submitted', v_uid)
  returning * into s;

  insert into public.document_suggestion_events (suggestion_id, event_type, to_status, actor_id)
  values (s.id, 'submitted', 'submitted', v_uid);

  if p_document is not null then
    insert into public.notifications (user_id, type, payload)
    select m.user_id, 'document_suggestion', jsonb_build_object(
        'suggestion_id', s.id, 'document_id', p_document, 'title', s.title,
        'status', 'submitted', 'suggestion_type', p_type, 'actor_id', v_uid,
        'reason', 'New suggestion: ' || s.title)
      from private.document_suggestion_managers(p_document) m
     where m.user_id <> v_uid;
  else
    insert into public.notifications (user_id, type, payload)
    select p.id, 'document_suggestion', jsonb_build_object(
        'suggestion_id', s.id, 'document_id', null, 'title', s.title,
        'status', 'submitted', 'suggestion_type', p_type, 'actor_id', v_uid,
        'reason', 'New document proposal: ' || s.title)
      from public.profiles p
     where p.active and p.removed_at is null and p.id <> v_uid
       and (p.is_owner or p.role in ('deputy_director', 'director'));
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'DOCUMENT_SUGGESTION_SUBMITTED', 'document_suggestions', s.id,
          jsonb_build_object('document_id', p_document, 'type', p_type));
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.submit_legal_request_to_cid(p_request uuid, p_change_summary text DEFAULT NULL::text, p_material_change boolean DEFAULT false)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_ver uuid; sup record;
        v_fast boolean; v_from text; v_n int := 0; v_siu boolean; c public.cases;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.created_by <> v_uid then raise exception 'only the requesting investigator may submit'; end if;
  if not private.can_edit_legal_draft(p_request, v_uid) then
    raise exception 'this request is not in an editable state';
  end if;
  if btrim(coalesce(r.title, '')) = '' or btrim(coalesce(r.narrative, '')) = '' then
    raise exception 'a title and a description/justification are required';
  end if;
  if r.request_type = 'warrant' then
    if r.priority is null then raise exception 'a warrant requires a priority'; end if;
    if r.subtype = 'arrest_warrant' and r.person_id is null then
      raise exception 'an arrest warrant requires a linked suspect';
    end if;
    if r.subtype = 'search_warrant'
       and r.person_id is null
       and nullif(btrim(coalesce(r.form_data->>'search_targets', '')), '') is null then
      raise exception 'a search warrant requires a subject or at least one search target';
    end if;
  end if;
  if r.request_type = 'subpoena' and r.recipient_type = 'entity'
     and btrim(coalesce(r.recipient_name, '')) = '' then
    raise exception 'a recipient is required';
  end if;

  v_siu := private.legal_is_siu(p_request);
  select * into c from public.cases where id = r.case_id;
  v_from := r.review_status;
  v_fast := (not v_siu)
            and v_from in ('returned_by_judge', 'returned_by_prosecutor')
            and not coalesce(p_material_change, false);

  if r.review_status like 'returned_by_%' and r.assigned_judge_id is not null then
    update public.legal_request_participants
       set removed_at = now(), removed_by = v_uid
     where legal_request_id = p_request and participant_role = 'judicial_reviewer'
       and user_id = r.assigned_judge_id and removed_at is null;
    update public.legal_requests set assigned_judge_id = null where id = p_request;
  end if;

  update public.legal_requests
     set responsible_bureau = private.legal_resolve_bureau(r.case_id)
   where id = p_request;

  if v_fast then
    v_ver := private.legal_freeze_version(p_request, 'prosecutor_queue', p_change_summary);
    update public.legal_requests
       set document_status = 'finalized', review_status = 'prosecutor_queue',
           queue_entered_at = now(),
           assigned_prosecutor_id = null, prosecutor_claimed_at = null,
           submitted_to_cid_at = coalesce(submitted_to_cid_at, now())
     where id = p_request returning * into r;
    perform private.legal_log(p_request, v_ver, 'resubmitted_to_prosecutor',
      v_from, 'prosecutor_queue', p_change_summary, null);
    perform private.legal_audit(p_request, 'LEGAL_RESUBMITTED_TO_PROSECUTOR',
      jsonb_build_object('version', v_ver, 'from', v_from));
    for sup in
      select m.user_id from public.justice_memberships m
       where m.active and (m.expires_at is null or m.expires_at > now())
         and m.justice_role in ('prosecutor', 'assistant_district_attorney', 'district_attorney')
         and r.responsible_bureau = any (private.prosecutor_bureaus_of(m.user_id))
         and r.classification <> 'sealed'
    loop
      v_n := v_n + 1;
      perform private.legal_notify(sup.user_id, p_request, 'legal_request',
        'A corrected ' || r.request_type || ' request re-entered the ' || private.bureau_label(r.responsible_bureau::text) || ' prosecutor queue.');
    end loop;
    return r;
  end if;

  if coalesce(p_material_change, false) then
    perform private.legal_log(p_request, null, 'material_change_declared',
      v_from, null, 'The investigator declared a material change - renewed command review required.', null);
  end if;

  if v_siu then
    v_ver := private.legal_freeze_version(p_request, 'siu_command_review', p_change_summary);
    update public.legal_requests
       set document_status = 'finalized', review_status = 'siu_command_review',
           submitted_to_cid_at = now()
     where id = p_request returning * into r;
    perform private.legal_log(p_request, v_ver, 'submitted_to_siu_command',
      v_from, 'siu_command_review', null, null);
    perform private.legal_audit(p_request, 'LEGAL_SUBMITTED_TO_SIU_COMMAND',
      jsonb_build_object('version', v_ver, 'material_change', coalesce(p_material_change, false)));
    for sup in
      select m.user_id from public.siu_memberships m
       where m.active and m.ended_at is null
         and m.siu_role = 'special_agent_in_charge'
         and not m.oversight_only
         and m.user_id <> v_uid
         and not private.siu_recused(r.case_id, m.user_id)
         and (coalesce(c.siu_classification, 'siu') <> 'siu_compartmented'
              or exists (select 1 from public.siu_compartment_members k
                          where k.case_id = r.case_id and k.user_id = m.user_id
                            and k.revoked_at is null))
    loop
      v_n := v_n + 1;
      perform private.legal_notify(sup.user_id, p_request, 'legal_request',
        'A ' || r.request_type || ' request awaits SIB command review.');
    end loop;
    if v_n = 0 then
      for sup in
        select p.id from public.profiles p
         where coalesce(private.justice_role_effective(p.id) = 'attorney_general', false)
      loop
        perform private.legal_notify(sup.id, p_request, 'legal_coverage',
          'An SIB legal request has no available SIB command reviewer.');
      end loop;
      perform private.legal_audit(p_request, 'LEGAL_SIU_COMMAND_UNCOVERED',
        jsonb_build_object('version', v_ver));
    end if;
    return r;
  end if;

  v_ver := private.legal_freeze_version(p_request, 'cid_supervisor_review', p_change_summary);
  update public.legal_requests
     set document_status = 'finalized', review_status = 'cid_supervisor_review',
         submitted_to_cid_at = now()
   where id = p_request returning * into r;
  perform private.legal_log(p_request, v_ver, 'submitted_to_cid', v_from, 'cid_supervisor_review', null, null);
  perform private.legal_audit(p_request, 'LEGAL_SUBMITTED_TO_CID',
    jsonb_build_object('version', v_ver, 'material_change', coalesce(p_material_change, false)));
  for sup in
    select p.id from public.profiles p
    where p.active and p.removed_at is null and p.id <> v_uid
      and ((p.role in ('senior_detective', 'bureau_lead') and p.division = r.responsible_bureau)
           or p.role in ('deputy_director', 'director'))
  loop
    perform private.legal_notify(sup.id, p_request, 'legal_request',
      'A ' || r.request_type || ' request awaits CID supervisor review.');
  end loop;
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.submit_legal_request_to_doj(p_request uuid, p_ada uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.legal_requests; v_ada uuid;
begin
  select * into r from public.legal_requests where id = p_request;
  if not found then raise exception 'request not found'; end if;
  if r.review_status <> 'submitted_to_doj' then
    raise exception 'request is not awaiting DOJ assignment';
  end if;
  v_ada := coalesce(p_ada, private.get_routing_ada_for_bureau(r.responsible_bureau));
  if v_ada is null then
    raise exception '% has no active routing ADA — assign coverage first or pass an ADA with a reason',
      r.responsible_bureau;
  end if;
  return public.reassign_legal_ada(p_request, v_ada, p_reason);
end $function$
;

CREATE OR REPLACE FUNCTION public.submit_narcotic_suggestion(p_narcotic uuid, p_type text, p_title text, p_explanation text, p_proposed_value text DEFAULT NULL::text, p_source_case uuid DEFAULT NULL::uuid, p_source_report uuid DEFAULT NULL::uuid, p_source_evidence uuid DEFAULT NULL::uuid)
 RETURNS narcotic_suggestions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  n public.narcotics;
  s public.narcotic_suggestions;
  v_uid uuid := (select auth.uid());
begin
  if not private.is_active() then raise exception 'not authorized'; end if;
  if p_type not in ('incorrect_name','missing_alias','wrong_category','incorrect_description',
                    'missing_packaging','missing_charge_link','missing_case_link',
                    'missing_place_link','new_substance','duplicate','other') then
    raise exception 'invalid suggestion type';
  end if;
  if btrim(coalesce(p_title, '')) = '' then raise exception 'a title is required'; end if;
  if btrim(coalesce(p_explanation, '')) = '' then raise exception 'an explanation is required'; end if;

  if p_narcotic is not null then
    select * into n from public.narcotics where id = p_narcotic;
    if not found then raise exception 'narcotic not found'; end if;
    if n.restricted and not private.can_edit_narcotics_intel() then
      raise exception 'narcotic not found';  -- do not leak restricted records
    end if;
  end if;

  insert into public.narcotic_suggestions
    (narcotic_id, suggestion_type, title, explanation, proposed_value,
     source_case_id, source_report_id, source_evidence_id, status, created_by)
  values (p_narcotic, p_type, btrim(p_title), btrim(p_explanation),
          nullif(btrim(coalesce(p_proposed_value, '')), ''),
          p_source_case, p_source_report, p_source_evidence, 'submitted', v_uid)
  returning * into s;

  insert into public.narcotic_suggestion_events (suggestion_id, event_type, to_status, actor_id)
  values (s.id, 'submitted', 'submitted', v_uid);

  -- Notify the catalog managers (never the submitter).
  insert into public.notifications (user_id, type, payload)
  select p.id, 'narcotic_suggestion', jsonb_build_object(
      'suggestion_id', s.id, 'narcotic_id', p_narcotic, 'title', s.title,
      'status', 'submitted', 'suggestion_type', p_type, 'actor_id', v_uid,
      'reason', 'New narcotics suggestion: ' || s.title)
    from public.profiles p
   where p.active and p.removed_at is null and p.id <> v_uid
     and (p.is_owner or p.role in ('bureau_lead', 'deputy_director', 'director'));

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'NARCOTIC_SUGGESTION_SUBMITTED', 'narcotic_suggestions', s.id,
          jsonb_build_object('narcotic_id', p_narcotic, 'type', p_type));
  return s;
end $function$
;

CREATE OR REPLACE FUNCTION public.surveillance_alert_ack(p_alert uuid, p_dismiss boolean DEFAULT false)
 RETURNS surveillance_alerts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); a public.surveillance_alerts;
begin
  select * into a from public.surveillance_alerts where id = p_alert for update;
  if not found then raise exception 'alert not found'; end if;
  if not private.is_active() or not private.can_access_case(a.case_id) then
    raise exception 'not permitted';
  end if;
  update public.surveillance_alerts
     set status = case when p_dismiss then 'dismissed' else 'acknowledged' end,
         acknowledged_by = v_uid, acknowledged_at = now()
   where id = p_alert returning * into a;
  return a;
end $function$
;

CREATE OR REPLACE FUNCTION public.surveillance_decide(p_target uuid, p_decision text, p_reason text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_approved_start timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS surveillance_targets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); t public.surveillance_targets; v_to text;
begin
  select * into t from public.surveillance_targets where id = p_target for update;
  if not found then raise exception 'surveillance target not found'; end if;
  if t.status <> 'pending_approval' then
    raise exception 'only a pending request can be decided';
  end if;
  if not private.can_authorize_surveillance(t.case_id) then
    raise exception 'authorizing surveillance requires Bureau Lead+ authority over this case';
  end if;
  if t.requested_by = v_uid then
    raise exception 'requesters cannot decide their own surveillance request';
  end if;
  if p_decision = 'authorize' then
    v_to := 'authorized';
    update public.surveillance_targets
       set status = 'authorized', approved_by = v_uid, approved_at = now(),
           approved_start = coalesce(p_approved_start, requested_start, now()),
           expires_at = p_expires_at
     where id = p_target returning * into t;
  elsif p_decision = 'deny' then
    if btrim(coalesce(p_reason, '')) = '' then raise exception 'denial requires a reason'; end if;
    v_to := 'denied';
    update public.surveillance_targets
       set status = 'denied', ended_at = now(), ended_by = v_uid, outcome_notes = p_reason
     where id = p_target returning * into t;
  elsif p_decision = 'return' then
    if btrim(coalesce(p_reason, '')) = '' then raise exception 'returning for changes requires a reason'; end if;
    v_to := 'draft';
    update public.surveillance_targets set status = 'draft'
     where id = p_target returning * into t;
  else
    raise exception 'invalid decision — authorize, deny, or return';
  end if;
  perform private.surveillance_log(p_target, p_decision || 'd', 'pending_approval', v_to, p_reason);
  if t.requested_by is not null and t.requested_by <> v_uid then
    insert into public.notifications (user_id, type, payload)
    values (t.requested_by, 'surveillance_decided', jsonb_build_object(
      'target_id', t.id, 'case_id', t.case_id, 'label', t.label, 'decision', p_decision,
      'reason', left('Surveillance request "' || t.label || '" was ' ||
        case p_decision when 'authorize' then 'authorized' when 'deny' then 'denied' else 'returned for changes' end
        || coalesce(': ' || p_reason, '.'), 500),
      'actor_id', v_uid, 'actor_name', (select display_name from public.profiles where id = v_uid)));
  end if;
  return t;
end $function$
;

CREATE OR REPLACE FUNCTION public.surveillance_deconflict(p_case uuid)
 RETURNS TABLE(kind text, ref_id uuid, my_count bigint, other_case_count bigint, visible_case_ids uuid[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select e.kind, e.ref_id,
         count(distinct o.id) filter (where o.case_id = p_case) as my_count,
         count(distinct o.case_id) filter (where o.case_id <> p_case) as other_case_count,
         coalesce(array_agg(distinct o.case_id) filter
           (where o.case_id <> p_case and private.can_access_case(o.case_id)), '{}') as visible_case_ids
  from public.surveillance_observation_entities e
  join public.surveillance_observations o
    on o.id = e.observation_id and o.verification_status = 'verified'
  where private.can_access_case(p_case)
    and exists (select 1 from public.surveillance_observation_entities e2
                 join public.surveillance_observations o2 on o2.id = e2.observation_id
                where o2.case_id = p_case and e2.kind = e.kind and e2.ref_id = e.ref_id)
  group by e.kind, e.ref_id
  having count(distinct o.case_id) filter (where o.case_id <> p_case) > 0
$function$
;

CREATE OR REPLACE FUNCTION public.surveillance_event_review(p_event uuid, p_decision text, p_notes text DEFAULT NULL::text)
 RETURNS surveillance_association_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); e public.surveillance_association_events; v_from text;
begin
  select * into e from public.surveillance_association_events where id = p_event for update;
  if not found then raise exception 'association event not found'; end if;
  if not private.is_active() or not private.can_access_case(e.case_id) then
    raise exception 'not permitted to review events on this case';
  end if;
  v_from := e.verification_status;
  if p_decision = 'verify' then
    update public.surveillance_association_events
       set verification_status = 'verified', verified_by = v_uid, verified_at = now()
     where id = p_event returning * into e;
  elsif p_decision = 'reject' then
    if btrim(coalesce(p_notes, '')) = '' then raise exception 'rejecting requires notes'; end if;
    update public.surveillance_association_events
       set verification_status = 'rejected', verified_by = v_uid, verified_at = now(),
           notes = coalesce(notes || e'\n', '') || 'Rejected: ' || p_notes
     where id = p_event returning * into e;
  elsif p_decision = 'reopen' then
    update public.surveillance_association_events
       set verification_status = 'unverified', verified_by = null, verified_at = null
     where id = p_event returning * into e;
  else
    raise exception 'invalid decision — verify, reject, or reopen';
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'SURV_EVENT_' || upper(p_decision), 'surveillance_association_events', p_event,
          jsonb_build_object('from', v_from, 'to', e.verification_status, 'case_id', e.case_id));
  return e;
end $function$
;

CREATE OR REPLACE FUNCTION public.surveillance_request_create(p_case uuid, p_target_type text, p_label text, p_reason text, p_objective text DEFAULT NULL::text, p_ref uuid DEFAULT NULL::uuid, p_priority text DEFAULT 'medium'::text, p_risk text DEFAULT NULL::text, p_requested_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_operation uuid DEFAULT NULL::uuid, p_submit boolean DEFAULT false)
 RETURNS surveillance_targets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); t public.surveillance_targets; v_bureau public.bureau;
begin
  if not private.is_active() or not private.can_access_case(p_case) then
    raise exception 'not permitted to request surveillance on this case';
  end if;
  select bureau into v_bureau from public.cases where id = p_case;
  insert into public.surveillance_targets
    (case_id, operation_id, target_type, ref_id, label, reason, objective,
     requested_by, bureau, priority, risk_level, requested_start, status)
  values (p_case, p_operation, p_target_type, p_ref, p_label, p_reason, p_objective,
          v_uid, v_bureau, coalesce(p_priority, 'medium'), p_risk, p_requested_start,
          case when p_submit then 'pending_approval' else 'draft' end)
  returning * into t;
  perform private.surveillance_log(t.id, 'requested', null, t.status, p_reason);
  return t;
end $function$
;

CREATE OR REPLACE FUNCTION public.surveillance_request_submit(p_target uuid)
 RETURNS surveillance_targets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); t public.surveillance_targets;
begin
  select * into t from public.surveillance_targets where id = p_target for update;
  if not found then raise exception 'surveillance target not found'; end if;
  if t.requested_by is distinct from v_uid and not private.is_command() then
    raise exception 'only the requester (or command) may submit this request';
  end if;
  if t.status <> 'draft' then raise exception 'only a draft can be submitted'; end if;
  update public.surveillance_targets set status = 'pending_approval'
   where id = p_target returning * into t;
  perform private.surveillance_log(p_target, 'submitted', 'draft', 'pending_approval', null);
  return t;
end $function$
;

CREATE OR REPLACE FUNCTION public.surveillance_transition(p_target uuid, p_action text, p_reason text DEFAULT NULL::text, p_new_expiry timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS surveillance_targets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); t public.surveillance_targets; v_from text;
begin
  select * into t from public.surveillance_targets where id = p_target for update;
  if not found then raise exception 'surveillance target not found'; end if;
  v_from := t.status;
  if not (t.requested_by = v_uid or private.is_command()) then
    raise exception 'not permitted to manage this surveillance target';
  end if;

  -- Lazy expiry: an authorized/active target past its window expires here.
  if t.expires_at is not null and t.expires_at <= now()
     and t.status in ('authorized', 'active', 'suspended') and p_action <> 'extend' then
    update public.surveillance_targets
       set status = 'expired', ended_at = coalesce(t.ended_at, t.expires_at)
     where id = p_target returning * into t;
    perform private.surveillance_log(p_target, 'expired', v_from, 'expired', 'authorization window elapsed');
    return t;
  end if;

  if p_action = 'activate' then
    if t.status not in ('authorized', 'suspended') then
      raise exception 'only an authorized or suspended target can be activated';
    end if;
    update public.surveillance_targets set status = 'active' where id = p_target returning * into t;
  elsif p_action = 'suspend' then
    if t.status <> 'active' then raise exception 'only an active target can be suspended'; end if;
    if btrim(coalesce(p_reason, '')) = '' then raise exception 'suspension requires a reason'; end if;
    update public.surveillance_targets set status = 'suspended' where id = p_target returning * into t;
  elsif p_action in ('complete', 'cancel') then
    if t.status in ('completed', 'denied', 'expired', 'cancelled') then
      raise exception 'surveillance is already concluded';
    end if;
    update public.surveillance_targets
       set status = case when p_action = 'complete' then 'completed' else 'cancelled' end,
           ended_at = now(), ended_by = v_uid,
           outcome_notes = coalesce(p_reason, outcome_notes)
     where id = p_target returning * into t;
  elsif p_action = 'extend' then
    if p_new_expiry is null or p_new_expiry <= now() then
      raise exception 'an extension needs a future expiry';
    end if;
    if btrim(coalesce(p_reason, '')) = '' then raise exception 'an extension requires renewed justification'; end if;
    if t.status not in ('authorized', 'active', 'suspended', 'expired') then
      raise exception 'only an authorized target can be extended';
    end if;
    if not private.can_authorize_surveillance(t.case_id) then
      raise exception 'extensions require Bureau Lead+ authority over this case';
    end if;
    if t.requested_by = v_uid then
      raise exception 'requesters cannot approve their own extension';
    end if;
    update public.surveillance_targets
       set expires_at = p_new_expiry,
           status = case when status = 'expired' then 'active' else status end,
           ended_at = case when status = 'expired' then null else ended_at end
     where id = p_target returning * into t;
  else
    raise exception 'invalid action — activate, suspend, complete, cancel, or extend';
  end if;
  perform private.surveillance_log(p_target, p_action || 'd', v_from, t.status, p_reason);
  return t;
end $function$
;

CREATE OR REPLACE FUNCTION public.transfer_doj_activate(p_transfer uuid, p_reassignments jsonb DEFAULT '{}'::jsonb)
 RETURNS member_transfers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); tr public.member_transfers; me public.profiles;
        t public.profiles; rec record; v_new uuid; v_n int := 0; v_handover jsonb;
begin
  select * into me from public.profiles where id = v_uid;
  select * into tr from public.member_transfers where id = p_transfer for update;
  if not found then raise exception 'transfer not found'; end if;
  if tr.status <> 'doj_accepted' then raise exception 'transfer is not ready for activation'; end if;
  if tr.user_id = v_uid then raise exception 'you cannot activate your own transfer'; end if;
  if not (coalesce(me.active, false) and me.role in ('deputy_director', 'director')
          or coalesce(me.is_owner, false)
          or coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)) then
    raise exception 'only Deputy Director+, the Attorney General, or the Owner may activate a transfer';
  end if;
  select * into t from public.profiles where id = tr.user_id for update;

  v_handover := public.transfer_handover(p_transfer);

  if tr.direction = 'cid_to_doj' then
    if tr.requested_role = 'prosecutor'
       and (tr.target_bureau is null or tr.target_bureau not in ('major_crimes', 'street_crimes')) then
      raise exception 'this prosecutor transfer has no home bureau — file a new transfer naming Major Crimes or Street Crimes';
    end if;
    for rec in select c.id, c.case_number from public.cases c
                where c.lead_detective_id = tr.user_id and c.status <> 'closed' and c.archived_at is null
    loop
      v_new := nullif(p_reassignments->'cases'->>rec.id::text, '')::uuid;
      if v_new is null and tr.retain_cid
         and (p_reassignments->'retain_case_ids') ? rec.id::text then
        continue;  -- explicitly retained under approved dual membership
      end if;
      if v_new is null then
        raise exception 'case % still needs a new lead detective before activation', rec.case_number;
      end if;
      if not exists (select 1 from public.profiles p
                      where p.id = v_new and p.active and p.removed_at is null and p.id <> tr.user_id) then
        raise exception 'proposed lead for case % is not an active member', rec.case_number;
      end if;
      update public.cases set lead_detective_id = v_new where id = rec.id;
      insert into public.notifications (user_id, type, payload)
      values (v_new, 'case_assigned', jsonb_build_object(
        'case_id', rec.id, 'case_number', rec.case_number,
        'reason', 'Case ' || rec.case_number || ' was handed to you during an organizational transfer.'));
      v_n := v_n + 1;
    end loop;
    v_new := nullif(p_reassignments->>'signoffs_to', '')::uuid;
    if v_new is not null then
      update public.cases set signoff_assignee_id = v_new
       where signoff_assignee_id = tr.user_id and signoff_status like 'awaiting_%';
    elsif exists (select 1 from public.cases c
                   where c.signoff_assignee_id = tr.user_id and c.signoff_status like 'awaiting_%')
          and not tr.retain_cid then
      raise exception 'pending sign-offs still route to this member — name a substitute (signoffs_to)';
    end if;

    if not tr.retain_cid then
      update public.profiles set active = false where id = tr.user_id;
      insert into public.role_events
        (target_id, actor_id, old_role, new_role, old_division, new_division,
         old_active, new_active, reason, source, source_id)
      values (tr.user_id, v_uid, t.role, t.role, t.division, t.division,
              true, false, 'Transferred to DOJ: ' || tr.requested_role, 'doj_transfer', tr.id);
      update public.case_assignments
         set removed_at = now(), removed_by = v_uid,
             removal_reason = 'Transferred to DOJ'
       where officer_id = tr.user_id and removed_at is null;
    end if;

    perform private.transfer_doj_set_membership(
      tr.user_id, tr.requested_role, v_uid,
      case when tr.retain_cid then tr.dual_expires_at else null end,
      tr.target_bureau);
  else
    for rec in select id from public.legal_requests
                where assigned_prosecutor_id = tr.user_id and review_status = 'prosecutor_review'
    loop
      perform private.legal_end_participant(rec.id, tr.user_id, 'prosecutor');
      update public.legal_requests
         set review_status = 'prosecutor_queue', assigned_prosecutor_id = null,
             prosecutor_claimed_at = null, queue_entered_at = now()
       where id = rec.id;
      perform private.legal_log(rec.id, null, 'prosecutor_unassigned',
        'prosecutor_review', 'prosecutor_queue', 'Holder transferred to CID.', null);
    end loop;
    for rec in select id from public.legal_requests
                where assigned_judge_id = tr.user_id and review_status = 'judicial_review'
    loop
      perform private.legal_end_participant(rec.id, tr.user_id, 'judicial_reviewer');
      update public.legal_requests
         set review_status = 'submitted_to_judge', assigned_judge_id = null
       where id = rec.id;
      perform private.legal_log(rec.id, null, 'judge_unassigned',
        'judicial_review', 'submitted_to_judge', 'Holder transferred to CID.', null);
    end loop;
    update public.justice_memberships
       set active = false, ended_at = now()
     where user_id = tr.user_id;
    update public.profiles
       set active = true, role = tr.requested_role::public.app_role,
           division = tr.target_bureau
     where id = tr.user_id;
    insert into public.role_events
      (target_id, actor_id, old_role, new_role, old_division, new_division,
       old_active, new_active, reason, source, source_id)
    values (tr.user_id, v_uid, t.role, tr.requested_role::public.app_role,
            t.division, tr.target_bureau,
            coalesce(t.active, false), true,
            'Returned from DOJ as ' || tr.requested_role, 'doj_transfer', tr.id);
  end if;

  update public.member_transfers
     set status = 'effective', effective_by = v_uid, effective_at = now(),
         handover = v_handover, updated_at = now()
   where id = p_transfer returning * into tr;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'TRANSFER_DOJ_EFFECTIVE', 'member_transfers', p_transfer,
          jsonb_build_object('member', tr.user_id, 'direction', tr.direction,
                             'role', tr.requested_role, 'cases_reassigned', v_n,
                             'retain_cid', tr.retain_cid,
                             'same_actor_stages', tr.cid_decided_by = tr.doj_decided_by));
  insert into public.notifications (user_id, type, payload)
  values (tr.user_id, 'membership_update', jsonb_build_object(
    'reason', 'Your organizational transfer is now effective ('
      || replace(tr.requested_role, '_', ' ') || ').'));
  insert into public.notifications (user_id, type, payload)
  select p.id, 'membership_update', jsonb_build_object(
    'reason', coalesce((select display_name from public.profiles where id = tr.user_id), 'A member')
      || ' transferred ' || replace(tr.direction, '_', '-') || ' (' || tr.requested_role || ').')
    from public.profiles p
   where p.active and p.removed_at is null and p.id <> v_uid and p.id <> tr.user_id
     and (p.role in ('deputy_director', 'director')
          or coalesce(private.justice_role_effective(p.id) = 'attorney_general', false))
     and not coalesce(p.is_test, false);
  return tr;
end $function$
;

CREATE OR REPLACE FUNCTION public.transfer_doj_cancel(p_transfer uuid, p_reason text DEFAULT NULL::text)
 RETURNS member_transfers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); tr public.member_transfers;
begin
  select * into tr from public.member_transfers where id = p_transfer for update;
  if not found then raise exception 'transfer not found'; end if;
  if tr.status in ('effective', 'rejected', 'cancelled') then
    raise exception 'transfer is already settled';
  end if;
  if not (tr.requested_by = v_uid or private.is_command() or private.owner_flag(v_uid)
          or coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)) then
    raise exception 'not authorized to cancel this transfer';
  end if;
  update public.member_transfers
     set status = 'cancelled', return_note = coalesce(p_reason, return_note), updated_at = now()
   where id = p_transfer returning * into tr;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'TRANSFER_DOJ_CANCELLED', 'member_transfers', p_transfer,
          jsonb_build_object('member', tr.user_id, 'reason', left(coalesce(p_reason, ''), 300)));
  return tr;
end $function$
;

CREATE OR REPLACE FUNCTION public.transfer_doj_decide(p_transfer uuid, p_stage text, p_decision text, p_note text DEFAULT NULL::text, p_retain_cid boolean DEFAULT false, p_dual_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS member_transfers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); tr public.member_transfers; me public.profiles;
        v_same boolean;
begin
  select * into me from public.profiles where id = v_uid;
  select * into tr from public.member_transfers where id = p_transfer for update;
  if not found then raise exception 'transfer not found'; end if;
  if tr.user_id = v_uid then raise exception 'you cannot decide your own transfer'; end if;
  if p_decision not in ('approve', 'return', 'reject') then raise exception 'invalid decision'; end if;
  if p_decision in ('return', 'reject') and btrim(coalesce(p_note, '')) = '' then
    raise exception 'a % requires a note', p_decision;
  end if;

  if p_stage = 'cid' then
    if tr.status <> 'requested' then raise exception 'transfer is not awaiting CID authorization'; end if;
    if not (coalesce(me.active, false) and me.role in ('deputy_director', 'director')
            or coalesce(me.is_owner, false)) then
      raise exception 'only a Deputy Director or higher may authorize this transfer';
    end if;
    update public.member_transfers
       set status = case p_decision when 'approve' then 'cid_approved'
                                    when 'return' then 'returned' else 'rejected' end,
           cid_decided_by = v_uid, cid_decided_at = now(), cid_note = p_note,
           return_note = case when p_decision = 'return' then p_note else return_note end,
           updated_at = now()
     where id = p_transfer returning * into tr;
  elsif p_stage = 'doj' then
    if tr.status <> 'cid_approved' then raise exception 'transfer is not awaiting DOJ acceptance'; end if;
    if tr.direction = 'cid_to_doj' and tr.requested_role = 'attorney_general' then
      if not coalesce(me.is_owner, false) then
        raise exception 'an Attorney General appointment is accepted by the Owner only';
      end if;
    elsif not (coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)
               or coalesce(me.is_owner, false)) then
      raise exception 'only the Attorney General or Owner may accept this transfer';
    end if;
    if p_decision = 'approve' and coalesce(p_retain_cid, false) then
      if tr.direction <> 'cid_to_doj' then raise exception 'dual membership applies to CID-to-DOJ only'; end if;
      if p_dual_expires_at is null or p_dual_expires_at <= now()
         or p_dual_expires_at > now() + interval '90 days' then
        raise exception 'temporary dual membership requires an expiry within 90 days';
      end if;
    end if;
    v_same := (tr.cid_decided_by = v_uid);
    if v_same and not coalesce(me.is_owner, false) then
      raise exception 'the same person cannot complete both approval stages (Owner excepted)';
    end if;
    update public.member_transfers
       set status = case p_decision when 'approve' then 'doj_accepted'
                                    when 'return' then 'returned' else 'rejected' end,
           doj_decided_by = v_uid, doj_decided_at = now(), doj_note = p_note,
           retain_cid = case when p_decision = 'approve' then coalesce(p_retain_cid, false) else retain_cid end,
           dual_expires_at = case when p_decision = 'approve' and coalesce(p_retain_cid, false)
                                  then p_dual_expires_at else dual_expires_at end,
           return_note = case when p_decision = 'return' then p_note else return_note end,
           updated_at = now()
     where id = p_transfer returning * into tr;
  else
    raise exception 'invalid stage';
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'TRANSFER_DOJ_' || upper(p_stage) || '_' || upper(p_decision),
          'member_transfers', p_transfer,
          jsonb_build_object('member', tr.user_id, 'status', tr.status,
                             'same_actor', coalesce(v_same, false),
                             'note', left(coalesce(p_note, ''), 300)));
  insert into public.notifications (user_id, type, payload)
  values (tr.user_id, 'membership_update', jsonb_build_object(
    'reason', 'Your organizational transfer was ' ||
      case p_decision when 'approve' then
        case p_stage when 'cid' then 'authorized by CID Command — awaiting DOJ acceptance.'
                     else 'accepted by the DOJ — awaiting activation.' end
      when 'return' then 'returned: ' || coalesce(p_note, '')
      else 'rejected: ' || coalesce(p_note, '') end));
  return tr;
end $function$
;

CREATE OR REPLACE FUNCTION public.transfer_doj_request(p_user uuid, p_direction text, p_role text, p_reason text, p_bureau bureau DEFAULT NULL::bureau)
 RETURNS member_transfers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); t public.profiles; tr public.member_transfers;
        v_jrole text;
begin
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required'; end if;
  if p_user = v_uid then raise exception 'you cannot propose your own transfer'; end if;
  select * into t from public.profiles where id = p_user;
  if t.id is null or t.removed_at is not null or coalesce(t.is_system, false) or coalesce(t.is_test, false) then
    raise exception 'target account is not eligible for a transfer';
  end if;
  v_jrole := (select justice_role from public.justice_memberships
               where user_id = p_user and active);
  if p_direction = 'cid_to_doj' then
    if not (private.is_command() or private.owner_flag(v_uid)) then
      raise exception 'only CID Command may propose a CID-to-DOJ transfer';
    end if;
    if not coalesce(t.active, false) then
      raise exception 'target is not an active CID member';
    end if;
    if p_role = 'prosecutor' and (p_bureau is null or p_bureau not in ('major_crimes', 'street_crimes')) then
      raise exception 'a prosecutor transfer needs a home bureau: Major Crimes or Street Crimes';
    end if;
  elsif p_direction = 'doj_to_cid' then
    if not (coalesce(private.justice_role_effective(v_uid) = 'attorney_general', false)
            or private.owner_flag(v_uid)) then
      raise exception 'only the Attorney General or Owner may propose a DOJ-to-CID transfer';
    end if;
    if v_jrole is null then raise exception 'target holds no active DOJ membership'; end if;
  else
    raise exception 'invalid direction';
  end if;
  insert into public.member_transfers
    (user_id, direction, requested_role, target_bureau, from_role, from_division,
     from_justice_role, reason, requested_by)
  values (p_user, p_direction, p_role, p_bureau, t.role::text, t.division::text,
          v_jrole, btrim(p_reason), v_uid)
  returning * into tr;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_uid, 'TRANSFER_DOJ_REQUESTED', 'member_transfers', tr.id,
          jsonb_build_object('member', p_user, 'direction', p_direction,
                             'role', p_role, 'bureau', p_bureau, 'reason', left(p_reason, 300)));
  insert into public.notifications (user_id, type, payload)
  values (p_user, 'membership_update', jsonb_build_object(
    'reason', 'An organizational transfer was proposed for you ('
      || replace(p_direction, '_', '-') || ', ' || replace(p_role, '_', ' ') || ').'));
  return tr;
end $function$
;

CREATE OR REPLACE FUNCTION public.transfer_handover(p_transfer uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when not exists (select 1 from public.member_transfers tr
                      where tr.id = p_transfer
                        and (tr.user_id = (select auth.uid())
                             or private.is_command()
                             or coalesce(private.justice_role_effective((select auth.uid())) = 'attorney_general', false)
                             or private.owner_flag((select auth.uid()))))
    then jsonb_build_object('error', 'transfer not found or not accessible')
    else (
      select jsonb_build_object(
        'member', tr.user_id,
        'led_cases', (
          select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'number', c.case_number, 'title', c.title)), '[]')
          from public.cases c
          where c.lead_detective_id = tr.user_id and c.status <> 'closed' and c.archived_at is null),
        'open_assignments', (
          select coalesce(jsonb_agg(jsonb_build_object('case_id', a.case_id, 'assignment', a.id)), '[]')
          from public.case_assignments a
          where a.officer_id = tr.user_id
            and (a.removed_at is null or a.removed_at > now())),
        'open_tasks', (
          select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'case_id', k.case_id, 'title', k.title)), '[]')
          from public.case_tasks k
          where k.assignee = tr.user_id and not k.done),
        'draft_reports', (
          select coalesce(jsonb_agg(jsonb_build_object('id', rp.id, 'case_id', rp.case_id, 'template', rp.template)), '[]')
          from public.reports rp
          where rp.author_id = tr.user_id and not rp.finalized),
        'open_legal_requests', (
          select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'number', l.request_number, 'status', l.review_status)), '[]')
          from public.legal_requests l
          where l.created_by = tr.user_id
            and l.review_status not in ('approved', 'denied', 'withdrawn', 'declined', 'cancelled', 'superseded')),
        'pending_signoffs', (
          select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'number', c.case_number)), '[]')
          from public.cases c
          where c.signoff_assignee_id = tr.user_id and c.signoff_status like 'awaiting_%'),
        'held_doj_work', (
          select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'number', l.request_number, 'status', l.review_status)), '[]')
          from public.legal_requests l
          where (l.assigned_prosecutor_id = tr.user_id and l.review_status = 'prosecutor_review')
             or (l.assigned_judge_id = tr.user_id and l.review_status = 'judicial_review')),
        'unread_notifications', (
          select count(*) from public.notifications n
          where n.user_id = tr.user_id and not n.read))
      from public.member_transfers tr where tr.id = p_transfer)
  end
$function$
;

CREATE OR REPLACE FUNCTION public.update_legal_draft(p_request uuid, p_title text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_form jsonb DEFAULT NULL::jsonb, p_narrative text DEFAULT NULL::text, p_person uuid DEFAULT NULL::uuid, p_recipient_type text DEFAULT NULL::text, p_recipient_name text DEFAULT NULL::text, p_classification text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_person public.persons;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if not private.can_edit_legal_draft(p_request, v_uid) then
    raise exception 'this request is not editable';
  end if;
  if p_person is not null then
    select * into v_person from public.persons where id = p_person;
    if not found then raise exception 'person not found'; end if;
  end if;
  if p_classification is not null
     and p_classification not in ('standard', 'restricted', 'classified', 'sealed') then
    raise exception 'invalid classification';
  end if;
  update public.legal_requests set
    title = coalesce(nullif(btrim(coalesce(p_title, '')), ''), title),
    priority = coalesce(p_priority, priority),
    form_data = coalesce(p_form, form_data),
    narrative = coalesce(p_narrative, narrative),
    person_id = coalesce(p_person, person_id),
    person_name_snapshot = coalesce(v_person.name, person_name_snapshot),
    recipient_type = coalesce(p_recipient_type, recipient_type),
    recipient_name = coalesce(nullif(btrim(coalesce(p_recipient_name, '')), ''), recipient_name),
    classification = coalesce(p_classification, classification)
  where id = p_request returning * into r;
  perform private.legal_log(p_request, null, 'edited', null, null, null, null);
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.warrant_set_status(p_report uuid, p_status text)
 RETURNS reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.reports;
  v_uid uuid := (select auth.uid());
  v_name text;
  v_from text;
  v_cmd boolean;
  v_authority text;
begin
  if p_status not in ('draft', 'signed', 'executed', 'returned') then
    raise exception 'invalid warrant status';
  end if;
  select * into r from public.reports where id = p_report for update;
  if not found then raise exception 'report not found'; end if;
  if not (private.is_active() and private.can_access_case(r.case_id)) then
    raise exception 'not permitted to update this warrant';
  end if;
  if r.template not in ('arrest_warrant', 'search_warrant', 'wiretap_warrant') then
    raise exception 'not a warrant report';
  end if;
  v_from := coalesce(r.fields->>'_warrant_status', 'draft');
  if v_from = p_status then
    raise exception 'this warrant is already % (it may have just changed) — reload and retry', p_status using errcode = 'P0001';
  end if;
  v_cmd := coalesce((select private.is_command()), false);
  if p_status = 'draft' then
    if not v_cmd then
      raise exception 'only command can revert a warrant to draft';
    end if;
    v_authority := 'override';
  elsif p_status = 'signed' then
    if v_from <> 'draft' then
      raise exception 'a warrant can only be signed from draft (it is %) — reload and retry', v_from using errcode = 'P0001';
    end if;
    if v_cmd then
      v_authority := 'command';
    elsif exists (select 1 from public.legal_requests lr
                   where lr.source_report_id = p_report and lr.review_status = 'approved') then
      v_authority := 'legal_approved';
    else
      raise exception 'marking a warrant signed requires command authority or an approved legal request for this report — submit it for Legal Review or have command sign it';
    end if;
  elsif p_status = 'executed' then
    if v_from <> 'signed' then
      raise exception 'a warrant cannot be executed before it is signed (it is %) — reload and retry', v_from using errcode = 'P0001';
    end if;
  elsif p_status = 'returned' then
    if v_from <> 'executed' then
      raise exception 'a warrant cannot be returned before it is executed (it is %) — reload and retry', v_from using errcode = 'P0001';
    end if;
  end if;
  select display_name into v_name from public.profiles where id = v_uid;
  update public.reports
     set fields = coalesce(fields, '{}'::jsonb)
       || jsonb_build_object('_warrant_status', p_status)
       || jsonb_build_object('_warrant_log',
            coalesce(fields->'_warrant_log', '[]'::jsonb) || jsonb_build_array(
              jsonb_build_object(
                'at', now(),
                'by', coalesce(v_name, 'Officer'),
                'by_id', v_uid,
                'from', v_from,
                'to', p_status
              ) || case when v_authority is not null
                     then jsonb_build_object('authority', v_authority)
                     else '{}'::jsonb end)),
         updated_at = now()
   where id = p_report
  returning * into r;
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION public.withdraw_legal_request(p_request uuid, p_note text DEFAULT NULL::text)
 RETURNS legal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); r public.legal_requests; v_from text;
begin
  select * into r from public.legal_requests where id = p_request for update;
  if not found then raise exception 'request not found'; end if;
  if r.created_by <> v_uid then raise exception 'only the requesting investigator may withdraw'; end if;
  if r.review_status in ('approved', 'denied', 'withdrawn') then
    raise exception 'decided requests cannot be withdrawn';
  end if;
  v_from := r.review_status;
  update public.legal_requests set review_status = 'withdrawn' where id = p_request returning * into r;
  perform private.legal_log(p_request, r.current_version_id, 'withdrawn', v_from, 'withdrawn', p_note, null);
  perform private.legal_audit(p_request, 'LEGAL_WITHDRAWN', null);
  perform private.legal_notify(r.assigned_ada_id, p_request, 'legal_update', 'A request was withdrawn by CID.');
  perform private.legal_notify(r.assigned_judge_id, p_request, 'legal_update', 'A request was withdrawn by CID.');
  return r;
end $function$
;

-- ---- private ----

CREATE OR REPLACE FUNCTION private.account_freeze_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.external_id is not null and new.external_id is distinct from old.external_id then
    raise exception 'account external_id is the immutable platform identity and cannot be changed once set';
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.account_link_guard_confirm()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.ownership_confidence = 'confirmed'
     and (tg_op = 'INSERT' or old.ownership_confidence is distinct from 'confirmed')
     and not private.is_command() then
    raise exception 'confirming account ownership is a command action (Bureau Lead or higher)';
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.account_link_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.ownership_confidence = 'confirmed'
     and (tg_op = 'INSERT' or old.ownership_confidence is distinct from 'confirmed') then
    new.confirmed_by := coalesce(new.confirmed_by, (select auth.uid()));
    new.confirmed_at := coalesce(new.confirmed_at, now());
  elsif new.ownership_confidence <> 'confirmed' then
    new.confirmed_by := null;
    new.confirmed_at := null;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.account_track_handle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    insert into public.account_handles (account_id, handle, is_current, source)
    values (new.id, new.handle, true, 'initial');
  elsif tg_op = 'UPDATE' and lower(btrim(new.handle)) is distinct from lower(btrim(old.handle)) then
    update public.account_handles set is_current = false where account_id = new.id and is_current;
    insert into public.account_handles (account_id, handle, is_current, source)
    values (new.id, new.handle, true, 'renamed');
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.announcement_recipients(p_audience text, p_mentions jsonb, p_author uuid)
 RETURNS TABLE(user_id uuid, mentioned boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with targets as (
    select m->>'target' as t from jsonb_array_elements(coalesce(p_mentions, '[]'::jsonb)) m
  ),
  aud as (
    select p.id from public.profiles p
    where p.active and p.removed_at is null
      and (not p.is_test or private.is_test_user(p_author))
      and (
      p_audience = 'all'
      or (p_audience = 'command' and (p.role in ('bureau_lead', 'deputy_director', 'director') or p.is_owner))
      or (p_audience in ('major_crimes', 'street_crimes', 'JTF') and p.division::text = p_audience)
    )
  ),
  ment as (
    select p.id from public.profiles p
    where p.active and p.removed_at is null
      and (not p.is_test or private.is_test_user(p_author))
      and exists (
      select 1 from targets t where
        (t.t = 'all' and private.can_post_audience('all'))
        or (t.t like 'role:%' and p.role::text = substring(t.t from 6))
        or t.t = p.id::text
    )
  )
  select ids.id as user_id, bool_or(ids.m) as mentioned
  from (
    select id, false as m from aud
    union all
    select id, true as m from ment
  ) ids
  where ids.id <> p_author
  group by ids.id
$function$
;

CREATE OR REPLACE FUNCTION private.assert_fresh_session()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_created timestamptz;
begin
  select s.created_at into v_created
    from auth.sessions s
   where s.id = nullif(auth.jwt()->>'session_id', '')::uuid;
  if v_created is null or v_created <= now() - interval '5 minutes' then
    raise exception 'permanent deletion requires a fresh sign-in (within the last 5 minutes) — sign out, sign back in, and retry';
  end if;
end $function$
;

CREATE OR REPLACE FUNCTION private.audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  j jsonb;
  rid uuid;
begin
  j := to_jsonb(coalesce(new, old));
  rid := coalesce((j->>'id')::uuid, (j->>'feedback_id')::uuid);
  insert into public.audit_log (actor_id, action, entity, entity_id)
  values ((select auth.uid()), tg_op, tg_table_name, rid);
  return coalesce(new, old);
end $function$
;

CREATE OR REPLACE FUNCTION private.audit_detail()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (
    (select auth.uid()),
    tg_op,
    tg_table_name,
    case tg_op when 'DELETE' then old.id else new.id end,
    case tg_op
      when 'DELETE' then jsonb_build_object('old', to_jsonb(old))
      when 'INSERT' then jsonb_build_object('new', to_jsonb(new))
      else jsonb_build_object('old', to_jsonb(old), 'new', to_jsonb(new))
    end
  );
  return coalesce(new, old);
end $function$
;

CREATE OR REPLACE FUNCTION private.audit_operation_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status is distinct from old.status then
    insert into public.audit_log (actor_id, action, entity, entity_id, detail)
    values ((select auth.uid()),
            case when new.status in ('resolved', 'closed') and old.status not in ('resolved', 'closed') then 'OP_CLOSED'
                 when old.status in ('resolved', 'closed') and new.status = 'active' then 'OP_REOPENED'
                 else 'OP_STATUS_CHANGED' end,
            'operations', new.id,
            jsonb_build_object('from', old.status, 'to', new.status, 'op_type', new.op_type));
  end if;
  return null;
end $function$
;

CREATE OR REPLACE FUNCTION private.block_direct_case_archive()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated', 'anon') then
    new.archived_at := old.archived_at;
    new.archived_by := old.archived_by;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.block_direct_case_bureau()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated','anon') and (
       new.bureau              is distinct from old.bureau or
       new.originating_bureau  is distinct from old.originating_bureau) then
