end $function$
;

CREATE OR REPLACE FUNCTION private.block_direct_login_denied()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated', 'anon') then
