CREATE OR REPLACE FUNCTION private.block_direct_report_finalize()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated','anon') then
    if new.finalized is distinct from old.finalized
       or new.signature is distinct from old.signature then
      raise exception 'reports can only be finalized via report_finalize()';
    end if;
    if old.finalized
       and coalesce(new.fields, '{}'::jsonb) is distinct from coalesce(old.fields, '{}'::jsonb) then
      raise exception 'a finalized report''s contents are locked (use warrant_set_status() for the warrant lifecycle)';
    end if;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.block_direct_signoff()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated','anon') and (
       new.signoff_status      is distinct from old.signoff_status or
       new.signoff_stage       is distinct from old.signoff_stage or
       new.signoff_assignee_id is distinct from old.signoff_assignee_id or
       new.signoff_submitted_by is distinct from old.signoff_submitted_by or
       new.signoff_submitted_at is distinct from old.signoff_submitted_at) then
    raise exception 'sign-off fields can only be changed via the sign-off RPCs';
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.block_direct_siu_case_cols()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.case_authority := 'cid';
      new.siu_classification := null;
      new.siu_assumed_at := null;
      new.siu_assumed_by := null;
      new.siu_assumption_reason := null;
      new.siu_returned_at := null;
      new.siu_stage := null;
      new.siu_category := null;
      new.siu_closure_reason := null;
      new.siu_closure_note := null;
    else
      if new.case_authority is distinct from old.case_authority then
        raise exception 'case authority can only be changed by an SIB authority RPC';
      end if;
      if new.siu_classification is distinct from old.siu_classification then
        raise exception 'the SIB classification can only be changed via siu_set_case_classification()';
      end if;
      if new.siu_assumed_at is distinct from old.siu_assumed_at
         or new.siu_assumed_by is distinct from old.siu_assumed_by
         or new.siu_assumption_reason is distinct from old.siu_assumption_reason
         or new.siu_returned_at is distinct from old.siu_returned_at then
        raise exception 'SIB control provenance is recorded only by siu_assume_control() / siu_release_control()';
      end if;
      if new.siu_stage is distinct from old.siu_stage
         or new.siu_category is distinct from old.siu_category
         or new.siu_closure_reason is distinct from old.siu_closure_reason
         or new.siu_closure_note is distinct from old.siu_closure_note then
        raise exception 'SIB case lifecycle fields are set only by the SIB lifecycle RPCs';
      end if;
    end if;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.block_direct_siu_note_grading()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.last_reviewed_at := null;
      new.last_reviewed_by := null;
      new.review_outcome := null;
    else
      if new.source_type is distinct from old.source_type
         or new.source_reliability is distinct from old.source_reliability
         or new.info_credibility is distinct from old.info_credibility
         or new.review_due_at is distinct from old.review_due_at then
        raise exception 'intelligence grading is changed only via siu_grade_note()';
      end if;
      if new.last_reviewed_at is distinct from old.last_reviewed_at
         or new.last_reviewed_by is distinct from old.last_reviewed_by
         or new.review_outcome is distinct from old.review_outcome then
        raise exception 'an intelligence review is recorded only by siu_review_note()';
      end if;
    end if;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.block_intel_link_change_under_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    if private.case_has_active_hold(old.case_id) then
      raise exception 'case is under an active legal hold — its intelligence links are preserved and cannot be removed (including by a merge) until the hold is lifted';
    end if;
    return old;
  end if;
  if (new.ref_id is distinct from old.ref_id
      or new.case_id is distinct from old.case_id
      or new.kind is distinct from old.kind)
     and private.case_has_active_hold(old.case_id) then
    raise exception 'case is under an active legal hold — its intelligence links are preserved and cannot be re-pointed (including by a merge) until the hold is lifted';
  end if;
  return new;
end $function$
;

