 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce((select active and role in ('bureau_lead','deputy_director','director')
                   from public.profiles where id = (select auth.uid())), false)
$function$
;

CREATE OR REPLACE FUNCTION private.can_approve_document(p_category text, p_class text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when coalesce(p_class, 'internal') = 'owner' then private.is_owner()
    when coalesce(p_class, 'internal') = 'justice' or p_category = 'justice'
      then private.can_manage_prosecutors()
    when p_category = 'sops' then private.is_command() or private.is_owner()
    else coalesce((select active and role in ('deputy_director', 'director')
                   from public.profiles where id = (select auth.uid())), false)
         or private.is_owner()
  end
$function$
;

CREATE OR REPLACE FUNCTION private.can_approve_legal(p_request uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
      from public.legal_requests r
      join public.cases c on c.id = r.case_id
      join public.profiles me on me.id = p_user
     where r.id = p_request
       and r.created_by <> p_user
       and p_user = (select auth.uid())
       and (coalesce(me.is_owner, false) or private.is_active())
       and private.can_access_case(r.case_id)
       and (case when c.case_authority = 'siu'
                 then private.siu_case_command(r.case_id)
                 else (me.role in ('deputy_director', 'director')
                       or coalesce(me.is_owner, false)
                       or (me.role = 'bureau_lead' and me.division = r.responsible_bureau)
                       or (me.role = 'bureau_lead' and c.bureau = 'JTF'))
            end))
$function$
;

CREATE OR REPLACE FUNCTION private.can_assign_cid_role(p_final_role app_role, p_bureau bureau)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles;
begin
  select * into me from public.profiles where id = (select auth.uid());
  if me.id is null then return false; end if;
  -- NULL and retired enum values are never assignable — not even by the
  -- Owner (the NULL-permissive `not in` would otherwise skip this guard).
  if p_final_role is null
     or p_final_role not in ('detective', 'senior_detective', 'bureau_lead',
                             'deputy_director', 'director') then
    return false;
  end if;
  if me.is_owner and me.active then return true; end if;
  if not me.active or me.removed_at is not null then return false; end if;
  return case p_final_role
    when 'detective' then
      (me.role = 'bureau_lead' and me.division = p_bureau)
      or me.role in ('deputy_director', 'director')
    when 'senior_detective' then
      (me.role = 'bureau_lead' and me.division = p_bureau)
      or me.role in ('deputy_director', 'director')
    when 'bureau_lead' then me.role in ('deputy_director', 'director')
    when 'deputy_director' then me.role = 'director'
    else false  -- director requires Owner; retired roles are never assignable
  end;
end $function$
;

CREATE OR REPLACE FUNCTION private.can_authorize_surveillance(p_case uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role text; v_div public.bureau; v_owner boolean; v_bureau public.bureau;
begin
  if not private.is_active() then return false; end if;
  select role, division, coalesce(is_owner, false) into v_role, v_div, v_owner
    from public.profiles where id = (select auth.uid());
  if v_owner or v_role in ('deputy_director', 'director') then return true; end if;
  if v_role <> 'bureau_lead' then return false; end if;
  select bureau into v_bureau from public.cases where id = p_case;
  return v_bureau = 'JTF' or v_bureau = v_div;
end $function$
;

