CREATE OR REPLACE FUNCTION private.can_view_legal_request(p_request uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.legal_requests r
    where r.id = p_request and (
      r.created_by = p_user
      or private.is_legal_participant(p_request, p_user)
      or private.owner_flag(p_user)
      or (r.submitted_to_doj_at is not null
          and coalesce(private.justice_role_effective(p_user) = 'attorney_general', false))
      or (r.submitted_to_doj_at is not null
          and not private.legal_is_siu(p_request)
          and private.justice_role_of(p_user) = 'district_attorney')
      or (r.review_status in ('prosecutor_queue', 'prosecutor_review',
                              'submitted_to_judge', 'returned_by_prosecutor', 'declined')
          and r.classification <> 'sealed'
          and not private.legal_is_siu(p_request)
          and coalesce(private.justice_role_effective(p_user) = 'prosecutor', false)
          and r.responsible_bureau = any (private.prosecutor_bureaus_of(p_user)))
      or (r.review_status in ('submitted_to_judge', 'judicial_review')
          and r.classification <> 'sealed'
          and coalesce(private.justice_role_effective(p_user) = 'judge', false))
      or (r.submitted_to_doj_at is not null
          and r.classification <> 'sealed'
          and r.approval_route = 'judge'
          and private.justice_role_of(p_user) = 'judge')
      or (r.submitted_to_doj_at is not null
          and r.classification <> 'sealed'
          and not private.legal_is_siu(p_request)
          and exists (
            select 1 from public.prosecutor_bureau_assignments a
            join public.justice_memberships m on m.user_id = a.prosecutor_id
            where a.prosecutor_id = p_user
              and a.bureau = r.responsible_bureau
              and a.ends_at is null and a.starts_at <= now()
              and m.active
              and m.justice_role in ('assistant_district_attorney', 'district_attorney')))
      or (r.review_status in ('cid_supervisor_review', 'siu_command_review')
          and private.can_review_as_cid(p_request, p_user))
      or (r.classification = 'standard'
          and private.is_active()
          and p_user = (select auth.uid())
          and private.can_access_case(r.case_id))))
$function$
;

CREATE OR REPLACE FUNCTION private.case_charge_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c record;
begin
  select pc.*, pv.status as version_status
    into c
    from public.penal_charges pc
    join public.penal_code_versions pv on pv.id = pc.version_id
   where pc.id = new.charge_id;
  if not found then
    raise exception 'no such charge';
  end if;

  if c.version_status = 'draft' then
    raise exception 'that charge belongs to an unpublished draft of the penal code';
  end if;
  if c.lifecycle <> 'active' then
    raise exception 'that charge is % and cannot be attached', c.lifecycle;
  end if;

  new.version_id := c.version_id;
  new.snap_code := c.code;
  new.snap_offense := c.offense;
  new.snap_penal_title := c.penal_title;
  new.snap_charge_class := c.charge_class;
  new.snap_fine := c.fine;
  new.snap_jail_months := c.jail_months;
  new.snap_judge_set_fine := c.judge_set_fine;
  new.snap_judge_set_jail := c.judge_set_jail;
  new.snap_stackable := c.stackable;
  new.snap_is_modifier := c.is_modifier;
  new.snap_is_rico := c.is_rico;
  new.snap_substance_schedule := c.substance_schedule;

  -- Live on arrival, but never pre-sentenced and never pre-decided by a court
  -- that has not seen it.
  new.status := 'approved';
  new.decided_by := null; new.decided_at := null; new.decision_note := null;
  new.imposed_fine := null; new.imposed_jail_months := null;
  new.imposed_by := null; new.imposed_at := null;
  new.added_by := (select auth.uid());
  new.added_at := now();
  new.updated_at := now();
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.case_charge_before_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.charge_id is distinct from old.charge_id
     or new.version_id is distinct from old.version_id
     or new.snap_code is distinct from old.snap_code
     or new.snap_offense is distinct from old.snap_offense
     or new.snap_penal_title is distinct from old.snap_penal_title
     or new.snap_charge_class is distinct from old.snap_charge_class
     or new.snap_fine is distinct from old.snap_fine
     or new.snap_jail_months is distinct from old.snap_jail_months
     or new.snap_judge_set_fine is distinct from old.snap_judge_set_fine
     or new.snap_judge_set_jail is distinct from old.snap_judge_set_jail
     or new.snap_stackable is distinct from old.snap_stackable
     or new.snap_is_modifier is distinct from old.snap_is_modifier
     or new.snap_is_rico is distinct from old.snap_is_rico
     or new.snap_substance_schedule is distinct from old.snap_substance_schedule
     or new.case_id is distinct from old.case_id
     or new.added_by is distinct from old.added_by
     or new.added_at is distinct from old.added_at then
    raise exception 'the charge snapshot is a historical record and cannot be edited';
  end if;

  if new.status is distinct from old.status then
    if not private.case_charge_transition_ok(old.status, new.status) then
      raise exception 'a charge cannot go from % to %', old.status, new.status;
    end if;
    if not private.case_charge_may(new.case_id, new.status) then
      raise exception 'you are not entitled to move this charge to %', new.status;
    end if;
    -- The self-approval bar is gone with the approval step: a charge is live
    -- when its author adds it, so such a rule would make every charge
    -- unaddable. Court transitions stay gated by justice role above.
    new.decided_by := (select auth.uid());
    new.decided_at := now();
  end if;

  if new.counts is distinct from old.counts
     and old.status in ('filed', 'convicted', 'dismissed') then
    raise exception 'counts cannot be changed once a charge has been filed';
  end if;

  if (new.imposed_fine is distinct from old.imposed_fine
      or new.imposed_jail_months is distinct from old.imposed_jail_months) then
    if coalesce(private.justice_role(), '') <> 'judge' then
      raise exception 'only a judge sets a penalty the code leaves to a judge';
    end if;
    new.imposed_by := (select auth.uid());
    new.imposed_at := now();
  end if;

  new.updated_at := now();
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.case_charge_court_read(p_case uuid, p_status text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select p_status in ('approved', 'filed', 'convicted', 'dismissed')
     and case when private.is_siu_case(p_case)
       then private.justice_role() in ('attorney_general', 'judge')
       else private.justice_role() is not null
     end
$function$
;

CREATE OR REPLACE FUNCTION private.case_charge_may(p_case uuid, p_to text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(case
    when p_to in ('approved', 'withdrawn') then
      private.can_access_case(p_case)
    when p_to = 'filed' then
      case when private.is_siu_case(p_case)
        then private.justice_role() = 'attorney_general'
        else private.justice_role() in ('prosecutor', 'assistant_district_attorney',
                                        'district_attorney', 'attorney_general')
      end
    when p_to in ('convicted', 'dismissed') then private.justice_role() = 'judge'
    else false
  end, false)
$function$
;

CREATE OR REPLACE FUNCTION private.case_charge_transition_ok(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case p_from
    when 'approved' then p_to in ('filed', 'withdrawn')
    when 'filed'    then p_to in ('convicted', 'dismissed')
    else false
  end
$function$
;

CREATE OR REPLACE FUNCTION private.case_has_active_hold(p_case uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.legal_holds h
    where h.lifted_at is null and (
      h.case_id = p_case
      or h.legal_request_id in (select id from public.legal_requests where case_id = p_case)
    ))
$function$
;

CREATE OR REPLACE FUNCTION private.case_number_base(p_bureau text)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case lower(coalesce(p_bureau, ''))
           when 'major_crimes' then 4000000
           when 'street_crimes' then 5000000
           when 'jtf' then 3000000
           when 'special_investigations' then 8000000
           else 4000000
         end::bigint
$function$
;

CREATE OR REPLACE FUNCTION private.case_service_notify(p_recipient uuid, p_type text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_payload jsonb;
begin
  if p_recipient is null then return; end if;
  v_payload :=
    (coalesce(p_payload, '{}'::jsonb)
      || case when p_payload ? 'reason'
              then jsonb_build_object('reason', left(p_payload->>'reason', 500))
              else '{}'::jsonb end
      || case when p_payload ? 'title'
              then jsonb_build_object('title', left(p_payload->>'title', 300))
              else '{}'::jsonb end)
    || jsonb_build_object(
         'actor_id', v_actor,
         'actor_name', (select display_name from public.profiles where id = v_actor));
  if exists (
    select 1 from public.notifications n
    where n.user_id = p_recipient
      and n.type = p_type
      and n.read = false
      and n.created_at > now() - interval '1 hour'
      and n.payload->>'case_id'    is not distinct from v_payload->>'case_id'
      and n.payload->>'request_id' is not distinct from v_payload->>'request_id'
      and n.payload->>'task_id'    is not distinct from v_payload->>'task_id'
      and n.payload->>'reason'     is not distinct from v_payload->>'reason'
      and n.payload->>'title'      is not distinct from v_payload->>'title'
      and n.payload->>'target'     is not distinct from v_payload->>'target'
  ) then
    return;
  end if;
  insert into public.notifications (user_id, type, payload)
  values (p_recipient, p_type, v_payload);
end $function$
;

CREATE OR REPLACE FUNCTION private.cid_role_rank(p_role app_role)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  -- Retired enum values (supervisor/command) rank 0: never assignable.
  select case p_role
    when 'detective' then 1
    when 'senior_detective' then 2
    when 'bureau_lead' then 3
    when 'deputy_director' then 4
    when 'director' then 5
    else 0
  end
$function$
;

CREATE OR REPLACE FUNCTION private.city2_reset(p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  t text;
  n bigint;
  steps jsonb := '[]'::jsonb;
  total_deleted bigint := 0;
  v_storage bigint;
  v_docs bigint;
  v_report jsonb;
begin
  if not (
    current_user in ('postgres', 'supabase_admin', 'service_role')
    or exists (select 1 from public.profiles p
               where p.id = (select auth.uid()) and p.is_owner and p.active)
  ) then
    raise exception 'city2_reset: caller is not Owner or a maintenance role';
  end if;

  if p_confirm is distinct from 'CITY2-FRESH-START' then
    raise exception 'city2_reset: confirmation phrase mismatch';
  end if;
  if not exists (select 1 from public.app_secrets
                 where key = 'city2_reset_armed'
                   and value = 'CITY2-FRESH-START-ARMED') then
    raise exception 'city2_reset: not armed (insert app_secrets key city2_reset_armed first; see migration 20261003120000)';
  end if;

  update public.legal_requests set current_version_id = null
   where current_version_id is not null;

  foreach t in array private.city2_wipe_tables() loop
    execute format('delete from public.%I', t);
    get diagnostics n = row_count;
    if n > 0 then
      steps := steps || jsonb_build_array(jsonb_build_object('table', 'public.' || t, 'deleted', n));
    end if;
    total_deleted := total_deleted + n;
  end loop;

  delete from public.documents where category = 'investigative';
  get diagnostics v_docs = row_count;
  total_deleted := total_deleted + v_docs;

  perform set_config('storage.allow_delete_query', 'true', true);
  delete from storage.objects where bucket_id = 'field-evidence';
  get diagnostics v_storage = row_count;
  perform set_config('storage.allow_delete_query', 'false', true);

  perform setval('private.legal_request_seq', 1, false);
  delete from private.field_submission_counters;

  delete from public.role_events;
  delete from public.notifications;
  delete from public.audit_log;
  perform setval('public.audit_log_id_seq', 1, false);

  delete from public.app_secrets where key = 'city2_reset_armed';

  v_report := jsonb_build_object(
    'reset', 'CITY2_FRESH_START_KEEP_ROSTER',
    'finished_at', now(),
    'rows_deleted_total', total_deleted,
    'rows_deleted_by_table', steps,
    'investigative_documents_deleted', v_docs,
    'roster_preserved', jsonb_build_object(
      'profiles', (select count(*) from public.profiles),
      'active_members', (select count(*) from public.profiles where active and not is_owner),
      'siu_memberships', (select count(*) from public.siu_memberships),
      'field_officers', (select count(*) from public.field_officers)),
    'storage_objects_deleted', v_storage,
    'verification', private.city2_verify()
  );

  insert into public.audit_log (actor_id, action, entity, detail)
  values ((select auth.uid()), 'CITY2_RESET', 'system',
          v_report - 'verification');

  return v_report;
end $function$
;

CREATE OR REPLACE FUNCTION private.city2_reset_preview()
 RETURNS TABLE(step integer, action text, target text, rows_now bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  t text;
  i integer := 0;
  n bigint;
begin
  foreach t in array private.city2_wipe_tables() loop
    i := i + 1;
    execute format('select count(*) from public.%I', t) into n;
    step := i; action := 'delete all rows'; target := 'public.' || t; rows_now := n;
    return next;
  end loop;
  i := i + 1;
  select count(*) into n from public.documents where category = 'investigative';
  step := i; action := 'delete filtered rows'; target := 'public.documents (category=investigative, + versions/sections via cascade)'; rows_now := n;
  return next;
  i := i + 1;
  select count(*) into n from public.profiles;
  step := i; action := 'PRESERVED VERBATIM (roster kept: role/bureau/active/LOA unchanged)'; target := 'public.profiles + siu_memberships + field_officers'; rows_now := n;
  return next;
  i := i + 1;
  select count(*) into n from private.field_submission_counters;
  step := i; action := 'delete all rows (counter reset)'; target := 'private.field_submission_counters'; rows_now := n;
  return next;
  i := i + 1;
  select count(*) into n from storage.objects where bucket_id = 'field-evidence';
  step := i; action := 'delete storage objects (bucket kept)'; target := 'storage.objects (bucket field-evidence)'; rows_now := n;
  return next;
  i := i + 1;
  select count(*) into n from public.role_events;
  step := i; action := 'delete all rows (history)'; target := 'public.role_events'; rows_now := n;
  return next;
  i := i + 1;
  select count(*) into n from public.audit_log;
  step := i; action := 'delete all rows, restart id sequence, write CITY2_RESET event'; target := 'public.audit_log'; rows_now := n;
  return next;
  i := i + 1;
  step := i; action := 'restart at 1 (next number LR-YYYY-0001)'; target := 'private.legal_request_seq'; rows_now := null;
  return next;
end $function$
;

CREATE OR REPLACE FUNCTION private.city2_verify()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  t text;
  n bigint;
  nonzero jsonb := '{}'::jsonb;
  total_remaining bigint := 0;
  fk record;
  orphans jsonb := '[]'::jsonb;
  fk_checked integer := 0;
  notnulls text;
  joincond text;
  preserved jsonb;
  seqs jsonb;
  posture jsonb;
begin
  foreach t in array private.city2_wipe_tables() loop
    execute format('select count(*) from public.%I', t) into n;
    if n > 0 then
      nonzero := nonzero || jsonb_build_object('public.' || t, n);
    end if;
    total_remaining := total_remaining + n;
  end loop;
  select count(*) into n from public.documents where category = 'investigative';
  if n > 0 then nonzero := nonzero || jsonb_build_object('public.documents[investigative]', n); end if;
  total_remaining := total_remaining + n;
  select count(*) into n from storage.objects where bucket_id = 'field-evidence';
  if n > 0 then nonzero := nonzero || jsonb_build_object('storage.objects[field-evidence]', n); end if;
  total_remaining := total_remaining + n;

  for fk in
    select con.oid,
           child.relname  as child_table,
           parent.relname as parent_table,
           con.conkey, con.confkey, con.conrelid, con.confrelid
    from pg_constraint con
    join pg_class child  on child.oid  = con.conrelid
    join pg_class parent on parent.oid = con.confrelid
    join pg_namespace cn on cn.oid = child.relnamespace
    join pg_namespace pn on pn.oid = parent.relnamespace
    where con.contype = 'f' and cn.nspname = 'public' and pn.nspname = 'public'
  loop
    select string_agg(format('c.%I = p.%I', a.attname, b.attname), ' and '),
           string_agg(format('c.%I is not null', a.attname), ' and ')
      into joincond, notnulls
    from unnest(fk.conkey) with ordinality as ck(attnum, ord)
    join unnest(fk.confkey) with ordinality as fk2(attnum, ord) on ck.ord = fk2.ord
    join pg_attribute a on a.attrelid = fk.conrelid  and a.attnum = ck.attnum
    join pg_attribute b on b.attrelid = fk.confrelid and b.attnum = fk2.attnum;
    execute format(
      'select count(*) from public.%I c where %s and not exists (select 1 from public.%I p where %s)',
      fk.child_table, notnulls, fk.parent_table, joincond) into n;
    fk_checked := fk_checked + 1;
    if n > 0 then
      orphans := orphans || jsonb_build_array(jsonb_build_object(
        'child', fk.child_table, 'parent', fk.parent_table, 'orphans', n));
    end if;
  end loop;

  select jsonb_build_object(
    'auth_users',            (select count(*) from auth.users),
    'profiles_total',        (select count(*) from public.profiles),
    'profiles_owner',        (select count(*) from public.profiles where is_owner),
    'profiles_owner_active', (select count(*) from public.profiles where is_owner and active),
    'profiles_active_members', (select count(*) from public.profiles where active and not is_owner),
    'profiles_role_assigned',  (select count(*) from public.profiles where role is not null and not is_owner),
    'siu_memberships',       (select count(*) from public.siu_memberships),
    'field_officers',        (select count(*) from public.field_officers),
    'penal_code_versions',   (select count(*) from public.penal_code_versions),
    'penal_charges',         (select count(*) from public.penal_charges),
    'penal_rules',           (select count(*) from public.penal_rules),
    'case_templates',        (select count(*) from public.case_templates),
    'app_secrets',           (select count(*) from public.app_secrets),
    'siu_settings',          (select count(*) from public.siu_settings),
    'surveillance_alert_rules', (select count(*) from public.surveillance_alert_rules),
    'documents_kept',        (select count(*) from public.documents),
    'feedback',              (select count(*) from public.feedback),
    'storage_buckets',       (select count(*) from storage.buckets),
    'integration_sources',   (select count(*) from public.integration_sources)
  ) into preserved;

  select jsonb_build_object(
    'legal_request_seq_last', (select last_value from pg_sequences where schemaname = 'private' and sequencename = 'legal_request_seq'),
    'field_submission_counters_rows', (select count(*) from private.field_submission_counters),
    'audit_log_rows', (select count(*) from public.audit_log)
  ) into seqs;

  select jsonb_build_object(
    'rls_disabled_public_tables', (
      select count(*) from pg_class c join pg_namespace ns on ns.oid = c.relnamespace
      where ns.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity),
    'realtime_tables', (
      select count(*) from pg_publication_tables where pubname = 'supabase_realtime'),
    'next_case_number_mcb', public.next_case_number('major_crimes')
  ) into posture;

  return jsonb_build_object(
    'clean',                total_remaining = 0 and orphans = '[]'::jsonb,
    'operational_rows_remaining', total_remaining,
    'nonzero_tables',       nonzero,
    'fk_constraints_checked', fk_checked,
    'fk_orphans',           orphans,
    'preserved',            preserved,
    'sequences',            seqs,
    'posture',              posture,
    'checked_at',           now()
  );
end $function$
;

