CREATE OR REPLACE FUNCTION private.default_case_originating_bureau()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.originating_bureau = 'JTF' then new.originating_bureau := null; end if;
  if new.bureau = 'JTF' and new.originating_bureau is null then
    select p.division into new.originating_bureau
      from public.profiles p
     where p.id = coalesce(new.created_by, (select auth.uid()))
       and p.division in ('major_crimes', 'street_crimes');
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.doc_class_visible(p_class text, p_owner uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(p_owner = (select auth.uid()), false)
      or case coalesce(p_class, 'internal')
        when 'internal' then private.is_active()
        when 'restricted' then
          coalesce((select active and (role in ('senior_detective', 'bureau_lead',
                     'deputy_director', 'director') or is_owner)
                    from public.profiles where id = (select auth.uid())), false)
        when 'command' then private.is_command() or private.is_owner()
        when 'justice' then coalesce(private.justice_role() is not null, false)
                            or private.is_owner()
        when 'siu' then private.siu_operates()
        when 'owner' then private.is_owner()
        else false
      end
$function$
;

CREATE OR REPLACE FUNCTION private.document_campaign_recipients(p_document uuid, p_audience text, p_targets jsonb, p_creator uuid)
 RETURNS TABLE(user_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select p.id from public.profiles p, public.documents d
  where d.id = p_document
    and p.active and p.removed_at is null and not p.is_system
    and p.is_test = private.is_test_user(p_creator)
    and p.id <> p_creator
    and (
      p_audience = 'all'
      or (p_audience in ('major_crimes', 'street_crimes', 'JTF') and p.division::text = p_audience)
      or (p_audience = 'command'
          and (p.role in ('bureau_lead', 'deputy_director', 'director') or p.is_owner))
      or (p_audience = 'detectives' and p.role = 'detective')
      or (p_audience = 'senior_detectives' and p.role = 'senior_detective')
      or (p_audience = 'specific'
          and coalesce(p_targets, '[]'::jsonb) @> to_jsonb(p.id::text))
    )
    and case coalesce(d.classification, 'internal')
      when 'internal' then true
      when 'restricted' then p.role in ('senior_detective', 'bureau_lead',
                                        'deputy_director', 'director') or p.is_owner
      when 'command' then p.role in ('bureau_lead', 'deputy_director', 'director') or p.is_owner
      when 'justice' then p.is_owner or exists (
        select 1 from public.justice_memberships m where m.user_id = p.id and m.active)
      when 'owner' then p.is_owner
      else false end
$function$
;

CREATE OR REPLACE FUNCTION private.document_initial_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.documents_versions
    (document_id, name, kind, content, modified_label, saved_by,
     version_number, change_type, change_summary, source_system)
  values (new.id, new.name, new.kind, new.content, new.modified_label,
          (select auth.uid()), new.current_version_number, 'editorial',
          'Created.', new.source_system)
  on conflict (document_id, version_number) where version_number is not null
  do nothing;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.document_suggestion_managers(p_document uuid)
 RETURNS TABLE(user_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select p.id
  from public.documents d
  join public.profiles p on p.active and p.removed_at is null
  where d.id = p_document
    and case coalesce(d.classification, 'internal')
      when 'owner' then p.is_owner
      when 'justice' then p.is_owner or exists (
        select 1 from public.justice_memberships m
         where m.user_id = p.id and m.active
           and m.justice_role in ('district_attorney', 'attorney_general'))
      when 'command' then p.is_owner or p.role in ('deputy_director', 'director')
      else
        p.is_owner
        or p.role in ('deputy_director', 'director')
        or (p.role = 'bureau_lead' and d.bureau is not null and p.division = d.bureau)
        or d.owner_user_id = p.id
    end
$function$
;

CREATE OR REPLACE FUNCTION private.field_access_request_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  new.user_id := (select auth.uid());
  new.status := 'pending';
  new.decided_by := null; new.decided_at := null; new.decision_reason := null;
  new.created_at := now(); new.updated_at := now();

  if private.is_active() then
    raise exception 'your account already has portal access';
  end if;
  if private.is_field_officer() then
    raise exception 'you already have Field Intelligence access';
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.field_case_visible(p_case uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.cases c
    where c.id = p_case
      and private.can_access_case_row(c.bureau, c.lead_detective_id, c.created_by, c.id))
$function$
;

CREATE OR REPLACE FUNCTION private.field_evidence_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_host text;
begin
  new.added_by := (select auth.uid());
  new.created_at := now();

  if new.kind = 'link' then
    new.storage_path := null;
    if new.external_url !~* '^https?://' then
      raise exception 'evidence links must be http or https URLs';
    end if;
    v_host := lower(split_part(split_part(new.external_url, '://', 2), '/', 1));
    new.is_medal := v_host = 'medal.tv' or v_host like '%.medal.tv';
  else
    new.external_url := null;
    new.is_medal := false;
  end if;

  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.field_jurisdiction_visible(p_jurisdiction text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select private.field_jurisdiction_visible_for((select auth.uid()), p_jurisdiction)
$function$
;

CREATE OR REPLACE FUNCTION private.field_jurisdiction_visible_for(p_user uuid, p_jurisdiction text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when coalesce(private.siu_standing(p_user) in
           ('owner', 'special_agent_in_charge', 'senior_special_agent', 'special_agent'),
         false) then true
    else coalesce((select p.active from public.profiles p where p.id = p_user), false)
  end
$function$
;

