CREATE OR REPLACE FUNCTION private.field_submission_readable(p_submission uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.field_submissions s
    where s.id = p_submission
      and (s.deleted_at is null
           or coalesce((select p.is_owner from public.profiles p
                         where p.id = (select auth.uid())), false))
      and (
        s.officer_id = (select auth.uid())
        or (
          private.is_active()
          and private.field_jurisdiction_visible(s.jurisdiction)
          and (
            not s.siu_sensitive
            or private.siu_is_agent()
            or s.siu_referred_by = (select auth.uid())
            or s.assigned_to = (select auth.uid())
          )
        )
      ))
$function$
;

CREATE OR REPLACE FUNCTION private.field_submission_transition_ok(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case p_from
    when 'draft' then false
    when 'new' then p_to in ('reviewing', 'reviewed', 'actionable', 'archived')
    when 'reviewing' then p_to in ('needs_info', 'reviewed', 'actionable', 'archived')
    when 'needs_info' then p_to in ('reviewing', 'reviewed', 'actionable', 'archived')
    when 'reviewed' then p_to in ('reviewing', 'actionable', 'archived')
    when 'actionable' then p_to in ('reviewing', 'reviewed', 'archived')
    when 'archived' then p_to in ('reviewing')
    else false
  end
$function$
;

CREATE OR REPLACE FUNCTION private.get_routing_ada_for_bureau(p_bureau bureau)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select a.prosecutor_id
    from public.prosecutor_bureau_assignments a
    join public.justice_memberships m on m.user_id = a.prosecutor_id
   where a.bureau = p_bureau and a.ends_at is null and a.starts_at <= now()
     and p_bureau in ('major_crimes', 'street_crimes')
     and m.active
     and m.justice_role in ('assistant_district_attorney', 'district_attorney')
     and a.assignment_type in ('acting', 'primary')
   order by case a.assignment_type when 'acting' then 0 else 1 end
   limit 1
$function$
;

CREATE OR REPLACE FUNCTION private.guard_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    if current_user in ('authenticated', 'anon') then
      new.approved_by := null;         new.approved_at := null;
      new.reviewed_at := null;         new.reviewed_by := null;
      new.review_note := null;         new.review_outcome := null;
      new.source_system := 'portal';   new.source_id := null;
      new.canonical_source := 'portal';
      new.source_modified_at := null;  new.last_synced_at := null;
      new.sync_status := null;         new.sync_error := null;
      new.current_version_number := 1;
      if not private.can_approve_document(new.category, new.classification) then
        new.mandatory := false;
        new.acknowledgement_required := false;
        new.acknowledgement_deadline := null;
      end if;
    end if;
    return new;
  end if;
  if current_user in ('authenticated', 'anon') then
    new.status := old.status;
    new.approved_by := old.approved_by;
    new.approved_at := old.approved_at;
    new.reviewed_at := old.reviewed_at;
    new.reviewed_by := old.reviewed_by;
    new.review_note := old.review_note;
    new.review_outcome := old.review_outcome;
    new.source_system := old.source_system;
    new.source_id := old.source_id;
    new.canonical_source := old.canonical_source;
    new.source_modified_at := old.source_modified_at;
    new.last_synced_at := old.last_synced_at;
    new.sync_status := old.sync_status;
    new.sync_error := old.sync_error;
    new.current_version_number := old.current_version_number;
    if not private.can_approve_document(old.category, old.classification) then
      new.category := old.category;
      new.document_type := old.document_type;
      new.classification := old.classification;
      new.owner_user_id := old.owner_user_id;
      new.owner_role := old.owner_role;
      new.approval_required := old.approval_required;
      new.effective_at := old.effective_at;
      new.review_due_at := old.review_due_at;
      new.expires_at := old.expires_at;
      new.mandatory := old.mandatory;
      new.acknowledgement_required := old.acknowledgement_required;
      new.acknowledgement_deadline := old.acknowledgement_deadline;
      new.tags := old.tags;
    end if;
    if old.canonical_source = 'google_drive'
       and (new.content ->> 'body') is distinct from (old.content ->> 'body') then
      new.sync_status := 'portal_newer';
    end if;
  end if;
  return new;
end $function$
;

