CREATE OR REPLACE FUNCTION private.guard_narcotic()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.created_by := (select auth.uid());
      if not private.can_manage_narcotics() then
        new.status := 'unidentified';
        new.confidence := coalesce(new.confidence, 'unverified');
        new.restricted := false;
        new.reviewed_at := null;
        new.reviewed_by := null;
        new.merged_into := null;
      end if;
    elsif tg_op = 'UPDATE' then
      new.created_by := old.created_by;
      new.merged_into := old.merged_into;  -- merge is RPC-only, for everyone
      if not private.can_manage_narcotics() then
        new.status := old.status;
        new.restricted := old.restricted;
        new.category := old.category;
        new.classification := old.classification;
        new.charge_codes := old.charge_codes;
        new.reviewed_at := old.reviewed_at;
        new.reviewed_by := old.reviewed_by;
      end if;
    end if;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.guard_narcotic_sale_observation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.created_by := (select auth.uid());
      new.investigator_id := coalesce(new.investigator_id, (select auth.uid()));
      new.restricted := true;
      if not private.can_edit_narcotics_intel() then new.state := 'draft'; end if;
    elsif tg_op = 'UPDATE' then
      new.created_by := old.created_by;
      new.series_id := old.series_id;
      new.narcotic_id := old.narcotic_id;
      new.restricted := true;
      if not private.can_edit_narcotics_intel() then new.state := old.state; end if;
    end if;
  end if;
  return new;
end $function$
;

