CREATE OR REPLACE FUNCTION private.guard_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid());
begin
  if tg_op = 'INSERT' then
    if current_user in ('authenticated', 'anon') then
      new.op_type := 'normal';
      new.lead_bureau := null;
      new.jtf_converted_at := null; new.jtf_converted_by := null;
      new.resolved_at := null;      new.resolved_by := null;
      if new.bureau is null then
        new.bureau := (select division from public.profiles where id = v_uid);
      elsif not private.is_command()
            and new.bureau is distinct from (select division from public.profiles where id = v_uid) then
        new.bureau := (select division from public.profiles where id = v_uid);
      end if;
      if new.bureau = 'JTF' then new.bureau := null; end if;
    end if;
    return new;
  end if;

  if current_user in ('authenticated', 'anon') then
    new.op_type := old.op_type;
    new.bureau := old.bureau;
    new.lead_bureau := old.lead_bureau;
    new.jtf_converted_at := old.jtf_converted_at;
    new.jtf_converted_by := old.jtf_converted_by;
    new.resolved_at := old.resolved_at;
    new.resolved_by := old.resolved_by;
  end if;

  if new.status is distinct from old.status then
    if new.status in ('resolved', 'closed') and old.status not in ('resolved', 'closed') then
      new.resolved_at := now(); new.resolved_by := v_uid;
    elsif new.status = 'active' then
      new.resolved_at := null; new.resolved_by := null;
    end if;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.guard_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  new.is_owner := old.is_owner;
  if private.is_command() then return new; end if;
  if (select auth.uid()) = new.id then
    new.role := old.role; new.active := old.active; new.division := old.division;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.guard_surveillance_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.created_by := (select auth.uid());
      new.verification_status := 'unverified';
      new.verified_by := null; new.verified_at := null;
      if new.confidence = 'confirmed' then new.confidence := 'probable'; end if;
    else
      new.case_id := old.case_id;
      new.created_by := old.created_by;
      new.verification_status := old.verification_status;
      new.verified_by := old.verified_by;
      new.verified_at := old.verified_at;
    end if;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.guard_surveillance_observation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.created_by := (select auth.uid());
      new.received_at := now();
      if new.source_type not in ('detective_manual', 'patrol_submission', 'other') then
        new.source_type := 'detective_manual';
      end if;
      new.verification_status := 'unverified';
      new.reviewed_by := null; new.reviewed_at := null; new.review_notes := null;
      new.promoted_at := null; new.promoted_by := null;
      new.ingestion_id := null; new.source_event_id := null;
      new.field_submission_id := null;
      if new.confidence = 'confirmed' then new.confidence := 'probable'; end if;
    else
      new.case_id := old.case_id;
      new.created_by := old.created_by;
      new.received_at := old.received_at;
      new.source_type := old.source_type;
      new.source_ref := old.source_ref;
      new.source_event_id := old.source_event_id;
      new.ingestion_id := old.ingestion_id;
      new.verification_status := old.verification_status;
      new.reviewed_by := old.reviewed_by;
      new.reviewed_at := old.reviewed_at;
      new.review_notes := old.review_notes;
      new.promoted_at := old.promoted_at;
      new.promoted_by := old.promoted_by;
      new.field_submission_id := old.field_submission_id;
    end if;
  end if;
  new.updated_at := now();
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.profiles (id, email, display_name, avatar_url, is_test)
  values (new.id, new.email,
          coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', new.email, 'Unassigned Officer'),
          new.raw_user_meta_data->>'avatar_url',
          new.email like 'rls-test-%@cidportal.test')
  on conflict (id) do nothing;
  return new;
end $function$
;

