$function$
;

CREATE OR REPLACE FUNCTION private.legal_add_participant(p_request uuid, p_user uuid, p_role text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into public.legal_request_participants
    (legal_request_id, user_id, participant_role, added_by)
  values (p_request, p_user, p_role, (select auth.uid()))
  on conflict (legal_request_id, user_id, participant_role)
  do update set removed_at = null, removed_by = null,
                added_by = excluded.added_by, added_at = now()
$function$
;

CREATE OR REPLACE FUNCTION private.legal_audit(p_request uuid, p_action text, p_detail jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), p_action, 'legal_requests', p_request, p_detail)
$function$
;

CREATE OR REPLACE FUNCTION private.legal_capacity(p_user uuid, p_capacity text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_cid boolean; v_doj text;
begin
  select coalesce(active, false) into v_cid from public.profiles where id = p_user;
  v_doj := private.justice_role_effective(p_user);
  if v_doj is null then return 'cid'; end if;
  if not v_cid then return 'doj:' || v_doj; end if;
  -- dual membership: an explicit choice is mandatory
  if p_capacity is null or p_capacity not in ('cid', 'doj') then
    raise exception 'you hold both CID and DOJ memberships — state the acting capacity (cid or doj)';
  end if;
  return case when p_capacity = 'doj' then 'doj:' || v_doj else 'cid' end;
end $function$
;

CREATE OR REPLACE FUNCTION private.legal_default_classification(p_type text, p_subtype text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case
    when p_type = 'warrant' then 'classified'
    when p_subtype in ('medical_records', 'financial_records', 'phone_records',
                       'social_media_accounts') then 'restricted'
    when p_subtype = 'testimony' then 'standard'
    else 'restricted'
  end
$function$
;

CREATE OR REPLACE FUNCTION private.legal_default_route(p_type text, p_subtype text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case
    when p_type = 'warrant' then 'judge'
    when p_subtype in ('financial_records') then 'ag'
    when p_subtype in ('medical_records', 'phone_records', 'social_media_accounts',
                       'surveillance_cctv', 'testimony') then 'judge'
    else 'da'  -- document_production, employment_records, housing_records, other
  end
$function$
;

