CREATE OR REPLACE FUNCTION private.legal_notify(p_user uuid, p_request uuid, p_kind text, p_reason text, p_extra jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.legal_requests; v_actor uuid := (select auth.uid());
        v_actor_name text; v_actor_test boolean; v_target_test boolean;
begin
  if p_user is null or p_user = v_actor then return; end if;
  select * into r from public.legal_requests where id = p_request;
  select email like 'rls-test-%@cidportal.test' into v_actor_test from auth.users where id = v_actor;
  select email like 'rls-test-%@cidportal.test' into v_target_test from auth.users where id = p_user;
  if coalesce(v_actor_test, false) and not coalesce(v_target_test, false) then return; end if;
  select display_name into v_actor_name from public.profiles where id = v_actor;
  if r.classification = 'sealed' then
    insert into public.notifications (user_id, type, payload)
    values (p_user, p_kind, jsonb_build_object(
      'request_id', p_request, 'sealed', true,
      'reason', 'A sealed legal request requires your attention.',
      'actor_id', v_actor));
  else
    insert into public.notifications (user_id, type, payload)
    values (p_user, p_kind, jsonb_build_object(
      'request_id', p_request, 'request_number', r.request_number,
      'request_type', r.request_type, 'title', r.title,
      'reason', p_reason, 'actor_id', v_actor, 'actor_name', v_actor_name) || coalesce(p_extra, '{}'::jsonb));
  end if;
end $function$
;

CREATE OR REPLACE FUNCTION private.legal_resolve_bureau(p_case uuid)
 RETURNS bureau
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.cases; v public.bureau; v_src text; v_pfx text;
begin
  select * into c from public.cases where id = p_case;
  if not found then raise exception 'case not found'; end if;
  if c.bureau in ('major_crimes', 'street_crimes') then return c.bureau; end if;
  if c.originating_bureau in ('major_crimes', 'street_crimes') then return c.originating_bureau; end if;

  -- Derivation for JTF-assigned cases. Priority mirrors the recorded history:
  -- the case-number prefix is the bureau the number was minted under (numbers
  -- never change on reassignment), then the lead's bureau, then the creator's.
  -- Legacy prefixes map through the restructure (LSB -> Major Crimes,
  -- BCB -> Street Crimes); an ex-SAB prefix is ambiguous under the split and
  -- falls through to the lead/creator derivation.
  v_pfx := split_part(coalesce(c.case_number, ''), '-', 1);
  if v_pfx in ('MCB', 'LSB') then
    v := 'major_crimes'; v_src := 'case_number';
  elsif v_pfx in ('SCB', 'BCB') then
    v := 'street_crimes'; v_src := 'case_number';
  end if;
  if v is null then
    select p.division into v from public.profiles p
     where p.id = c.lead_detective_id and p.division in ('major_crimes', 'street_crimes');
    if v is not null then v_src := 'lead_detective'; end if;
  end if;
  if v is null then
    select p.division into v from public.profiles p
     where p.id = c.created_by and p.division in ('major_crimes', 'street_crimes');
    if v is not null then v_src := 'creator'; end if;
  end if;
  if v is null then
    raise exception 'this case needs a responsible bureau for legal routing — a CID supervisor must select Major Crimes or Street Crimes on the case';
  end if;

  update public.cases set originating_bureau = v
   where id = c.id and originating_bureau is null;
  if found then
    insert into public.audit_log (actor_id, action, entity, entity_id, detail)
    values ((select auth.uid()), 'ORIGINATING_BUREAU_SET', 'cases', c.id,
            jsonb_build_object('bureau', v, 'source', 'derived:' || v_src,
                               'via', 'legal_resolve_bureau'));
  end if;
  return v;
end $function$
;

CREATE OR REPLACE FUNCTION private.legal_sign(p_request uuid, p_version uuid, p_action text, p_signature text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); v_name text; v_role text;
begin
  select display_name into v_name from public.profiles where id = v_uid;
  v_role := coalesce(private.justice_role_of(v_uid),
                     (select role::text from public.profiles where id = v_uid));
  insert into public.legal_request_signatures
    (legal_request_id, version_id, signer_id, signer_name_snapshot,
     signer_role_snapshot, signature, action)
  values (p_request, p_version, v_uid, coalesce(v_name, 'Unknown'), coalesce(v_role, 'unknown'),
          coalesce(nullif(btrim(coalesce(p_signature, '')), ''), coalesce(v_name, 'Signed')), p_action);
end $function$
;

CREATE OR REPLACE FUNCTION private.mdt_project(p_request uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.legal_requests; v_judge text;
begin
  select * into r from public.legal_requests where id = p_request;
  if r.request_type <> 'warrant' or r.subtype <> 'arrest_warrant' then return; end if;
  if r.classification = 'sealed' and r.executed_at is null then return; end if;
  select display_name into v_judge from public.profiles where id = r.decided_by;
  insert into public.mdt_wanted_projections
    (legal_request_id, person_id, person_name_snapshot, wanted_status,
     warrant_reference, warrant_type, issuing_judge_name, issue_date, expires_at,
     classification_safe_warning, sync_status)
  values (p_request, r.person_id, r.person_name_snapshot, p_status,
          r.request_number, r.subtype, v_judge, r.issued_at, r.expires_at,
          case r.priority when 'Critical' then 'Approach with caution'
                          when 'High' then 'Elevated risk' else null end,
          'pending')
  on conflict (legal_request_id) do update
    set wanted_status = excluded.wanted_status,
        issue_date = excluded.issue_date, expires_at = excluded.expires_at,
        issuing_judge_name = excluded.issuing_judge_name,
        sync_status = 'pending';
end $function$
;

CREATE OR REPLACE FUNCTION private.mr_history(p_request uuid, p_action text, p_from text, p_to text, p_note text, p_internal boolean)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into public.membership_request_history
    (request_id, actor_id, action, from_status, to_status, note, internal)
  values (p_request, (select auth.uid()), p_action, p_from, p_to, p_note, coalesce(p_internal, false));
$function$
;

CREATE OR REPLACE FUNCTION private.next_field_submission_no()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare y int := extract(year from now())::int; n int;
begin
  insert into private.field_submission_counters (year, last_no)
  values (y, 1)
  on conflict (year) do update set last_no = private.field_submission_counters.last_no + 1
  returning last_no into n;
  return 'FI-' || y::text || '-' || lpad(n::text, 4, '0');
end $function$
;

CREATE OR REPLACE FUNCTION private.next_legal_request_number()
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select 'LR-' || to_char(now(), 'YYYY') || '-'
         || lpad(nextval('private.legal_request_seq')::text, 4, '0')
$function$
;

CREATE OR REPLACE FUNCTION private.norm_org(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select nullif(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          -- Dots go BEFORE the suffix strip, so a dotted abbreviation is a word
          -- by the time the word-boundary match looks at it. Without this,
          -- "Drenger Blade M.C." normalized to "drengerblademc" and failed to
          -- match "Drenger Blade MC" -- the exact spelling variation this
          -- function exists to absorb.
          regexp_replace(
            regexp_replace(lower(coalesce(p, '')),
              '\m(motorcycle club|motorcycle gang)\M', 'mc', 'g'),
            '\.', '', 'g'),
          '\m(mc|gang|crew|syndicate|family|cartel)\M', '', 'g'),
        '[^a-z0-9]', '', 'g'),
      's$', '', 'g'),
    '')
$function$
;

CREATE OR REPLACE FUNCTION private.norm_plate(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select nullif(upper(regexp_replace(coalesce(p, ''), '[^a-zA-Z0-9]', '', 'g')), '')
$function$
;

CREATE OR REPLACE FUNCTION private.notify_owners_client_error()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o record;
begin
  for o in select id from public.profiles
            where is_owner and active
              and is_test = private.is_test_user(new.reporter_id) loop
    if not exists (
      select 1 from public.notifications n
      where n.user_id = o.id and n.type = 'client_error'
        and not n.read and n.created_at > now() - interval '15 minutes'
    ) then
      insert into public.notifications (user_id, type, payload)
      values (o.id, 'client_error', jsonb_build_object('reason', left(new.message, 160), 'route', new.route));
    end if;
  end loop;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.op_has_bureau(p_op uuid, p_bureau bureau)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.operation_bureaus ob
    where ob.operation_id = p_op and ob.bureau = p_bureau and ob.left_at is null
  ) $function$
;

CREATE OR REPLACE FUNCTION private.owner_flag(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce((select is_owner and removed_at is null
                   from public.profiles where id = p_user), false)
$function$
;

CREATE OR REPLACE FUNCTION private.pba_validate(p_prosecutor uuid, p_bureau bureau, p_type text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role text;
begin
  if p_bureau not in ('major_crimes', 'street_crimes') then
    raise exception 'a prosecutor bureau must be Major Crimes or Street Crimes';
  end if;
  select justice_role into v_role from public.justice_memberships
   where user_id = p_prosecutor and active;
  if v_role is null then raise exception 'target has no active justice membership'; end if;
  if v_role = 'judge' then raise exception 'a Judge may never receive a bureau assignment'; end if;
  if v_role = 'attorney_general' then raise exception 'the Attorney General oversees DOJ-wide and does not take bureau assignments'; end if;
  if v_role = 'district_attorney' and p_type <> 'acting' then
    raise exception 'a District Attorney may only serve as acting bureau prosecutor';
  end if;
  if v_role = 'assistant_district_attorney' and p_type not in ('primary', 'supporting', 'acting') then
    raise exception 'invalid assignment type';
  end if;
end $function$
;

CREATE OR REPLACE FUNCTION private.penal_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    private.is_owner()
    or exists (select 1 from public.penal_administrators a
                where a.user_id = (select auth.uid()) and a.revoked_at is null
                  and private.is_active()),
    false)
$function$
;

CREATE OR REPLACE FUNCTION private.permanent_delete_active_filter(p_ref text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case p_ref
    when 'siu_undercover_operations.agent_id'   then 'ended_at is null'
    when 'siu_undercover_operations.handler_id' then 'ended_at is null'
    when 'siu_sources.handler_id'               then 'deactivated_at is null'
    when 'siu_watchlist.assigned_agent'         then 'removed_at is null'
    else null
  end
$function$
;

CREATE OR REPLACE FUNCTION private.permanent_delete_active_refs()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select array[
    'cases.lead_detective_id', 'cases.signoff_assignee_id',
    'cases.signoff_submitted_by', 'gangs.lead_detective_id',
    'siu_undercover_operations.agent_id', 'siu_undercover_operations.handler_id',
    'siu_sources.handler_id',
    'siu_watchlist.assigned_agent',
    'field_submissions.assigned_to', 'field_submissions.siu_assigned_to'
  ]
$function$
;

CREATE OR REPLACE FUNCTION private.permanent_delete_blocker_refs()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select array[
    'legal_requests.created_by', 'legal_requests.assigned_ada_id',
    'legal_requests.assigned_judge_id', 'legal_requests.cid_reviewed_by',
    'legal_requests.decided_by', 'legal_requests.issued_by',
    'legal_requests.executed_by', 'legal_requests.served_by',
    'legal_requests.return_filed_by', 'legal_requests.revoked_by',
    'legal_requests.closed_by', 'legal_requests.source_submitter_id',
    'legal_requests.imported_by', 'legal_requests.assigned_prosecutor_id',
    'legal_request_actions.actor_id', 'legal_request_exhibits.added_by',
    'legal_request_participants.user_id', 'legal_request_participants.added_by',
    'legal_request_participants.removed_by', 'legal_request_signatures.signer_id',
    'legal_request_versions.created_by',
    'case_signoff_history.actor_id',
    'trackers.deputy_sig', 'trackers.director_sig',
    'reports.author_id',
    'custody_chain.transferred_by',
    'evidence.collected_by',
    'justice_memberships.user_id',
    'prosecutor_bureau_assignments.prosecutor_id'
  ]
$function$
