CREATE OR REPLACE FUNCTION private.permanent_delete_plan()
 RETURNS TABLE(bucket text, tbl text, col text, ref text, filter text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with fk as (
    select cl.relname::text as tbl, a.attname::text as col, c.confdeltype,
           c.conrelid, a.attnum
      from pg_constraint c
      join pg_class cl on cl.oid = c.conrelid
      join lateral unnest(c.conkey) k(attnum) on true
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k.attnum
     where c.contype = 'f'
       and c.confrelid = 'public.profiles'::regclass
       and c.connamespace = 'public'::regnamespace
  )
  select
    case
      when (f.tbl || '.' || f.col) = any (private.permanent_delete_blocker_refs())
        then 'blockers'
      when (f.tbl || '.' || f.col) = any (private.permanent_delete_active_refs())
        then 'active_work'
      when f.confdeltype = 'r' then 'blockers'
      when f.confdeltype = 'c' then 'cascade'
      when f.confdeltype = 'n' then 'set_null'
      when exists (
        select 1 from pg_index i
         where i.indrelid = f.conrelid and i.indisunique
           and i.indnkeyatts = 1 and i.indkey[0] = f.attnum)
        then 'deleted'
      else 'repoint'
    end as bucket,
    f.tbl, f.col, f.tbl || '.' || f.col as ref,
    private.permanent_delete_active_filter(f.tbl || '.' || f.col) as filter
  from fk f
$function$
;

CREATE OR REPLACE FUNCTION private.permanent_delete_refmap(p_target uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  n bigint;
  out_map jsonb := jsonb_build_object(
    'blockers', '{}'::jsonb, 'active_work', '{}'::jsonb, 'repoint', '{}'::jsonb,
    'cascade', '{}'::jsonb, 'set_null', '{}'::jsonb, 'deleted', '{}'::jsonb);
  blocker_total bigint := 0;
begin
  for r in select * from private.permanent_delete_plan() order by ref loop
    execute format(
      'select count(*) from public.%I where %I = $1%s',
      r.tbl, r.col,
      case when r.filter is null then '' else ' and ' || r.filter end)
      into n using p_target;

    if n > 0 then
      out_map := jsonb_set(out_map, array[r.bucket, r.ref], to_jsonb(n));
      if r.bucket in ('blockers', 'active_work') then
        blocker_total := blocker_total + n;
      end if;
    end if;
  end loop;

  return out_map || jsonb_build_object('blocker_total', blocker_total);
end $function$
;

CREATE OR REPLACE FUNCTION private.prosecutor_bureaus_of(p_user uuid)
 RETURNS bureau[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(array_agg(distinct b), '{}')
  from (
    select m.prosecutor_bureau as b from public.justice_memberships m
     where m.user_id = p_user and m.prosecutor_bureau is not null
    union all
    select c.bureau from public.prosecutor_coverage c
     where c.prosecutor_id = p_user and c.ended_at is null
       and c.starts_at <= now()
       and (c.expires_at is null or c.expires_at > now())
  ) x where b is not null
$function$
;

CREATE OR REPLACE FUNCTION private.rls_test_cleanup_surveillance(ids uuid[], case_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare leaked jsonb := '[]'::jsonb; n int;
begin
  delete from public.surveillance_alerts where case_id = any(case_ids);
  delete from public.surveillance_observations where case_id = any(case_ids);
  delete from public.surveillance_targets where case_id = any(case_ids);
  delete from public.bridge_ingestion_events where source like 'rls-test%';

  select count(*) into n from public.surveillance_observations s
   where s.created_by = any(ids) and not (s.case_id = any(case_ids));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'surveillance_observations.created_by', 'rows', n); end if;

  select count(*) into n from public.surveillance_targets s
   where s.requested_by = any(ids) and not (s.case_id = any(case_ids));
  if n > 0 then leaked := leaked || jsonb_build_object('surface', 'surveillance_targets.requested_by', 'rows', n); end if;

  return leaked;
end $function$
;

CREATE OR REPLACE FUNCTION private.role()
 RETURNS app_role
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select role from public.profiles where id = (select auth.uid()) and active $function$
;

CREATE OR REPLACE FUNCTION private.signoff_assert_decider(c cases, p_uid uuid, p_role app_role)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.can_access_case(c.id) then
    raise exception 'you do not have access to this case';
  end if;
  if p_uid is not distinct from c.signoff_submitted_by
     or p_uid is not distinct from c.lead_detective_id then
    raise exception 'the case owner cannot decide their own sign-off';
  end if;
  if p_uid is distinct from c.signoff_assignee_id and p_role is distinct from 'director' then
    raise exception 'this case is assigned to another reviewer';
  end if;
end $function$
;

CREATE OR REPLACE FUNCTION private.signoff_notify(p_recipient uuid, p_actor uuid, p_type text, p_case cases, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_recipient is null or p_recipient = p_actor then return; end if;
  if coalesce((select is_test from public.profiles where id = p_recipient), false)
     or coalesce((select is_test from public.profiles where id = p_actor), false) then return; end if;
  insert into public.notifications (user_id, type, payload)
  values (p_recipient, p_type, jsonb_build_object(
    'case_id', p_case.id, 'case_number', p_case.case_number, 'reason', p_reason,
    'actor_id', p_actor, 'actor_name', (select display_name from public.profiles where id = p_actor)));
end $function$
;

CREATE OR REPLACE FUNCTION private.signoff_pick(p_stage text, p_bureau bureau, p_exclude uuid[] DEFAULT NULL::uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare mapped text; v uuid; ex uuid[] := coalesce(p_exclude, '{}');
begin
  mapped := case p_stage when 'bureau_lead' then 'bureau_lead'
                         when 'deputy' then 'deputy_director'
                         when 'director' then 'director' end;
  if mapped is null then return null; end if;
  if p_stage = 'bureau_lead'
     and exists (select 1 from public.profiles
                 where active and role = 'bureau_lead' and division = p_bureau
                   and not (id = any(ex))) then
    select id into v from public.profiles
      where active and role = 'bureau_lead' and division = p_bureau and not loa
        and not (id = any(ex))
      order by created_at limit 1;
  else
    select id into v from public.profiles
      where active and role = mapped::public.app_role and not loa
        and not (id = any(ex))
      order by created_at limit 1;
  end if;
  return v;
end $function$
;

CREATE OR REPLACE FUNCTION private.signoff_route(p_start integer, p_bureau bureau, p_exclude uuid[] DEFAULT NULL::uuid[], OUT stage text, OUT assignee uuid)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_arr text[] := array['bureau_lead','deputy','director']; i int; a uuid;
begin
  for i in greatest(p_start,0)+1 .. array_length(order_arr,1) loop
    a := private.signoff_pick(order_arr[i], p_bureau, p_exclude);
    if a is not null then stage := order_arr[i]; assignee := a; return; end if;
  end loop;
  stage := null; assignee := null;
end $function$
;

CREATE OR REPLACE FUNCTION private.signoff_status_of(p_stage text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case p_stage when 'bureau_lead' then 'awaiting_bureau_lead'
                      when 'deputy' then 'awaiting_deputy'
                      when 'director' then 'awaiting_director' end
$function$
;

CREATE OR REPLACE FUNCTION private.siu_audience_excludes(p_case uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (p_user is not null and p_user is distinct from (select auth.uid()))
      or (p_case is not null and not private.can_access_case(p_case))
$function$
;

CREATE OR REPLACE FUNCTION private.siu_audience_rank(p_case uuid, p_user uuid)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case when p_user is not null then 1
              when p_case is not null then 2
              else 3 end
$function$
;

CREATE OR REPLACE FUNCTION private.siu_audit(p_action text, p_entity_id uuid, p_detail jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), p_action, 'siu', p_entity_id, p_detail)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_blocked(p_type text, p_id uuid, p_section text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when p_id is null then false
    when private.siu_sees_compartmented() then false
    else exists (
      select 1 from public.siu_visibility v
       where v.entity_type = p_type and v.entity_id = p_id
         and case v.scope
           when 'record' then
             v.state = 'siu_only'
             or (v.state = 'revealed'
                 and private.siu_audience_excludes(v.revealed_to_case_id, v.revealed_to_user_id))
             or (v.state = 'partial' and p_section is not null
                 and not (p_section = any(v.revealed_sections)))
           when 'sections' then
             v.state = 'siu_only'
             and p_section is not null
             and p_section = any(v.hidden_sections)
           else false
         end)
  end
$function$
;

CREATE OR REPLACE FUNCTION private.siu_can_appoint()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(private.siu_standing() in ('owner', 'special_agent_in_charge', 'oversight'), false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_can_read_case_note(p_case uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    case when private.is_siu_case(p_case)
         then private.siu_case_read(p_case)
         else private.siu_oversight_read() end,
    false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_case_access(p_cid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with s as (select private.siu_standing() as standing,
                    (select auth.uid()) as uid)
  select coalesce(case
    when (select standing from s) is null then false
    when not private.is_siu_case(p_cid) then false
    when private.siu_recused(p_cid, (select uid from s)) then false
    else case private.siu_case_classification(p_cid)
      when 'siu_compartmented' then
        private.siu_in_compartment(p_cid, (select uid from s))
      when 'siu_command' then
        (select standing from s) in ('owner', 'special_agent_in_charge')
        or private.siu_in_compartment(p_cid, (select uid from s))
      when 'siu_restricted' then
        (select standing from s) in ('owner', 'special_agent_in_charge')
        or ((select standing from s) in ('senior_special_agent', 'special_agent')
            and private.siu_case_assigned(p_cid, (select uid from s)))
        or private.siu_in_compartment(p_cid, (select uid from s))
      else
        (select standing from s) in
          ('owner', 'special_agent_in_charge', 'senior_special_agent', 'special_agent')
        or private.siu_in_compartment(p_cid, (select uid from s))
    end
  end, false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_case_assigned(p_cid uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from public.siu_case_agents a
                  where a.case_id = p_cid and a.user_id = p_user and a.removed_at is null)
      or exists (select 1 from public.cases c
                  where c.id = p_cid and c.case_authority = 'siu' and c.lead_detective_id = p_user)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_case_classification(p_cid uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce((select c.siu_classification from public.cases c
                    where c.id = p_cid and c.case_authority = 'siu'), 'siu')
$function$
;

CREATE OR REPLACE FUNCTION private.siu_case_command(p_cid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    private.siu_case_access(p_cid)
    and (private.siu_is_command()
         or exists (select 1 from public.cases c
                     where c.id = p_cid and c.lead_detective_id = (select auth.uid()))),
    false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_case_read(p_cid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    private.siu_case_access(p_cid)
    or (private.is_siu_case(p_cid)
        and not private.siu_recused(p_cid, (select auth.uid()))
        and coalesce(private.siu_case_classification(p_cid), 'siu') = 'siu'
        and coalesce((select c.siu_stage from public.cases c where c.id = p_cid),
                     'investigation') <> 'preliminary_inquiry'
        and private.siu_standing() = 'oversight'),
    false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_cid_attached(p_type text, p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case p_type
    when 'person' then
         exists (select 1 from public.field_claim_links        where person_id = p_id)
      or exists (select 1 from public.field_claim_verdicts     where person_id = p_id)
      or exists (select 1 from public.field_submission_evidence where person_id = p_id)
      or exists (select 1 from public.gang_members             where person_id = p_id)
      or exists (select 1 from public.person_places            where person_id = p_id)
      or exists (select 1 from public.person_vehicles          where person_id = p_id)
      or exists (select 1 from public.media                    where person_id = p_id)
      or exists (select 1 from public.narcotic_persons         where person_id = p_id)
      or exists (select 1 from public.legal_requests           where person_id = p_id)
      or exists (select 1 from public.legal_seized_items       where person_id = p_id)
      or exists (select 1 from public.mdt_exports              where person_id = p_id)
      or exists (select 1 from public.mdt_wanted_projections   where person_id = p_id)
      or exists (select 1 from public.account_links            where person_id = p_id)
    when 'vehicle' then
         exists (select 1 from public.field_claim_links        where vehicle_id = p_id)
      or exists (select 1 from public.field_claim_verdicts     where vehicle_id = p_id)
      or exists (select 1 from public.field_submission_evidence where vehicle_id = p_id)
      or exists (select 1 from public.person_vehicles          where vehicle_id = p_id)
      or exists (select 1 from public.media                    where vehicle_id = p_id)
      or exists (select 1 from public.narcotic_vehicles        where vehicle_id = p_id)
      or exists (select 1 from public.legal_seized_items       where vehicle_id = p_id)
      or exists (select 1 from public.mdt_exports              where vehicle_id = p_id)
    when 'gang' then
         exists (select 1 from public.field_claim_links        where gang_id = p_id)
      or exists (select 1 from public.gang_members             where gang_id = p_id)
      or exists (select 1 from public.gang_places              where gang_id = p_id)
      or exists (select 1 from public.gang_ranks               where gang_id = p_id)
      or exists (select 1 from public.gang_turf                where gang_id = p_id)
      or exists (select 1 from public.media                    where gang_id = p_id)
      or exists (select 1 from public.narcotic_gangs           where gang_id = p_id)
      or exists (select 1 from public.ballistic_footprints     where gang_id = p_id)
      or exists (select 1 from public.persons                  where gang_id = p_id)
      or exists (select 1 from public.vehicles                 where gang_id = p_id)
    when 'place' then
         exists (select 1 from public.field_claim_links        where place_id = p_id)
      or exists (select 1 from public.gang_places              where place_id = p_id)
      or exists (select 1 from public.person_places            where place_id = p_id)
      or exists (select 1 from public.media                    where place_id = p_id)
      or exists (select 1 from public.narcotic_places          where place_id = p_id)
      or exists (select 1 from public.narcotic_hotspots        where place_id = p_id)
      or exists (select 1 from public.place_process_steps      where place_id = p_id)
    else false
  end
$function$
;

CREATE OR REPLACE FUNCTION private.siu_entity_exists(p_type text, p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case p_type
    when 'person'  then exists (select 1 from public.persons  where id = p_id)
    when 'vehicle' then exists (select 1 from public.vehicles where id = p_id)
    when 'gang'    then exists (select 1 from public.gangs    where id = p_id)
    when 'place'   then exists (select 1 from public.places   where id = p_id)
    else false
  end
$function$
;

CREATE OR REPLACE FUNCTION private.siu_handler_access(p_case uuid, p_handler uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    private.siu_case_access(p_case)
    and (p_handler = (select auth.uid()) or private.siu_is_command()),
    false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_hidden(p_type text, p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select private.siu_blocked(p_type, p_id, null)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_in_compartment(p_cid uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from public.siu_compartment_members m
                  where m.case_id = p_cid and m.user_id = p_user and m.revoked_at is null)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_is_agent()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(private.siu_standing() in
    ('owner', 'special_agent_in_charge', 'senior_special_agent', 'special_agent'), false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_is_command()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(private.siu_standing() in ('owner', 'special_agent_in_charge'), false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_may_control_visibility()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    private.siu_standing() in
      ('owner', 'special_agent', 'senior_special_agent', 'special_agent_in_charge')
    or (select p.active and p.removed_at is null and p.role = 'director'
          from public.profiles p where p.id = (select auth.uid())),
    false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_may_request_access(p_user uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with u as (select coalesce(p_user, (select auth.uid())) as uid)
  select coalesce((select p.active and p.role = 'director' and not coalesce(p.is_test, false)
                     from public.profiles p, u where p.id = u.uid), false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_member_active()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  -- Membership, not standing: excludes 'oversight' (the AG) and anyone whose
  -- membership or profile has been closed.
  select private.siu_membership_role((select auth.uid())) is not null
$function$
;

CREATE OR REPLACE FUNCTION private.siu_membership_oversight(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.siu_memberships m
     join public.profiles p on p.id = m.user_id
    where m.user_id = p_user and m.active and m.oversight_only
      and p.active and p.removed_at is null)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_membership_role(p_user uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select m.siu_role
    from public.siu_memberships m
    join public.profiles p on p.id = m.user_id
   where m.user_id = p_user
     and m.active
     and not m.oversight_only
     and p.active and p.removed_at is null
$function$
;

CREATE OR REPLACE FUNCTION private.siu_operates()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select private.siu_standing() is not null $function$
;

CREATE OR REPLACE FUNCTION private.siu_oversight_read()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select coalesce(private.siu_is_agent(), false) $function$
;

CREATE OR REPLACE FUNCTION private.siu_recused(p_cid uuid, p_user uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    exists (select 1 from public.siu_conflicts k
             where k.case_id = p_cid
               and k.agent_id = coalesce(p_user, (select auth.uid()))
               and k.status <> 'cleared'),
    false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_release_open()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select coalesce((select s.enabled_for_non_owner from public.siu_settings s where s.id), false) $function$
;

CREATE OR REPLACE FUNCTION private.siu_sees_compartmented()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select private.siu_operates() or private.siu_may_control_visibility()
$function$
;

CREATE OR REPLACE FUNCTION private.siu_side_attached(p_type text, p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case p_type
    when 'person' then
         exists (select 1 from public.siu_targets              where person_id = p_id)
      or exists (select 1 from public.siu_watchlist            where person_id = p_id)
      or exists (select 1 from public.siu_sources              where person_id = p_id)
      or exists (select 1 from public.field_siu_enterprise     where person_id = p_id)
      or exists (select 1 from public.surveillance_observations where person_id = p_id)
    when 'vehicle' then
         exists (select 1 from public.siu_targets              where vehicle_id = p_id)
      or exists (select 1 from public.siu_watchlist            where vehicle_id = p_id)
      or exists (select 1 from public.field_siu_enterprise     where vehicle_id = p_id)
      or exists (select 1 from public.surveillance_observations where vehicle_id = p_id)
    when 'gang' then
         exists (select 1 from public.siu_targets              where gang_id = p_id)
      or exists (select 1 from public.siu_watchlist            where gang_id = p_id)
      or exists (select 1 from public.field_siu_enterprise     where gang_id = p_id)
    when 'place' then
         exists (select 1 from public.siu_targets              where place_id = p_id)
      or exists (select 1 from public.siu_watchlist            where place_id = p_id)
      or exists (select 1 from public.field_siu_enterprise     where place_id = p_id)
      or exists (select 1 from public.surveillance_observations where place_id = p_id)
      or exists (select 1 from public.surveillance_association_events where place_id = p_id)
    else false
  end
$function$
;

CREATE OR REPLACE FUNCTION private.siu_standing(p_user uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with u as (select coalesce(p_user, (select auth.uid())) as uid),
       f as (select coalesce(
               (select coalesce(p.is_test, false) from public.profiles p, u where p.id = u.uid),
               false) as is_fixture)
  select case
    when (select coalesce((select p.is_owner and p.active from public.profiles p, u where p.id = u.uid), false)) then 'owner'
    when not private.siu_release_open() then null
    when (select private.siu_membership_role((select uid from u))) is not null
      then (select private.siu_membership_role((select uid from u)))
    when (select private.siu_membership_oversight((select uid from u))) then 'oversight'
    when coalesce((select private.justice_role_effective((select uid from u))) = 'attorney_general', false)
     and not (select is_fixture from f)
      then 'oversight'
    else null
  end
$function$
;

CREATE OR REPLACE FUNCTION private.siu_temp_access(p_cid uuid, p_user uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with u as (select coalesce(p_user, (select auth.uid())) as uid)
  select coalesce(
    private.is_siu_case(p_cid)
    and coalesce(private.siu_case_classification(p_cid), 'siu') = 'siu'
    and not private.siu_recused(p_cid, (select uid from u))
    and (select coalesce((select p.active from public.profiles p, u where p.id = u.uid), false))
    and exists (select 1 from public.siu_temporary_access t, u
                 where t.case_id = p_cid and t.user_id = u.uid
                   and t.revoked_at is null and t.expires_at > now()),
    false)
$function$
;

CREATE OR REPLACE FUNCTION private.siu_visibility_forget()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  delete from public.siu_visibility
   where entity_type = tg_argv[0] and entity_id = old.id;
  return old;
end
$function$
;

CREATE OR REPLACE FUNCTION private.siu_watch_live(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce((select w.status in ('active', 'monitor', 'review_due', 'suspended')
                     and w.expires_at > now()
                     from public.siu_watchlist w where w.id = p_id), false)
$function$
;

CREATE OR REPLACE FUNCTION private.surveillance_alert_scan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; n int; v_label text;
begin
  -- repeated_vehicle: same vehicle (or plate snapshot) on this case.
  select * into r from public.surveillance_alert_rules where rule_key = 'repeated_vehicle' and enabled;
  if found and (new.vehicle_id is not null or nullif(btrim(coalesce(new.plate_snapshot, '')), '') is not null) then
    select count(*) into n from public.surveillance_observations o
     where o.case_id = new.case_id
       and o.observed_at > now() - make_interval(days => r.window_days)
       and ((new.vehicle_id is not null and o.vehicle_id = new.vehicle_id)
         or (new.vehicle_id is null and upper(btrim(o.plate_snapshot)) = upper(btrim(new.plate_snapshot))));
    if n >= r.threshold then
      v_label := coalesce('vehicle ' || new.vehicle_id::text, 'plate ' || upper(btrim(new.plate_snapshot)));
      insert into public.surveillance_alerts
        (alert_type, case_id, target_id, observation_id, title, explanation, dedupe_key)
      values ('repeated_vehicle', new.case_id, new.target_id, new.id,
              'Repeated vehicle observed',
              format('Rule repeated_vehicle: %s observed %s times in the last %s days on this case (threshold %s). A pattern is an investigative lead, not proof of criminal activity.',
                     v_label, n, r.window_days, r.threshold),
              format('repeated_vehicle:%s:%s', new.case_id, coalesce(new.vehicle_id::text, upper(btrim(new.plate_snapshot)))))
      on conflict (dedupe_key) where status = 'open' do nothing;
    end if;
  end if;

  -- repeated_person.
  select * into r from public.surveillance_alert_rules where rule_key = 'repeated_person' and enabled;
  if found and new.person_id is not null then
    select count(*) into n from public.surveillance_observations o
     where o.case_id = new.case_id and o.person_id = new.person_id
       and o.observed_at > now() - make_interval(days => r.window_days);
    if n >= r.threshold then
      insert into public.surveillance_alerts
        (alert_type, case_id, target_id, observation_id, title, explanation, dedupe_key)
      values ('repeated_person', new.case_id, new.target_id, new.id,
              'Repeated person observed',
              format('Rule repeated_person: the same person appears in %s observations in the last %s days on this case (threshold %s). A pattern is an investigative lead, not proof of criminal activity.',
                     n, r.window_days, r.threshold),
              format('repeated_person:%s:%s', new.case_id, new.person_id))
      on conflict (dedupe_key) where status = 'open' do nothing;
    end if;
  end if;

  -- repeated_location_activity: activity volume at a monitored place.
  select * into r from public.surveillance_alert_rules where rule_key = 'repeated_location_activity' and enabled;
  if found and new.place_id is not null then
    select count(*) into n from public.surveillance_observations o
     where o.case_id = new.case_id and o.place_id = new.place_id
       and o.observed_at > now() - make_interval(days => r.window_days);
    if n >= r.threshold then
      insert into public.surveillance_alerts
        (alert_type, case_id, target_id, observation_id, title, explanation, dedupe_key)
      values ('repeated_location_activity', new.case_id, new.target_id, new.id,
              'Repeated activity at monitored location',
              format('Rule repeated_location_activity: %s observations at this location in the last %s days on this case (threshold %s). A pattern is an investigative lead, not proof of criminal activity.',
                     n, r.window_days, r.threshold),
              format('repeated_location_activity:%s:%s', new.case_id, new.place_id))
      on conflict (dedupe_key) where status = 'open' do nothing;
    end if;
  end if;

  -- multiple_targets_co_located: distinct ACTIVE targets observed at one
  -- place within the rule window.
  select * into r from public.surveillance_alert_rules where rule_key = 'multiple_targets_co_located' and enabled;
  if found and new.place_id is not null and new.target_id is not null then
    select count(distinct o.target_id) into n from public.surveillance_observations o
      join public.surveillance_targets t on t.id = o.target_id
     where o.place_id = new.place_id
       and o.observed_at > now() - make_interval(days => r.window_days)
       and t.status in ('authorized', 'active');
    if n >= r.threshold then
      insert into public.surveillance_alerts
        (alert_type, case_id, target_id, observation_id, title, explanation, dedupe_key)
      values ('multiple_targets_co_located', new.case_id, new.target_id, new.id,
              'Multiple surveillance targets co-located',
              format('Rule multiple_targets_co_located: %s distinct active surveillance targets observed at the same location within %s day(s) (threshold %s). A pattern is an investigative lead, not proof of criminal activity.',
                     n, r.window_days, r.threshold),
              format('multiple_targets_co_located:%s:%s', new.case_id, new.place_id))
      on conflict (dedupe_key) where status = 'open' do nothing;
    end if;
  end if;
  return null;
end $function$
;

CREATE OR REPLACE FUNCTION private.surveillance_log(p_target uuid, p_action text, p_from text, p_to text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.surveillance_target_history
    (target_id, action, from_status, to_status, actor_id, actor_role, reason)
  values (p_target, p_action, p_from, p_to, (select auth.uid()),
          (select role from public.profiles where id = (select auth.uid())), p_reason);
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'SURV_' || upper(p_action), 'surveillance_targets', p_target,
          jsonb_build_object('from', p_from, 'to', p_to, 'reason', p_reason));
end $function$
;

CREATE OR REPLACE FUNCTION private.sync_case_operation_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  o public.operations;
  v_old uuid := case when tg_op = 'UPDATE' then old.operation_id else null end;
begin
  if v_old is not distinct from new.operation_id then return new; end if;

  if v_old is not null then
    select * into o from public.operations where id = v_old;
    if v_uid is not null and o.op_type = 'jtf' and not private.can_manage_joint(new.id) then
      raise exception 'removing a case from a JTF operation requires joint-case management authority';
    end if;
    update public.operation_case_links
       set removed_at = now(), removed_by = v_uid,
           removal_reason = case when new.operation_id is not null then 'relinked to another operation' else removal_reason end
     where operation_id = v_old and case_id = new.id and removed_at is null;
    insert into public.audit_log (actor_id, action, entity, entity_id, detail)
    values (v_uid, 'OP_CASE_UNLINKED', 'operation_case_links', new.id,
            jsonb_build_object('operation_id', v_old, 'case_number', new.case_number));
    if o.op_type = 'jtf' and new.lead_detective_id is not null and new.lead_detective_id is distinct from v_uid then
      insert into public.notifications (user_id, type, payload)
      values (new.lead_detective_id, 'op_joint_removed', jsonb_build_object(
        'case_id', new.id, 'case_number', new.case_number, 'operation_id', v_old,
        'operation_name', o.name,
        'reason', 'Case ' || coalesce(new.case_number, '') || ' was removed from Joint Operation “' || o.name || '”.',
        'actor_id', v_uid, 'actor_name', (select display_name from public.profiles where id = v_uid)));
    end if;
  end if;

  if new.operation_id is not null then
    select * into o from public.operations where id = new.operation_id;
    if not found then raise exception 'operation not found'; end if;
    if v_uid is not null and o.op_type = 'jtf' then
      if o.status <> 'active' then
        raise exception 'cases can only be linked to an ACTIVE JTF operation';
      end if;
      if new.bureau <> 'JTF' and not private.op_has_bureau(o.id, new.bureau) then
        raise exception 'bureau % is not a participating bureau of this JTF operation', new.bureau;
      end if;
      if not private.can_manage_joint(new.id) then
        raise exception 'linking a case to a JTF operation requires joint-case management authority (command, case lead, or creator)';
      end if;
    end if;
    insert into public.operation_case_links (operation_id, case_id, added_by, was_jtf)
    values (o.id, new.id, v_uid, o.op_type = 'jtf')
    on conflict (operation_id, case_id) where removed_at is null do nothing;
    insert into public.audit_log (actor_id, action, entity, entity_id, detail)
    values (v_uid, 'OP_CASE_LINKED', 'operation_case_links', new.id,
            jsonb_build_object('operation_id', o.id, 'case_number', new.case_number, 'jtf', o.op_type = 'jtf'));
    if o.op_type = 'jtf' and new.lead_detective_id is not null and new.lead_detective_id is distinct from v_uid then
      insert into public.notifications (user_id, type, payload)
      values (new.lead_detective_id, 'op_joint_linked', jsonb_build_object(
        'case_id', new.id, 'case_number', new.case_number, 'operation_id', o.id,
        'operation_name', o.name,
        'reason', 'Case ' || coalesce(new.case_number, '') || ' joined Joint Operation “' || o.name || '”.',
        'actor_id', v_uid, 'actor_name', (select display_name from public.profiles where id = v_uid)));
    end if;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin new.updated_at = now(); return new; end $function$
;

CREATE OR REPLACE FUNCTION private.touch_cases()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.last_stale_notified_at is distinct from old.last_stale_notified_at then
    new.updated_at = old.updated_at;
  else
    new.updated_at = now();
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.touch_membership_requests()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin new.updated_at := now(); return new; end $function$
;

CREATE OR REPLACE FUNCTION private.transfer_apply(p_id uuid, p_actor profiles, p_override boolean)
 RETURNS transfer_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.transfer_requests; t public.profiles; v_new_role public.app_role;
begin
  select * into r from public.transfer_requests where id = p_id for update;
  select * into t from public.profiles where id = r.target_id for update;
  if t.id is null or t.removed_at is not null or not t.active or t.login_denied then
    raise exception 'member is no longer transferable';
  end if;
  if t.division is distinct from r.from_bureau then
    raise exception 'member has moved since this transfer was requested';
  end if;
  -- A plain transfer must never clobber a promotion/demotion made while the
  -- request was pending: with no role change on the request, the member's
  -- LIVE role travels with them. A request that DID carry a role change is
  -- stale once the member's role moved — fail it for a fresh review.
  if r.to_role is distinct from r.from_role then
    if t.role is distinct from r.from_role then
      raise exception 'member''s role changed since this transfer was requested — reject it and request again';
    end if;
    v_new_role := r.to_role;
  else
    v_new_role := t.role;
  end if;
  update public.profiles set division = r.to_bureau, role = v_new_role where id = r.target_id;
  update public.transfer_requests
     set status = 'completed', completed_by = p_actor.id, completed_at = now()
   where id = p_id returning * into r;
  insert into public.role_events (target_id, actor_id, old_role, new_role,
    old_division, new_division, old_active, new_active, reason, source, source_id)
  values (r.target_id, p_actor.id, t.role, v_new_role,
    r.from_bureau, r.to_bureau, t.active, t.active, r.reason, 'transfer', r.id);
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (p_actor.id, 'TRANSFER_COMPLETED', 'transfer_requests', r.id,
    jsonb_build_object('target_id', r.target_id, 'from', r.from_bureau, 'to', r.to_bureau,
      'from_role', t.role, 'to_role', v_new_role, 'override', p_override));
  perform private.transfer_notify(r, p_actor,
    'Transfer to ' || r.to_bureau || ' completed.');
  return r;
end $function$
;

CREATE OR REPLACE FUNCTION private.transfer_doj_set_membership(p_user uuid, p_role text, p_actor uuid, p_expires timestamp with time zone, p_bureau bureau)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into public.justice_memberships
    (user_id, agency, justice_role, active, approved_by, approved_at,
     ended_at, expires_at, prosecutor_bureau)
  values (p_user, case when p_role = 'judge' then 'judiciary' else 'doj' end,
          p_role, true, p_actor, now(), null, p_expires,
          case when p_role = 'prosecutor' then p_bureau end)
  on conflict (user_id) do update
    set agency = excluded.agency, justice_role = excluded.justice_role,
        active = true, approved_by = excluded.approved_by, approved_at = excluded.approved_at,
        ended_at = null, expires_at = excluded.expires_at,
        prosecutor_bureau = excluded.prosecutor_bureau
$function$
;

CREATE OR REPLACE FUNCTION private.transfer_notify(p_transfer transfer_requests, p_actor profiles, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.notifications (user_id, type, payload)
  values (p_transfer.target_id, 'membership_update', jsonb_build_object(
    'transfer_id', p_transfer.id, 'status', p_transfer.status,
    'reason', p_reason, 'actor_id', p_actor.id, 'actor_name', p_actor.display_name));
  if private.is_test_user(p_actor.id) then return; end if;
  insert into public.notifications (user_id, type, payload)
  select p.id, 'membership_update', jsonb_build_object(
    'transfer_id', p_transfer.id, 'status', p_transfer.status,
    'reason', p_reason, 'actor_id', p_actor.id, 'actor_name', p_actor.display_name)
    from public.profiles p
   where p.active and p.removed_at is null and not p.is_test
     and p.id <> p_actor.id and p.id <> p_transfer.target_id
     and ((p.role = 'bureau_lead' and p.division in (p_transfer.from_bureau, p_transfer.to_bureau))
          or p.role in ('deputy_director', 'director'));
end $function$
;

CREATE OR REPLACE FUNCTION private.user_department(p_user uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case
    when private.siu_release_open()
     and private.siu_membership_role(coalesce(p_user, (select auth.uid()))) is not null
    then 'siu' else 'cid'
  end
$function$
;

CREATE OR REPLACE FUNCTION private.uuid_or_null(p text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  return p::uuid;
exception when others then
  return null;
end $function$
;

