  as permissive for delete to authenticated
  using (private.can_announce());

create policy ann_ins on public.announcements
  as permissive for insert to authenticated
  with check ((private.can_announce() AND private.can_post_audience(audience)));

create policy ann_sel on public.announcements
  as permissive for select to authenticated
  using ((private.is_active() AND ((audience = 'all'::text) OR (audience = ( SELECT (profiles.division)::text AS division
   FROM profiles
  WHERE (profiles.id = ( SELECT auth.uid() AS uid)))) OR ((audience = 'specific_members'::text) AND (mentions @> jsonb_build_array(jsonb_build_object('target', (( SELECT auth.uid() AS uid))::text)))) OR (author_id = ( SELECT auth.uid() AS uid)) OR private.is_command() OR private.is_owner())));

create policy ann_upd on public.announcements
  as permissive for update to authenticated
  using (private.can_announce())
  with check ((private.can_announce() AND private.can_post_audience(audience)));

