create policy document_suggestions_sel on public.document_suggestions
  as permissive for select to authenticated
  using (((created_by = ( SELECT auth.uid() AS uid)) OR private.is_owner() OR ((document_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM documents d
  WHERE ((d.id = document_suggestions.document_id) AND private.can_manage_document_suggestions(d.classification, d.owner_user_id, d.folder, d.bureau))))) OR ((document_id IS NULL) AND COALESCE(( SELECT (profiles.active AND (profiles.role = ANY (ARRAY['bureau_lead'::app_role, 'deputy_director'::app_role, 'director'::app_role])))
   FROM profiles
